window.BOOK={"key":"umdafiqh","app":"mutoon","lsk":"mutoon_umdafiqh_v1","title":"عمدة الفقه","unitWord":"فقرة","sub":"الفقه الحنبلي: على مذهب الإمام أحمد · موفق الدين ابن قدامة المقدسي (ت ٦٢٠هـ) · ١٥٧ بابًا","source":"عمدة الفقه ت. أحمد محمد عزوز (المكتبة العصرية ١٤٢٥هـ) = https://shamela.ws/book/11315 = https://ketabonline.com/ar/books/827 — اللفظ المتداول، مقابلًا بمتن «العدة شرح العمدة» (https://shamela.ws/book/10908) · قوبل بـ: الشكل منقول كلمةً كلمةً من متن «وبل الغمامة» المشكول (https://shamela.ws/book/145206، انظر umdafiqh.wabl.json) حيث اتفق اللفظ في ثلاث كلمات متتالية فأكثر، والباقي مكمَّل بالذكاء الاصطناعي — انظر umdafiqh-sources.md","note":"اللفظ المتداول (طبعة عزوز، مقابَلة كلمةً كلمةً بمتن «العدة شرح العمدة»). والشكل منقول من متن «وبل الغمامة» المشكول حيث اتفق اللفظ (٩٦٪ من الكلمات)، ومكمَّل بالذكاء الاصطناعي في الباقي (نحو ١٥٥٠ كلمة)، وكل ذلك في تقرير المصادر.","chapters":[{"id":"um1","title":"مُقَدِّمَةُ الْمَتْنِ","units":[{"id":"um1_1","label":"مُقَدِّمَةُ الْمَتْنِ · ١","segs":[["matn","الْحَمْدُ لِلَّهِ أَهْلِ الْحَمْدِ وَمُسْتَحِقِّهِ، حَمْدًا يَفْضُلُ عَلَى كُلِّ حَمْدٍ، كَفَضْلِ اللَّهِ عَلَى خَلْقِهِ."]]},{"id":"um1_2","label":"مُقَدِّمَةُ الْمَتْنِ · ٢","segs":[["matn","وَأَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، شَهَادَةَ قَائِمٍ لِلَّهِ بِحَقِّهِ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، غَيْرَ مُرْتَابٍ فِي صِدْقِهِ، صَلَّى اللَّهُ عَلَيْهِ وَعَلَى آلِهِ وَصَحْبِهِ وَسَلَّمَ، مَا جَادَ سَحَابٌ بِوَدْقِهِ، وَمَا رَعَدَ بَعْدَ بَرْقِهِ."]]},{"id":"um1_3","label":"مُقَدِّمَةُ الْمَتْنِ · ٣","segs":[["matn","أَمَّا بَعْدُ: فَهَذَا كِتَابٌ فِي الْفِقْهِ، اخْتَصَرْتُهُ حَسَبَ الْإِمْكَانِ، وَاقْتَصَرْتُ فِيهِ عَلَى قَوْلٍ وَاحِدٍ؛ لِيَكُونَ عُمْدَةً لِقَارِئِهِ، فَلَا يَلْتَبِسُ الصَّوَابُ عَلَيْهِ بِاخْتِلَافِ الْوُجُوهِ وَالرِّوَايَاتِ."]]},{"id":"um1_4","label":"مُقَدِّمَةُ الْمَتْنِ · ٤","segs":[["matn","سَأَلَنِي بَعْضُ إِخْوَانِي تَلْخِيصَهُ؛ لِيَقْرُبَ عَلَى الْمُتَعَلِّمِينَ، وَيَسْهُلَ حِفْظُهُ عَلَى الطَّالِبِينَ، فَأَجَبْتُهُ إِلَى ذَلِكَ، مُعْتَمِدًا عَلَى اللَّهِ سُبْحَانَهُ فِي إِخْلَاصِ الْقَصْدِ لِوَجْهِهِ الْكَرِيمِ، وَالْمَعُونَةِ عَلَى الْوُصُولِ إِلَى رِضْوَانِهِ الْعَظِيمِ، وَهُوَ حَسْبُنَا وَنِعْمَ الْوَكِيلُ."]]},{"id":"um1_5","label":"مُقَدِّمَةُ الْمَتْنِ · ٥","segs":[["matn","وَأَوْدَعْتُهُ أَحَادِيثَ صَحِيحَةً؛ تَبَرُّكًا بِهَا، وَاعْتِمَادًا عَلَيْهَا، وَجَعَلْتُهَا مِنَ الصِّحَاحِ؛ لِأَسْتَغْنِيَ عَنْ نِسْبَتِهَا إِلَيْهَا."]]}],"group":"مُقَدِّمَةُ الْمَتْنِ"},{"id":"um2","title":"بَابُ أَحْكَامِ الْمِيَاهِ","units":[{"id":"um2_1","label":"بَابُ أَحْكَامِ الْمِيَاهِ · ١","segs":[["matn","خُلِقَ الْمَاءُ طَهُورًا، يُطَهِّرُ مِنَ الأَحْدَاثِ وَالنَّجَاسَاتِ، فَلَا تَحْصُلُ الطَّهَارَةُ بِمَائِعٍ غَيْرِهِ فَإِذَا بَلَغَ الْمَاءُ قُلَّتَيْنِ، أَوْ كَانَ جَارِيًا، لَمْ يُنَجِّسْهُ شَيْءٌ، إِلَّا مَا غَيَّرَ لَوْنَهُ، أَوْ طَعْمَهُ، أَوْ رِيحَهُ، وَمَا سِوَى ذَلِكَ يَنْجُسُ بِمُخَالَطَةِ النَّجَاسَةِ."]]},{"id":"um2_2","label":"بَابُ أَحْكَامِ الْمِيَاهِ · ٢","segs":[["matn","وَالْقُلَّتَانِ: مَا قَارَبَ مِائَةً وَثَمَانِيَةَ أَرْطَالٍ بِالدِّمَشْقِيِّ. وَإِنْ طُبِخَ فِي الْمَاءِ مَا لَيْسَ بِطَهُورٍ، وَكَذَلِكَ مَا خَالَطَهُ فَغَلَبَ عَلَى اسْمِهِ، أَوْ اسْتُعْمِلَ فِي رَفْعِ حَدَثٍ سَلَبَ طَهُورِيَّتَهُ."]]},{"id":"um2_3","label":"بَابُ أَحْكَامِ الْمِيَاهِ · ٣","segs":[["matn","وَإِذَا شَكَّ فِي طَهَارَةِ الْمَاءِ، أَوْ غَيْرِهِ، أَوْ نَجَاسَتِهِ، بَنَى عَلَى الْيَقِينِ. وَإِنْ خَفِيَ مَوْضِعُ النَّجَاسَةِ مِنَ الثَّوْبِ أَوْ غَيْرِهِ، غَسَلَ مَا يَتَيَقَّنُ بِهِ غَسْلَهَا."]]},{"id":"um2_4","label":"بَابُ أَحْكَامِ الْمِيَاهِ · ٤","segs":[["matn","وَإِنِ اشْتَبَهَ مَاءٌ طَاهِرٌ بِنَجِسٍ، وَلَمْ يَجِدْ غَيْرَهُمَا تَيَمَّمَ وَتَرَكَهُمَا، وَإِنِ اشْتَبَهَ طَهُورٌ بِطَاهِرٍ تَوَضَّأَ مِنْ كُلِّ وَاحِدٍ مِنْهُمَا."]]},{"id":"um2_5","label":"بَابُ أَحْكَامِ الْمِيَاهِ · ٥","segs":[["matn","وَإِنِ اشْتَبَهَتْ ثِيَابٌ طَاهِرَةٌ بِنَجِسَةٍ، صَلَّى فِي كُلِّ ثَوْبٍ صَلَاةً بِعَدَدِ النَّجِسِ، وَزَادَ صَلَاةً."]]},{"id":"um2_6","label":"بَابُ أَحْكَامِ الْمِيَاهِ · ٦","segs":[["matn","وتُغْسَلُ نَجَاسَةُ الْكَلْبِ وَالْخِنْزِيرِ سَبْعًا، إِحْدَاهُنَّ بِالتُّرَابِ، وَيُجْزِئُ فِي سَائِرِ النَّجَاسَاتِ ثَلَاثٌ مُنْقِيَةٌ، وَإِنْ كَانَ عَلَى الأَرْضِ فَصَبَّةٌ وَاحِدَةٌ تَذْهَبُ بِعَيْنِهَا؛ لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ «صُبُّوا عَلَى بَوْلِ الأَعْرَابِيِّ ذَنُوبًا مِنْ مَاءٍ»."]]},{"id":"um2_7","label":"بَابُ أَحْكَامِ الْمِيَاهِ · ٧","segs":[["matn","وَيُجْزِئُ فِي بَوْلِ الْغُلَامِ الَّذِي لَمْ يَأْكُلِ الطَّعَامَ النَّضْحُ، وَكَذَلِكَ الْمَذْيُ، وَيُعْفَى عَنْ يَسِيرِهِ وَيَسِيرِ الدَّمِ، وَمَا تَوَلَّدَ مِنْهُ مِنَ الْقَيْحِ وَالصَّدِيدِ وَنَحْوِهِ، وَهُوَ مَا لَا يَفْحُشُ فِي النَّفْسِ. وَمَنِيُّ الآدَمِيِّ، وَبَوْلُ مَا يُؤْكَلُ لَحْمُهُ طَاهِرٌ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"um3","title":"بَابُ الآنِيَةِ","units":[{"id":"um3_1","label":"بَابُ الآنِيَةِ · ١","segs":[["matn","لَا يَجُوزُ اسْتِعْمَالُ آنِيَةِ الذَّهَبِ وَالْفِضَّةِ، فِي طَهَارَةٍ وَلَا غَيْرِهَا؛ لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «لَا تَشْرَبُوا فِي آنِيَةِ الذَّهَبِ وَالفِضَّةِ، وَلَا تَأْكُلُوا فِي صِحَافِهَا؛ فَإِنَّهَا لَهُمْ فِي الدُّنْيَا وَلَكُمْ فِي الآخِرَةِ»."]]},{"id":"um3_2","label":"بَابُ الآنِيَةِ · ٢","segs":[["matn","وَحُكْمُ الْمُضَبَّبِ بِهِمَا حُكْمُهُمَا، إِلَّا أَنْ تَكُونَ الْضَبَّةُ يَسِيرَةً مِنَ الْفِضَّةٍ."]]},{"id":"um3_3","label":"بَابُ الآنِيَةِ · ٣","segs":[["matn","وَيَجُوزُ اسْتِعْمَالُ سَائِرِ الآنِيَةِ الطَّاهِرَةِ وَاتِّخَاذُهَا، وَاسْتِعْمَالُ أَوَانِي أَهْلِ الْكِتَابِ، وَثِيَابِهِمْ مَا لَمْ تُعْلَمْ نَجَاسَتُهَا، وَصُوفُ الْمَيْتَةِ وَشَعَرُهَا طَاهِرٌ، وَكُلُّ جِلْدِ مَيْتَةٍ دُبِغَ أَوْ لَمْ يُدْبَغْ فَهُوَ نَجِسٌ وَكَذَلِكَ عِظَامُهَا."]]},{"id":"um3_4","label":"بَابُ الآنِيَةِ · ٤","segs":[["matn","وَكُلُّ مَيْتَةٍ نَجِسَةٌ إِلَّا الآدَمِيَّ، وَحَيَوَانَ الْمَاءِ، الَّذِي لَا يَعِيشُ إِلَّا فِيهِ؛ لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْبَحْرِ: «هُوَ الطَّهُورُ مَاؤُهُ، الْحِلُّ مَيْتَتُهُ»، وَمَا لَا نَفْسَ لَهُ سَائِلَةً إِذَا لَمْ يَكُنْ مُتَوَلِّدًا مِنَ النَّجَاسَاتِ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"um4","title":"بَابُ قَضَاءِ الْحَاجَةِ","units":[{"id":"um4_1","label":"بَابُ قَضَاءِ الْحَاجَةِ · ١","segs":[["matn","يُسْتَحَبُّ لِمَنْ أَرَادَ دُخُولَ الْخَلَاءِ أَنْ يَقُولَ: «بِسْمِ اللهِ، أَعُوذُ بِاللهِ مِنَ الْخُبُثِ وَالْخَبَائِثِ،» «وَمِنَ الرِّجْسِ النَّجِسِ الشَّيْطَانِ الرَّجِيمِ.» وَإِذَا خَرَجَ قَالَ: «غُفْرَانَكَ،» «الْحَمْدُ لِلَّهِ الَّذِي أَذْهَبَ عَنِّي الأَذَى وَعَافَانِي.»"]]},{"id":"um4_2","label":"بَابُ قَضَاءِ الْحَاجَةِ · ٢","segs":[["matn","وَيُقَدِّمُ رِجْلَهُ اليُسْرَى فِي الدُّخُولِ وَالْيُمْنَى فِي الْخُرُوجِ، وَلَا يَدْخُلُهُ بِشَيْءٍ فِيهِ ذِكْرُ اللهِ تَعَالَى إِلَّا مِنْ حَاجَةٍ، وَيَعْتَمِدُ فِي جُلُوسِهِ عَلَى رِجْلِهِ الْيُسْرَى."]]},{"id":"um4_3","label":"بَابُ قَضَاءِ الْحَاجَةِ · ٣","segs":[["matn","وَإِنْ كَانَ فِي الْفَضَاءِ، أَبْعَدَ وَاسْتَتَرَ، وَارْتَادَ لِبَوْلِهِ مَوْضِعًا رَخْوًا، وَلَا يَبُولُ فِي ثُقْبٍ وَلَا شَقٍّ، وَلَا طَرِيقٍ وَلَا ظِلٍّ نَافِعٍ، وَلَا تَحْتَ شَجَرَةٍ مُثْمِرَةٍ، وَلَا يَسْتَقْبِلُ شَمْسًا وَلَا قَمَرًا، وَلَا يَسْتَقْبِلُ الْقِبْلَةَ وَلَا يَسْتَدْبِرُهَا؛"]]},{"id":"um4_4","label":"بَابُ قَضَاءِ الْحَاجَةِ · ٤","segs":[["matn","لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «لَا تَسْتَقْبِلُوا الْقِبْلَةَ بِغَائِطٍ وَلَا بَوْلٍ وَلَا تَسْتَدْبِرُوهَا.»"]]},{"id":"um4_5","label":"بَابُ قَضَاءِ الْحَاجَةِ · ٥","segs":[["matn","وَيَجُوزُ ذَلِكَ فِي الْبُنْيَانِ وَإِذَا انْقَطَعَ الْبَوْلُ مَسَحَ مِنْ أَصْلِ ذَكَرِهِ إِلَى رَأْسِهِ، ثُمَّ يَنْتُرُهُ ثَلَاثًا، وَلَا يَمَسُّ ذَكَرَهُ بِيَمِينِهِ،"]]},{"id":"um4_6","label":"بَابُ قَضَاءِ الْحَاجَةِ · ٦","segs":[["matn","وَلَا يَتَمَسَّحُ بِهَا، ثُمَّ يَسْتَجْمِرُ وِتْرًا، ثُمَّ يَسْتَنْجِي بِالْمَاءِ، فَإِنِ اقْتَصَرَ عَلَى الِاسْتِجْمَارِ أَجْزَأَهُ، وَإِنَّمَا يُجْزِئُ الِاسْتِجْمَارُ إِذَا لَمْ تَتَعَدَّ النَّجَاسَةُ مَوْضِعَ الْحَاجَةِ."]]},{"id":"um4_7","label":"بَابُ قَضَاءِ الْحَاجَةِ · ٧","segs":[["matn","وَلَا يُجْزِئُ أَقَلُّ مِنْ ثَلَاثِ مَسَحَاتٍ مُنَقِّيَةٍ، وَيَجُوزُ الِاسْتِجْمَارُ بِكُلَّ طَاهِرٍ وَيَكُونُ مُنْقِيًا إِلَّا الرَّوْثَ وَالْعِظَامَ، وَمَا لَهُ حُرْمَةٌ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"um5","title":"بَابُ الْوُضُوءِ","units":[{"id":"um5_1","label":"بَابُ الْوُضُوءِ · ١","segs":[["matn","لَا يَصِحُّ الْوُضُوءُ، وَلَا غَيْرُهُ مِنَ الْعِبَادَاتِ، إِلَّا أَنْ يَنْوِيَهُ؛ لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى،» ثُمَّ يَقُولُ: بِسْمِ اللهِ."]]},{"id":"um5_2","label":"بَابُ الْوُضُوءِ · ٢","segs":[["matn","وَيَغْسِلُ كَفَّيْهِ ثَلَاثًا، ثُمَّ يَتَمَضْمَضُ وَيَسْتَنْشِقُ ثَلَاثًا يَجْمَعُ بَيْنَهُمَا بِغَرْفَةٍ أَوْ ثَلَاثٍ، ثُمَّ يَغْسِلُ وَجْهَهُ ثَلَاثًا، مِنْ مَنَابِتِ شَعَرِ الرَّأْسِ إِلَى مَا انْحَدَرَ مِنَ اللَّحْيَيْنِ وَالذَّقَنِ، وَإِلَى أُصُولِ الأُذُنَيْنِ."]]},{"id":"um5_3","label":"بَابُ الْوُضُوءِ · ٣","segs":[["matn","وَيُخَلِّلُ لِحْيَتَهُ إِنْ كَانَتْ كَثِيفَةً، وَإِنْ كَانَتْ تَصِفُ الْبَشَرَةَ لَزِمَهُ غَسْلُهَا، ثُمَّ يَغْسِلُ يَدَيْهِ إِلَى الْمِرْفَقَيْنِ ثَلَاثًا، وَيُدْخِلُهُمَا فِي الْغَسْلِ، ثُمَّ يَمْسَحُ رَأْسَهُ مَعَ الأُذُنَيْنِ، يَبْدَأُ بِيَدَيِّهِ مِنْ مُقَدَّمِهِ، ثُمَّ يُمِرُّهُمَا إِلَى قَفَاهُ، ثُمَّ يَرُدُّهُمَا إِلَى مُقَدَّمِهِ."]]},{"id":"um5_4","label":"بَابُ الْوُضُوءِ · ٤","segs":[["matn","ثُمَّ يَغْسِلُ رِجْلَيْهِ إِلَى الْكَعْبَيْنِ ثَلَاثًا، وَيُدْخِلُهُمَا فِي الْغَسْلِ، وَيُخَلِّلُ أَصَابِعَهُمَا، ثُمَّ يَرْفَعُ نَظَرَهُ إِلَى السَّمَاءِ، فَيَقُولُ: «أَشْهَدُ أَنْ لَا إِلهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ»."]]},{"id":"um5_5","label":"بَابُ الْوُضُوءِ · ٥","segs":[["matn","وَالْوَاجِبُ مِنْ ذَلِكَ النِّيَّةُ، وَالْغَسْلُ مَرَّةً مَرَّةً، مَا خَلَا الْكَفَّيْنِ، وَمَسْحُ الرَّأْسِ كُلِّهِ. وَتَرْتِيبُ الْوُضُوءِ عَلَى مَا ذَكَرْنَا، وَأَنْ لَا يُؤَخِّرَ غَسْلَ عُضْوٍ حَتَّى يَنْشَفَ الَّذِي قَبْلَهُ."]]},{"id":"um5_6","label":"بَابُ الْوُضُوءِ · ٦","segs":[["matn","وَالْمَسْنُونُ التَّسْمِيَةُ، وَغَسْلُ الْكَفَّيْنِ، وَالْمُبَالَغَةُ فيِ الْمَضْمَضَةِ وَالِاسْتِنْشَاقِ، إِلَّا أَنْ يَكُونَ صَائِمًا، وَتَخْلِيلُ اللِّحْيَةِ وَالأَصَابِعِ، وَمَسْحُ الأُذُنَيْنِ. وَغَسْلُ الْمَيَامِنِ قَبْلَ الْمَيَاسِرِ، وَالْغَسْلُ ثَلَاثًا ثَلَاثًا. وَتُكْرَهُ الزِّيادَةُ عَلَيْهَا، وَالإِسْرَافُ فِي الْمَاءِ."]]},{"id":"um5_7","label":"بَابُ الْوُضُوءِ · ٧","segs":[["matn","وَيُسَنُّ السِّوَاكُ عِنْدَ تَغَيُّرِ الْفَمِ، وَعِنْدَ الْقِيَامِ مِنَ النَّوْمِ، وَعِنْدَ الصَّلَاةِ؛ لِقَوْلِ رَسُوِلِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لِأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ» وَيُسْتَحَبُّ فِي سَائِرِ الأَوْقَاتِ إلَّا لِلصَّائِمِ بَعْدَ الزَّوَالِ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"um6","title":"بَابُ الْمَسْحِ عَلَى الْخُفَّيْنِ","units":[{"id":"um6_1","label":"بَابُ الْمَسْحِ عَلَى الْخُفَّيْنِ · ١","segs":[["matn","يَجُوزُ الْمَسْحُ عَلَى الْخُفَّيْنِ، وَمَا أَشْبَهَهُمَا مِنَ الْجَوَارِبِ الصَّفِيقَةِ الَّتِي تَثْبُتُ فِي الْقَدَمَيْنِ، وَالْجَرَامِيقِ الَّتِي تُجَاوِزُ الْكَعْبَيْنِ فِي الطَّهَارَةِ الصُّغْرَى، يَوْمًا وَلَيْلَةً لِلْمُقِيمِ وَثَلَاثًا لِلْمُسَافِرِ، مِنَ الْحَدَثِ إِلَى مِثْلِهِ؛"]]},{"id":"um6_2","label":"بَابُ الْمَسْحِ عَلَى الْخُفَّيْنِ · ٢","segs":[["matn","لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «يَمْسَحُ الْمُسَافِرُ ثَلَاثَةَ أَيَّامٍ وَلَيَالِيهِنَّ، وَالْمُقِيمُ يَوْمًا وَلَيْلَةً». وَمَتَى مَسَحَ ثُمَّ انْقَضَتِ الْمُدَّةُ، أَوْ خَلَعَ قَبْلَهَا، بَطَلَتْ طَهَارَتُهُ."]]},{"id":"um6_3","label":"بَابُ الْمَسْحِ عَلَى الْخُفَّيْنِ · ٣","segs":[["matn","وَمَنْ مَسَحَ مُسَافِرًا ثُمَّ أَقَامَ، أَوْ مُقِيمًا ثُمَّ سَافَرَ، أَتمَّ مَسْحَ مُقِيمٍ."]]},{"id":"um6_4","label":"بَابُ الْمَسْحِ عَلَى الْخُفَّيْنِ · ٤","segs":[["matn","وَيَجُوزُ الْمَسْحُ عَلَى الْعِمَامَةِ إِذَا كَانَتْ ذَاتَ ذُؤَابَةٍ، سَاتِرَةً لِجَمِيعِ الرَّأْسِ إِلَّا مَا جَرَتِ الْعَادَةُ بِكَشْفِهِ، وَمِنْ شَرْطِ الْمَسْحِ عَلَى جَمِيعِ ذَلِكَ، أَنْ يَلْبَسَهُ عَلَى طَهَارَةٍ كَامِلَةٍ."]]},{"id":"um6_5","label":"بَابُ الْمَسْحِ عَلَى الْخُفَّيْنِ · ٥","segs":[["matn","وَيَجُوزُ الْمَسْحُ عَلَى الْجَبِيرَةِ، إِذَا لَمْ يَتَعَدَّ بِشَدِّهَا مَوْضِعَ الْحَاجَةِ إِلَى أَنْ يَحُلَّهَا، وَالرَّجُلُ وَالْمَرْأَةُ فِي ذَلِكَ سَوَاءٌ، إِلَّا أَنَّ الْمَرْأَةَ لَا تَمْسَحُ عَلَى الْعِمَامَةِ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"um7","title":"بَابُ نَوَاقِضِ الْوُضُوءِ","units":[{"id":"um7_1","label":"بَابُ نَوَاقِضِ الْوُضُوءِ · ١","segs":[["matn","وَهِيَ سَبْعَةٌ: الْخَارِجُ مِنَ السَّبِيلَيْنِ وَالْخَارِجُ النَّجِسُ مِنْ غَيْرِهِمَا، إِذَا فَحُشَ."]]},{"id":"um7_2","label":"بَابُ نَوَاقِضِ الْوُضُوءِ · ٢","segs":[["matn","وَزَوَالُ الْعَقْلِ إِلَّا النَّوْمَ الْيَسِيرَ جَالِسًا أَوْ قَائِمًا وَلَمْسُ الذَّكَرِ بِيَدِهِ، وَلَمْسُ امْرَأَةٍ بِشَهْوَةٍ وَالرِّدَّةُ عَنِ الإِسْلَامِ، وَأَكْلُ لَحْمِ الْجَزُورِ، لِمَا رُوِيَ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قِيلَ لَهُ: أَنَتَوَضَّأُ مِنْ لُحُومِ الإِبِلِ؟"]]},{"id":"um7_3","label":"بَابُ نَوَاقِضِ الْوُضُوءِ · ٣","segs":[["matn","قَالَ: «نَعَمْ، تَوَضَّأُوا مِنْهَا،» قِيلَ: أَفَنَتَوَضَّأُ مِنْ لُحُومِ الْغَنَمِ؟ قَالَ: «إِنْ شِئْتَ فَتَوَضَّأْ، وَإِنْ شِئْتَ فَلَا تَتَوَضَّأْ»."]]},{"id":"um7_4","label":"بَابُ نَوَاقِضِ الْوُضُوءِ · ٤","segs":[["matn","وَمَنْ تَيَقَّنَ الطَّهَارَةَ، وَشَكَّ فِي الْحَدَثِ، أَوْ تَيَقَّنَ الْحَدَثَ، وَشَكَّ فِي الطَّهَارَةِ، فَهُوَ عَلَى مَا تَيَقَّنَ مِنْهُمَا."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"um8","title":"بَابُ الْغُسْلِ مِنَ الْجَنَابَةِ","units":[{"id":"um8_1","label":"بَابُ الْغُسْلِ مِنَ الْجَنَابَةِ · ١","segs":[["matn","وَالْمُوجِبُ لَهُ: خُرُوجُ الْمَنِيِّ، وَهُوَ: الْمَاءُ الدَّافِقُ، وَالْتِقَاءُ الْخِتَانَيْنِ."]]},{"id":"um8_2","label":"بَابُ الْغُسْلِ مِنَ الْجَنَابَةِ · ٢","segs":[["matn","وَالْوَاجِبُ فِيهِ: النِّيَّةُ، وَتَعْمِيمُ بَدَنِهِ بِالْغَسْلِ، مَعَ الْمَضْمَضَةِ وَالْاِسْتِنْشَاقِ وَتُسَنُّ التَّسْمِيَةُ، وَيَدْلُكُ بَدَنَهُ بِيَدِهِ، وَيَفْعَلَ كَمَا رَوَتْ مَيْمُونَةُ، قَالَتْ: سَتَرْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَاغْتَسَلَ مِنَ الْجَنَابَةِ،"]]},{"id":"um8_3","label":"بَابُ الْغُسْلِ مِنَ الْجَنَابَةِ · ٣","segs":[["matn","فَبَدَأَ فَغَسَلَ يَدَيْهِ، ثُمَّ صَبَّ بِيَمِينِهِ عَلَى شِمَالِهِ، فَغَسَلَ فَرْجَهُ وَمَا أَصَابَهُ، ثُمَّ ضَرَبَ بِيَدِهِ عَلَى الْحَائِطِ وَالْأَرْضِ ثُمَّ تَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ، ثُمَّ أَفَاضَ الْمَاءَ عَلَى بَدَنِهِ، ثَمَّ تَنَحَّى فَغَسَلَ رِجْلَيْهِ."]]},{"id":"um8_4","label":"بَابُ الْغُسْلِ مِنَ الْجَنَابَةِ · ٤","segs":[["matn","وَلَا يَجِبُ نَقْضُ الشَّعْرِ فِي غَسْلِ الْجَنَابَةِ إِذَا رَوَّى أُصُولَهُ. وَإِذَا نَوَى بِغَسْلِهِ الطَّهَارَتَيْنِ، أَجْزَأَ عَنْهُمَا."]]},{"id":"um8_5","label":"بَابُ الْغُسْلِ مِنَ الْجَنَابَةِ · ٥","segs":[["matn","وَكَذَلِكَ لَوْ تَيَمَّمَ لِلْحَدَثَيْنِ وَالنَّجَاسَةِ عَلَى بَدَنِهِ أَجْزَأَ عَنْ جَمِيعِهَا، وَإِنْ نَوَى بَعْضَهَا فَلَيْسَ لَهُ إِلَّا مَا نَوَى."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"um9","title":"بَابُ التَّيَمُّمِ","units":[{"id":"um9_1","label":"بَابُ التَّيَمُّمِ · ١","segs":[["matn","وَصِفَتُهُ: أَنْ يَضْرِبَ بِيَدَيْهِ عَلَى الصَّعِيدِ الطَّيِّبِ ضَرْبَةً وَاحِدَةً، فَيَمْسَحَ بِهِمَا وَجْهَهُ وَكَفَّيْهِ؛ لِقَوْلِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِعَمَّارِ: «إِنَّمَا كَانَ يَكْفِيكَ هَكَذَا» وَضَرَبَ بِيَدَيْهِ الأَرْضَ، فَمَسَحَ بِهِمَا وَجْهَهُ وَكَفَّيْهِ."]]},{"id":"um9_2","label":"بَابُ التَّيَمُّمِ · ٢","segs":[["matn","وَإِنْ تَيَمَّمَ بِأَكْثَرَ مِنْ ضَرْبَةٍ، أَوْ مَسَحَ أَكْثَرَ، جَازَ. وَلَهُ شُرُوطٌ أَرْبَعَةٌ: أَحَدُهَا: الْعَجْزُ عَنِ اسْتِعْمَالِ الْمَاءِ، إِمَّا لِعَدَمِهِ، أَوْ خَوْفِ الضَّرَرِ بِاسْتِعْمَالِهِ؛"]]},{"id":"um9_3","label":"بَابُ التَّيَمُّمِ · ٣","segs":[["matn","لِمَرَضٍ، أَوْ بَرْدٍ شَدِيدٍ أَوْ خَوْفِ الْعَطَشِ عَلَى نَفْسِهِ، أَوْ رَفِيقِهِ أَوْ بَهِيمَتِهِ أَوْ خَوْفٍ عَلَى نَفْسِهِ، أَوْ مَالِهِ فِي طَلَبِهِ،"]]},{"id":"um9_4","label":"بَابُ التَّيَمُّمِ · ٤","segs":[["matn","أَوْ إِعْوَازِهِ إِلَّا بِثَمَنٍ كَثِيرٍ، فَإِنْ أَمْكَنَهُ اسْتِعْمَالُهُ فِي بَعْضِ بَدَنِهِ، أَوْ وَجَدَ مَاءً لَا يَكْفِيهِ لِطَهَارَتِهِ، اسْتَعْمَلَهُ، وَتَيَمَّمَ لِلْبَاقِي."]]},{"id":"um9_5","label":"بَابُ التَّيَمُّمِ · ٥","segs":[["matn","الثَّانِي: الْوَقْتُ، فَلَا يَتَيَمَّمُ لِفَرِيضَةٍ قَبْلَ وَقْتِهَا، وَلَا لِنَافِلَةٍ فِي وَقْتِ النَّهْيِ عَنْهَا."]]},{"id":"um9_6","label":"بَابُ التَّيَمُّمِ · ٦","segs":[["matn","الثَّالِثُ: النِّيَّةُ، فَإِنْ تَيَمَّمَ لِنَافِلَةٍ، لَمْ يُصَلِّ بِهَا فَرْضًا وَإِنْ تَيَمَّمَ لِفَرِيضَةٍ، فَلَهُ فِعْلُهَا، وَفِعْلُ مَا شَاءَ مِنَ الْفَرَائِضِ وَالنَّوَافِلِ، حَتَّى يَخْرُجَ وَقْتُهَا."]]},{"id":"um9_7","label":"بَابُ التَّيَمُّمِ · ٧","segs":[["matn","الرَّابِعُ: التُّرَابُ، فَلَا يَتَيَمَّمَ إِلَّا بِتُرَابٍ طَاهِرٍ، لَهُ غُبَارٌ. ويُبْطِلُ التَّيَمُّمَ مَا يُبْطِلُ طَهَارَةَ الْمَاءِ، وَخُرُوجُ الوَقْتِ، وَالْقُدْرَةُ عَلَى اسْتِعْمَالِ الْمَاءِ، وَإِنْ كَانَ فِي الصَّلَاةِ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"um10","title":"بَابُ الْحَيْضِ","units":[{"id":"um10_1","label":"بَابُ الْحَيْضِ · ١","segs":[["matn","وَيَمْنَعُ عَشَرَةَ أَشْيَاءَ: فِعْلَ الصَّلَاةِ، وَوُجُوبَهَا، وَفِعْلَ الصِّيَامِ، وَالطَّوَافَ، وَقِرَاءَةَ الْقُرْآنِ، وَمَسَّ الْمُصْحَفِ، وَاللُّبْثَ فِي الْمَسْجِدِ، وَالْوَطْءَ فِي الْفَرْجِ، وَسُنَّةَ الطَّلَاقِ، وَالِاعْتِدَادَ بِالأَشْهُرِ."]]},{"id":"um10_2","label":"بَابُ الْحَيْضِ · ٢","segs":[["matn","وَيُوجِبُ الْغُسْلَ، وَالْبُلُوغَ، وَالِاعْتِدَادَ بِهِ، فَإِذَا انْقَطَعَ الدَّمُ، أُبِيحَ فِعْلُ الصَّوْمِ، وَالطَّلَاقُ، وَلَمْ يُبَحْ سَائِرُهَا حَتَّى تَغْتَسِلَ، وَيَجُوزُ الِاسْتِمْتَاعُ مِنَ الْحَائِضِ، بِمَا دُونَ الْفَرْجِ؛ لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «اصْنَعُوا كُلَّ شَيْءٍ غَيْرَ النِّكَاحَ.»"]]},{"id":"um10_3","label":"بَابُ الْحَيْضِ · ٣","segs":[["matn","وَأَقَلُّ الْحَيْضِ يَوْمٌ وَلَيْلَةٌ، وَأَكْثَرُهُ خَمْسَةَ عَشَرَ يَوْمًا، وَأَقَلُّ الطُّهْرِ بَيْنَ الْحَيْضَتَيْنِ ثَلَاثَةَ عَشَرَ يَوْمًا، وَلَا حَدَّ لِأَكْثَرِهِ. وَأَقَلُّ سِنٍّ تَحِيضُ لَهُ الْمَرْأَةُ تِسْعُ سِنِينَ وَأَكْثَرُهُ سِتُّونَ."]]},{"id":"um10_4","label":"بَابُ الْحَيْضِ · ٤","segs":[["matn","وَالْمُبْتَدَأَةُ إِذَا رَأَتِ الدَّمَ لِوَقْتٍ تَحِيضُ فِي مِثْلِهِ، جَلَسَتْ، فَإِنِ انْقَطَعَ لِأَقَلَّ مِنْ يَوْمٍ وَلَيْلَةٍ، فَلَيْسَ بَحَيْضٍ، وَإِنْ جَاوَزَ ذَلِكَ وَلَمْ يَعْبُرْ أَكْثَرَ الْحَيْضِ، فَهُوَ حَيْضٌ، فَإِذَا تَكَرَّرَ ثَلَاثَةَ أَشْهُرٍ بِمَعْنًى وَاحِدٍ، صَارَ عَادَةً، وَإِنْ عَبَرَ ذَلِكَ فَالزَّائِدُ اسْتَحَاضَةٌ."]]},{"id":"um10_5","label":"بَابُ الْحَيْضِ · ٥","segs":[["matn","وَعَلَيْهَا أَنْ تَغْتَسِلَ عِنْدَ آخِرِ الْحَيْضِ، وَتَغْسِلَ فَرْجَهَا وَتَعْصِبَهُ، ثُمَّ تَتَوَضَّأَ لِوَقْتِ كُلِّ صَلَاةٍ، وَتُصَلِّي، وَكَذَا حُكْمُ مَنْ بِهِ سَلَسُ الْبَوْلِ، وَمَا فِي مَعْنَاهُ، فَإِذَا اسْتَمَرَّ بِهَا الدَّمُ فِي الشَّهْرِ الآخَرِ، فَإِنْ كَانَتْ مُعْتَادَةً، فَحَيْضُهَا أَيَّامُ عَادَتِهَا."]]},{"id":"um10_6","label":"بَابُ الْحَيْضِ · ٦","segs":[["matn","وَإِنْ لَمْ تَكُنْ مُعْتَادَةً وَكَانَ لَهَا تَمْيِيزٌ وَهُوَ أَنْ يَكُونَ بَعْضُ دَمِهَا أَسْوَدَ ثَخِينًا، وَبَعْضُهُ أَحْمَرَ رَقِيقًا فَحَيْضُهَا زَمَنُ الأَسْوَدِ الثَّخِينِ."]]},{"id":"um10_7","label":"بَابُ الْحَيْضِ · ٧","segs":[["matn","وَإِنْ كَانَتْ مُبْتَدَأَةً، أَوْ نَاسِيَةً لِعَادَتِهَا، وَلَا تَمْيِيزَ لَهَا، فَحَيْضُهَا مِنْ كُلِّ شَهْرٍ سِتَّةُ أَيَّامٍ، أَوْ سَبْعَةٌ؛ لِأَنَّهُ غَالِبُ عَادَاتِ النِّسَاءِ. وَالْحَامِلُ لَا تَحِيضُ."]]},{"id":"um10_8","label":"بَابُ الْحَيْضِ · ٨","segs":[["matn","إِلَّا أَنْ تَرَى الدَّمَ قَبْلَ وِلَادَتِهَا بِيَوْمٍ أَوْ يَوْمَيْنِ فَيَكُونُ دَمَ نِفَاسٍ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"um11","title":"بَابُ النِّفَاسِ","units":[{"id":"um11_1","label":"بَابُ النِّفَاسِ · ١","segs":[["matn","وَهُوَ: الدَّمُ الْخَارِجُ بِسَبَبِ الْوِلَادَةِ، وَحُكْمُهُ حُكْمُ الْحَيْضِ فِيمَا يَحِلُّ وَيَحْرُمُ وَيَجِبُ وَيَسْقُطُ بِهِ."]]},{"id":"um11_2","label":"بَابُ النِّفَاسِ · ٢","segs":[["matn","وَأَكْثَرُهُ أَرْبَعُونَ يَوْمًا، وَلَا حَدَّ لِأَقَلِّهِ، وَمَتَى رَأَتِ الطُّهْرَ، اغْتَسَلَتْ، وَهِيَ طَاهِرٌ وَإِنْ عَادَ فِي مُدَّةِ الأَرْبَعِينَ، فَهُوَ نِفَاسٌ أَيْضًا."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"um12","title":"كِتَابُ الصَّلَاةِ","units":[{"id":"um12_1","label":"كِتَابُ الصَّلَاةِ · ١","segs":[["matn","رَوَى عُبَادَةُ بْنُ الصَّامِتِ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:"]]},{"id":"um12_2","label":"كِتَابُ الصَّلَاةِ · ٢","segs":[["matn","«خَمْسُ صَلَوَاتٍ كَتَبَهُنَّ اللهُ عَلَى الْعِبَادِ فِي الْيَوْمِ وَاللَّيْلَةِ، فَمَنْ حَافَظَ عَلَيْهِنَّ، كَانَ لَهُ عَهْدٌ عِنْدَ اللَّهِ أَنْ يُدْخِلَهُ الْجَنَّةَ، وَمَنْ لَمْ يُحَافِظْ عَلَيْهِنَّ، لَمْ يَكُنْ لَهُ عِنْدَ اللهِ عَهْدٌ، إِنْ شَاءَ عَذَّبَهُ، وَإِنْ شَاءَ غَفَرَ لَهُ»."]]},{"id":"um12_3","label":"كِتَابُ الصَّلَاةِ · ٣","segs":[["matn","فَالصَّلَوَاتُ الْخَمْسُ وَاجِبَةٌ عَلَى كُلِّ مُسْلِمٍ، عَاقِلٍ، بَالِغٍ، إِلَّا الْحَائِضَ، وَالنُّفَسَاءَ، فَمَنْ جَحَدَ وُجُوبَهَا لِجَهْلِهِ، عُرِّفَ ذَلِكَ، وَإِنْ جَحَدَهَا عِنَادًا، كَفَرَ."]]},{"id":"um12_4","label":"كِتَابُ الصَّلَاةِ · ٤","segs":[["matn","وَلَا يَحِلُّ تَأْخِيرُهَا عَنْ وَقْتِ وُجُوبِهَا إِلَّا لِنَاوٍ جَمْعَهَا، أَوْ مُشْتَغِلٍ بِشَرْطِهَا، فَإِنْ تَرَكَهَا تَهَاوُنًا، بِهَا اسْتُتِيبَ ثَلَاثًا، فَإِنْ تَابَ، وَإِلَّا قُتِلَ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um13","title":"بَابُ الأَذَانِ وَالإِقَامَةِ","units":[{"id":"um13_1","label":"بَابُ الأَذَانِ وَالإِقَامَةِ · ١","segs":[["matn","وَهُمَا مَشْرُوعَانِ لِلصَّلَوَاتِ الْخَمْسِ دُونَ غَيْرِهَا، لِلرِّجَالِ دُونَ النِّسَاءِ. وَالأَذَانُ خَمْسَ عَشْرَةَ كَلِمَةً، لَا تَرْجِيعَ فِيهِ، وَالإِقَامَةُ إِحْدَى عَشْرَةَ. كَلِمَةً."]]},{"id":"um13_2","label":"بَابُ الأَذَانِ وَالإِقَامَةِ · ٢","segs":[["matn","وَيَنْبَغِي أَنْ يَكُونَ الْمُؤَذِّنُ أَمِينًا، صَيِّتًا، عَالِمًا بِالأَوْقَاتِ، وَيُسْتَحَبُّ أَنْ يُؤَذِّنَ قَائِمًا، مُتَطَهِّرًا عَلَى مَوْضِعٍ عَالٍ، مُسْتَقْبِلَ الْقِبْلَةِ، فَإِذَا بَلَغَ الْحَيْعَلَةَ، الْتَفَتَ يَمِينًا وَشِمَالاً وَلَا يُزِيلُ قَدَمَيْهِ، وَيَجْعَلُ إِصْبَعَيْهِ فِي أُذُنَيْهِ، وَيَتَرَسَّلَ فِي الأَذَانِ، وَيَحْدُرُ الإِقَامَةَ."]]},{"id":"um13_3","label":"بَابُ الأَذَانِ وَالإِقَامَةِ · ٣","segs":[["matn","وَيَقُولُ فِي أَذَانِ الصُّبْحِ: بَعْدَ الْحَيْعَلَةِ الصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ، مَرَّتَيْنِ وَلَا يُؤَذِّنُ قَبْلَ الْأَوْقَاتِ إِلَّا لَهَا؛ لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «إِنَّ بِلَالاً يُؤَذِّنُ بِلَيْلٍ، فَكُلُوا وَاشْرَبُوا حَتَّى يُؤَذِّنَ ابْنُ أُمِّ مَكْتُومٍ»."]]},{"id":"um13_4","label":"بَابُ الأَذَانِ وَالإِقَامَةِ · ٤","segs":[["matn","وَيُسْتَحَبُّ لِمَنْ سَمِعَ الْمُؤَذِّنَ، أَنْ يَقُولَ كَمَا يَقُولُ؛ لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «إِذَا سَمِعْتُمُ النِّدَاءَ فَقُولُوا مِثْلَ مَا يَقُولُ»."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um14","title":"بَابُ شَرَائِطِ الصَّلَاةِ","units":[{"id":"um14_1","label":"بَابُ شَرَائِطِ الصَّلَاةِ · ١","segs":[["matn","وَهِيَ سِتَّةٌ: أَحَدُهَا: الطَّهَارَةُ مِنَ الْحَدَثِ؛ لِقَوْلِ رَسُوِلِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «لَا صَلَاةَ لِمَنْ أَحْدَثَ حَتَّى يَتَوَضَّأَ»."]]},{"id":"um14_2","label":"بَابُ شَرَائِطِ الصَّلَاةِ · ٢","segs":[["matn","الشَّرْطُ الثَّانِي: الْوَقْتُ، وَوَقْتُ الظُّهْرِ مِنَ زَوَالِ الشَّمْسِ إِلَى أَنْ يَصِيرَ ظِلُّ كُلِّ شَيْءٍ مِثْلَهُ، وَوَقْتُ الْعَصْرِ وَهِيَ الْوُسْطَى مِنْ آخِرِ وَقْتِ الظُّهْرِ إِلَى أَنْ تَصْفَرَّ الشَّمْسُ، ثُمَّ يَذْهَبُ وَقْتُ الِاخْتِيَارِ، وَيَبْقَى وَقْتُ الضَّرُورَةِ إِلَى غُرُوبِ الشَّمْسِ."]]},{"id":"um14_3","label":"بَابُ شَرَائِطِ الصَّلَاةِ · ٣","segs":[["matn","وَوَقْتُ الْمَغْرِبِ: إِلَى أَنْ يَغِيبَ الشَّفَقُ الأَحْمَرُ. وَوَقْتُ الْعِشَاءِ: مِنْ ذَلِكَ إِلَى نِصْفِ اللَّيْلِ، ثُمَّ يَبْقَى وَقْتُ الضَّرُورَةِ إِلَى طُلُوعِ الْفَجْرِ الثَّانِي. وَوَقْتُ الْفَجْرِ: مِنْ ذَلِكَ إِلَى طُلُوعِ الشَّمْسِ."]]},{"id":"um14_4","label":"بَابُ شَرَائِطِ الصَّلَاةِ · ٤","segs":[["matn","وَمَنْ كَبَّرَ لِلصَّلَاةِ قَبْلَ خُرُوجِ وَقْتِهَا، فَقَدْ أَدْرَكَهَا، وَالصَّلَاةُ فِي أَوَّلِ الْوَقْتِ أَفْضَلُ إِلَّا فِي الْعِشَاءِ الْآخِرَةِ، وَفِي شِدَّةِ الْحَرِّ فِي الظُّهْرِ. الشَّرْطُ الثَّالِثُ: سِتْرُ الْعَوْرَةِ بِمَا لَا يَصِفُ الْبَشَرَةَ."]]},{"id":"um14_5","label":"بَابُ شَرَائِطِ الصَّلَاةِ · ٥","segs":[["matn","وَعَوْرَةُ الرَّجُلِ وَالأَمَةِ، مَا بَيْنَ السُّرَّةِ وَالرُّكْبَةِ، وَالْحُرَّةُ كُلُّهَا عَوْرَةٌ، إِلَّا وَجْهَهَا وَكَفَّيْهَا. وَأُمُّ الْوَلَدِ وَالْمُعْتَقُ بَعْضُهَا كَالأَمَةِ. وَمَنْ صَلَّى فِي ثَوْبٍ مَغْصُوبٍ، أَوْ دَارٍ مَغْصُوبَةٍ، لَمْ تَصِحَّ صَلَاتُهُ."]]},{"id":"um14_6","label":"بَابُ شَرَائِطِ الصَّلَاةِ · ٦","segs":[["matn","وَلُبْسُ الذَّهَبِ وَالْحَرِيرِ مُبَاحٌ لِلنِّسَاءِ دُونَ الرِّجَالِ، إِلَّا عِنْدَ الْحَاجَةِ؛ لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الذَّهَبِ وَالْحَرِيرِ: «هذَانِ حَرَامٌ عَلَى ذُكُورِ أُمَّتِي، حِلٌّ لِإِنَاثِهِمْ»."]]},{"id":"um14_7","label":"بَابُ شَرَائِطِ الصَّلَاةِ · ٧","segs":[["matn","وَمَنْ صَلَّى مِنَ الرِّجَالِ فِي ثَوْبٍ وَاحِدٍ، بَعْضُهُ عَلَى عَاتِقِهِ، أَجْزَأَهُ ذَلِكَ، فَإِنْ لَمْ يَجِدْ إِلَّا مَا يَسْتُرُ عَوْرَتَهُ، سَتَرَهَا، فَإِنْ لَمْ يَكْفِ جَمِيعَهَا، سَتَرَ الْفَرْجَيْنِ، فَإِنْ لَمْ يَكْفِهِمَا، سَتَرَ أَحَدُهُمَا."]]},{"id":"um14_8","label":"بَابُ شَرَائِطِ الصَّلَاةِ · ٨","segs":[["matn","فَإِنْ عَدِمَ السِّتْرَ بِكُلِّ حَالِ، صَلَّى جَالِسًا يُومِئُ بِالرُّكُوعِ وَالسُّجُودِ، وَإِنْ صَلَّى قَائِمًا، جَازَ. وَمَنْ لَمْ يَجِدْ إِلَّا ثَوْبًا نَجِسًا، أَوْ مَكَانًا نَجِسًا، صَلَّى فِيهِمَا، وَلَا إِعَادَةَ عَلَيْهِ."]]},{"id":"um14_9","label":"بَابُ شَرَائِطِ الصَّلَاةِ · ٩","segs":[["matn","الشَّرْطُ الرَّابِعُ: الطَّهَارَةُ مِنَ النَّجَاسَةِ فِي بَدَنِهِ، وَثَوْبِهِ، وَمَوْضِعِ صَلَاتِهِ، إِلَّا النَّجَاسَةَ الْمَعْفُوَّ عَنْهَا، كَيَسِيرِ الدَّمِ وَنَحْوِهِ."]]},{"id":"um14_10","label":"بَابُ شَرَائِطِ الصَّلَاةِ · ١٠","segs":[["matn","وَإِنْ صَلَّى وَعَلَيْهِ نَجَاسَةٌ لَمْ يَكُنْ عَلِمَ بِهَا، أَوْ عَلِمَ بِهَا، ثُمَّ نَسِيَهَا، فَصَلَاتُهُ صَحِيحَةٌ. وَإِنْ عَلِمَ بِهَا فِي الصَّلَاةِ، أَزَالَهَا، وَبَنَى عَلَى صَلَاتِهِ."]]},{"id":"um14_11","label":"بَابُ شَرَائِطِ الصَّلَاةِ · ١١","segs":[["matn","وَالأَرْضُ كُلُّهَا مَسْجِدٌ تَصِحُّ الصَّلَاةُ فِيهَا، إِلَّا الْمَقْبَرَةَ، وَالْحَمَّامَ، والْحُشَّ، وَأَعْطَانَ الإِبِلِ. وَقَارِعَةَ الطَّرِيقِ."]]},{"id":"um14_12","label":"بَابُ شَرَائِطِ الصَّلَاةِ · ١٢","segs":[["matn","الشَّرْطُ الْخَامِسُ: اسْتِقْبَالُ الْقِبْلَةِ، إِلَّا فِي النَّافِلَةِ عَلَى الرَّاحِلَةِ لِلْمُسَافِرِ، فَإِنَّهُ يُصَلِّي حَيْثُ كَانَ وَجْهُهُ، وَالْعَاجِزُ عَنِ الِاسْتِقْبَالِ؛ لِخَوْفٍ، أَوْ غَيْرِهِ، فَيُصَلِّي كَيْفَمَا أَمْكَنَهُ، وَمَنْ عَدَاهُمَا، لَا تَصِحُّ صَلَاتُهُ إِلَّا مُسْتَقْبِلَ الْكَعْبَةِ."]]},{"id":"um14_13","label":"بَابُ شَرَائِطِ الصَّلَاةِ · ١٣","segs":[["matn","فَإِنْ كَانَ قَرِيبًا مِنْهَا، لَزِمَتْهُ الصَّلَاةُ إِلَى عَيْنِهَا، وَإِنْ كَانَ بَعِيدًا، فَإِلَى جِهَتِهَا. وَإِنْ خَفِيَتْ الْقِبْلَةُ فِي الْحَضَرِ، سَأَلَ وَاسْتَدَلَّ بِمَحَارِيبِ الْمُسْلِمِينَ، وَإِنْ أَخْطَأَ، فَعَلَيْهِ الإِعَادَةُ."]]},{"id":"um14_14","label":"بَابُ شَرَائِطِ الصَّلَاةِ · ١٤","segs":[["matn","وَإِنْ خَفِيَتْ فِي السَّفَرِ، اجْتَهَدَ، وَصَلَّى، وَلَا إِعَادَةَ عَلَيْهِ. وَإِنِ اخْتَلَفَ مُجْتَهِدَانِ، لَمْ يَتْبَعْ أَحَدُهُمَا صَاحِبَهُ. وَيَتْبَعُ الأَعْمَى وَالْعَامِيُّ أَوْثَقَهُمَا فِي نَفْسِهِ."]]},{"id":"um14_15","label":"بَابُ شَرَائِطِ الصَّلَاةِ · ١٥","segs":[["matn","الشَّرْطُ السَّادِسُ: النِّيَّةُ لِلصَّلَاةِ بِعَيْنِهَا، وَيَجُوزُ تَقْدِيمُهَا عَلَى التَّكْبِيرِ بِالزَّمَنِ الْيَسِيرِ، إِذَا لَمْ يَفْسَخْهَا."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um15","title":"بَابُ آدَابِ الْمَشْيِ إِلَى الصَّلَاةِ","units":[{"id":"um15_1","label":"بَابُ آدَابِ الْمَشْيِ إِلَى الصَّلَاةِ · ١","segs":[["matn","يُسْتَحَبُّ الْمَشْيُ إِلَى الصَّلَاةِ بِسَكِينَةٍ وَوَقَارٍ، وَيُقَارِبُ بَيْنَ خُطَاهُ، وَلَا يُشَبِّكُ أَصَابِعَهُ، وَيَقُولُ: بِسْمِ اللهِ ﴿الَّذِي خَلَقَنِي فَهُوَ يَهْدِينِ﴾ الآيَاتُ إِلَى قَوْلِهِ ﴿إِلَّا مَنْ أَتَى اللَّهَ بِقَلْبٍ سَلِيمٍ﴾ وَيَقُولُ:"]]},{"id":"um15_2","label":"بَابُ آدَابِ الْمَشْيِ إِلَى الصَّلَاةِ · ٢","segs":[["matn","«اللهُمَّ إِنِّي أَسْأَلُكَ بِحَقِّ السَّائِلِينَ عَلَيْكَ، وَبِحَقِّ مَمْشَايَ هَذَا، فَإِنِّي لَمْ أَخْرُجْ أَشَرًا، وَلَا بَطَرًا، وَلَا رِيَاءً، وَلَا سُمْعَةً،» خَرَجْتُ اتِّقَاءَ سَخَطِكَ، وَابْتِغَاءَ مَرْضَاتِكَ، أَسْأَلُكَ أَنْ تُنْقِذَنِي مِنَ النَّارِ، وَأَنْ تَغْفِرَ لِي ذُنُوبِي، إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ."]]},{"id":"um15_3","label":"بَابُ آدَابِ الْمَشْيِ إِلَى الصَّلَاةِ · ٣","segs":[["matn","فَإِذَا سَمِعَ الإِقَامَةَ، لَمْ يَسْعَ إِلَيْهَا؛ لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ:» إِذَا أُقِيمَتِ الصَّلَاةُ، فَلَا تَأْتُوهَا وَأَنْتُمْ تَسْعَوْنَ، وَائْتُوهَا وَعَلَيْكُمُ السَّكِينَةَ، فَمَا أَدْرَكْتُمْ، فَصَلُّوا، وَمَا فَاتَكُمْ، فَأَتِمُّوا."]]},{"id":"um15_4","label":"بَابُ آدَابِ الْمَشْيِ إِلَى الصَّلَاةِ · ٤","segs":[["matn","«وَإِذَا أُقِيمَتِ الصَّلَاةُ، فَلَا صَلَاةَ إِلَّا الْمَكْتُوبَةُ وَإِذَا أَتَى الْمَسْجِدَ، قَدَّمَ رِجْلَهُ الْيُمْنَى فِي الدُّخُولِ، وَقَالَ: بِسْمِ اللهِ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِ اللهِ،"]]},{"id":"um15_5","label":"بَابُ آدَابِ الْمَشْيِ إِلَى الصَّلَاةِ · ٥","segs":[["matn","اللهُمَّ اغْفِرْ لِي ذُنُوبِي، وَافْتَحْ لِي أَبْوَابَ رَحْمَتِكَ، وَإِذَا خَرَجَ قَدَّمَ رِجْلَهُ اليُسْرَى، وَقَالَ ذَلِكَ، إِلَّا أَنَّهُ يَقُولُ: وَافْتَحْ لِي أَبْوَابَ فَضْلِكَ.»"]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um16","title":"بَابُ صِفَةِ الصَّلَاةِ","units":[{"id":"um16_1","label":"بَابُ صِفَةِ الصَّلَاةِ · ١","segs":[["matn","وَإِذَا قَامَ إِلَى الصَّلَاةِ، قَالَ: اللهُ أَكْبَرُ، يَجْهَرُ بِهَا الإِمَامُ وَبِسَائِرِ التَّكْبِيرِ، لِيُسْمِعَ مَنْ خَلْفَهُ، وَيُخْفِيهِ غَيْرُهُ، وَيَرْفَعُ يَدَيْهِ عِنْدَ ابْتِدَاءِ التَّكْبِيرِ إِلَى حَذْوِ مَنْكِبَيْهِ، أَوْ إِلَى فُرُوعِ أُذُنَيْهِ، وَيَجْعَلُهُمَا تَحْتَ سُرَّتِهِ،"]]},{"id":"um16_2","label":"بَابُ صِفَةِ الصَّلَاةِ · ٢","segs":[["matn","وَيَجْعَلُ بَصَرَهُ إِلَى مَوْضِعِ سُجُودِهِ، ثُمَّ يَقُولُ: سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، وَتَبَارَكَ اسْمُكَ، وَتَعَالَى جَدُّكَ، وَلَا إِلهَ غَيْرُكَ، ثُمَّ يَقُولُ: أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ، ثُمَّ يَقُولُ بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ، وَلَا يَجْهَرُ بِشَيْءٍ مِنْ ذَلِكَ؛"]]},{"id":"um16_3","label":"بَابُ صِفَةِ الصَّلَاةِ · ٣","segs":[["matn","لِقَوْلِ أَنَسٍ صَلَّيْتُ خَلْفَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَبِي بَكْرٍ وَعُمَرَ وَعُثْمَانَ فَلَمْ أَسْمَعْ أَحَدًا مِنْهُمْ يَجْهَرُ بِبِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ، ثُمَّ يَقْرَأُ الْفَاتِحَةَ، وَلَا صَلَاةَ لِمَنْ لَمْ يَقْرَأْ بِهَا، إِلَّا الْمَأْمُومُ فَإِنَّ قِرَاءَةَ الإِمَامِ لَهُ قِرَاءَةٌ،"]]},{"id":"um16_4","label":"بَابُ صِفَةِ الصَّلَاةِ · ٤","segs":[["matn","وَيُسْتَحَبُّ أَنْ يَقْرَأَ فِي سَكَتَاتِ الإِمَامِ، وَفِيمَا لَا يَجْهَرُ فِيهِ، ثُمَّ يَقْرَأُ بِسُورَةٍ تَكُونُ فِي الصُّبْحِ مِنْ طِوَالِ الْمُفَصَّلِ،"]]},{"id":"um16_5","label":"بَابُ صِفَةِ الصَّلَاةِ · ٥","segs":[["matn","وَفِي الْمَغْرِبِ مِنْ قِصَارِهِ، وَفِي سَائِرِ الصَّلَوَاتِ مِنْ أَوْسَطِهِ وَيَجْهَرُ الإِمَامُ بِالْقِرَاءَةِ فِي الصُّبْحِ وَالأُولَيَيْنِ مِنَ الْمَغْرِبِ وَالْعِشَاءِ، وَيُسِرُّ فِيمَا عَدَا ذَلِكَ."]]},{"id":"um16_6","label":"بَابُ صِفَةِ الصَّلَاةِ · ٦","segs":[["matn","ثُمَّ يُكَبِّرُ وَيَرْكَعُ، وَيَرْفَعُ يَدَيْهِ كَرَفْعِهِ الأَوَّلِ، ثُمَّ يَضَعُ يَدَيْهِ عَلَى رُكْبَتَيْهِ وَيُفَرِّجُ أَصَابِعَهُ، وَيَمُدُّ ظَهْرَهُ، وَيَجْعَلُ رَأْسَهُ حِيَالَهُ، ثُمَّ يَقُولُ: سُبْحَانَ رَبِّيَ الْعَظِيمِ، ثَلَاثًا، ثُمَّ يَرْفَعُ رَأْسَهُ قَائِلاً:"]]},{"id":"um16_7","label":"بَابُ صِفَةِ الصَّلَاةِ · ٧","segs":[["matn","سَمِعَ اللهُ لِمَنْ حَمِدَهُ، وَيَرْفَعُ يَدَيْهِ كَرَفْعِهِ الأَوَّلِ، فَإِذَا اعْتَدَلَ قَائِمًا، قَالَ: رَبَّنَا وَلَكَ الْحَمْدُ، مِلْءَ السَّمَاوَاتِ وَمِلْءَ الأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ وَيَقْتَصِرُ الْمَأْمُومُ عَلَى قَوْلِ: رَبَّنَا وَلَكَ الْحَمْدُ."]]},{"id":"um16_8","label":"بَابُ صِفَةِ الصَّلَاةِ · ٨","segs":[["matn","ثُمَّ يَخِرُّ سَاجِدًا مُكَبِّرًا وَلَا يَرْفَعُ يَدَيْهِ، وَيَكُونُ أَوَّلَ مَا يَقَعُ مِنْهُ عَلَى الأَرْضِ رُكْبَتَاهُ، ثَمَّ كَفَّاهُ، ثُمَّ جَبْهَتُهُ وَأَنْفُهُ، وَيُجَافِي عَضُدَيْهِ عَنْ جَنْبَيْهِ، وَبَطْنَهُ عَنْ فَخِذَيْهِ، وَيَجْعَلُ يَدَيْهِ حَذْوَ مَنْكِبَيْهِ."]]},{"id":"um16_9","label":"بَابُ صِفَةِ الصَّلَاةِ · ٩","segs":[["matn","وَيَكُونُ عَلَى أَطْرَافِ قَدَمَيْهِ، ثُمَّ يَقُولُ: سُبْحَانَ رَبِّيَ الأَعْلَى، ثَلَاثًا، ثُمَّ يَرْفَعُ رَأْسَهُ مُكَبِّرًا، وَيَجْلِسُ مُفْتَرِشًا، فَيَفْرِشُ رِجْلَهُ الْيُسْرَى وَيَجْلِسُ عَلَيْهَا،"]]},{"id":"um16_10","label":"بَابُ صِفَةِ الصَّلَاةِ · ١٠","segs":[["matn","وَينْصِبُ الْيُمْنَى وَيَثْنِي أَصَابِعَهَا نَحْوَ القِبْلَةِ، وَيَقُولُ: رَبِّي اغْفِرْ لِي، ثَلَاثًا، ثُمَّ يَسْجُدُ الثَّانِيَةَ كَالأُولَى، ثُمَّ يَرْفَعُ رَأْسَهُ مُكَبِّرًا، وَيَنْهَضُ قَائِمًا، فَيُصَلِّي الثَّانِيَةَ كَالأُولَى."]]},{"id":"um16_11","label":"بَابُ صِفَةِ الصَّلَاةِ · ١١","segs":[["matn","فَإِذَا فَرَغَ مِنْهُمَا جَلَسَ لِلتَّشَهُّدِ مُفْتَرِشًا، وَيَضَعُ يَدَهُ الْيُسْرَى عَلَى فَخِذِهِ الْيُسْرَى، وَيَدَهُ الْيُمْنَى عَلَى فَخِذِهِ اليُمْنَى، يَقْبِضُ مِنْهَا الْخِنْصِرَ وَالْبِنْصِرَ، وَيُحَلِّقُ الإِبْهَامَ مَعَ الْوُسْطَى وَيُشِيرُ بِالسَّبَابَةِ، فِي تَشَهُّدِهِ مِرَارًا، وَيَقُولُ:"]]},{"id":"um16_12","label":"بَابُ صِفَةِ الصَّلَاةِ · ١٢","segs":[["matn","«التَّحِيَّاتُ لِلَّهِ، وَالصَّلَوَاتُ، وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللهِ، وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلهَ إِلَّا اللهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ،» فَهَذَا أَصَحُّ مَا رُوِيَ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي التَّشَهُّدِ،"]]},{"id":"um16_13","label":"بَابُ صِفَةِ الصَّلَاةِ · ١٣","segs":[["matn","ثُمَّ يَقُولُ: اللهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَآلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ، وَبَارِكْ عَلَى مُحَمَّدٍ، وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ."]]},{"id":"um16_14","label":"بَابُ صِفَةِ الصَّلَاةِ · ١٤","segs":[["matn","وَيُسْتَحَبُّ أَنْ يَتَعَوَّذَ مِنْ عَذَابِ جَهَنَّمَ، وَمِنْ عَذَابِ الْقَبْرِ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَمِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ، ثُمَّ يُسَلِّمُ عَنْ يَمِينِهِ: السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللهِ، وَعَنْ يَسَارِهِ كَذَلِكَ."]]},{"id":"um16_15","label":"بَابُ صِفَةِ الصَّلَاةِ · ١٥","segs":[["matn","وَإِنْ كَانَتِ الصَّلَاةُ أَكْثَرَ مِنْ رَكْعَتَيْنِ، نَهَضَ بَعْدَ التَّشَهُّدِ الأَوَّلِ، كَنُهُوضِهِ مِنَ السُّجُودِ، ثُمَّ يُصَلِّي رَكْعَتَيْنِ لَا يَقْرَأُ فِيهِمَا بَعْدَ الْفَاتِحَةِ شَيْئًا، فَإِذَا جَلَسَ لِلتَّشَهُّدِ الأَخِيرِ، تَوَرَّكَ؛ فَنَصَبَ رِجْلَهُ الْيُمْنَى وَفَرَشَ الْيُسْرَى، وَأَخْرَجَهَا عَنْ يَمِينِهِ."]]},{"id":"um16_16","label":"بَابُ صِفَةِ الصَّلَاةِ · ١٦","segs":[["matn","وَلَا يَتَوَرَّكُ إِلَّا فِي صَلَاةٍ فِيهَا تَشَهُّدَانِ، فِي الأَخِيرِ مِنْهُمَا، فَإِذَا سَلَّمَ اسْتَغْفَرَ ثَلَاثًا، وَقَالَ: اللهُمَّ أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ، تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالإِكْرَامِ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um17","title":"بَابُ أَرْكَانِ الصَّلَاةِ وَوَاجِبَاتِهَا","units":[{"id":"um17_1","label":"بَابُ أَرْكَانِ الصَّلَاةِ وَوَاجِبَاتِهَا · ١","segs":[["matn","أَرْكَانُهَا اثْنَا عَشَرَ: الْقِيَامُ، مَعَ الْقُدْرَةِ وَتَكْبِيرَةُ الإِحْرَامِ، وَقِرَاءَةُ الْفَاتِحَةِ، والرُّكُوعُ، وَالرَّفْعُ مِنْهُ، وَالسُّجُودُ، عَلَى السَّبْعَةِ الْأَعْضَاءِ وَالْجُلُوسُ عَنْهُ، وَالطُّمَأْنِينَةُ فِي هَذِهِ الأَرْكَانِ، وَالتَّشَهُّدُ الأَخِيرُ، وَالْجُلُوسُ لَهُ، وَالتَّسْلِيمَةُ الأُولَى، وَتَرْتِيبُهَا عَلَى مَا ذَكَرْنَاهُ."]]},{"id":"um17_2","label":"بَابُ أَرْكَانِ الصَّلَاةِ وَوَاجِبَاتِهَا · ٢","segs":[["matn","فَهَذِهِ الأَرْكَانُ لَا تَتِمُّ الصَّلَاةُ إِلَّا بِهَا. وَوَاجِبَاتُهَا سَبْعَةٌ: التَّكْبِيرُ غَيْرَ تَكْبِيرَةِ الإِحْرَامِ، وَالتَّسْبِيحُ فِي الرُّكُوعِ وَالسُّجُودِ مَرَّةً مَرَّةً، وَالتَّسْمِيعُ وَالتَّحْمِيدُ فِي الرَّفْعِ مِنَ الرُّكُوعِ، وَقَوْلُ: رَبِّي اغْفِرْ لِي بَيْنَ السَّجْدَتَيْنِ وَالتَّشَهُّدُ الأَوَّلُ، وَالْجُلُوسُ لَهُ،"]]},{"id":"um17_3","label":"بَابُ أَرْكَانِ الصَّلَاةِ وَوَاجِبَاتِهَا · ٣","segs":[["matn","وَالصَّلَاةُ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي التَّشَهُّدِ الأَخِيرِ فَهَذِهِ إِنْ تَرَكَهَا عَمْدًا، بَطَلَتْ صَلَاتُهُ، وَإِنْ تَرَكَهَا سَهْوًا، سَجَدَ لَهَا، وَمَا عَدَا هَذَا، فَسُنَنٌ، لَا تَبْطُلُ الصَّلَاةُ بِعَمْدِهَا وَلَا يَجِبُ السُّجُودُ لِسَهْوِهَا."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um18","title":"بَابُ سُجُودِ السَّهْوِ","units":[{"id":"um18_1","label":"بَابُ سُجُودِ السَّهْوِ · ١","segs":[["matn","وَالسَّهْوُ عَلَى ثَلَاثَةِ أَضْرُبٍ: أَحَدُهَا: زِيَادَةُ فِعْلٍ مِنْ جِنْسِ الصَّلَاةِ كَرَكْعَةٍ، أَوْ رُكْنٍ، فَتَبْطُلُ الصَّلَاةُ بِعَمْدِهِ، وَيَسْجُدُ لِسَهْوِهِ."]]},{"id":"um18_2","label":"بَابُ سُجُودِ السَّهْوِ · ٢","segs":[["matn","وَإِنْ ذَكَرَ وَهُوَ فِي الرَّكْعَةِ الزَّائِدَةِ، جَلَسَ فِي الْحَالِ، وَإِنْ سَلَّمَ عَنْ نَقْصٍ فِي صَلَاتِهِ، أَتَى بِمَا بَقِيَ عَلَيْهِ مِنْهَا، ثُمَّ سَجَدَ."]]},{"id":"um18_3","label":"بَابُ سُجُودِ السَّهْوِ · ٣","segs":[["matn","وَلَوْ فَعَلَ مَا لَيْسَ مِنْ جِنْسِ الصَّلَاةِ، لَاسْتَوَى عَمْدُهُ وَسَهْوُهُ، فَإِنْ كَانَ كَثِيرًا، أَبْطَلَهَا، وَإِنْ كَانَ يَسِيرًا، كَفِعْلِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي حَمْلِهِ أُمَامَةَ، وَفَتْحِهِ الْبَابِ لِعَائِشَةَ، فَلَا بَأْسَ."]]},{"id":"um18_4","label":"بَابُ سُجُودِ السَّهْوِ · ٤","segs":[["matn","الضَّرْبُ الثَّانِي: النَّقْصُ، كَنِسْيَانِ وَاجِبٍ، فَإِنْ قَامَ عَنِ التَّشّهُّدِ الأَوَّلِ، فَذَكَرَ قَبْلَ أَنْ يَسْتَتِمَّ قَائِمًا، رَجَعَ، فَأَتَى بِهِ، وَإِنِ اسْتَتَمَّ قَائِمًا، لَمْ يَرْجِعْ، وَإِنْ نَسِيَ رُكْنًا، فَذَكَرَهُ قَبْلَ شُرُوعِهِ فِي قِرَاءَةِ رَكْعَةٍ أُخْرَى،"]]},{"id":"um18_5","label":"بَابُ سُجُودِ السَّهْوِ · ٥","segs":[["matn","رَجَعَ، فَأَتَى بِهِ وَبِمَا بَعْدَهُ، وَإِنْ ذَكَرَهُ بَعْدَ ذَلِكَ، بَطَلَتِ الرَّكْعَةُ الَّتِي تَرَكَهُ مِنْهَا وَإِنْ نَسِيَ أَرْبَعَ سَجَدَاتٍ مِنْ أَرْبَعِ رَكَعَاتٍ، فَذَكَرَ فِي التَّشَهُّدِ، سَجَدَ فِي الْحَالِ، فَصَحَّتْ لَهُ رَّكْعَةُ، ثُمَّ يَأْتِي بِثَلَاثِ رَكَعَاتٍ."]]},{"id":"um18_6","label":"بَابُ سُجُودِ السَّهْوِ · ٦","segs":[["matn","الضَّرْبُ الثَّالِثُ: الشَّكُّ، فَمَتَى شَكَّ فِي تَرْكِ رُكْنٍ، فَهُوَ كَتَرْكِهِ، وَمَنْ شَكَّ فِي عَدَدِ الرَّكَعَاتِ، بَنَى عَلَى الْيَقِينِ، إِلَّا الإِمَامَ خَاصَّةً، فَإِنَّهُ يَبْنِي عَلَى غَالِبِ ظَنِّهِ."]]},{"id":"um18_7","label":"بَابُ سُجُودِ السَّهْوِ · ٧","segs":[["matn","وَلِكُلِّ سَهْوٍ سَجْدَتَانِ قَبْلَ السَّلَامِ إِلَّا مَنْ سَلَّمَ عَنْ نَقْصٍ فِي صَلَاتِهِ وَالإِمَامُ إِذَا بَنَى عَلَى غَالِبِ ظَنِّهِ، وَالنَّاسِي لِلسُّجُودِ قَبْلَ السَّلَامِ، فَإِنَّهُ يَسْجُدُ سَجْدَتَيْنِ بَعْدَ سَلَامِهِ، ثُمَّ يَتَشَهَّدُ وَيُسَلِّمُ."]]},{"id":"um18_8","label":"بَابُ سُجُودِ السَّهْوِ · ٨","segs":[["matn","وَلَيْسَ عَلَى الْمَأْمُومِ سُجُودُ سَهْوٍ، إِلَّا أَنْ يَسْهُوَ إِمَامُهُ، فَيَسْجُدُ مَعَهُ. وَمَنْ سَهَا إِمَامُهُ، أَوْ نَابَهُ أَمْرٌ فِي صَلَاتِهِ، فَالتَّسْبِيحُ لِلرِّجَالِ، وَالتَّصْفِيقُ لِلنِّسَاءِ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um19","title":"بَابُ صَلَاةِ التَّطَوُّعِ","units":[{"id":"um19_1","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ١","segs":[["matn","وَهِيَ عَلَى خَمْسَةِ أَضْرُبٍ: أَحَدُهَا: السُّنَنُ الرَّوَاتِبُ وَهِيَ الَّتِي قَالَ ابْنُ عُمَرَ: رَضِيَ اللهُ عَنْهُ عَشْرُ رَكَعَاتٍ، حَفِظْتُهُنَّ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: رَكْعَتَيْنِ قَبْلَ الظُّهْرِ، وَرَكْعَتَيْنِ بَعْدَهَا،"]]},{"id":"um19_2","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ٢","segs":[["matn","وَرَكْعَتَيْنِ بَعْدَ الْمَغْرِبِ فِي بَيْتِهِ، وَرَكْعَتَيْنِ بَعْدَ الْعِشَاءِ فِي بَيْتِهِ، وَرَكْعَتَيْنِ قَبْلَ الْفَجْرِ، حَدَّثَتْنِي حَفْصَةُ أَنْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا طَلَعَ الْفَجْرُ وَأَذَّنَ الْمُؤَذِّنُ، صَلَّى رَكْعَتَيْنِ، وَهُمَا آكَدُهَا."]]},{"id":"um19_3","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ٣","segs":[["matn","وَيَسْتَحَبُّ تَخْفِيفُهُمَا، وَفِعْلُهُمَا فِي الْبَيْتِ أَفْضَلُ، وَكَذَلِكَ رَكْعَتَا الْمَغْرِبِ."]]},{"id":"um19_4","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ٤","segs":[["matn","الضَّرْبُ الثَّانِي: الْوِتْرُ، وَوَقْتُهُ: مَا بَيْنَ الْعِشَاءِ وَالْفَجْرِ، وَأَقَلُّهُ: رَكْعَةٌ، وَأَكْثَرُهُ إِحْدَى عَشْرَةَ وَأَدْنَى الكَمَالِ: ثَلَاثٌ بِتَسْلِيمَتَيْنِ، وَيَقْنُتُ فِي الثَّالِثَةِ بَعْدَ الرُّكُوعِ."]]},{"id":"um19_5","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ٥","segs":[["matn","الضَّرْبُ الثَّالِثُ: التَّطَوُّعُ الْمُطْلَقُ، وَتَطَوُّعُ اللَّيْلِ أَفْضَلُ مِنْ تَطَوُّعِ النَّهَارِ، وَالنِّصْفُ الأَخِيرُ أَفْضَلُ مِنَ الأَوَّلِ، وَصَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى، وَصَلَاةُ الْقَاعِدِ عَلَى النِّصْفِ مِنْ صَلَاةِ الْقَائِمِ."]]},{"id":"um19_6","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ٦","segs":[["matn","الضَّرْبُ الرَّابِعُ: مَا تُسَنُّ لَهُ الْجَمَاعَةُ، وَهُوَ ثَلَاثَةُ أَنْوَاعٍ: أَحَدُهَا: التَّرَاوِيحُ، وَهِيَ: عِشْرُونَ رَكْعَةً بَعْدَ الْعِشَاءِ فِي رَمَضَانَ. وَالثَّانِي: صَلَاةُ الْكُسُوفِ، فَإِذَا كُسِفَتِ الشَّمْسُ، أَوِ الْقَمَرُ، فَزِعَ النَّاسُ إِلَى الصَّلَاةِ."]]},{"id":"um19_7","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ٧","segs":[["matn","إِنْ أَحَبُّوا جَمَاعَةً، وَإِنْ أَحَبُّوا فُرَادَى فَيُكَبِّرُ، وَيَقْرَأُ الْفَاتِحَةَ وَسُورَةً طَوِيلَةً، ثُمَّ يَرْكَعْ رُكُوعَا طَوِيلاً، ثُمَّ يَرْفَعُ فَيَقْرَأُ الْفَاتِحَةَ وَسُورَةً طَوِيلَةً دُونَ الَّتِي قَبْلَهَا،"]]},{"id":"um19_8","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ٨","segs":[["matn","ثُمَّ يَرْكَعُ فَيُطِيلُ دُونَ الَّذِي قَبْلَهُ، ثُمَّ يَرْفَعُ، ثُمَّ يَسْجُدُ سَجْدَتَيْنِ طَوِيلَتَيْنِ، ثُمَّ يَقُومُ فَيَفْعَلُ مِثْلَ ذَلِكَ، فَتَكُونُ أَرْبَعَ رَكَعَاتٍ وَأَرْبَعَ سَجَدَاتٍ."]]},{"id":"um19_9","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ٩","segs":[["matn","الثَّالِثُ: صَلَاةُ الِاسْتِسْقَاءِ، إِذَا أَجْدَبَتِ الأَرْضُ، وَاحْتَبَسَ الْقَطْرُ، خَرَجَ النَّاسُ مَعَ الإِمَامِ مُتَخَشِّعِينَ، مُتَبَذِّلِينَ، مُتَذَلِّلِينَ، مُتَضَرِّعِينَ، فَيُصَلِّي بِهِمْ رَكْعَتَيْنِ، كَصَلَاةِ العَيْدِ، ثُمَّ يَخْطُبُ بِهِمْ خُطْبَةً وَاحِدَةً،"]]},{"id":"um19_10","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ١٠","segs":[["matn","وَيُكْثِرُ فِيهَا مِنَ الِاسْتِغْفَارِ وَتِلَاوَةِ الآيَاتِ الَّتِي فِيهَا الأَمْرُ بِهِ، وَيُحَوِّلُ النَّاسُ أَرْدِيَتَهُمْ، وَإِنْ خَرَجَ مَعَهُمْ أَهْلُ الذِّمَّةِ لَمْ يُمْنَعُوا وَيُؤْمَرُوا أَنْ يَنْفَرِدُوا عَنِ الْمُسْلِمِينَ."]]},{"id":"um19_11","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ١١","segs":[["matn","الضَّرْبُ الْخَامِسُ: سُجُودُ التِّلَاوَةِ، وَهِيَ أَرْبَعَ عَشْرَةَ سَجْدَةً، فِي الْحَجِّ مِنْهَا اثْنَتَانِ، وَيُسَنُّ السُّجُودُ لِلتَّالِي، وَالْمُسْتَمِعِ دُونَ السَّامِعِ. وَيُكَبِّرُ إِذَا سَجَدَ، وَإِذَا رَفَعَ، رَأْسَهُ ثُمَّ يُسَلِّمُ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um20","title":"بَابُ السَّاعَاتِ الَّتِي نُهِيَ عَنِ الصَّلَاةِ فِيهَا","units":[{"id":"um20_1","label":"بَابُ السَّاعَاتِ الَّتِي نُهِيَ عَنِ الصَّلَاةِ فِيهَا · ١","segs":[["matn","وَهِيَ خَمْسٌ: بَعْدَ الْفَجْرِ حَتَّى تَطْلُعَ الشَّمْسُ، وَبَعْدَ طُلُوعِهَا حَتَّى تَرْتَفِعَ قِيدَ رُمْحٍ، وَعِنْدَ قِيَامِهَا حَتَّى تَزُولُ، وَبَعْدَ الْعَصْرِ حَتَّى تَتَضَيَّفَ الشَّمْسُ لِلْغُرُوبِ، وَإِذَا تَضَيَّفَتْ حَتَّى تَغْرُبَ."]]},{"id":"um20_2","label":"بَابُ السَّاعَاتِ الَّتِي نُهِيَ عَنِ الصَّلَاةِ فِيهَا · ٢","segs":[["matn","فَهذِهِ السَّاعَاتُ الَّتِي لَا يُصَلَّى فِيهَا تَطَوُّعًا، إِلَّا فِي إِعَادَةِ الْجَمَاعَةِ إِذَا أُقِيمَتْ وَهُوَ فِي الْمَسْجِدِ، وَرَكْعَتَيْ الطَّوَافِ بَعْدَهُ، وَالصَّلَاةَ عَلَى الْجَنَازَةِ، وَقَضَاءَ السُّنَنِ الرَّوَاتِبِ فِي وَقْتَيْنِ مِنْهَا، وَهُمَا: بَعْدَ الْفَجْرِ، وَبَعْدَ الْعَصْرِ، وَيَجُوزُ قَضَاءُ الْمَفْرُوضَاتِ فِي جَمِيعِ الأَوْقَاتِ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um21","title":"بَابُ الإِمَامَةِ","units":[{"id":"um21_1","label":"بَابُ الإِمَامَةِ · ١","segs":[["matn","رَوَى أَبُو مَسْعُودٍ الْبَدْرِيُّ، رَضِيَ اللهُ عَنْهُ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ:"]]},{"id":"um21_2","label":"بَابُ الإِمَامَةِ · ٢","segs":[["matn","«يَؤُمُّ الْقَوْمَ أَقْرَؤُهُمْ لِكِتَابِ اللهِ فَإِنْ كَانُوا فِي الْقِرَاءَةِ سَوَاءً، فَأَعْلَمُهُمْ بِالسُّنَّةِ، فَإِنْ كَانُوا فِي السُّنَّةِ سَوَاءً، فَأَقْدَمُهُمْ هِجْرَةً، فَإِنَ كَانُوا فِي الْهِجْرَةِ سَوَاءً، فَلْيَؤُمَّهُمْ أَكْبَرُهُمْ سِنًّا وَلَا» يَؤُمَّنَّ الرَّجُلُ الرَّجُلَ فِي بَيْتِهِ،"]]},{"id":"um21_3","label":"بَابُ الإِمَامَةِ · ٣","segs":[["matn","وَلَا فِي سُلْطَانِهِ، وَلَا يُجْلَسُ عَلَى تَكْرِمَتِهِ إِلَّا بِإِذْنِهِ، «وَقَالَ لِمَالِكِ بْنِ الْحُوَيْرِثِ وَصَاحِبِهِ:» إِذَا حَضَرَتِ الصَّلَاةُ، فَلْيُؤَذِّنْ أَحَدُكُمَا، وَليَؤُمُّكُمَا أَكْبَرُكُمَا. «وَكَانَتْ قِرَاءَتُهُمَا مُتَقَارِبَةً.»"]]},{"id":"um21_4","label":"بَابُ الإِمَامَةِ · ٤","segs":[["matn","وَلَا تَصِحُّ الصَّلَاةُ خَلْفَ مَنْ صَلَاتُهُ فَاسِدَةٌ، إِلَّا لِمَنْ لَمْ يَعْلَمْ بِحَدَثِ نَفْسِهِ، وَلَمْ يَعْلَمْهُ الْمَأْمُومُ حَتَّى سَلَّمَ، فَإِنَّهُ يُعِيدُ وَحْدَهُ، وَلَا تَصِحُّ خَلْفَ تَارِكِ رُكْنٍ، إِلَّا إِمَامَ الْحَيِّ، إِذَا صَلَّى جَالِسًا؛"]]},{"id":"um21_5","label":"بَابُ الإِمَامَةِ · ٥","segs":[["matn","لِمَرَضٍ يُرْجَى بُرْؤُهُ، فَإِنَّهُمْ يُصَلُّونَ وَرَاءَهُ جُلُوسًا، إِلَّا أَنْ يَبْتَدِئَهَا قَائِمًا، ثُمَّ يَعْتَلُّ، فَيَجْلِسُ، فَإِنَّهُمْ يَأْتَمُّونَ وَرَاءَهُ قِيَامًا."]]},{"id":"um21_6","label":"بَابُ الإِمَامَةِ · ٦","segs":[["matn","وَلَا تَصِحُّ إِمَامَةُ الْمَرْأَةِ، بِالرِّجَالِ، وَمَنْ بِهِ سَلَسُ الْبَوْلِ، وَالأُمِّيِّ الَّذِي لَا يُحْسِنُ الْفَاتِحَةَ، أَوْ يُخِلَّ بِحَرْفٍ مِنْهَا، إِلَّا بِمِثْلِهِمْ. وَيَجُوزُ ائْتِمَامُ الْمُتَوَضِّئِ بِالْمُتَيَمِّمِ، وَالْمُفْتَرِضِ بِالْمُتَنَفِّلِ."]]},{"id":"um21_7","label":"بَابُ الإِمَامَةِ · ٧","segs":[["matn","وَإِذَا كَانَ الْمَأْمُومُ وَاحِدًا، وَقَفَ عَنْ يَمِينِ الإِمَامِ، فَإِنْ وَقَفَ عَنْ يَسَارِهِ، أَوْ قُدَّامَهُ أَوْ وَحْدَهُ، لَمْ تَصِحَّ إِلَّا أَنْ تَكُونَ امْرَأَةً، فَتَقِفُ وَحْدَهَا خَلْفَهُ، وَإِنْ كَانُوا جَمَاعَةً، وَقَفُوا خَلْفَهُ،"]]},{"id":"um21_8","label":"بَابُ الإِمَامَةِ · ٨","segs":[["matn","فَإِنْ وَقَفُوا عَنْ يَمِينِهِ، أَوْ عَنْ جَانِبَيْهِ، صَحَّ، فَإِنْ وَقَفُوا قُدَّامَهُ، أَوْ عَنْ يَسَارِهِ، لَمْ تَصِحَّ وَإِنْ صَلَّتْ امْرَأَةٌ بِنِسَاءٍ قَامَتْ مَعَهُنَّ فِي الصَّفِّ وَسَطَهُنَّ وَكَذَلِكَ إِمَامُ الرِّجَالِ الْعُرَاةِ يَقُومُ وَسْطَهُمْ."]]},{"id":"um21_9","label":"بَابُ الإِمَامَةِ · ٩","segs":[["matn","وَإِنِ اجْتَمَعَ رِجَالٌ وَصِبْيَانُ، وَخَنَاثَى وَنِسَاءٌ، قُدِّمَ الرِّجَالُ، ثُمَّ الصِّبْيَانُ، ثُمَّ الْخُنَاثَى، ثُمَّ النِّسَاءُ. وَمَنْ كَبَّرَ قَبْلَ سَلَامِ الإِمَامِ، فَقَدْ أَدْرَكَ الْجَمَاعَةَ، وَمَنْ أَدْرَكَ الرُّكُوعَ، فَقَدْ أَدْرَكَ الرَّكْعَةَ، وَإِلَّا فَلَا."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um22","title":"بَابُ صَلَاةِ الْمَرِيضِ","units":[{"id":"um22_1","label":"بَابُ صَلَاةِ الْمَرِيضِ · ١","segs":[["matn","وَالْمَرِيضُ إِذَا كَانَ الْقِيَامُ يَزِيدُ فِي مَرَضِهِ، صَلَّى جَالِسًا، فَإِنْ لَمْ يُطِقْ، فَعَلَى جَنْبِهِ؛"]]},{"id":"um22_2","label":"بَابُ صَلَاةِ الْمَرِيضِ · ٢","segs":[["matn","لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِعِمْرَانَ بْنِ حُصَيْنٍ: «صَلِّ قَائِمًا، فَإِنْ لَمْ تَسْتَطِعْ، فَقَاعِدًا، فَإِنْ لَمْ تَسْتَطِعْ، فَعَلَى جَنْبِكَ» فَإِنْ شَقَّ عَلَيْهِ، فَعَلَى ظَهْرِهِ، فَإِنْ عَجَزَ عَنِ الرُّكُوعِ وَالسُّجُودِ، أَوْمَأَ إِيمَاءً."]]},{"id":"um22_3","label":"بَابُ صَلَاةِ الْمَرِيضِ · ٣","segs":[["matn","وَعَلَيْهِ قَضَاءُ مَا فَاتَهُ مِنَ الصَّلَوَاتِ فِي إِغْمَائِهِ، وَإِنْ شَقَّ عَلَيْهِ فِعْلُ كُلِّ صَلَاةٍ فِي وَقْتِهَا، فَلَهُ الْجَمْعُ بَيْنَ الظُّهْرِ وَالْعَصْرِ، وَبَيْنَ الْعِشَاءَيْنِ فِي وَقْتِ إِحْدَاهُمَا."]]},{"id":"um22_4","label":"بَابُ صَلَاةِ الْمَرِيضِ · ٤","segs":[["matn","فَإِنْ جَمَعَ فِي وَقْتِ الأُولَى، اشْتُرِطَ نِيَّةُ الْجَمْعِ عِنْدَ فِعْلِهَا، وَيُعْتَبَرُ اسْتِمْرَارُ الْعُذْرِ حَتَّى يَشْرَعَ فِي الثَّانِيَةِ مِنْهُمَا، وَلَا يُفَرِّقَ بَيْنَهُمَا، إِلَّا بِقَدْرِ الْوُضُوءِ."]]},{"id":"um22_5","label":"بَابُ صَلَاةِ الْمَرِيضِ · ٥","segs":[["matn","وَإِنْ أَخَّرَ، اعْتُبِرَ اسْتِمْرَارُ الْعُذْرِ إِلَى دُخُولِ وَقْتِ الثَّانِيَةِ وَأَنْ يَنْوِيَ الْجَمْعَ فِي وَقْتِ الأُولَى، قَبْلَ أَنْ يَضِيقَ عَنْ فِعْلِهَا، وَيَجُوزُ الْجَمْعُ لِلْمُسَافِرِ الَّذِي لَهُ الْقَصْرُ، وَيَجُوزُ فِي الْمَطَرِ بَيْنَ الْعِشَاءَيْنِ"]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um23","title":"بَابُ صَلَاةِ الْمُسَافِرِ","units":[{"id":"um23_1","label":"بَابُ صَلَاةِ الْمُسَافِرِ · ١","segs":[["matn","وَإِذَا كَانَتْ مَسَافَةُ سَفَرِهِ سِتَّةَ عَشَرَ فَرْسَخًا، وَهِيَ مَسِيرَةُ يَوْمَيْنِ قَاصِدَيْنِ، وَكَانَ مُبَاحًا، فَلَهُ قَصْرُ الرُّبَاعِيَّةِ خَاصَّةً."]]},{"id":"um23_2","label":"بَابُ صَلَاةِ الْمُسَافِرِ · ٢","segs":[["matn","إِلَّا أَنْ يَأْتَمَّ بِمُقِيمٍ، أَوْ لَمْ يَنْوِ الْقَصْرَ، أَوْ نَسِيَ صَلَاةَ حَضَرٍ، فَيَذْكُرَهَا فِي السَّفَرِ، أَوْ صَلَاةَ سَفَرٍ، فَيَذْكُرَهَا فِي الْحَضَرِ، فَعَلَيْهِ الإِتْمَامُ."]]},{"id":"um23_3","label":"بَابُ صَلَاةِ الْمُسَافِرِ · ٣","segs":[["matn","وَلِلْمُسَافِرِ أَنْ يُتِمَّ، وَالْقَصْرُ أَفْضَلُ وَمَنْ نَوَى الإِقَامَةَ أَكْثَرَ مِنْ إِحْدَى وَعِشْرِينَ صَلَاةً، أَتَمَّ، وَإِنْ لَمْ يُجْمِعْ عَلَى ذَلِكَ، قَصَرَ أَبَدًا."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um24","title":"بَابُ صَلَاةِ الْخَوْفِ","units":[{"id":"um24_1","label":"بَابُ صَلَاةِ الْخَوْفِ · ١","segs":[["matn","وَتَجُوزُ صَلَاةُ الْخَوْفِ، عَلَى كُلِّ صِفَةٍ صَلَّاهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ."]]},{"id":"um24_2","label":"بَابُ صَلَاةِ الْخَوْفِ · ٢","segs":[["matn","وَالْمُخْتَارُ مِنْهَا: أَنْ يَجْعَلَهُمُ الإِمَامُ طَائِفَتَيْنِ، طَائِفَةً تَحْرُسُ، وَالأُخْرَى تُصَلِّي مَعَهُ رَكْعَةً، فَإِذَا قَامَ إِلَى الثَّانِيَةِ، نَوَتْ مُفَارَقَتَهُ وَأَتَمَّتْ صَلَاتَهَا، وَذَهَبَتْ تَحْرُسُ، وَجَاءَتِ الأُخْرَى،"]]},{"id":"um24_3","label":"بَابُ صَلَاةِ الْخَوْفِ · ٣","segs":[["matn","فَصَلَّتْ مَعَهُ الرَّكْعَةَ الثَّانِيَةَ، فَإِذَا جَلَسَ لِلتَّشَهُّدِ، قَامَتْ فَأَتَتْ بِرَكْعَةٍ أُخْرَى، وَيَنْتَظِرُ حَتَّى تَتَشَهَّدَ، ثُمَّ يُسَلِّمُ بِهَا، وَإِنِ اشْتَدَّ الْخَوْفُ صَلَّوْا رِجَالاً وَرُكْبَانًا إِلَى الْقِبْلَةِ، وَإِلَى غَيْرِهَا."]]},{"id":"um24_4","label":"بَابُ صَلَاةِ الْخَوْفِ · ٤","segs":[["matn","يُومِئُونَ بِالرُّكُوعِ وَالسُّجُودِ، وَكَذَلِكَ كُلُّ خَائِفٍ عَلَى نَفْسِهِ، يُصَلِّي عَلَى حَسَبِ حَالِهِ، وَيَفْعَلُ كُلَّ مَا يَحْتَاجُ إِلَى فِعْلِهِ، مِنْ هَرَبٍ، أَوْ غَيْرِهِ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um25","title":"بَابُ صَلَاةِ الْجُمُعَةِ","units":[{"id":"um25_1","label":"بَابُ صَلَاةِ الْجُمُعَةِ · ١","segs":[["matn","كُلُّ مَنْ لَزِمَتْهُ الْمَكْتُوبَةُ لَزِمَتْهُ الْجُمُعَةُ، إِنْ كَانَ مُسْتَوْطِنًا بِبِنَاءٍ، وَبَيْنَهُ وَبَيْنَ الْجَامِعِ فَرْسَخٌ فَمَا دُونَ ذَلِكَ إِلَّا الْمَرْأَةَ، وَالْعَبْدَ،"]]},{"id":"um25_2","label":"بَابُ صَلَاةِ الْجُمُعَةِ · ٢","segs":[["matn","وَالْمُسَافِرَ، وَالْمَعْذُورَ بِمَرَضٍ، أَوْ مَطَرٍ، أَوْ خَوْفٍ، وَإِنْ حَضَرُوهَا أَجْزَأَتْهُمْ، وَلَمْ تَنْعَقِدْ بِهِمْ، إِلَّا الْمَعْذُورَ إِذَا حَضَرَهَا، وَجَبَتْ عَلَيْهِ، وَانْعَقَدَتْ بِهِ."]]},{"id":"um25_3","label":"بَابُ صَلَاةِ الْجُمُعَةِ · ٣","segs":[["matn","وَمِنْ شَرْطِ صِحَّتِهَا: فِعْلُهَا فِي وَقْتِهَا، فِي قَرْيَةٍ، وَأَنْ يَحْضُرَهَا مِنَ الْمُسْتَوْطِنِينَ بِهَا أَرْبَعُونَ مِنْ أَهْلِ وُجُوبِهَا، وَأَنْ تَتَقَدَّمَهَا خُطْبَتَانِ، فِي كُلِّ خُطْبَةٍ حَمْدُ اللهِ تَعَالَى، وَالصَّلَاةُ عَلَى رَسُولِهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَقِرَاءَةُ آيَةٍ، وَالْمَوْعِظَةُ."]]},{"id":"um25_4","label":"بَابُ صَلَاةِ الْجُمُعَةِ · ٤","segs":[["matn","وَيُسْتَحَبُّ أَنْ يَخْطُبَ عَلَى مِنْبَرٍ، فَإِذَا صَعِدَ، أَقْبَلَ عَلَى النَّاسِ، فَسَلَّمَ عَلَيْهِمْ، ثُمَّ يَجْلِسُ إِلَى فَرَاغِ الأَذَانِ، ثُمَّ يَقُومُ الإِمَامُ، فَيَخْطُبُ، بِهِمْ ثُمَّ يَجْلِسُ، ثُمَّ يَخْطُبُ الْخُطْبَةَ الثَّانِيَّةَ، ثُمَّ تُقَامُ الصَّلَاةُ، فَيَنْزِلُ، فَيُصَلِّي بِهِمْ رَكْعَتَيْنِ، يَجْهَرُ فِيهِمَا بِالْقِرَاءَةِ."]]},{"id":"um25_5","label":"بَابُ صَلَاةِ الْجُمُعَةِ · ٥","segs":[["matn","فَمَنْ أَدْرَكَ مَعَهُ مِنْهَا رَكْعَةً، أَتَمَّهَا جُمُعَةً، وَإِلَّا أَتَمَّهَا ظُهْرًا، وَكَذَلِكَ إِنْ نَقَصَ الْعَدَدُ، أَوْ خَرَجَ الْوَقْتُ وَقَدْ صَلَّوْا رَكْعَةً، أَتَمُّوهَا جُمُعَةً، وَإِلَّا أَتَمُّوهَا ظُهْرًا."]]},{"id":"um25_6","label":"بَابُ صَلَاةِ الْجُمُعَةِ · ٦","segs":[["matn","وَلَا يَجُوزُ أَنْ يَصَلَّى فِي الْمِصْرِ أَكْثَرُ مِنْ جُمُعَةٍ، إِلَّا أَنْ تَدْعُوَ الْحَاجَةُ إِلَى أَكْثَرَ مِنْهَا."]]},{"id":"um25_7","label":"بَابُ صَلَاةِ الْجُمُعَةِ · ٧","segs":[["matn","وَيُسْتَحَبُّ لِمَنْ أَتَى الْجُمُعَةَ أَنْ يَغْتَسِلَ، وَيَلْبَسَ ثَوْبَيْنِ نَظِيفَيْنِ، وَيَتَطَيَّبَ، وَيُبَكِّرَ إِلَيْهَا، فَإِنْ جَاءَ، وَالإِمَامُ يَخْطُبُ، لَمْ يَجْلِسْ، حَتَّى يُصَلِّيَ رَكْعَتَيْنِ يُوجِزُ فِيهِمَا."]]},{"id":"um25_8","label":"بَابُ صَلَاةِ الْجُمُعَةِ · ٨","segs":[["matn","وَلَا يَجُوزُ الكَلَامُ وَالإِمَامُ يَخْطُبُ، إِلَّا الْإِمَامَ أَوْ مَنْ كَلَّمَهُ الْإِمَامُ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um26","title":"بَابُ صَلَاةِ الْعِيدَيْنِ","units":[{"id":"um26_1","label":"بَابُ صَلَاةِ الْعِيدَيْنِ · ١","segs":[["matn","وَهِيَ فَرْضٌ عَلَى الْكِفَايَةِ، إِذَا قَامَ بِهَا أَرْبَعُونَ مِنْ أَهْلِ الْمِصْرِ، سَقَطَتْ عَنْ سَائِرِهِمْ. وَوَقْتُهَا: مِنِ ارْتِفَاعِ الشَّمْسِ إِلَى الزَّوَالِ."]]},{"id":"um26_2","label":"بَابُ صَلَاةِ الْعِيدَيْنِ · ٢","segs":[["matn","وَالسُّنَّةُ فِعْلُهَا فِي الْمُصَلَّى، وَتَعْجِيلُ الأَضْحَى، وَتَأْخِيرُ الْفِطْرِ، وَالْفِطْرُ فِي الْفِطْرِ خَاصَّةً، قَبْلَ الصَّلَاةِ. وَيُسَنُّ أَنْ يَغْتَسِلَ، وَيَتَنَظَّفَ وَيَتَطَيَّبَ."]]},{"id":"um26_3","label":"بَابُ صَلَاةِ الْعِيدَيْنِ · ٣","segs":[["matn","فَإِذَا حَلَّتِ الصَّلَاةُ، تَقَدَّمَ الإِمَامُ، فَصَلَّى بِهِمْ رَكْعَتَيْنِ بِلَا أَذَانٍ وَلَا إِقَامَةٍ، يُكَبِّرُ فِي الأُولَى سَبْعًا بِتَكْبِيرَةِ الإِحْرَامِ، وَفِي الثَّانِيَةِ خَمْسًا سِوَى تَكْبِيرَةِ الْقِيَامِ،"]]},{"id":"um26_4","label":"بَابُ صَلَاةِ الْعِيدَيْنِ · ٤","segs":[["matn","وَيَرْفَعُ يَدَيْهِ مَعَ كُلِّ تَكْبِيرَةٍ، وَيَحْمَدُ اللهِ وَيُصَلِّي عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْنَ كُلِّ تَكْبِيرَتَيْنِ، ثُمَّ يَقْرَأُ الْفَاتِحَةَ وَسُورَةً، يَجْهَرُ فِيهِمَا بِالْقِرَاءَةِ، فَإِذَا سَلَّمَ خَطَبَ بِهِمْ خُطْبَتَيْنِ."]]},{"id":"um26_5","label":"بَابُ صَلَاةِ الْعِيدَيْنِ · ٥","segs":[["matn","فَإِنَ كَانَ فِطْرًا، حَثَّهُمْ عَلَى الصَّدَقَةِ، وَبَيّنَ لَهُمْ حُكْمَهَا، وَإِنْ كَانَ أَضْحَى، بَيَّنَ لَهُمْ حُكْمَ الأُضْحِيَّةِ. وَالتَّكْبِيرَاتُ الزَّوَائِدُ، وَالْخُطْبَتَانِ سُنَّةٌ، وَلَا يَتَنَفَّلُ قَبْلَ صَلَاةِ الْعَيْدِ، وَلَا بَعْدَهَا فِي مَوْضِعِهَا."]]},{"id":"um26_6","label":"بَابُ صَلَاةِ الْعِيدَيْنِ · ٦","segs":[["matn","وَمَنْ أَدْرَكَ الإِمَامَ قَبْلَ سَلَامِهِ، أَتَمَّهَا عَلَى صِفَتِهَا، وَمَنْ فَاتَتْهُ فَلَا قَضَاءَ عَلَيْهِ، فَإِنْ أَحَبَّ، صَلَّاهَا تَطَوُّعًا، إِنْ شَاءَ رَكْعَتَيْنِ، وَإِنْ شَاءَ أَرْبَعًا، وَإِنْ شَاءَ صَلَّاهَا عَلَى صِفَتِهَا."]]},{"id":"um26_7","label":"بَابُ صَلَاةِ الْعِيدَيْنِ · ٧","segs":[["matn","وَيُسْتَحَبُّ التَّكْبِيرُ فِي لَيْلَتَيِ الْعِيدَيْنِ، وَيُكَبِّرُ فِي الأَضْحَى عَقِيبَ الْفَرَائِضِ فِي الْجَمَاعَةِ، مِنْ صَلَاةِ الْفَجْرِ يَوْمَ عَرَفَةَ إِلَى الْعَصْرِ مِنْ آخِرِ أَيَّامِ التَّشْرِيقِ، وَصِفَةُ التَّكْبِيرِ شَفْعًا: اللهُ أَكْبَرُ اللهُ أَكْبَرُ، لَا إِلهَ إِلَّا اللهُ، وَاللهُ أَكْبَرُ اللهُ أَكْبَرُ، وَللهِ الْحَمْدُ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"um27","title":"كِتَابُ الْجَنَائِزِ","units":[{"id":"um27_1","label":"كِتَابُ الْجَنَائِزِ · ١","segs":[["matn","وإذَا تُيُقِّنَ مَوْتُهُ، غُمِّضَتْ عَيْنَاهُ، وَشُدَّ لَحْيَاهُ، وَجُعِلَ عَلَى بَطْنِهِ مِرْآةٌ أَوْ غَيْرُهَا، كَحَدِيدَةٍ فَإِذَا أَخَذَ فِي غَسْلِهِ سُتِرَتْ عَوْرَتَهُ،"]]},{"id":"um27_2","label":"كِتَابُ الْجَنَائِزِ · ٢","segs":[["matn","ثُمَّ يَعْصُرُ بَطْنَهُ عَصْرًا رَفِيقًا، ثُمَّ يَلُفُّ عَلَى يَدِهِ خِرْقَةً فَيُنَجِّيهِ بِهَا ثُمَّ يُوَضِّئُهُ ثُمَّ يَغْسِلُ رَأْسَهُ وَلِحْيَتَهُ بِمَاءٍ وَسِدْرٍ، ثُمَّ شِقَّهُ الأَيْمَنَ، ثُمَّ الأَيْسَرَ،"]]},{"id":"um27_3","label":"كِتَابُ الْجَنَائِزِ · ٣","segs":[["matn","ثُمَّ يَغْسِلُهُ كَذَلِكَ مَرَّةً ثَانِيَةً، وَثَالِثَةً، يُمِرُّ فِي كُلِّ مَرَّةٍ يَدَهُ، فَإِنْ خَرَجَ مِنْهُ شَيْءٌ، غَسَلَهُ، وَسَدَّهُ بِقُطْنٍ، فَإِنْ لَمْ يَسْتَمْسِكْ،"]]},{"id":"um27_4","label":"كِتَابُ الْجَنَائِزِ · ٤","segs":[["matn","فَبِطِينٍ حُرٍّ، وَيُعِيدُ وُضُوءَهُ، وَإِنْ لَمْ يَنْقَ بِثَلَاثٍ، زَادَ إِلَى خَمْسٍ أَوْ إِلَى سَبْعٍ، ثُمَّ يُنَشِّفُهُ بِثَوْبٍ، وَيَجْعَلُ الطِّيبَ فِي مَغَابِنِهِ وَمَوَاضِعِ سُجُودِهِ."]]},{"id":"um27_5","label":"كِتَابُ الْجَنَائِزِ · ٥","segs":[["matn","وَإِنْ طَيَّبَهُ كُلَّهُ، كَانَ حَسَنًا، وَيُجَمِّرُ أَكْفَانَهُ، وَإِنْ كَانَ شَارِبُهُ أَوْ أَظْفَارُهُ طَوِيلَةً أَخَذَ مِنْهُ، وَلَا يُسَرِّحُ شَعْرَهُ، وَالْمَرْأَةُ يُضْفَرُ شَعْرُهَا ثَلَاثَةَ قُرُونٍ،"]]},{"id":"um27_6","label":"كِتَابُ الْجَنَائِزِ · ٦","segs":[["matn","وَيُسْدَلُ مِنْ وَرَائِهَا ثُمَّ يُكَفَّنُ فِي ثَلَاثَةِ أَثْوَابٍ بِيضٍ، لَيْسَ فِيهَا قَمِيصٌ وَلَا عِمَامَةٌ، يُدْرَجُ فِيهَا إِدْرَاجًا، وَإِنْ كُفِّنَ فِي قَمِيصٍ وَإِزَارٍ وَلِفَافَةٍ، فَلَا بَأْسَ."]]},{"id":"um27_7","label":"كِتَابُ الْجَنَائِزِ · ٧","segs":[["matn","وَالْمَرْأَةُ تُكَفَّنُ فِي خَمْسَةِ أَثْوَابٍ: فِي دِرْعٍ وَمِقْنَعَةٍ وَإِزَارٍ وَلِفَافَتَيْنِ."]]},{"id":"um27_8","label":"كِتَابُ الْجَنَائِزِ · ٨","segs":[["matn","وَأَحَقُّ النَّاسِ بِغَسْلِهِ وَالصَّلَاةِ عَلَيْهِ وَدَفْنِهِ، وَصِيُّهُ فِي ذَلِكَ، ثُمَّ الأَبُ، ثُمَّ الْجَدُّ، ثُمَّ الأَقْرَبُ فَالأَقْرَبُ، مِنَ الْعَصَبَاتِ وَأَوْلَى النَّاسِ بِغَسْلِ الْمَرْأَةِ: الأُمُّ، ثُمَّ الْجَدَّةُ، ثُمَّ الأَقْرَبُ فَالأَقْرَبُ مِنْ نِسَائِهَا، إِلَّا أَنَّ الأَمِيرَ يُقَدَّمُ فِي الصَّلَاةِ عَلَى الأَبِ وَمَنْ بَعْدَهُ."]]},{"id":"um27_9","label":"كِتَابُ الْجَنَائِزِ · ٩","segs":[["matn","وَالصَّلَاةُ عَلَيْهِ: يُكَبِّرُ، وَيَقْرَأُ الْفَاتِحَةَ، ثُمَّ يُكَبِّرُ الثَّانِيَةَ وَيُصَلِّي عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ يُكَبِّرُ وَيَقُولُ: اللهُمَّ اغْفِرْ لِحَيِّنَا وَميِّتِنَا، وَشَاهِدِنَا وَغَائِبِنَا، وَصَغِيرِنَا وَكَبِيرِنَا، وَذَكَرِنَا وَأُنْثَانَا إِنَّكَ تَعْلَمُ مُنْقَلَبَنَا وَمَثْوَانَا، وَأَنْتَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ."]]},{"id":"um27_10","label":"كِتَابُ الْجَنَائِزِ · ١٠","segs":[["matn","اللهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا، فَأَحْيِهِ عَلَى الإِسْلَامِ وَالسُّنَّةِ، وَمَنْ تَوَفَّيْتَهُ فَتَوَفَّهُ عَلَيِهِمَا."]]},{"id":"um27_11","label":"كِتَابُ الْجَنَائِزِ · ١١","segs":[["matn","اللهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ، وَعَافِهِ وَاعْفُ عَنْهُ، وَأَكْرِمْ نُزُلَهُ، وَوَسِّعْ مَدْخَلَهُ، وَاغْسِلْهُ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهِ مِنَ الْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الأَبْيَضُ مِنَ الدَّنَسِ، وَأَبْدِلْهُ دَارًا خَيْرًا مِنْ دَارِهِ، وَجِوَارًا خَيْرًا مِنْ جِوَارِهِ،"]]},{"id":"um27_12","label":"كِتَابُ الْجَنَائِزِ · ١٢","segs":[["matn","وَزَوْجًا خَيْرًا مِنْ زَوْجِهِ، وَأَدْخِلْهُ الْجَنَّةَ، وَأَعِذْهُ مِنْ عَذَابِ الْقَبْرِ، وَمِنْ عَذَابِ النَّارِ، وَافْسَحْ لَهُ فِي قَبْرِهِ، وَنَوِّرْ لَهُ فِيهِ، ثُمَّ يُكَبِّرُ وَيُسَلِّمُ تَسْلِيمَةً وَاحِدَةً عَنْ يَمِينِهِ، وَيَرْفَعُ يَدَيْهِ مَعَ كُلِّ تَكْبِيرَةٍ."]]},{"id":"um27_13","label":"كِتَابُ الْجَنَائِزِ · ١٣","segs":[["matn","وَالْوَاجِبُ مِنْ ذَلِكَ: التَّكْبِيرَاتُ، وَالْقِرَاءَةُ، وَالصَّلَاةُ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَأَدْنَى دُعَاءٍ الْحَيِّ لِلْمَيِّتِ، وَالسَّلَامُ. وَمَنْ فَاتَتْهُ الصَّلَاةُ عَلَيْهِ، صَلَّى عَلَى الْقَبْرِ إِلَى شَهْرٍ."]]},{"id":"um27_14","label":"كِتَابُ الْجَنَائِزِ · ١٤","segs":[["matn","وَإِنْ كَانَ الْمَيِّتُ غَائِبًا عَنِ الْبَلَدِ، صُلِّيَ عَلَيْهِ بِالنِّيَّةِ."]]},{"id":"um27_15","label":"كِتَابُ الْجَنَائِزِ · ١٥","segs":[["matn","وَمَنْ تَعَذَّرَ غَسْلُهُ لِعَدَمِ الْمَاءِ، أَوْ الْخَوْفِ عَلَيْهِ مِنَ التَّقَطُّعِ، كَالْمَجْدُورِ أَوِ الْمُحْتَرِقِ أَوْ لِكَوْنِ الْمَرْأَةِ بَيْنَ رِجَالٍ، أَوِ الرَّجُلِ بَيْنَ نِسَاءٍ، فَإِنَّهُ يُيَمَّمُ، إِلَّا أَنَّ لِكُلِّ مِنَ الزَّوْجَيْنِ غَسْلَ صَاحِبِهِ، وَكَذَلِكَ أُمُّ الْوَلَدِ مَعَ سَيِّدِهَا."]]},{"id":"um27_16","label":"كِتَابُ الْجَنَائِزِ · ١٦","segs":[["matn","وَالشَّهِيدُ إِذَا مَاتَ فِي الْمَعْرَكَةِ، لَمْ يُغَسَّلْ، وَلَمْ يَصَلَّ عَلَيْهِ، وَيُنَحَّى عَنْهُ الْحَدِيدُ وَالْجُلُودُ، ثُمَّ يُزَمَّلُ فِي ثِيَابِهِ، وَإِنْ كُفِّنَ بِغَيْرِهَا فَلَا بَأْسَ."]]},{"id":"um27_17","label":"كِتَابُ الْجَنَائِزِ · ١٧","segs":[["matn","وَالْمُحْرِمُ يُغَسَّلُ بِمَاءٍ وَسِدْرٍ، وَلَا يُلْبَسُ مَخِيطًا، وَلَا يُقَرَّبُ طِيبًا، وَلَا يُغَطَّى رَأْسُهُ وَلَا يُقْطَعُ شَعْرُهُ وَلَا ظُفُرُهُ."]]},{"id":"um27_18","label":"كِتَابُ الْجَنَائِزِ · ١٨","segs":[["matn","وَيُسْتَحَبُّ دَفْنُ الْمَيِّتِ فِي لَحْدٍ، وَيُنْصَبُ عَلَيْهِ اللَّبِنُ نَصْبًا، كَمَا صُنِعَ بِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَلَا يُدْخِلُ الْقَبْرَ آجُرًّا وَلَا خَشَبًا، وَلَا شَيْئًا مَسَّتْهُ النَّارُ."]]},{"id":"um27_19","label":"كِتَابُ الْجَنَائِزِ · ١٩","segs":[["matn","وَيُسْتَحَبُّ تَعْزِيَةُ أَهْلِ الْمَيِّتِ. وَالْبُكَاءُ عَلَيْهِ غَيْرُ مَكْرُوهٍ، إِذَا لَمْ يَكُنْ مَعَهُ نَدْبٌ وَلَا نِيَاحَةٌ."]]},{"id":"um27_20","label":"كِتَابُ الْجَنَائِزِ · ٢٠","segs":[["matn","وَلَا بَأْسَ بِزِيَارَةِ الْقُبُورِ لِلرِّجَالِ، وَيَقُولُ إِذَا مَرَّ بِهَا أَوْ زَارَهَا: سَلَامٌ عَلَيْكُمْ أَهْلَ دَارَ قَوْمٍ مُؤْمِنِينَ، وَإِنَّا إِنْ شَاءَ اللهُ بِكُمْ لَاحِقُونَ، اللهُمَّ لَا تَحْرِمْنَا أَجْرَهُمْ، وَلَا تَفْتِنَّا بَعْدَهُمْ، وَاغْفِرْ لَنَا وَلَهُمْ، نَسْأَلُ اللهَ لَنَا وَلَكُمُ الْعَافِيَةَ."]]},{"id":"um27_21","label":"كِتَابُ الْجَنَائِزِ · ٢١","segs":[["matn","وَأَيُّ قُرْبَةٍ فَعَلَهَا، وَجَعَلَ ثَوَابَهَا لِلْمَيِّتِ الْمُسْلِمِ، نَفَعَهُ ذَلِكَ."]]}],"group":"كِتَابُ الْجَنَائِزِ"},{"id":"um28","title":"كِتَابُ الزَّكَاةِ","units":[{"id":"um28_1","label":"كِتَابُ الزَّكَاةِ · ١","segs":[["matn","وَهِيَ وَاجِبَةٌ عَلَى كُلِّ مُسْلِمٍ حُرٍّ، مَلَكَ نِصَابًا، مِلْكًا تَامًّا."]]},{"id":"um28_2","label":"كِتَابُ الزَّكَاةِ · ٢","segs":[["matn","وَلَا زَكَاةَ فِي مَالٍ حَتَّى يَحُولَ عَلَيْهِ الْحَوْلُ، إِلَّا فِي الْخَارِجِ مِنَ الأَرْضِ، وَنَمَاءَ النِّصَابِ مِنَ النِّتَاجِ وَالرِّبْحِ، فَإِنَّ حَوْلَهُمَا حَوْلُ أَصْلِهِمَا."]]},{"id":"um28_3","label":"كِتَابُ الزَّكَاةِ · ٣","segs":[["matn","وَلَا تَجِبُ الزَّكَاةُ إِلَّا فِي أَرْبَعَةِ أَنْوَاعٍ: السَّائِمَةِ مِنْ بَهِيمَةِ الأَنْعَامِ، وَالْخَارِجِ مِنَ الأَرْضِ، وَالأَثْمَانِ، وَعُرُوضِ التِّجَارَةِ."]]},{"id":"um28_4","label":"كِتَابُ الزَّكَاةِ · ٤","segs":[["matn","وَلَا زَكَاةَ فِي شَيْءٍ مِنْ ذَلِكَ حَتَّى يَبْلُغَ نِصَابًا، وَتَجِبُ فِيمَا زَادَ عَلَى النِّصَابِ بِحِسَابِهِ، إِلَّا السَّائِمَةَ، فَلَا شَيْءَ فِي أَوْقَاصِهَا."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"um29","title":"بَابُ زَكَاةِ السَّائِمَةِ","units":[{"id":"um29_1","label":"بَابُ زَكَاةِ السَّائِمَةِ · ١","segs":[["matn","وَهِيَ الرَّاعِيَةُ، وَهِيَ ثَلَاثَةُ أَنْوَاعٍ: أَحَدُهَا: الإِبِلُ، وَلَا شَيْءَ فِيهَا حَتَّى تَبْلُغَ خَمْسًا، فَيَجِبُ فِيهَا شَاةٌ، وَفِي الْعَشْرِ شَاتَانِ، وَفِي خَمْسَ عَشْرَةَ ثَلَاثُ شِيَاهٍ، وَفِي الْعِشْرِينَ أَرْبَعُ شِيَاهٍ،"]]},{"id":"um29_2","label":"بَابُ زَكَاةِ السَّائِمَةِ · ٢","segs":[["matn","إِلَى خَمْسٍ وَعِشْرِينَ، فَفِيهَا بِنْتُ مَخَاضٍ، وَهِيَ: بِنْتُ سَنَةٍ، فَإِنْ لَمْ تَكُنْ عِنْدَهُ، فَابْنُ لَبُونٍ، وَهُوَ: ابْنُ سَنَتَيْنِ، إِلَى سِتٍّ وَثَلَاثِينَ، فَيَجِبُ فِيهَا بِنْتُ لَبُونٍ، إِلَى سِتٍّ وَأَرْبَعِينَ،"]]},{"id":"um29_3","label":"بَابُ زَكَاةِ السَّائِمَةِ · ٣","segs":[["matn","فَيَجِبُ فِيهَا حِقَّةٌ لَهَا ثَلَاثُ سِنِينَ، إِلَى إِحْدَى وَسِتِّينَ، فَيَجِبُ فِيهَا جَذَعَةٌ، لَهَا أَرْبَعُ سِنِينَ، إِلَى سِتٍّ وَسَبْعِينَ، فَفِيهَا ابْنَتَا لَبُونٍ، إِلَى إِحْدَى وَتِسْعِينَ، فَفِيهَا حِقَّتَانِ، إِلَى عِشْرِينَ وَمِائَةٍ،"]]},{"id":"um29_4","label":"بَابُ زَكَاةِ السَّائِمَةِ · ٤","segs":[["matn","فَإِذَا زَادَتْ وَاحِدَةً، فَفِيهَا ثَلَاثُ بَنَاتِ لَبُونٍ، ثُمَّ فِي كُلِّ خَمْسِينَ حِقَّةٌ، وَفِي كُلِّ أَرْبَعِينَ بِنْتُ لَبُونٍ، إِلَى مِائَتَيْنِ فَيَجْتَمِعُ فِيهَا الْفَرْضَانِ، فَإِنْ شَاءَ أَخْرَجَ أَرْبَعَ حِقَاقٍ، وَإِنْ شَاءَ خَمْسَ بَنَاتِ لَبُونٍ."]]},{"id":"um29_5","label":"بَابُ زَكَاةِ السَّائِمَةِ · ٥","segs":[["matn","وَمَنْ وَجَبَتْ عَلَيْهِ سِنٌّ فَلَمْ يَجِدْهَا، أَخْرَجَ أَدْنَى مِنْهَا وَمَعَهَا شَاتَانِ، أَوْ عِشْرُونَ دِرْهَمًا، وَإِنْ شَاءَ أَخْرَجَ أَعْلَى مِنْهَا وَأَخَذَ شَاتَيْنِ أَوْ عِشْرِينَ دِرْهَمًا."]]},{"id":"um29_6","label":"بَابُ زَكَاةِ السَّائِمَةِ · ٦","segs":[["matn","النَّوْعُ الثَّانِي: الْبَقَرُ، وَلَا شَيْءَ فِيهَا حَتَّى تَبْلُغَ ثَلَاثِينَ، فَيَجِبُ فِيهَا تَبِيعٌ، أَوْ تَبِيعَةٌ، لَهَا سَنَةٌ، إِلَى أَرْبَعِينَ، فَفِيهَا مُسِنَّةٌ، لَهَا سَنَتَانِ، إِلَى سِتِّينَ، فَفِيهَا تَبِيعَانِ، إِلَى سَبْعِينَ فَفِيهَا تَبِيعٌ وَمُسِنَّةٌ، ثُمَّ فِي كُلِّ ثَلَاثِينَ تَبِيعٌ، وَفِي كُلِّ أَرْبَعِينَ مُسِنَّةٌ."]]},{"id":"um29_7","label":"بَابُ زَكَاةِ السَّائِمَةِ · ٧","segs":[["matn","النَّوْعُ الثَّالِثُ: الْغَنَمُ، وَلَا شَيْءَ فِيهَا حَتَّى تَبْلُغَ أَرْبَعِينَ، فَفِيهَا شَاةٌ، إِلَى عِشْرِينَ وَمِائَةٍ، فَإِذَا زَادَتْ وَاحِدَةً، فَفِيهَا شَاتَانِ، إِلَى مِائَتَيْنِ فَإِذَا زَادَتْ وَاحِدَةً، فَفِيهَا ثَلَاثُ شِيَاهٍ، ثُمَّ فِي كُلِّ مِائَةٍ شَاةٌ."]]},{"id":"um29_8","label":"بَابُ زَكَاةِ السَّائِمَةِ · ٨","segs":[["matn","وَلَا يُؤْخَذُ فِي الصَّدَقَةِ تَيْسٌ، وَلَا ذَاتَ عَوَارٍ، وَلَا هَرِمَةٌ، وَلَا الرُّبَّى، وَلَا الْمَاخِضُ، وَلَا الأَكُولَةُ، وَلَا يُؤْخَذُ شِرَارُ الْمَالِ، وَلَا كَرَائِمُهُ،"]]},{"id":"um29_9","label":"بَابُ زَكَاةِ السَّائِمَةِ · ٩","segs":[["matn","إِلَّا أَنْ يَتَبَرَّعَ بِهِ أَرْبَابُ الْمَالِ وَلَا يُخْرِجُ إِلَّا أُنْثَى صَحِيحَةً، إِلَّا فِي الثَّلَاثِينَ مِنَ الْبَقَرِ، وَابْنَ لَبُونٍ مَكَانَ بِنْتِ مَخَاضٍ إِذَا عَدِمَهَا،"]]},{"id":"um29_10","label":"بَابُ زَكَاةِ السَّائِمَةِ · ١٠","segs":[["matn","إِلَّا أَنْ تَكُونَ مَاشِيَةٌ كُلُّهَا ذُكُورٌ أَوْ مِرَاضٌ فَيُجْزِئُ وَاحِدٌ مِنْهَا، وَلَا يُخْرِجُ إِلَّا جَذَعَةً مِنَ الضَّأْنِ، أَوْ ثَنِيَّةً مِنَ الْمَعْزِ، وَالسِّنَّ الْمَنْصُوصَ عَلَيْهَا، إِلَّا أَنْ يَخْتَارَ رَبُّ الْمَالِ إِخْرَاجَ سِنٍّ أَعْلَى مِنَ الْوَاجِبِ، أَوْ تَكُونَ كُلُّهَا صِغَارًا، فَيُخْرِجُ صَغِيرَةً."]]},{"id":"um29_11","label":"بَابُ زَكَاةِ السَّائِمَةِ · ١١","segs":[["matn","وَإِنْ كَانَ فِيهَا صِحَاحٌ وَمِرَاضٌ، وَذُكُورٌ وَإِنَاثٌ، وَصِغَارٌ وَكِبَارٌ، أَخْرَجَ صَحِيحَةً كَبِيرَةً، قِيمَتُهَا عَلَى قِيمَةِ الْمَالَيْنِ، فَإِنْ كَانَ فِيهَا بَخَاتِيُّ وَعِرَابٌ، وَبَقَرٌ وَجَوَامِيسُ، وَمَعْزٌ وَضَأْنٌ، وَكِرَامٌ وَلِئَامٌ، وَسِمَانٌ وَمَهَازِيلُ، أُخِذَ مِنْ أَحَدُهُمَا بِقَدْرِ قِيمَةِ الْمَالَيْنِ."]]},{"id":"um29_12","label":"بَابُ زَكَاةِ السَّائِمَةِ · ١٢","segs":[["matn","وَإِنِ اخْتَلَطَ جَمَاعَةٌ فِي نِصَابٍ مِنَ السَّائِمَةِ حَوْلاً كَامِلاً، وَكَانَ مَرْعَاهُمْ وَفَحْلُهُمْ، وَمَبِيتُهُمْ وَمِحْلَبُهُمْ، وَمَشْرَبُهُمْ وَاحِدًا، فَحُكْمُ زَكَاتِهِمْ حُكْمُ زَكَاةِ الْوَاحِدِ."]]},{"id":"um29_13","label":"بَابُ زَكَاةِ السَّائِمَةِ · ١٣","segs":[["matn","وَإِذَا أُخْرِجَ الْفَرْضُ مِنْ مَالِ أَحَدِهِمْ، رَجَعَ عَلَى خُلَطَائِهِ بِحِصَصِهِمْ مِنْهُ، وَلَا تُؤَثِّرُ الْخِلْطَةُ إِلَّا فِي السَّائِمَةِ."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"um30","title":"بَابُ زَكَاةِ الْخَارِجِ مِنَ الأَرْضِ","units":[{"id":"um30_1","label":"بَابُ زَكَاةِ الْخَارِجِ مِنَ الأَرْضِ · ١","segs":[["matn","وَهُوَ نَوْعَانِ: أَحَدُهُمَا: النَّبَاتُ، فَتَجِبُ الزَّكَاةُ مِنْهُ فِي كُلِّ حَبٍّ وَثَمَرٍ، يُكَالُ وَيُدَّخَرُ، إِذَا خَرَجَ مِنْ أَرْضِهِ، وَبَلَغَ خَمْسَةَ أَوْسُقٍ؛ لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «لَيْسَ فِي حَبٍّ وَلَا ثَمَرٍ صَدَقَةٌ حَتَّى يَبْلُغَ خَمْسَةَ أَوْسُقٍ.»"]]},{"id":"um30_2","label":"بَابُ زَكَاةِ الْخَارِجِ مِنَ الأَرْضِ · ٢","segs":[["matn","وَالوَسْقُ: سِتُّونَ صَاعًا، وَالصَّاعُ: رِطْلٌ بِالدِّمَشْقِيِّ وَأُوقِيَّةُ وَخَمْسَةُ أَسْبَاعِ أُوقِيَّةٍ. فَجَمِيعُ النِّصَابِ: مَا قَارَبَ ثَلَاثَمِائَةٍ وَاثْنَيْنِ وَأَرْبَعِينَ رِطْلاً وَسِتَّةَ أَسْبَاعِ رِطْلٍ."]]},{"id":"um30_3","label":"بَابُ زَكَاةِ الْخَارِجِ مِنَ الأَرْضِ · ٣","segs":[["matn","وَيَجِبُ الْعُشْرُ فِيمَا سُقِيَ مِنَ السَّمَاءِ وَالسُّيُوحِ، وَنِصْفُ الْعُشْرِ فِيمَا سُقِيَ بِكُلْفَةٍ، كَالدَّوَالِي وَالنَّوَاضِحِ، وَإِذَا بَدَا الصَّلَاحُ فِي الثِّمَارِ وَاشْتَدَّ الْحَبُّ، وَجَبَتِ الزَّكَاةُ، وَلَا يُخْرَجُ الْحَبُّ إِلَّا مُصَفًّى، وَلَا الثَّمَرُ إِلَّا يَابِسًا."]]},{"id":"um30_4","label":"بَابُ زَكَاةِ الْخَارِجِ مِنَ الأَرْضِ · ٤","segs":[["matn","وَلَا زَكَاةَ فِيمَا يَكْتَسِبُهُ مِنْ مُبَاحِ الْحَبِّ وَالثَّمَرِ، وَلَا فِي اللَّقَاطِ، وَلَا مَا يَأْخُذُهُ أُجْرَةً لِحَصَادِهِ."]]},{"id":"um30_5","label":"بَابُ زَكَاةِ الْخَارِجِ مِنَ الأَرْضِ · ٥","segs":[["matn","وَلَا يُضَمُّ صِنْفٌ مِنَ الْحَبِّ وَالثَّمَرِ إِلَى غَيْرِهِ فِي تَكْمِيلِ النِّصَابِ، فَإِنْ كَانَ صِنْفًا وَاحِدًا، مُخْتَلِفَ الأَنْوَاعِ، كَالتُّمُورِ، فَفِيهَا الزَّكَاةُ، وَيُخْرِجُ مِنْ كُلِّ نَوْعٍ زَكَاتَهُ، وَإِنْ أَخْرَجَ جَيِّدًا عَنِ الرَّدِيءِ، جَازَ، وَلَهُ أَجْرُهُ."]]},{"id":"um30_6","label":"بَابُ زَكَاةِ الْخَارِجِ مِنَ الأَرْضِ · ٦","segs":[["matn","النَّوْعُ الثَّانِي: الْمَعْدِنُ، فَمَنِ اسْتَخْرَجَ مِنْ مَعْدِنٍ نِصَابًا مِنَ الذَّهَبِ أَوِ الْفِضَّةِ، أَوْ مَا قِيمَتُهُ نِصَابًا مِنَ الْجَوَاهِرِ، أَوِ الْكُحْلِ وَالصُّفْرِ وَالْحَدِيدِ أَوْ غَيْرِهِ فَعَلَيْهِ الزَّكَاةُ، وَلَا يُخْرَجُ إِلَّا بَعْدَ السَّبْكِ وَالتَّصْفِيَةِ."]]},{"id":"um30_7","label":"بَابُ زَكَاةِ الْخَارِجِ مِنَ الأَرْضِ · ٧","segs":[["matn","وَلَا شَيْءَ فِي اللُّؤْلُؤِ وَالْمَرْجَانِ، وَالْعَنْبَرِ وَالْمِسْكِ، وَلَا شَيْءَ فِي صَيْدِ الْبَرِّ وَالْبَحْرِ. وَفِي الرِّكَازِ الْخُمُسُ، أَيَّ نَوْعٍ كَانَ مِنَ الْمَالِ، قَلَّ أَوْ كَثُرَ، وَمَصْرِفُهُ مَصْرِفُ الْفَيْءِ، وَبَاقِيهِ لِوَاجِدِهِ."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"um31","title":"بَابُ زَكَاةِ الأَثْمَانِ","units":[{"id":"um31_1","label":"بَابُ زَكَاةِ الأَثْمَانِ · ١","segs":[["matn","وَهِيَ نَوْعَانِ: ذَهَبٌ وَفِضَّةٌ، وَلَا زَكَاةَ فِي الْفِضَّةِ حَتَّى تَبْلُغَ مِائَتَيْ دِرْهَمٍ، فَيَجِبُ فِيهَا خَمْسَةُ دَرَاهِمَ، وَلَا فِي الذَّهَبِ حَتَّى يَبْلُغَ عِشْرِينَ مِثْقَالاً، فَيَجِبُ فِيهَا نِصْفُ مِثْقَالٍ، فَإِنْ كَانَ فِيهِمَا غِشٌّ، فَلَا زَكَاةَ فِيهِمَا حَتَّى يَبْلُغَ قَدْرُ الذَّهَبِ وَالْفِضَّةِ نِصَابًا."]]},{"id":"um31_2","label":"بَابُ زَكَاةِ الأَثْمَانِ · ٢","segs":[["matn","فَإِنْ شَكَّ فِي ذَلِكَ، خُيِّرَ بَيْنَ الإِخْرَاجِ وَبَيْنَ سَبْكِهِمَا؛ لِيَعْلَمَ قَدْرَ ذَلِكَ. وَلَا زَكَاةَ فِي الْحُلِّيِّ الْمُبَاحِ، الْمُعَدِّ لِلِاسْتِعْمَالِ، وَالْعَارِيَةِ. وَيُبَاحُ لِلنِّسَاءِ كُلُّ مَا جَرَتْ الْعَادَةُ بِلُبْسِهِ مِنَ الذَّهَبِ وَالْفِضَّةِ."]]},{"id":"um31_3","label":"بَابُ زَكَاةِ الأَثْمَانِ · ٣","segs":[["matn","وَيُبَاحُ لِلرِّجَالِ مِنَ الْفِضَّةِ: الْخَاتَمُ، وَحِلْيَةُ السَّيْفِ، وَالْمِنْطَقَةُ، وَنَحْوُهَا. فَأَمَّا الْمُعَدُّ لِلْكِرَاءِ أَوِ الِادِّخَارِ وَالْمُحَرَّمُ فَفِيهِ الزَّكَاةُ."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"um32","title":"بَابُ حُكْمِ الدَّيْنِ","units":[{"id":"um32_1","label":"بَابُ حُكْمِ الدَّيْنِ · ١","segs":[["matn","مَنْ كَانَ لَهُ دَيْنٌ عَلَى مَلِيءٍ، أَوْ مَالٌ يُمْكِنُ خَلَاصُهُ، كَالْمَجْحُودِ الَّذِي لَهُ بِهِ بَيِّنَةٌ، وَالْمَغْصُوبِ الَّذِي يَتَمَكَّنُ مِنْ أَخْذِهِ، فَعَلَيْهِ زَكَاتُهُ إِذَا قَبَضَهُ، لِمَا مَضَى."]]},{"id":"um32_2","label":"بَابُ حُكْمِ الدَّيْنِ · ٢","segs":[["matn","وَإِنْ كَانَ مُتَعَذِّرًا كَالدَّيْنِ عَلَى مُفْلِسٍ أَوْ عَلَى جَاحِدٍ، وَلَا بَيِّنَةَ بِهِ، وَالْمَغْصُوبِ، وَالضَّالِّ الَّذِي لَا يُرْجَى وُجُودُهُ، فَلَا زَكَاةَ فِيهِ."]]},{"id":"um32_3","label":"بَابُ حُكْمِ الدَّيْنِ · ٣","segs":[["matn","وَحُكْمُ الصَّدَاقِ حُكْمُ الدَّيْنِ، وَمَنْ كَانَ عَلَيْهِ دَيْنٌ يَسْتَغْرِقُ النِّصَابَ الَّذِي مَعَهُ، أَوْ يَنْقُصُهُ، فَلَا زَكَاةَ فِيهِ."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"um33","title":"بَابُ زَكَاةِ الْعُرُوضِ","units":[{"id":"um33_1","label":"بَابُ زَكَاةِ الْعُرُوضِ · ١","segs":[["matn","وَلَا زَكَاةَ فِيهَا حَتَّى يَنْوِيَ بِهَا التِّجَارَةَ، وَهِيَ نِصَابٌ حَوْلاً ثُمَّ يُقَوِّمُهَا، فَإِذَا بَلَغَتْ أَقَلَّ نِصَابٍ مِنَ الذَّهَبِ وَالْفِضَّةِ أَخْرَجَ الزَّكَاةَ مِنْ قِيمَتِهَا."]]},{"id":"um33_2","label":"بَابُ زَكَاةِ الْعُرُوضِ · ٢","segs":[["matn","وَإِنْ كَانَ عِنْدَهُ ذَهَبٌ أَوْ فِضَّةٌ، ضَمَّهَا إِلَى قِيمَةِ الْعُرُوضِ فِي تَكْمِيلِ النِّصَابِ."]]},{"id":"um33_3","label":"بَابُ زَكَاةِ الْعُرُوضِ · ٣","segs":[["matn","وَإِذَا نَوَى بِعُرُوضِ التِّجَارَةِ الْقُنْيَةَ، فَلَا زَكَاةَ فِيهَا ثُمَّ إِنْ نَوَى بِهَا بَعْدَ ذَلِكَ التِّجَارَةَ، اسْتَأْنَفَ لَهُ حَوْلاً."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"um34","title":"بَابُ زَكَاةِ الْفِطْرِ","units":[{"id":"um34_1","label":"بَابُ زَكَاةِ الْفِطْرِ · ١","segs":[["matn","وَهِيَ وَاجِبَةٌ عَلَى كُلِّ مُسْلِمٍ، إِذَا مَلَكَ فَضْلاً عَنْ قُوتِهِ وَقُوتِ عِيَالِهِ، لَيْلَةَ الْعِيدِ وَيَوْمَهُ، وَقَدْرُ الْفِطْرَةِ: صَاعٌ مِنَ الْبُرِّ أَوِ الشَّعِيرِ،"]]},{"id":"um34_2","label":"بَابُ زَكَاةِ الْفِطْرِ · ٢","segs":[["matn","أَوْ دَقِيقِهِمَا أَوْ سَوِيقِهِمَا، أَوْ مِنَ التَّمْرِ أَوِ الزَّبِيبِ، فَإِنْ لَمْ يَجِدْهُ، أَخْرَجَ مِنْ قُوتِهِ أَيَّ شَيْءٍ كَانَ، صَاعًا."]]},{"id":"um34_3","label":"بَابُ زَكَاةِ الْفِطْرِ · ٣","segs":[["matn","وَمَنْ لَزِمَتْهُ فِطْرَةُ نَفْسِهِ، لَزِمَتْهُ فِطْرَةُ مَنْ تَلْزَمُهُ مُؤْنَتُهُ لَيْلَةَ الْعِيدِ، إِذَا مَلَكَ مَا يُؤَدِّي عَنْهُ فَإِنْ كَانَتْ مُؤْنَتُهُ تَلْزَمُ جَمَاعَةً، كَالْعَبْدِ الْمُشْتَرَكِ، أَوِ الْمُعْسِرِ الْقَرِيبِ لِجَمَاعَةٍ، فَفِطْرُتُهُ عَلَيْهِمْ عَلَى حَسَبِ مُؤْنَتِهِ."]]},{"id":"um34_4","label":"بَابُ زَكَاةِ الْفِطْرِ · ٤","segs":[["matn","وَإِنْ كَانَ بَعْضُهُ حُرًّا، فَفِطْرَتُهُ عَلَيْهِ وَعَلَى سَيِّدِهِ. وَيُسْتَحَبُّ إِخْرَاجُ الْفِطْرَةِ يَوْمَ الْعِيدِ قَبْلَ الصَّلَاةِ وَلَا يَجُوزُ تَأْخِيرُهَا عَنْ يَوْمِ الْعِيدِ، وَيَجُوزُ تَقْدِيمُهَا عَلَيْهِ بِيَوْمٍ أَوْ يَوْمَيْنِ."]]},{"id":"um34_5","label":"بَابُ زَكَاةِ الْفِطْرِ · ٥","segs":[["matn","وَيَجُوزُ أَنْ يُعْطَى وَاحِدٌ مَا يَلْزَمُ الْجَمَاعَةَ، وَالْجَمَاعَةُ مَا يَلْزَمُ الْوَاحِدَ."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"um35","title":"بَابُ إِخْرَاجِ الزَّكَاةِ","units":[{"id":"um35_1","label":"بَابُ إِخْرَاجِ الزَّكَاةِ · ١","segs":[["matn","لَا يَجُوزُ تَأْخِيرُهَا عَنْ وَقْتِ وُجُوبِهَا، إِذَا أَمْكَنَ إِخْرَاجُهَا، فَإِنْ فَعَلَ فَتَلِفَ الْمَالُ، لَمْ تَسْقُطْ عَنْهُ الزَّكَاةُ، وَإِنْ تَلِفَ قَبْلَهُ، سَقَطَتْ. وَيَجُوزُ تَعْجِيلُهَا إِذَا كَمُلَ النِّصَابُ، وَلَا يَجُوزُ قَبْلَ ذَلِكَ."]]},{"id":"um35_2","label":"بَابُ إِخْرَاجِ الزَّكَاةِ · ٢","segs":[["matn","فَإِنْ عَجَّلَهَا إِلَى غَيْرِ مُسْتَحِقِّهَا، لَمْ يُجْزِئْهُ وَإِنْ صَارَ عِنْدَ الْوُجُوبِ مِنْ أَهْلِهَا."]]},{"id":"um35_3","label":"بَابُ إِخْرَاجِ الزَّكَاةِ · ٣","segs":[["matn","وَإِنْ دَفَعَهَا إِلَى مُسْتَحِقِّهَا، فَمَاتَ أَوِ اسْتَغْنَى أَوِ ارْتَدَّ، أَجْزَأَتْ، عَنْهُ وَإِنْ تَلِفَ الْمَالُ، لَمْ يَرْجِعْ عَلَى الآخِذِ."]]},{"id":"um35_4","label":"بَابُ إِخْرَاجِ الزَّكَاةِ · ٤","segs":[["matn","وَلَا تُنْقَلُ الصَّدَقَةُ إِلَى بَلَدٍ تُقْصَرُ إِلَيْهِ الصَّلَاةُ إِلَّا أَنْ لَا يَجِدَ مَنْ يَأْخُذُهَا فِي بَلَدِهَا."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"um36","title":"بَابُ مَنْ يَجُوزُ دَفْعُ الزَّكَاةِ إِلَيْهِ","units":[{"id":"um36_1","label":"بَابُ مَنْ يَجُوزُ دَفْعُ الزَّكَاةِ إِلَيْهِ · ١","segs":[["matn","وَهُمْ ثَمَانِيَةُ: الْأَوَّلُ: الْفُقَرَاءُ، وَهُمُ: الَّذِينَ لَا يَجِدُونَ مَا يَقَعَ مَوْقِعًا مِنْ كِفَايَتِهِمْ بِكَسْبٍ وَلَا غَيْرِهِ. الثَّانِي: الْمَسَاكِينُ، وَهُمُ: الَّذِينَ يَجِدُونَ ذَلِكَ، وَلَا يَجِدُونَ تَمَامَ الْكِفَايَةِ."]]},{"id":"um36_2","label":"بَابُ مَنْ يَجُوزُ دَفْعُ الزَّكَاةِ إِلَيْهِ · ٢","segs":[["matn","الثَّالِثُ: الْعَامِلُونَ عَلَيْهَا، وَهُمُ: السُّعَاةُ عَلَيْهَا، وَمَنْ يُحْتَاجُ إِلَيْهِ فِيهَا."]]},{"id":"um36_3","label":"بَابُ مَنْ يَجُوزُ دَفْعُ الزَّكَاةِ إِلَيْهِ · ٣","segs":[["matn","الرَّابِعُ: الْمُؤَلَّفَةُ قُلُوبُهُمْ، وَهُمُ: السَّادَةُ الْمُطَاعُونَ فِي عَشَائِرِهِمْ، الَّذِينَ يُرْجَى بِعَطِيَّتِهِمْ دَفْعُ شَرِّهِمْ، أَوْ قُوَّةُ إِيمَانِهِمْ، أَوْ دَفْعُهُمْ عَنِ الْمُسْلِمِينَ، أَوْ إِعَانَتُهُمْ عَلَى أَخْذِ الزَّكَاةِ مِمَّنْ يَمْتَنِعُ مِنْ دَفْعِهَا."]]},{"id":"um36_4","label":"بَابُ مَنْ يَجُوزُ دَفْعُ الزَّكَاةِ إِلَيْهِ · ٤","segs":[["matn","الْخَامِسُ: الرِّقَابُ، وَهُمُ: الْمُكَاتَبُونَ، وَإِعْتَاقُ الرَّقِيقِ. السَّادِسُ: الْغَارِمُونَ، وَهُمُ: الْمَدِينُونَ لِإِصْلَاحِ نُفُوسِهِمْ فِي مُبَاحٍ، أَوْ لِإِصْلَاحٍ بَيْنَ طَائِفَتَيْنِ مِنَ الْمُسْلِمِينَ. السَّابِعُ: فِي سَبِيلِ اللهِ، وَهُمُ: الْغُزَاةُ الَّذِينَ لَا دِيوَانَ لَهُمْ."]]},{"id":"um36_5","label":"بَابُ مَنْ يَجُوزُ دَفْعُ الزَّكَاةِ إِلَيْهِ · ٥","segs":[["matn","الثَّامِنُ: ابْنُ السَّبِيلِ، وَهُوَ: الْمُسَافِرُ الْمُنْقَطِعُ بِهِ، وَإِنْ كَانَ ذَا يَسَارٍ فِي بَلَدِهِ. فَهَؤُلَاءِ هُمْ أَهْلُ الزَّكَاةِ، لَا يَجُوزُ دَفْعُهَا إِلَى غَيْرِهِمْ، وَيَجُوزُ دَفْعُهَا إِلَى وَاحِدٍ مِنْهُمْ."]]},{"id":"um36_6","label":"بَابُ مَنْ يَجُوزُ دَفْعُ الزَّكَاةِ إِلَيْهِ · ٦","segs":[["matn","لِأَنَّهُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بَنِي زُرَيْقٍ بِدَفْعِ صَدَقَتِهِمْ إِلَى سَلَمَةَ بْنِ صَخْرٍ وَقَالَ لِقَبِيصَةَ: «أَقِمْ يَا قَبِيصَةُ حَتَّى تَأْتِيَنَا الصَّدَقَةُ، فَنَأْمُرَ لَكَ بِهَا»."]]},{"id":"um36_7","label":"بَابُ مَنْ يَجُوزُ دَفْعُ الزَّكَاةِ إِلَيْهِ · ٧","segs":[["matn","وَيُدْفَعُ إِلَى الْفَقِيرِ، وَالْمِسْكِينِ مَا تَتِمُّ بِهِ كِفَايَتُهُ، وَإِلَى الْعَامِلِ قَدْرُ عُمَالَتِهِ، وَإِلَى الْمُؤَلَّفِ مَا يَحْصُلُ بِهِ تَأْلِيفُهُ، وَإِلَى الْمُكَاتَبِ وَالْغَارِمِ مَا يَقْضِي بِهِ دَيْنَهُ،"]]},{"id":"um36_8","label":"بَابُ مَنْ يَجُوزُ دَفْعُ الزَّكَاةِ إِلَيْهِ · ٨","segs":[["matn","وَإِلَى الْغَازِي مَا يَحْتَاجُ إِلَيْهِ لِغَزْوِهِ، وَإِلَى ابْنِ السَّبِيلِ مَا يُوصِلُهُ إِلَى بَلَدِهِ، وَلَا يُزَادُ وَاحِدٌ مِنْهُمْ عَلَى ذَلِكَ."]]},{"id":"um36_9","label":"بَابُ مَنْ يَجُوزُ دَفْعُ الزَّكَاةِ إِلَيْهِ · ٩","segs":[["matn","وَخَمْسَةٌ مِنْهُمْ لَا يَأْخُذُونَ إِلَّا مَعَ الْحَاجَةِ، وَهُمُ: الْفَقِيرُ، وَالْمِسْكِينُ، وَالْمُكَاتَبُ، وَالْغَارِمِ لِنَفْسِهِ، وَابنُ السَّبِيلِ أَرْبَعَةٌ يَجُوزُ الدَّفْعُ إِلَيْهِمْ مَعَ الْغِنَى، وَهُمُ: الْعَامِلُ، وَالْمُؤَلَّفُ، وَالْغَازِي، وَالْغَارِمُ لِإِصْلَاحِ ذَاتِ الْبَيْنِ."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"um37","title":"بَابُ مَنْ لَا يَجُوزُ دَفْعُ الزَّكَاةِ إِلَيْهِ","units":[{"id":"um37_1","label":"بَابُ مَنْ لَا يَجُوزُ دَفْعُ الزَّكَاةِ إِلَيْهِ · ١","segs":[["matn","لَا تَحِلُّ الصَّدَقَةُ لِغَنِيٍّ، وَلَا لِقَوِيٍّ مُكْتَسِبٍ، وَلَا تَحِلُّ لِآلِ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَهُمْ: بَنُو هَاشِمٍ وَمَوَالِيهِمْ."]]},{"id":"um37_2","label":"بَابُ مَنْ لَا يَجُوزُ دَفْعُ الزَّكَاةِ إِلَيْهِ · ٢","segs":[["matn","وَلَا يَجُوزُ دَفْعُهَا إِلَى الْوَالِدَيْنِ، وَإِنْ عَلَوْا، وَلَا إِلَى الْوَلَدِ وَإِنْ سَفَلَ، وَلَا مَنْ تَلْزَمُهُ مُؤْنَتُهُ، وَلَا إِلَى كَافِرٍ. فَأَمَّا صَدَقَةُ التَّطَوُّعِ، فَيَجُوزُ دَفْعُهَا إِلَى هَؤُلاِءِ، وَإِلَى غَيْرِهِمْ."]]},{"id":"um37_3","label":"بَابُ مَنْ لَا يَجُوزُ دَفْعُ الزَّكَاةِ إِلَيْهِ · ٣","segs":[["matn","وَلَا يَجُوزُ دَفْعُ الزَّكَاةِ إِلَّا بِنِيَّةٍ، إِلَّا أَنْ يَأْخُذَهَا الإِمَامُ قَهْرًا. وَإِذَا دَفَعَ الزَّكَاةَ إِلَى غَيْرِ مُسْتَحِقِّهَا، لَمْ يُجْزِهِ إِلَّا الْغَنِيَّ إِذَا ظَنَّهُ فَقِيرًا."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"um38","title":"كِتَابُ الصِّيَامِ","units":[{"id":"um38_1","label":"كِتَابُ الصِّيَامِ · ١","segs":[["matn","يَجِبُ صِيَامُ رَمَضَانَ عَلَى كُلِّ مُسْلِمٍ بَالِغٍ عَاقِلٍ قَادِرٍ عَلَى الصَّوْمِ، وَيُؤْمَرُ بِهِ الصَّبِيُّ إِذَا أَطَاقَهُ."]]},{"id":"um38_2","label":"كِتَابُ الصِّيَامِ · ٢","segs":[["matn","وَيَجِبُ بِأَحَدِ ثَلَاثَةِ أَشْيَاءَ: كَمَالِ شَعْبَانَ، وَرُؤْيَةِ هِلَالِ رَمَضَانَ وَوُجُودِ غَيْمٍ أَوْ قَتْرٍ لَيْلَةَ الثَّلَاثِينَ يَحُولُ دُونَهُ."]]},{"id":"um38_3","label":"كِتَابُ الصِّيَامِ · ٣","segs":[["matn","وَإِذَا رَأَى الْهِلَالَ وَحْدَهُ، صَامَ، فَإِنْ كَانَ عَدْلاً، صَامَ النَّاسُ بِقَوْلِهِ وَلَا يُفْطِرُ إِلَّا بِشَهَادَةِ عَدْلَيْنِ وَلَا يُفْطِرُ إِذَا رَآهُ وَحْدَهُ."]]},{"id":"um38_4","label":"كِتَابُ الصِّيَامِ · ٤","segs":[["matn","وَإِنْ صَامُوا بِشَهَادَةِ اثْنَيْنِ ثَلَاثِينَ يَوْمًا، أَفْطَرُوا، وَإِنْ كَانَ بِغَيْمٍ، أَوْ قَوْلِ وَاحِدٍ، لَمْ يُفْطِرُوا، إِلَّا أَنْ يَرَوْهُ، أَوْ يُكْمِلُوا الْعِدَّةَ."]]},{"id":"um38_5","label":"كِتَابُ الصِّيَامِ · ٥","segs":[["matn","وَإِذَا اشْتَبَهَتِ الأَشْهُرُ عَلَى الأَسِيرِ، تَحَرَّى، وَصَامَ، فَإِنْ وَافَقَ الشَّهْرَ أَوْ مَا بَعْدَهُ، أَجْزَأَهُ، وَإِنْ وَافَقَ قَبْلَهُ، لَمْ يَجْزِهِ."]]}],"group":"كِتَابُ الصِّيَامِ"},{"id":"um39","title":"بَابُ أَحْكَامِ الْمُفْطِرِينَ فِي رَمَضَانَ","units":[{"id":"um39_1","label":"بَابُ أَحْكَامِ الْمُفْطِرِينَ فِي رَمَضَانَ · ١","segs":[["matn","وَيُبَاحُ الْفِطْرُ فِي رَمَضَانَ لِأَرْبَعَةِ أَقْسَامٍ: أَحَدُهَا: الْمَرِيضُ الَّذِي يَتَضَرَّرُ بِهِ، وَالْمُسَافِرُ الَّذِي لَهُ الْقَصْرُ، فَالْفِطْرُ لَهُمَا أَفْضَلُ، وَعَلَيْهِمَا الْقَضَاءُ، وَإِنْ صَامَا، أَجْزَأَهُمَا."]]},{"id":"um39_2","label":"بَابُ أَحْكَامِ الْمُفْطِرِينَ فِي رَمَضَانَ · ٢","segs":[["matn","الثَّانِي: الْحَائِضُ وَالنُّفَسَاءُ، تُفْطِرَانِ وَتَقْضِيَانِ، وَإِنْ صَامَتَا، لَمْ يُجْزِئْهُمَا. الثَّالِثُ: الْحَامِلُ وَالْمُرْضِعُ، إِذَا خَافَتَا عَلَى أَنْفُسِهِمَا، أَفْطَرَتَا، وَقَضَتَا، وَإِنْ خَافَتَا عَلَى وَلَدَيْهِمَا، أَفْطَرَتَا وَقَضَتَا، وَأَطْعَمَتَا عَنِ كُلِّ يَوْمٍ مِسْكِينًا."]]},{"id":"um39_3","label":"بَابُ أَحْكَامِ الْمُفْطِرِينَ فِي رَمَضَانَ · ٣","segs":[["matn","الرَّابِعُ: الْعَاجِزُ عَنِ الصِّيَامِ لِكِبَرٍ، أَوْ مَرَضٍ لَا يُرْجَى بُرْؤُهُ، فَإِنَّهُ يُطْعِمُ عَنْ كُلِّ يَوْمٍ مِسْكِينًا."]]},{"id":"um39_4","label":"بَابُ أَحْكَامِ الْمُفْطِرِينَ فِي رَمَضَانَ · ٤","segs":[["matn","وَعَلَى سَائِرِ مَنْ أَفْطَرَ الْقَضَاءُ لَا غَيْرُ إِلَّا مَنْ أَفْطَرَ بِجِمَاعٍ فِي الْفَرْجِ، فَإِنَّهُ يَقْضِي، وَيُعْتِقُ رَقَبَةً، فَإِنْ لَمْ يَجِدْ،"]]},{"id":"um39_5","label":"بَابُ أَحْكَامِ الْمُفْطِرِينَ فِي رَمَضَانَ · ٥","segs":[["matn","فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ، فَإِنْ لَمْ يَسْتَطِعْ، فَإِطْعَامُ سِتِّينَ مِسْكِينًا، فَإِنْ لَمْ يَجِدْ، سَقَطَتْ عَنْهُ، فَإِنْ جَامَعَ وَلَمْ يُكَفِّرْ حَتَّى جَامَعَ ثَانِيَةً، فَكَفَّارَةٌ وَاحِدَةٌ. وَإِنْ كَفَّرَ، ثُمَّ جَامَعَ، فَكَفَّارَةٌ ثَانِيَةٌ."]]},{"id":"um39_6","label":"بَابُ أَحْكَامِ الْمُفْطِرِينَ فِي رَمَضَانَ · ٦","segs":[["matn","وَكُلُّ مَنْ لَزِمَهُ الإِمْسَاكُ فِي رَمَضَانَ، فَجَامَعَ، فَعَلَيْهِ كَفَّارَةٌ. وَمَنْ أَخَّرَ الْقَضَاءَ؛ لِعُذْرٍ حَتَّى أَدْرَكَهُ رَمَضَانُ آخَرُ، فَلَيْسَ عَلَيْهِ غَيْرُ الْقَضَاءِ وَإِنْ فَرَّطَ، أَطْعَمَ مَعَ الْقَضَاءِ لِكُلِّ يَوْمٍ مِسْكِينًا."]]},{"id":"um39_7","label":"بَابُ أَحْكَامِ الْمُفْطِرِينَ فِي رَمَضَانَ · ٧","segs":[["matn","وَإِنْ تَرَكَ الْقَضَاءَ حَتَّى مَاتَ لِعُذْرٍ، فَلَا شَيْءَ عَلَيْهِ، وَإِنْ كَانَ لِغَيْرِ عُذْرٍ، أُطْعِمَ عَنْهُ لِكُلِّ يَوْمٍ مِسْكِينٌ إِلَّا أَنْ يَكُونَ الصَّوْمُ مَنْذُورًا، فَإِنَّهُ يُصَامُ عَنْهُ، وَكَذَلِكَ كُلُّ نَذْرِ طَاعَةٍ."]]}],"group":"كِتَابُ الصِّيَامِ"},{"id":"um40","title":"بَابُ مَا يُفْسِدُ الصَّوْمَ","units":[{"id":"um40_1","label":"بَابُ مَا يُفْسِدُ الصَّوْمَ · ١","segs":[["matn","وَمَنْ أَكَلَ أَوْ شَرِبَ، أَوْ اسْتَعَطَ، أَوِ أَوْصَلَ إِلَى جَوْفِهِ شَيْئًا مِنْ أَيِّ مَوْضِعٍ كَانَ، أَوِ اسْتَقَاءَ فَقَاءَ أَوِ اسْتَمْنَى، أَوْ قَبَّلَ،"]]},{"id":"um40_2","label":"بَابُ مَا يُفْسِدُ الصَّوْمَ · ٢","segs":[["matn","أَوْ لَمَسَ، فَأَمْنَى أَوْ أَمْذَى، أَوْ كَرَّرَ النَّظَرَ حَتَّى أَنْزَلَ، أَوِ احْتَجَمَ، عَامِدًا، ذَاكِرًا لِصَوْمِهِ، فَسَدَ وَإِنْ فَعَلَهُ نَاسِيًا أَوْ مُكْرَهًا، لَمْ يَفْسُدْ، صَوْمُهُ."]]},{"id":"um40_3","label":"بَابُ مَا يُفْسِدُ الصَّوْمَ · ٣","segs":[["matn","وَإِنْ طَارَ إِلَى حَلْقِهِ ذُبَابٌ أَوْ غُبَارٌ، أَوْ تَمَضْمَضَ أَوِ اسْتَنْشَقَ، فَوَصَلَ إِلَى حَلْقِهِ مَاءٌ، أَوْ فَكَّرَ فَأَنْزَلَ، أَوْ قَطَّرَ فِي إِحْلِيلِهِ، أَوِ احْتَلَمَ، أَوْ ذَرَعَهُ الْقَيْءُ، لَمْ يَفْسُدْ صَوْمُهُ."]]},{"id":"um40_4","label":"بَابُ مَا يُفْسِدُ الصَّوْمَ · ٤","segs":[["matn","وَمَنْ أَكَلَ يَظُنُّهُ لَيْلاً، فَبَانَ نَهَارًا، فَعَلَيْهِ الْقَضَاءُ وَمَنْ أَكَلَ شَاكًّا فِي طُلُوعِ الْفَجْرِ، لَمْ يَفْسُدْ صَوْمُهُ، وَإِنْ أَكَلَ شَاكًّا فِي غُرُوبِ الشَّمْسِ فَعَلَيْهِ الْقَضَاءُ."]]}],"group":"كِتَابُ الصِّيَامِ"},{"id":"um41","title":"بَابُ صِيَامِ التَّطَوُّعِ","units":[{"id":"um41_1","label":"بَابُ صِيَامِ التَّطَوُّعِ · ١","segs":[["matn","أَفْضَلُ الصِّيَامِ صِيَامُ دَاوُدَ عَلَيْهِ السَّلَامُ، كَانَ يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمًا، وَأَفْضَلُ الصِّيَامِ بَعْدَ شَهْرِ رَمَضَانَ، شَهْرُ اللهِ الَّذِي يَدْعُونَهُ الْمُحَرَّمَ، وَمَا مِنْ أَيَّامٍ الْعَمَلُ الصَّالِحُ فِيهِنَّ أَحَبُّ إِلَى اللهِ مِنْ عَشْرِ ذِي الْحِجَّةِ،"]]},{"id":"um41_2","label":"بَابُ صِيَامِ التَّطَوُّعِ · ٢","segs":[["matn","وَمَنْ صَامَ رَمَضَانَ وَأَتْبَعَهُ بِسِتٍّ مِنْ شَوَّالٍ، فَكَأَنَّمَا صَامَ الدَّهْرَ كُلَّهُ، وَصِيَامُ يَوْمِ عَاشُورَاءَ كَفَّارَةُ سَنَةٍ، وَصِيَامُ يَوْمِ عَرَفَةَ كَفَّارَةُ سَنَتَيْنِ، وَلَا يُسْتَحَبُّ لِمَنْ بِعَرَفَةَ أَنْ يَصُومَهُ، وَيُسْتَحَبُّ صِيَامُ أَيَّامِ الْبِيضِ، وَالِاثْنَيْنِ وَالْخَمِيسِ."]]},{"id":"um41_3","label":"بَابُ صِيَامِ التَّطَوُّعِ · ٣","segs":[["matn","وَالصَّائِمُ الْمُتَطَوِّعُ أَمِيرُ نَفْسِهِ، إِنْ شَاءَ صَامَ، وَإِنْ شَاءَ أَفْطَرَ، وَلَا قَضَاءَ عَلَيْهِ وَكَذَلِكَ سَائِرُ التَّطَوُّعِ، إِلَّا الْحَجَّ وَالْعُمْرَةَ، فَإِنَّهُ يَجِبُ إِتْمَامُهُمُا، وَقَضَاءُ مَا أَفْسَدَ مِنْهُمَا."]]},{"id":"um41_4","label":"بَابُ صِيَامِ التَّطَوُّعِ · ٤","segs":[["matn","وَنَهَى رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ صَوْمِ يَوْمَيْنِ: يَوْمِ الْفِطْرِ، وَيَوْمِ الْأَضْحَى وَنَهَى عَنْ صَوْمِ أَيَّامِ التَّشْرِيقِ، إِلَّا أَنَّهُ رَخَّصَ فِي صَوْمِهَا لِلْمُتَمَتِّعِ، إِذَا لَمْ يَجِدِ الْهَدْيَ، وَلَيْلَةُ الْقَدْرِ فِي الْوِتْرِ مِنَ الْعَشْرِ الأَوَاخِرِ مِنْ رَمَضَانَ."]]}],"group":"كِتَابُ الصِّيَامِ"},{"id":"um42","title":"بَابُ الِاعْتَكَافِ","units":[{"id":"um42_1","label":"بَابُ الِاعْتَكَافِ · ١","segs":[["matn","وَهُوَ لُزُومُ الْمَسْجِدِ، لِطَاعَةِ اللهِ تَعَالَى فِيهِ، وَهُوَ سُنَّةٌ، إِلَّا أَنْ يَكُونَ نَذْرًا، فَيَلْزَمُ الْوَفَاءُ بِهِ."]]},{"id":"um42_2","label":"بَابُ الِاعْتَكَافِ · ٢","segs":[["matn","وَيَصِحُّ مِنَ الْمَرْأَةِ فِي كُلِّ مَسْجِدٍ، غَيْرِ مَسْجِدِ بَيْتِهَا، وَلَا يَصِحُّ مِنَ الرَّجُلِ إِلَّا فِي مَسْجِدٍ تُقَامُ فِيهِ الْجَمَاعَةُ، وَاعْتِكَافُهُ فِي مَسْجِدٍ تُقَامُ فِيهِ الْجُمُعَةُ أَفْضَلُ."]]},{"id":"um42_3","label":"بَابُ الِاعْتَكَافِ · ٣","segs":[["matn","وَمَنْ نَذَرَ الِاعْتِكَافَ، أَوِ الصَّلَاةَ فِي مَسْجِدٍ، فَلَهُ فِعْلُ ذَلِكَ فِي غَيْرِهِ، إِلَّا الْمَسَاجِدَ الثَّلَاثَةَ، فَإِذَا نَذَرَ ذَلِكَ فِي الْمَسْجِدِ الْحَرَامِ، لَزِمَهُ،"]]},{"id":"um42_4","label":"بَابُ الِاعْتَكَافِ · ٤","segs":[["matn","وَإِنْ نَذَرَ الِاعْتِكَافَ فِي مَسْجِدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، جَازَ لَهُ أَنْ يَعْتَكِفَ فِي الْمَسْجِدِ الْحَرَامِ وَإِنْ نَذَرَ أَنْ يَعْتَكِفَ فِي الْمَسْجِدِ الأَقْصَى، فَلَهُ فِعْلُهُ فِي أَيِّهِمَا أَحَبَّ."]]},{"id":"um42_5","label":"بَابُ الِاعْتَكَافِ · ٥","segs":[["matn","وَيُسْتَحَبُّ لِلْمُعْتَكِفِ الِاشْتِغَالُ بِفِعْلِ الْقُرَبِ وَاجْتِنَابُ مَا لَا يَعْنِيهِ مِنْ قَوْلٍ وَفِعْلٍ، وَلَا يَبْطُلُ الِاعْتِكَافُ بِشَيْءٍ مِنْ ذَلِكَ."]]},{"id":"um42_6","label":"بَابُ الِاعْتَكَافِ · ٦","segs":[["matn","وَلَا يَخْرُجُ مِنَ الْمَسْجِدِ، إِلَّا لِمَا لَا بُدَّ لَهُ مِنْهُ، إِلَّا أَنْ يَشْتَرِطَ، وَلَا يُبَاشِرُ امْرَأَةً، وَإِنْ سَأَلَ عَنِ الْمَرِيضِ فِي طَرِيقِهِ أَوْ عَنْ غَيْرِهِ وَلَمْ يُعَرِّجْ إِلَيْهِ، جَازَ."]]}],"group":"كِتَابُ الصِّيَامِ"},{"id":"um43","title":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ","units":[{"id":"um43_1","label":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ · ١","segs":[["matn","يَجِبُ الْحَجُّ وَالعُمْرَةُ مَرَّةً فِي الْعُمُرِ، عَلَى الْمُسْلِمِ، الْعَاقِلِ، الْبَالِغِ، الْحُرِّ، إِذَا اسْتَطَاعَ إِلَيْهِ سَبِيلاً، وَالِاسْتِطَاعَةُ أَنْ يَجِدَ زَادًا، وَرَاحِلَةً بِآلَتِهِمَا، مِمَّا يَصْلُحُ لِمِثْلِهِ، فَاضِلاً عَمَّا يَحْتَاجُ إِلَيْهِ لِقَضَاءِ دَيْنِهِ، وَمُؤْنَةِ نَفْسِهِ، وَعِيَالِهِ عَلَى الدَّوَامِ."]]},{"id":"um43_2","label":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ · ٢","segs":[["matn","وَيُعْتَبَرُ لِلْمَرْأَةِ وُجُودُ مَحْرَمِهَا وَهُوَ زَوْجُهَا، وَمَنْ تَحْرُمُ عَلَيْهِ عَلَى التَّأْبِيدِ بِنَسَبٍ، أَوْ سَبَبٍ مُبَاحٍ. فَمَنْ فَرَّطَ حَتَّى مَاتَ، أُخْرِجَ عَنْهُ مِنْ مَالِهِ، حَجَّةٌ، وَعُمْرَةٌ."]]},{"id":"um43_3","label":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ · ٣","segs":[["matn","وَلَا يَصِحُّ الْحَجَّ مِنْ كَافِرٍ، وَلَا مَجْنُونٍ، وَيَصِحُّ مِنَ الصَّبِيِّ، وَالْعَبْدِ، وَلَا يُجْزِئُهُمَا، عَنْهُمَا وَيَصِحُّ مِنْ غَيْرِ الْمُسْتَطِيعِ وَالْمَرْأَةِ بِغَيْرِ مَحْرَمٍ."]]},{"id":"um43_4","label":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ · ٤","segs":[["matn","وَمَنْ حَجَّ عَنْ غَيْرِهِ، وَلَمْ يَكُنْ حَجَّ عَنْ نَفْسِهِ، أَوْ عَنْ نَذْرِهِ أَوْ عَنْ نَفْلِهِ، وَفَعَلَهُ قَبْلَ حَجَّةِ الإِسْلَامِ، وَقَعَ حَجُّهُ عَنْ فَرْضِ نَفْسِهِ، دُونَ غَيْرهِ."]]}],"group":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ"},{"id":"um44","title":"بَابُ الْمَوَاقِيتِ","units":[{"id":"um44_1","label":"بَابُ الْمَوَاقِيتِ · ١","segs":[["matn","وَمِيقَاتُ أَهْلِ الْمَدِينَةِ: ذُو الْحُلَيْفَةِ، وَأَهْلِ الشَّامِ وَالْمَغْرِبِ وَمِصْرَ الْجُحْفَةُ، وَالْيَمَنِ: يَلَمْلَمُ، وَلِنَجْدٍ: قَرْنٌ، وَلِلْمَشْرِقِ: ذَاتُ عِرْقٍ فَهَذِهِ الْمَوَاقِيتُ لِأَهْلِهَا وَلِكُلِّ مَنْ يَمُرُّ عَلَيْهَا وَمَنْ مَنْزِلُهُ دُونَ الْمِيقَاتِ،"]]},{"id":"um44_2","label":"بَابُ الْمَوَاقِيتِ · ٢","segs":[["matn","فَمِيقَاتُهُ مِنْ مَنْزِلِهِ حَتَّى أَهْلُ مَكَّةَ يُهِلُّونَ مِنْهَا لِحَجِّهِمْ، وَيُهِلُّونَ لِلْعُمْرَةِ مِنَ أَدْنَى الْحِلِّ، وَمَنْ لَمْ يَكُنْ طَرِيقُهُ عَلَى مِيقَاتٍ، فَمِيقَاتُهُ حَذْوَ أَقْرَبِهَا إِلَيْهِ."]]},{"id":"um44_3","label":"بَابُ الْمَوَاقِيتِ · ٣","segs":[["matn","وَلَا يَجُوزُ لِمَنْ أَرَادَ دُخُولَ مَكَّةَ تَجَاوُزُ الْمِيقَاتِ غَيْرَ مُحْرِمٍ، إِلَّا لِقِتَالٍ مُبَاحٍ، وَحَاجَةٍ تَتَكَرَّرُ، كَالْحَطَّابِ وَنَحْوِهِ."]]},{"id":"um44_4","label":"بَابُ الْمَوَاقِيتِ · ٤","segs":[["matn","ثُمَّ إِذَا أَرَادَ النُّسُكَ، أَحْرَمَ مِنْ مَوْضِعِهِ، وَإِنْ جَاوَزَهُ غَيْرَ مُحْرِمٍ رَجَعَ فَأَحْرَمَ مِنَ الْمِيقَاتِ، وَلَا دَمَ عَلَيْهِ؛"]]},{"id":"um44_5","label":"بَابُ الْمَوَاقِيتِ · ٥","segs":[["matn","لِأَنَّهُ أَحْرَمَ مِنْ مِيقَاتِهِ فَإِنْ أَحْرَمَ مِنْ دُونِهِ، فَعَلَيْهِ دَمٌ، سَوَاءٌ رَجَعَ إِلَى الْمِيقَاتِ، أَوْ لَمْ يَرْجِعْ وَالأَفْضَلُ أَنْ لَا يُحْرِمَ قَبْلَ الْمِيقَاتِ، فَإِنْ فَعَلَ فَهُوَ مُحْرِمٌ."]]},{"id":"um44_6","label":"بَابُ الْمَوَاقِيتِ · ٦","segs":[["matn","وَأَشْهُرُ الْحَجِّ: شَوَّالٌ، وَذُو الْقَعْدَةِ، وَعَشْرٌ مِنْ ذِي الْحِجَّةِ."]]}],"group":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ"},{"id":"um45","title":"بَابُ الإِحْرَامِ","units":[{"id":"um45_1","label":"بَابُ الإِحْرَامِ · ١","segs":[["matn","مَنْ أَرَادَ الإِحْرَامَ اسْتُحِبَّ لَهُ أَنْ يَغْتَسِلَ، وَيَتَنَظَّفَ، وَيَتَطَيَّبَ، وَيَتَجَرَّدَ عَنِ الْمَخِيطِ وَيَلْبَسَ إِزَارًا وَرِدَاءً أَبْيَضَيْنِ نَظِيفَيْنِ، ثُمَّ يُصَلِّيَ رَكْعَتَيْنِ وَيُحْرِمَ عَقِيبَهُمَا، وَهُوَ أَنْ يَنْوِيَ الإِحْرَامَ، وَيُسْتَحَبُّ أَنْ يَنْطِقَ بِمَا أَحْرَمَ بِهِ."]]},{"id":"um45_2","label":"بَابُ الإِحْرَامِ · ٢","segs":[["matn","وَيَشْتَرِطَ، وَيَقُولُ: اللهُمَّ إِنِّي أُرِيدُ النُّسُكَ الْفُلَانِيَّ، فَإِنْ حَبَسَنِي حَابِسٌ، فَمَحَلِّي حَيْثُ حَبَسْتَنِي."]]},{"id":"um45_3","label":"بَابُ الإِحْرَامِ · ٣","segs":[["matn","وَهُوَ مُخَيَّرٌ بَيْنَ التَّمَتُّعِ، وَالإِفْرَادِ، وَالْقِرَانِ، وَأَفْضَلُهَا التَّمَتُّعُ، ثُمَّ الإِفْرَادُ، ثُمَّ الْقِرَانُ، وَالتَّمَتُّعُ: أَنْ يُحْرِمَ بِالْعُمْرَةِ فِي أَشْهُرِ الْحَجِّ، وَيَفْرَغُ مِنْهَا، ثُمَّ يُحْرِمَ بِالْحَجِّ فِي عَامِهِ، وَالإِفْرَادُ: أَنْ يُحْرِمَ بِالْحَجِّ وَحْدَهُ."]]},{"id":"um45_4","label":"بَابُ الإِحْرَامِ · ٤","segs":[["matn","وَالْقِرَانُ: أَنْ يُحْرِمَ بِهِمَا، أَوْ يُحْرِمَ بِالْعُمْرَةِ ثُمَّ يُدْخِلُ عَلَيْهَا الْحَجَّ، وَلَوْ أَحْرَمَ بِالْحَجِّ، ثُمَّ أَدْخَلَ عَلَيْهِ العُمْرَةَ، لَمْ يَنْعَقِدْ إِحْرَامُهُ بِالْعُمْرَةِ."]]},{"id":"um45_5","label":"بَابُ الإِحْرَامِ · ٥","segs":[["matn","فَإِذَا اسْتَوَى عَلَى رَاحِلَتِهِ لَبَّى، فَقَالَ لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الحَمْدَ وَالنِّعْمَةَ لَكَ وَالمُلْكَ، لَا شَرِيكَ لَكَ."]]},{"id":"um45_6","label":"بَابُ الإِحْرَامِ · ٦","segs":[["matn","وَيُسْتَحَبُّ الإِكْثَارُ مِنْهَا وَرَفْعُ الصَّوْتِ بِهَا لِغَيْرِ النِّسَاءِ وَهِيَ آكَدُ فِيمَا إِذَا عَلَا نَشَزًا، أَوْ هَبَطَ وَادِيًا، أَوْ سَمِعَ مُلَبِّيًا، أَوْ فَعَلَ مَحْظُورًا نَاسِيًا، أَوْ لَقِيَ رَكْبًا وَفِي أَدْبَارِ الصَّلَاةِ، الْمَكْتُوبَةِ وَبِالأَسْحَارِ، وَإِقْبَالِ اللَّيْلِ وَالنَّهَارِ."]]}],"group":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ"},{"id":"um46","title":"بَابُ مَحْظُورَاتِ الإِحْرَامِ","units":[{"id":"um46_1","label":"بَابُ مَحْظُورَاتِ الإِحْرَامِ · ١","segs":[["matn","وَهِيَ تِسْعَةٌ: حَلْقُ الشَّعَرِ، وَقَلْمُ الظُّفُرِ فَفِي ثَلَاثَةٍ مِنْهَا دَمٌ، وَفِي كُلِّ وَاحِدٍ مِمَّا دُونَهُ مُدُّ طَعَامٍ، وَهُوَ رُبُعُ الصَّاعِ وَإِنْ خَرَجَ فِي عَيْنِهِ شَعَرٌ فَقَلَعَهُ، أَوْ نَزَلَ شَعَرُهُ فَغَطَّى عَيْنَهُ أَوِ انْكَسَرَ ظُفْرُهُ فَقَصَّهُ، فَلَا شَيْءَ عَلَيْهِ."]]},{"id":"um46_2","label":"بَابُ مَحْظُورَاتِ الإِحْرَامِ · ٢","segs":[["matn","الثَّالِثُ: لُبْسُ المَخِيطِ إِلَّا أَنْ لَا يَجِدَ إِزَارًا، فَيَلْبَسَ سَرَاوِيلَ، أَوْ لَا يَجِدَ نَعْلَيْنِ، فَيَلْبَسَ خُفَّيْنِ، وَلَا فِدْيَةَ عَلَيْهِ. الرَّابِعُ: تَغْطِيَةُ الرَّأْسِ، وَالأُذُنَانِ مِنْهُ. الخَامِسُ: الطِّيبُ فِي بَدَنِهِ وَثِيَابِهِ."]]},{"id":"um46_3","label":"بَابُ مَحْظُورَاتِ الإِحْرَامِ · ٣","segs":[["matn","السَّادِسُ: قَتْلُ الصَّيْدِ وَهُوَ: مَا كَانَ وَحْشِيًّا مُبَاحًا، وَأَمَّا الْأَهْلِيُّ فَلَا يَحْرُمُ، وَأَمَّا صَيْدُ الْبَحْرِ فَإِنَّهُ مُبَاحٌ. السَّابِعُ: عَقْدُ النِّكَاحِ حَرَامٌ وَلَا فِدْيَةَ فِيهِ."]]},{"id":"um46_4","label":"بَابُ مَحْظُورَاتِ الإِحْرَامِ · ٤","segs":[["matn","الثَّامِنُ: الْمُبَاشَرَةُ لِشَهْوَةٍ فِيمَا دُونَ الْفَرْجِ فَإِنْ أَنْزَلَ بِهَا فَعَلَيْهِ بَدَنَةٌ، وَإِلَّا فَفِيهَا شَاةٌ. وَحَجُّهُ صَحِيحٌ."]]},{"id":"um46_5","label":"بَابُ مَحْظُورَاتِ الإِحْرَامِ · ٥","segs":[["matn","التَّاسِعُ: الْوَطْءُ فِي الْفَرْجِ فَإِنْ كَانَ قَبْلَ التَّحَلُّلِ الأَوَّلِ، فَسَدَ الْحَجُّ وَوَجَبَ الْمُضِيُّ فِي فَاسِدِهِ، وَالْحَجُّ مِنْ قَابِلٍ، وَيَجِبُ عَلَى الْمُجَامِعِ بَدَنَةٌ وَإِنْ كَانَ بَعْدَ التَّحَلُّلِ الأَوَّلِ، فَفِيهِ شَاةٌ، وَيُحْرِمُ مِنَ التَّنْعِيمِ؛"]]},{"id":"um46_6","label":"بَابُ مَحْظُورَاتِ الإِحْرَامِ · ٦","segs":[["matn","لِيَطُوفَ مُحْرِمًا، وَإِنْ وَطِئَ فِي الْعُمْرَةِ، أَفْسَدَهَا وَلَا يُفْسِدُ النُّسُكُ بِغَيْرِهِ. وَالْمَرْأَةُ كَالرَّجُلِ، إِلَّا أَنَّ إِحْرَامَهَا فِي وَجْهِهَا، وَلَهَا لُبْسُ الْمَخِيطِ."]]}],"group":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ"},{"id":"um47","title":"بَابُ الْفِدْيَةِ","units":[{"id":"um47_1","label":"بَابُ الْفِدْيَةِ · ١","segs":[["matn","وَهِيَ عَلَى ضَرْبَيْنِ: أَحَدُهُمَا: عَلَى التَّخْيِيرِ وَهِيَ فِدْيَةُ الأَذَى وَاللُّبْسِ وَالطِّيبِ فَلَهُ الْخِيَارُ بَيْنَ صِيَامِ ثَلَاثَةِ أَيَّامٍ، أَوْ إِطْعَامِ ثَلَاثَةِ آصُعٍ مِنْ تَمْرٍ لِسِتَّةِ مَسَاكِينَ، أَوْ ذَبْحِ شَاةٍ وَجَزَاءُ الصَّيْدِ مِثْلُ مَا قَتَلَ مِنَ النَّعَمِ إِلَّا الطَّائِرَ،"]]},{"id":"um47_2","label":"بَابُ الْفِدْيَةِ · ٢","segs":[["matn","فَإِنَّ فِيهِ قِيمَتَهُ إِلَّا الْحَمَامَةَ، فَفِيهَا شَاةٌ وَالنَّعَامَةُ، فِيهَا بَدَنَةٌ، وَيَتَخَيَّرُ بَيْنَ إِخْرَاجِ الْمِثْلِ وَتَقْوِيمِهِ بِطَعَامٍ فَيُطْعِمُ كُلَّ مِسْكِينٍ مُدًّا أَوْ يَصُومُ عَنْ كُلِّ مُدٍّ يَوْمًا."]]},{"id":"um47_3","label":"بَابُ الْفِدْيَةِ · ٣","segs":[["matn","الضَّرْبُ الثَّانِي: عَلَى التَّرْتِيبِ: وَهُوَ الْمُتَمَتِّعُ يَلْزَمُهُ شَاةٌ، فَإِنْ لَمْ يَجِدْ، فَصِيَامُ ثَلَاثَةِ أَيَّامٍ فِي الْحَجِّ وَسَبْعَةٍ إِذَا رَجَعَ."]]},{"id":"um47_4","label":"بَابُ الْفِدْيَةِ · ٤","segs":[["matn","وَفِدْيَةُ الْجِمَاعِ بَدَنَةٌ فَإِنْ لَمْ يَجِدْ، فَصِيُامُ كَصِيَامِ الْمُتَمَتِّعِ وَكَذَلِكَ الْحُكْمُ فِي دَمِ الْفَوَاتِ. وَالْمُحْصَرِ يَلْزَمُهُ دَمٌ فَإِنْ لَمْ يَجِدْ، فَصِيَامُ عَشَرَةِ أَيَّامٍ."]]},{"id":"um47_5","label":"بَابُ الْفِدْيَةِ · ٥","segs":[["matn","وَمَنْ كَرَّرَ مَحْظُورًا مِنْ جِنْسٍ غَيْرِ قَتْلِ الصَّيْدِ فَكَفَّارَةٌ وَاحِدَةٌ فَإِنْ كَفَّرَ عَنِ الأَوَّلِ قَبْلَ فِعْلِ الثَّانِي سَقَطَ حُكْمُ مَا كَفَّرَ عَنْهُ وَإِنْ فَعَلَ مَحْظُورًا مِنْ أَجْنَاسٍ، فَلِكُلِّ وَاحِدٍ كَفَّارَةٌ."]]},{"id":"um47_6","label":"بَابُ الْفِدْيَةِ · ٦","segs":[["matn","وَالْحَلْقُ وَالتَّقْلِيمُ وَالْوَطْءُ وَقَتْلُ الصَّيْدِ يَسْتَوِي عَمْدُهُ وَسَهْوُهُ، وَسَائِرُ الْمَحْظُورَاتِ لَا شَيْءَ فِي سَهْوِهِ."]]},{"id":"um47_7","label":"بَابُ الْفِدْيَةِ · ٧","segs":[["matn","وَكُلُّ هَدْيٍ أَوْ إِطْعَامٍ، فَهُوَ لِمَسَاكِينِ الْحَرَمِ إِلَّا فِدْيَةَ الأَذَى فَإِنَّهُ يُفَرِّقُهَا فِي الْمَوْضِعِ الَّذِي حَلَقَ بِهِ وَهَدْيُ الْمُحْصَرِ يَنْحَرُهُ فِي مَوْضِعِهِ، وَأَمَّا الصِّيَامُ فَيُجْزِئُهُ بِكُلِّ مَكَانٍ."]]}],"group":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ"},{"id":"um48","title":"بَابُ دُخُولِ مَكَّةَ","units":[{"id":"um48_1","label":"بَابُ دُخُولِ مَكَّةَ · ١","segs":[["matn","يُسْتَحَبُّ أَنْ يَدْخُلَ مَكَّةَ مِنْ أَعْلَاهَا وَيَدْخُلَ الْمَسْجِدَ مِنْ."]]},{"id":"um48_2","label":"بَابُ دُخُولِ مَكَّةَ · ٢","segs":[["matn","بَابِ بَنِي شَيْبَةَ؛ لِأَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، دَخَلَ مِنْهُ فَإِذَا رَأَى البَيْتَ، رَفَعَ يَدَيْهِ، وَكَبَّرَ اللهَ وَحَمِدَهُ، وَدَعَا، ثُمَّ يَبْتَدِئُ بِطَوَافِ الْعُمْرَةِ،"]]},{"id":"um48_3","label":"بَابُ دُخُولِ مَكَّةَ · ٣","segs":[["matn","إِنْ كَانَ مُعْتَمِرًا أَوْ بِطَوَافِ الْقُدُومِ، إِنْ كَانَ مُفْرِدًا أَوْ قَارِنًا فَيَضْطَبِعُ بِرِدَائِهِ فَيَجْعَلَ وَسْطَهُ تَحْتَ عَاتِقِهِ الأَيْمَنِ وَطَرْفَيْهِ عَلَى عَاتِقِهِ الأَيْسَرِ، وَيَبْدَأُ بِالْحَجَرِ الأَسْوَدِ فَيَسْتَلِمُهُ وَيُقَبِّلُهُ وَيَقُولُ:"]]},{"id":"um48_4","label":"بَابُ دُخُولِ مَكَّةَ · ٤","segs":[["matn","بِسْمِ اللهِ، وَاللهُ أَكْبَرُ اللهُمَّ إِيمَانًا بِكَ، وَتَصْدِيقًا بِكِتَابِكَ، وَوَفَاءً بِعَهْدِكَ، وَاتِّبَاعًا لِسُنَّةِ نَبِيِّكَ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثُمَّ يَأْخُذُ عَنْ يَمِينِهِ وَيَجْعَلُ الْبَيْتَ عَنْ يَسَارِهِ فَيَطُوفُ سَبْعًا،"]]},{"id":"um48_5","label":"بَابُ دُخُولِ مَكَّةَ · ٥","segs":[["matn","يَرْمُلُ فِي الثَّلَاثَةِ الأُوَلِ مِنَ الْحَجَرِ إِلَى الْحَجَرِ، وَيَمْشِي فِي الأَرْبَعَةِ الأخرَى وَكُلَّمَا حَاذَى الرُّكْنَ اليَمَانِيَّ وَالْحَجَرَ، اسْتَلَمَهُمَا، وَكَبَّرَ وَهَلَّلَ وَيَقُولُ بَيْنَ الرُّكْنَيْنِ:"]]},{"id":"um48_6","label":"بَابُ دُخُولِ مَكَّةَ · ٦","segs":[["matn","﴿رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ﴾ وَيَدْعُو فِي سَائِرِهِ بِمَا أَحَبَّ، ثُمَّ يُصَلِّي رَكْعَتَيْنِ خَلْفَ الْمَقَامِ،"]]},{"id":"um48_7","label":"بَابُ دُخُولِ مَكَّةَ · ٧","segs":[["matn","وَيَعُودُ إِلَى الرُّكْنِ فَيَسْتَلِمُهُ ثُمَّ يَخْرُجُ إِلَى الصَّفَا مِنْ بَابِهِ فَيَرْقَى عَلَيْهِ وَيُكَبِّرُ اللهَ وَيُهَلِّلُهُ وَيَدْعُوهُ ثُمَّ يَنْزِلُ فَيَمْشِي إِلَى العَلَمِ، ثُمَّ يَسْعَى إِلَى الْعَلَمِ الآخَرِ، ثُمَّ يَمْشِي حَتَّى يَأْتِيَ الْمَرْوَةِ فَيَفْعَلُ كَفِعْلِهِ عَلَى الصَّفَا،"]]},{"id":"um48_8","label":"بَابُ دُخُولِ مَكَّةَ · ٨","segs":[["matn","ثُمَّ يَنْزِلُ فَيَمْشِي فِي مَوْضِعِ مَشْيِهِ، وَيَسْعَى فِي مَوْضِعِ سَعْيِهِ حَتَّى يُكْمِلَ سَبْعَةَ أَشْوَاطٍ يَحْتَسِبُ بِالذَّهَابِ سَعْيَةً وَبِالرُّجُوعِ سَعْيَةً، يَفْتَتِحُ بِالصَّفَا وَيَخْتَتِمُ بِالْمَرْوَةِ، ثُمَّ يُقَصِّرُ مِنْ شَعَرِهِ،"]]},{"id":"um48_9","label":"بَابُ دُخُولِ مَكَّةَ · ٩","segs":[["matn","إِنْ كَانَ مُعْتَمِرًا وَقَدْ حَلَّ، إِلَّا الْمُتَمَتِّعَ إِنْ كَانَ مَعَهُ هَدْيٌ وَالْقَارِنَ وَالْمُفْرِدَ فَإِنَّهُ لَا يَحِلُّ، وَالْمَرْأَةُ كَالرَّجُلِ، إِلَّا أَنَّهَا لَا تَرْمُلُ فِي طَوَافٍ وَلَا سَعْيٍ."]]}],"group":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ"},{"id":"um49","title":"بَابُ صِفَةِ الْحَجِّ","units":[{"id":"um49_1","label":"بَابُ صِفَةِ الْحَجِّ · ١","segs":[["matn","وَإِذَا كَانَ يَوْمُ التَّرْوِيَةِ، فَمَنْ كَانَ حَلَالاً، أَحْرَمَ مِنْ مَكَّةَ، وَخَرَجَ إِلَى عَرَفَاتٍ، فَإِذَا زَالَتِ الشَّمْسُ يَوْمَ عَرَفَةَ، صَلَّى الظُّهْرَ وَالْعَصْرَ يَجْمَعُ بَيْنَهُمَا بِأَذَانٍ وَإِقَامَتَيْنِ،"]]},{"id":"um49_2","label":"بَابُ صِفَةِ الْحَجِّ · ٢","segs":[["matn","ثُمَّ يَرُوحُ إِلَى الْمَوْقِفِ، وَعَرَفَاتٌ كُلُّهَا مَوْقِفٌ، إِلَّا بَطْنُ عُرَنَةَ، وَيُسْتَحَبُّ أَنْ يَقِفَ فِي مَوْقِفِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، أَوْ قَرِيبًا مِنْهُ، عَلَى الْجَبَلِ قَرِيبًا مِنَ الصَّخَرَاتِ،"]]},{"id":"um49_3","label":"بَابُ صِفَةِ الْحَجِّ · ٣","segs":[["matn","وَيَجْعَلُ حَبْلَ الْمُشَاةِ بَيْنَ يَدَيْهِ، وَيَسْتَقْبِلُ الْقِبْلَةَ، وَيَكُونُ رَاكِبًا، وَيُكْثِرُ مِنْ قَوْلِ: لَا إِلهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، بِيَدِهِ الْخَيْرُ،"]]},{"id":"um49_4","label":"بَابُ صِفَةِ الْحَجِّ · ٤","segs":[["matn","وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، وَيَجْتَهِدُ فِي الدُّعَاءِ وَالرَّغْبَةِ إِلَى اللهِ عَزَّ وَجَلَّ، إِلَى غُرُوبِ الشَّمْسِ، ثُمَّ يَدْفَعُ مَعَ الإِمَامِ إِلَى مُزْدَلِفَةٍ، عَلَى طَرِيقِ الْمَأْزِمَيْنِ وَعَلَيْهِ السَّكِينَةُ وَالْوَقَارُ."]]},{"id":"um49_5","label":"بَابُ صِفَةِ الْحَجِّ · ٥","segs":[["matn","وَيَكُونُ مُلَبِّيًا ذَاكِرًا لِلَّهِ عَزَّ وَجَلَّ، فَإِذَا وَصَلَ إِلَى مُزْدَلِفَةَ صَلَّى بِهَا الْمَغْرِبَ وَالْعِشَاءَ قَبْلَ حَطِّ الرِّحَالِ، يَجْمَعُ بَيْنَهُمَا ثُمَّ يَبِيتُ بِهَا ثُمَّ يُصَلِّي الْفَجْرَ بِغَلَسٍ وَيَأْتِي الْمَشْعَرَ الْحَرَامَ،"]]},{"id":"um49_6","label":"بَابُ صِفَةِ الْحَجِّ · ٦","segs":[["matn","فَيَقِفُ عِنْدَهُ، وَيَدْعُو وَيُسْتَحَبُّ أَنْ يَكُونَ مِنْ دُعَائِهِ: اللهُمَّ كَمَا وَقَفْتَنَا فِيهِ، وَأَرَيْتَنَا إِيَّاهُ، فَوَفِّقْنَا لِذِكْرِكَ، كَمَا هَدَيْتَنَا، وَاغْفِرْ لَنَا وَارْحَمْنَا، كَمَا وَعَدْتَنَا بِقَوْلِكِ، وَقَوْلُكَ الْحَقُّ:"]]},{"id":"um49_7","label":"بَابُ صِفَةِ الْحَجِّ · ٧","segs":[["matn","﴿فَإِذَا أَفَضْتُمْ مِنْ عَرَفَاتٍ فَاذْكُرُوا اللهَ عِنْدَ الْمَشْعَرِ الْحَرَامِ وَاذْكُرُوهُ كَمَا هَدَاكُمْ وَإِنْ كُنْتُمْ مِنْ قَبْلِهِ لَمِنَ الضَّالِّينَ ثُمَّ أَفِيضُوا مِنْ حَيْثُ أَفَاضَ النَّاسُ وَاسْتَغْفِرُوا اللَّهَ إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ﴾ وَيَقِفُ حَتَّى يُسْفِرَ جِدًّا ثُمَّ يَدْفَعُ قَبْلَ طُلُوعِ الشَّمْسِ،"]]},{"id":"um49_8","label":"بَابُ صِفَةِ الْحَجِّ · ٨","segs":[["matn","فَإِذَا بَلَغَ مُحَسِّرًا أَسْرَعَ قَدْرَ رَمْيَةٍ بِحَجَرٍ، حَتَّى يَأْتِيَ مِنًى، فَيَبْتَدِئُ بِجَمْرَةِ الْعَقَبَةِ فَيَرْمِيهَا بِسَبْعِ حَصَيَاتٍ كَحَصَى الْخَذْفِ، يُكَبِّرُ مَعَ كُلِّ حَصَاةٍ، وَيَرْفَعُ يَدَيْهِ فِي الرَّمْيِ، وَيَقْطَعُ التَّلْبِيَةَ بِابْتِدَاءِ الرَّمْيِ، وَيَسْتَبْطِنُ الْوَادِيَ وَيَسْتَقْبِلُ الْقِبْلَةَ وَلَا يَقِفُ عِنْدَهَا، ثُمَّ يَنْحَرُ هَدْيَهُ،"]]},{"id":"um49_9","label":"بَابُ صِفَةِ الْحَجِّ · ٩","segs":[["matn","ثُمَّ يَحْلِقُ رَأْسَهُ أَوْ يُقَصِّرُهُ ثُمَّ قَدْ حَلَّ لَهُ كُلُّ شَيْءٍ إِلَّا النِّسَاءِ ثُمَّ يُفِيضُ إِلَى مَكَّةَ، فَيَطُوفُ لِلزِّيَارَةِ،"]]},{"id":"um49_10","label":"بَابُ صِفَةِ الْحَجِّ · ١٠","segs":[["matn","وَهُوَ الطَّوَافُ الْوَاجِبُ الَّذِي بِهِ تَمَامُ الْحَجِّ، ثُمَّ يَسْعَى بَيْنَ الصَّفَا وَالْمَرْوَةِ، إِنْ كَانَ مُتَمَتِّعًا، أَوْ مِمَّنْ لَمْ يَسْعَ مَعَ طَوَافِ القُدُومِ. ثُمَّ قَدْ حَلَّ مِنْ كُلِّ شَيْءٍ."]]},{"id":"um49_11","label":"بَابُ صِفَةِ الْحَجِّ · ١١","segs":[["matn","وَيُسْتَحَبُّ أَنْ يَشْرَبَ مِنْ مَاءِ زَمْزَمَ لِمَا أحبَّ وَيَتَضَلَّعَ مِنْهُ ثُمَّ يَقُولُ: اللهُمَّ اجْعَلْهُ لَنَا عِلْمًا نَافِعًا، وَرِزْقًا وَاسِعًا، وَرِيًّا وَشِبَعًا، وَشِفَاءً مِنْ كُلِّ دَاءٍ، وَاغْسِلْ بِهِ قَلْبِي، وَامْلأْهُ مِنْ خَشْيَتِكَ وَحِكْمَتِكَ."]]}],"group":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ"},{"id":"um50","title":"بَابُ مَا يَفْعَلُهُ بَعْدَ الْحِلِّ","units":[{"id":"um50_1","label":"بَابُ مَا يَفْعَلُهُ بَعْدَ الْحِلِّ · ١","segs":[["matn","ثُمَّ يَرْجِعُ إِلَى مِنَى وَلَا يَبِيتُ لَيَالِيَهَا إِلَّا بِهَا فَيَرْمِي بِهَا الْجَمَرَاتِ بَعْدَ الزَّوَالِ مِنْ أَيَّامِهَا، كُلَّ جَمْرَةٍ بِسَبْعٍ حَصَيَاتٍ،"]]},{"id":"um50_2","label":"بَابُ مَا يَفْعَلُهُ بَعْدَ الْحِلِّ · ٢","segs":[["matn","يَبْتَدِئُ بِالْجَمْرَةِ الأُولَى، فَيَسْتَقْبِلُ الْقِبْلَةَ، وَيَرْمِيهَا بِسَبْعٍ حَصَيَاتٍ كَمَا رَمَى جَمْرَةَ الْعَقَبَةِ، ثُمَّ يَتَقَدَّمَ فَيَقِفُ فَيَدْعُو اللَّهَ ثُمَّ يَأْتِي الْوُسْطَى، فَيَرْمِيهَا كَذَلِكَ."]]},{"id":"um50_3","label":"بَابُ مَا يَفْعَلُهُ بَعْدَ الْحِلِّ · ٣","segs":[["matn","ثُمَّ يَرْمِي جَمْرَةَ الْعَقَبَةِ، وَلَا يَقِفُ عِنْدَهَا، ثُمَّ يَرْمِي فِي الْيَوْمِ الثَّانِي كَذَلِكَ، فَإِنْ أَحَبَّ أَنْ يَتَعَجَّلَ فِي يَوْمَيْنِ خَرَجَ قَبْلَ الْغُرُوبِ، فَإِنْ غَرَبَتِ الشَّمْسُ وَهُوَ بِمِنًى، لَزِمَهُ الْمَبِيتُ بِمِنًى وَالرَّمْيُ مِنْ غَدٍ، فَإِنْ كَانَ مُتَمَتِّعًا أَوْ قَارِنًا،"]]},{"id":"um50_4","label":"بَابُ مَا يَفْعَلُهُ بَعْدَ الْحِلِّ · ٤","segs":[["matn","فَقَدِ انقَضَى حَجُّهُ وَعُمْرَتُهُ، وَإِنْ كَانَ مُفْرِدًا خَرَجَ إِلَى التَّنْعِيمِ، فَأَحْرَمَ بِالْعُمْرَةِ مِنْهُ، ثُمَّ يَأْتِي مَكَّةَ، فَيَطُوفُ وَيَسْعَى، وَيَحْلِقُ أَوْ يُقَصِّرُ، فَإِنْ لَمْ يَكُنْ لَهُ شَعَرٌ، اسْتُحِبَّ أَنْ يُمِرَّ الْمُوسَى عَلَى رَأْسِهِ، وَقَدْ تَمَّ حَجُّهُ وَعُمْرَتُهُ."]]},{"id":"um50_5","label":"بَابُ مَا يَفْعَلُهُ بَعْدَ الْحِلِّ · ٥","segs":[["matn","وَلَيْسَ فِي عَمَلِ الْقَارِنِ زِيَادَةً عَلَى عَمَلِ الْمُفْرِدِ، لَكِنْ عَلَيْهِ وَعَلَى الْمُتَمَتِّعِ دَمٌ، لِقَوْلِهِ تَعَالَى: ﴿فَمَنْ تَمَتَّعَ بِالْعُمْرَةِ إِلَى الْحَجِّ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلَاثَةِ أَيَّامٍ فِي الْحَجِّ وَسَبْعَةٍ إِذَا رَجَعْتُمْ﴾."]]},{"id":"um50_6","label":"بَابُ مَا يَفْعَلُهُ بَعْدَ الْحِلِّ · ٦","segs":[["matn","وَإِذَا أَرَادَ القُفُولَ، لَمْ يَخْرُجْ حَتَّى يُوَدِّعَ الْبَيْتَ بِطَوَافٍ عِنْدَ فَرَاغِهِ مِنْ جَمِيعِ أُمُورِهِ، حَتَّى يَكُونَ آخِرَ عَهْدِهِ بِالبَيْتِ، فَإِنِ اشْتَغَلَ بَعْدَهُ بِتِجَارَةٍ أَعَادَهُ،"]]},{"id":"um50_7","label":"بَابُ مَا يَفْعَلُهُ بَعْدَ الْحِلِّ · ٧","segs":[["matn","وَيُسْتَحَبُّ لَهُ إِذَا طَافَ أَنْ يَقِفَ فِي الْمُلْتَزَمِ بَيْنَ الرُّكْنِ وَالْبَابِ، فَيَلْتَزِمُ الْبَيْتَ، وَيَقُولُ: اللهُمَّ هَذَا بَيْتُكَ، وَأَنَا عَبْدُكَ وَابْنُ عَبْدِكَ وَابْنُ أَمَتِكَ،"]]},{"id":"um50_8","label":"بَابُ مَا يَفْعَلُهُ بَعْدَ الْحِلِّ · ٨","segs":[["matn","حَمَلْتَنِي عَلَى مَا سَخَّرْتَ لِي مِنْ خَلْقِكَ، وَسَيَّرْتَنِي فِي بِلَادِكَ، حَتَّى بَلَّغْتَنِي بِنِعْمَتِكَ إِلَى بَيْتِكَ، وَأَعَنْتَنِي عَلَى أَدَاءِ نُسُكِي، فَإِنْ كُنْتَ رَضِيتَ عَنِّي، فَازْدَدْ عَنِّي رِضًا،"]]},{"id":"um50_9","label":"بَابُ مَا يَفْعَلُهُ بَعْدَ الْحِلِّ · ٩","segs":[["matn","وَإِلَّا فَمُنَّ الآنَ قَبْلَ أَنْ تَنْأَى عَنْ بَيْتِكَ دَارِي، فَهَذَا أَوَانُ انْصِرَافِي إِنْ أَذِنْتَ لِي، غَيْرَ مُسْتَبْدِلٍ بِكَ، وَلَا بِبَيْتِكَ وَلَا رَاغِبٍ عَنْكَ، وَلَا عَنْ بَيْتِكَ."]]},{"id":"um50_10","label":"بَابُ مَا يَفْعَلُهُ بَعْدَ الْحِلِّ · ١٠","segs":[["matn","اللَّهُمَّ أَصْحِبْنِي الْعَافِيَةَ فِي بَدَنِي، وَالصِّحَةَ فِي جِسْمِي، وَالعِصْمَةَ فِي دِينِي، وَأَحْسِنْ مُنْقَلَبِي، وَارْزُقْنِي طَاعَتَكَ مَا أَبْقَيْتَنِي، وَاجْمَعْ لِي بَيْنَ خَيْرَيِ الدُّنْيَا وَالآخِرَةِ، إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، وَيَدْعُو بِمَا أَحَبَّ، ثُمَّ يُصَلِّي عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ."]]},{"id":"um50_11","label":"بَابُ مَا يَفْعَلُهُ بَعْدَ الْحِلِّ · ١١","segs":[["matn","فَمَنْ خَرَجَ قَبْلَ الْوَدَاعِ، رَجَعَ إِلَيْهِ إِنْ كَانَ قَرِيبًا، وَإِنْ بَعُدَ بَعَثَ بِدَمٍ، إلَّا الْحَائِضَ وَالنُّفَسَاءَ، فَلَا وَدَاعَ عَلَيْهِمَا، وَيُسْتَحَبُّ لَهُمَا الْوُقُوفُ عِنْدَ بَابِ الْمَسْجِدِ، وَالدُّعَاءُ."]]}],"group":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ"},{"id":"um51","title":"بَابُ أَرْكَانِ الْحَجِّ وَالعُمْرَةِ","units":[{"id":"um51_1","label":"بَابُ أَرْكَانِ الْحَجِّ وَالعُمْرَةِ · ١","segs":[["matn","أَرْكَانُ الْحَجِّ: الْوُقُوفُ بِعَرَفَةَ وَطَوَافُ الزِّيَارَةِ وَوَاجِبَاتُهُ الإِحْرَامُ مِنَ الْمِيقَاتِ وَالْوُقُوفُ بِعَرَفَةَ إِلَى اللَّيْلِ وَالْمَبِيتُ بِمُزْدَلِفَةَ إِلَى نِصْفِ اللَّيْلِ، وَالسَّعْيُ وَالْمَبِيتُ بِمِنًى، وَالرَّمْيُ، وَالْحَلْقُ، وَطَوَافُ الْوَدَاعِ."]]},{"id":"um51_2","label":"بَابُ أَرْكَانِ الْحَجِّ وَالعُمْرَةِ · ٢","segs":[["matn","وَأَرْكَانُ الْعُمْرَةِ: وَالطَّوَافُ، وَوَاجِبَاتُهَا: الإِحْرَامُ، وَالسَّعْيُ، وَالْحَلْقُ. فَمَنْ تَرَكَ رُكْنًا لَمْ يَتِمَّ نُسُكُهُ إِلَّا بِهِ وَمَنْ تَرَكَ وَاجِبًا، جَبَرَهُ بِدَمٍ، وَمَنْ تَرَكَ سُنَّةً فَلَا شَيْءَ عَلَيْهِ،"]]},{"id":"um51_3","label":"بَابُ أَرْكَانِ الْحَجِّ وَالعُمْرَةِ · ٣","segs":[["matn","وَمَنْ لَمْ يَقِفْ بِعَرَفَةَ حَتَّى طَلَعَ الْفَجْرُ يَوْمَ النَّحْرِ، فَقَدْ فَاتَهُ الْحَجُّ فَيَتَحَلَّلُ بِطَوَافٍ وَسَعْيٍ، وَيَنْحَرُ هَدْيًا إِنْ كَانَ مَعَهُ، وَعَلَيْهِ الْقَضَاءُ."]]},{"id":"um51_4","label":"بَابُ أَرْكَانِ الْحَجِّ وَالعُمْرَةِ · ٤","segs":[["matn","وَإِنْ أَخْطَأَ النَّاسُ الْعَدَدَ فَوَقَفُوا فِي غَيْرِ يَوْمِ عَرَفَةَ، أَجْزَأَهُمْ ذَلِكَ وَإِنْ فَعَلَ ذَلِكَ نَفَرٌ مِنْهُمْ، فَقَدْ فَاتَهُمُ الْحَجُّ."]]},{"id":"um51_5","label":"بَابُ أَرْكَانِ الْحَجِّ وَالعُمْرَةِ · ٥","segs":[["matn","وَيُسْتَحَبُّ لِمَنْ حَجَّ زِيَارَةِ قَبْرِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَقَبْرَيْ صَاحِبَيْهِ رَضِيَ اللهُ عَنْهُمَا."]]}],"group":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ"},{"id":"um52","title":"بَابُ الْهَدْيِ وَالْأُضْحِيَّةِ","units":[{"id":"um52_1","label":"بَابُ الْهَدْيِ وَالْأُضْحِيَّةِ · ١","segs":[["matn","وَالْهَدْيُ وَالأُضْحِيَّةُ سُنَّةٌ لَا تَجِبُ إِلَّا بِالنَّذْرِ وَالتَّضْحِيَةُ أَفْضَلُ مِنَ الصَّدَقَةِ بِثَمَنِهَا وَالأَفْضَلُ فِيهِمَا الإِبِلُ، ثُمَّ الْبَقَرُ ثُمَّ الْغَنَمُ، وَيُسْتَحَبُّ اسْتِحْسَانُهَا وَاسْتِسْمَانُهَا."]]},{"id":"um52_2","label":"بَابُ الْهَدْيِ وَالْأُضْحِيَّةِ · ٢","segs":[["matn","وَلَا يُجْزِئُ إِلَّا الْجَذَعُ مِنَ الضَّأْنِ، وَالثَّنِيُّ مِمَّا سِوَاهُ وَثَنِيُّ الْمَعْزِ: مَا لَهُ سَنَةٌ، وَثَنِيُّ الإِبِلِ: مَا كَمَلَ لَهُ خَمْسُ سِنِينَ وَمِنَ الْبَقَرِ: مَا لَهُ سَنَتَانِ."]]},{"id":"um52_3","label":"بَابُ الْهَدْيِ وَالْأُضْحِيَّةِ · ٣","segs":[["matn","وَتُجْزِئُ الشَّاةُ عَنْ وَاحِدٍ، وَالْبَدَنَةُ وَالْبَقَرَةُ عَنْ سَبْعَةٍ، وَلَا تُجْزِئُ الْعَوْرَاءُ، الْبَيِّنُ عَوَرُهَا وَلَا الْعَجْفَاءُ الَّتِي لَا تُنْقِي، وَلَا الْعَرْجَاءُ، الْبَيِّنُ ظَلَعُهَا وَلَا الْمَرِيضَةُ،"]]},{"id":"um52_4","label":"بَابُ الْهَدْيِ وَالْأُضْحِيَّةِ · ٤","segs":[["matn","الْبَيِّنُ مَرَضُهَا، وَلَا الْعَضْبَاءُ الَّتِي ذَهَبَ أَكْثَرُ قَرْنِهَا أَوْ أُذُنِهَا، وَتُجْزِئُ الْجَمَّاءُ وَالْبَتْرَاءُ وَالْخَصِيُّ، وَمَا شُقَّتْ أُذُنُهَا، أَوْ خُرِقَتْ أَوْ قُطِعَ أَقَلُّ مِنْ نِصْفِهَا."]]},{"id":"um52_5","label":"بَابُ الْهَدْيِ وَالْأُضْحِيَّةِ · ٥","segs":[["matn","وَالسُّنَّةُ نَحْرُ الإِبِلِ قَائِمَةً مَعْقُولَةً يَدُهَا الْيُسْرَى، وَذَبْحُ الْبَقَرِ وَالْغَنَمِ، عَلَى صِفَاحِهَا وَيَقُولُ عِنْدَ ذَلِكَ: بِسْمِ اللهِ وَاللهُ أَكْبَرُ اللَّهُمَّ هَذَا مِنْكَ وَلَكَ."]]},{"id":"um52_6","label":"بَابُ الْهَدْيِ وَالْأُضْحِيَّةِ · ٦","segs":[["matn","وَلَا يُسْتَحَبُّ أَنْ يَذْبَحَهَا إِلَّا مُسْلِمٌ، وَإِنْ ذَبَحَهَا صَاحِبُهَا فَهُوَ أَفْضَلُ. وَوَقْتُ الذَّبْحِ يَوْمَ الْعِيدِ بَعْدَ صَلَاةِ الْعِيدِ، إِلَى آخِرِ يَوْمَيْنِ مِنْ أَيَّامِ التَّشْرِيقِ."]]},{"id":"um52_7","label":"بَابُ الْهَدْيِ وَالْأُضْحِيَّةِ · ٧","segs":[["matn","وتَتَعَيَّنُ الأُضْحِيَّةُ بِقَوْلِهِ: هَذِهِ أُضْحِيَّةٌ، وَالْهَدْيُ بِقَوْلِهِ: هَذَا هَدْيٌ، وَإِشْعَارِهِ وَتَقْلِيدِهِ مَعَ النِّيَّةِ."]]},{"id":"um52_8","label":"بَابُ الْهَدْيِ وَالْأُضْحِيَّةِ · ٨","segs":[["matn","وَلَا يُعْطَى الْجَزَّارُ بِأُجْرَتِهِ شَيْئًا مِنْهَا وَالسُّنَّةُ أَنْ يَأْكُلَ ثُلُثَ أُضْحِيَّتِهِ وَيُهْدِي ثُلُثَهَا، وَيَتَصَدَّقَ بِثُلُثِهَا وَإِنْ أَكَلَ أَكْثَرَ جَازَ وَلَهُ أَنْ يَنْتَفِعَ بِجِلْدِهَا وَلَا يَبِيعُهُ، وَلَا شَيْئًا مِنْهَا، فَأَمَّا الْهَدْيُ إِنْ كَانَ تَطَوُّعًا،"]]},{"id":"um52_9","label":"بَابُ الْهَدْيِ وَالْأُضْحِيَّةِ · ٩","segs":[["matn","اسْتُحِبَّ لَهُ الأَكْلُ مِنْهُ لِأَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَمَرَ مِنْ كُلِّ جَزُورٍ بِبِضْعَةٍ فَطُبِخَتْ، فَأَكَلَ مِنْ لَحْمِهَا، وَحَسَا مِنْ مَرَقِهَا وَلَا يَأْكُلُ مِنْ وَاجِبٍ إِلَّا مِنْ هَدْيِ الْمُتْعَةِ وَالْقِرَانِ."]]},{"id":"um52_10","label":"بَابُ الْهَدْيِ وَالْأُضْحِيَّةِ · ١٠","segs":[["matn","وَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «مَنْ أَرَادَ أَنْ يُضَحِّيَ فَدَخَلَ الْعَشْرُ، فَلَا يَأْخُذْ مِنْ شَعَرِهِ وَلَا مِنْ بَشَرَتِهِ شَيْئًا حَتَّى يُضَحِّيَ»"]]}],"group":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ"},{"id":"um53","title":"بَابُ العَقِيقَةِ","units":[{"id":"um53_1","label":"بَابُ العَقِيقَةِ · ١","segs":[["matn","وَهِيَ سُنَّةٌ عَنِ الْغُلَامِ شَاتَانِ مُتَكَافِئَتَانِ وَعَنِ الْجَارِيَةِ شَاةٌ تُذْبَحُ يَوْمَ سَابِعِهِ، وَيُحْلَقُ رَأْسُهُ وَيُتَصَدَّقُ بِوَزْنِهِ وَرِقًا، فَإِنْ فَاتَ،"]]},{"id":"um53_2","label":"بَابُ العَقِيقَةِ · ٢","segs":[["matn","يَوْمُ سَابِعِهِ فَفِي أَرْبَعَةَ عَشَرَ فَإِنْ فَاتَ، فَفِي أَحَدَ وَعِشْرِينَ وَيَنْزِعُهَا أَعْضَاءً، وَلَا يَكْسِرُ لَهَا عَظْمًا وَحُكْمُهَا حُكْمُ الأُضْحِيَّةِ فِيمَا سِوَى ذَلِكَ."]]}],"group":"كِتَابُ الْحَجِّ وَالْعُمْرَةِ"},{"id":"um54","title":"كِتَابُ الْبُيُوعِ","units":[{"id":"um54_1","label":"كِتَابُ الْبُيُوعِ · ١","segs":[["matn","قَالَ اللهُ تَعَالَى: ﴿وَأَحَلَّ اللَّهُ الْبَيْعَ﴾ وَالْبَيْعُ: مُعَاوَضَةُ الْمَالِ بِالْمَالِ. وَيَجُوزُ بَيْعُ كُلِّ مَمْلُوكٍ فِيهِ نَفْعٌ مُبَاحٌ، إِلَّا الْكَلْبَ فَإِنَّهُ لَا يَجُوزُ بَيْعُهُ وَلَا غُرْمَ عَلَى مُتْلِفِهِ،"]]},{"id":"um54_2","label":"كِتَابُ الْبُيُوعِ · ٢","segs":[["matn","لِأَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ ثَمَنِ الْكَلْبِ، وَقَالَ: «مَنِ اقْتَنَى كَلْباً إِلَّا كَلْبَ مَاشِيَةٍ أَوْ صَيْدٍ، نَقَصَ مِنْ عَمَلِهِ كُلَّ يَوْمٍ قِيرَاطَانِ»."]]},{"id":"um54_3","label":"كِتَابُ الْبُيُوعِ · ٣","segs":[["matn","وَلَا يَجُوزُ بَيْعُ مَا لَيْسَ بِمَمْلُوكٍ لِبَائِعِهِ، إِلَّا بِإِذْنِ مَالِكِهِ، أَوْ وِلَايَةٍ عَلَيِهِ، وَلَا بَيْعُ مَا لَا نَفْعَ فِيهِ كَالْحَشَرَاتِ،"]]},{"id":"um54_4","label":"كِتَابُ الْبُيُوعِ · ٤","segs":[["matn","وَلَا مَا نَفْعُهُ مُحَرَّمٌ، كَالْخَمْرِ وَالْمَيْتَةِ، وَلَا بَيْعُ مَعْدُومٍ، كَالَّذِي تَحْمِلُ أَمَتُهُ أَوْ شَجَرَتُهُ، أَوْ مَجْهُولٍ، كَالْحَمْلِ، وَالْغَائِبِ الَّذِي لَمْ يُوصَفْ،"]]},{"id":"um54_5","label":"كِتَابُ الْبُيُوعِ · ٥","segs":[["matn","وَلَمْ تَتَقَدَّمْ رُؤْيَتُهُ، وَلَا مَعْجُوزٍ عَنْ تَسْلِيمِهِ، كَالآبِقِ، وَالشَّارِدِ، وَالطَّيْرِ فِي الْهَوَاءِ، وَالسَّمَكِ فِي الْمَاءِ، وَلَا بَيْعُ الْمَغْصُوبِ، إِلَّا لِغَاصِبِهِ،"]]},{"id":"um54_6","label":"كِتَابُ الْبُيُوعِ · ٦","segs":[["matn","أَوْ مَنْ يَقْدِرُ عَلَى أَخْذِهِ مِنْهُ، وَلَا بَيْعُ غَيْرِ مُعَيَّنٍ، كَعَبْدٍ مِنْ عَبِيدِهِ أَوْ شَاةٍ مِنْ قَطِيعِهِ إِلَّا فِيمَا تَتَسَاوَى أَجْزَاؤُهُ، كَقَفِيزٍ مِنْ صُبْرَةٍ."]]},{"id":"um54_7","label":"كِتَابُ الْبُيُوعِ · ٧","segs":[["matn","فَصْلٌ: وَنَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُلَامَسَةِ، وَهِيَ: أَنْ يَقُولَ: أَيُّ ثَوْبٍ لَمَسْتَهُ، فَهُوَ لَكَ بِكَذَا، وعَنِ الْمُنَابَذَةِ، وَهِيَ: أَنْ يَقُولَ: أَيُّ ثَوْبٍ نَبَذْتَهُ إِلَيَّ،"]]},{"id":"um54_8","label":"كِتَابُ الْبُيُوعِ · ٨","segs":[["matn","فَهُوَ عَلَيَّ بِكَذَا، وَعَنِ بَيْعِ الْحَصَاةِ، وَهُوَ: أَنْ يَقُولَ: ارْمِ الْحَصَاةَ، فَأَيُّ ثَوْبٍ وَقَعَتْ عَلَيْهِ، فَهُوَ بَيْعِ الرَّجُلِ عَلَى بَيْعِ أَخِيهِ، وَعَنْ بَيْعِ حَاضِرٍ لِبَادٍ، وَهُوَ:"]]},{"id":"um54_9","label":"كِتَابُ الْبُيُوعِ · ٩","segs":[["matn","أَنْ يَكُونَ لَهُ سِمْسَارًا وَعَنِ النَّجْشِ، وَهُوَ: أَنْ يَزِيدَ فِي السِّلْعَةِ مَنْ لَا يُرِيدُ شِرَاءَهَا وَعَنْ بَيْعَتَيْنِ فِي بَيْعَةٍ، وَهُوَ أَنْ يَقُولَ: بِعْتُكَ هَذَا بِعَشَرَةٍ صِحَاحِ، أَوْ عِشْرِينَ مُكَسَّرَةً،"]]},{"id":"um54_10","label":"كِتَابُ الْبُيُوعِ · ١٠","segs":[["matn","أَوْ يَقُولَ: بِعْتُكَ هَذَا عَلَى أَنْ تَبِيعَنِي هَذَا، أَوْ تَشْتَرِي مِنِّي هَذَا وَقَالَ: «لَا تَلَقَّوْا السِّلَعَ حَتَّى يُهْبَطَ بِهَا الأَسْوَاقَ» وَقَالَ: «مَنِ اشْتَرَى طَعَامًا، فَلَا يَبِعْهُ حَتَّى يَسْتَوْفِيَهُ»"]]}],"group":"كِتَابُ الْبُيُوعِ"},{"id":"um55","title":"بَابُ الرِّبَا","units":[{"id":"um55_1","label":"بَابُ الرِّبَا · ١","segs":[["matn","عَنْ عُبَادَةَ بْنِ الصَّامِتِ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ:"]]},{"id":"um55_2","label":"بَابُ الرِّبَا · ٢","segs":[["matn","«الذَّهَبُ بِالذَّهَبِ، وَالْفِضَّةُ بِالْفِضَّةِ، وَالبُرُّ بِالْبُرِّ، وَالشَّعِيرُ بِالشَّعِيرِ، وَالتَّمْرُ بِالتَّمْرِ، وَالْمِلْحُ بِالْمِلْحِ، مِثْلاً بِمِثْلٍ، سَوَاءً بِسَوَاءٍ، فَإِذَا اخْتَلَفَتْ هَذِهِ الأَصْنَافُ، فَبِيعُوا كَيْفَ شِئْتُمْ إِذَا كَانَ يَدًا بِيَدٍ، فَمَنْ زَادَ أَوِ اسْتَزَادَ فَقَدْ أَرْبَى» وَلَا يَجُوزُ بَيْعُ مَطْعُومٍ مَكِيلٍ،"]]},{"id":"um55_3","label":"بَابُ الرِّبَا · ٣","segs":[["matn","أَوْ مَوْزُونٍ بِجِنْسِهِ إِلَّا مِثْلاً بِمِثْلٍ وَلَا يَجُوزُ بَيْعُ مَكِيلٍ مِنْ ذَلِكَ بِشَيْءٍ مِنْ جِنْسِهِ وَزْنًا، وَلَا مَوْزُونٍ كَيْلاً وَإِنِ اخْتَلَفَ الْجِنْسَانِ، جَازَ بَيْعُهُ كَيْفَ شَاءَ يَدًا بِيَدٍ وَلَمْ يَجُزِ النَّسَاءُ فِيهِ، وَلَا التَّفَرُّقُ قَبْلَ الْقَبْضِ إِلَّا فِي الثَّمَنِ بِالْمُثَمَّنِ."]]},{"id":"um55_4","label":"بَابُ الرِّبَا · ٤","segs":[["matn","وَكُلُّ شَيْئَيْنِ جَمَعَهُمَا اسِمٌ خَاصٌ، فَهُمَا جِنْسٌ وَاحِدٌ، إلَّا أَنْ يَكُونَا مِنْ أَصْلَيْنِ مُخْتَلِفَيْنِ، فَإِنَّ فُرُوعَ الأَجْنَاسِ أَجْنَاسٌ، وَإِنِ اتَّفَقَتْ أَسْمَاؤُهَا كَالأَدِقَّةِ وَالأَدْهَانِ."]]},{"id":"um55_5","label":"بَابُ الرِّبَا · ٥","segs":[["matn","وَلَا يَجُوزُ بَيْعُ رَطْبٍ مِنْهَا بِيَابِسٍ مِنْ جِنْسِهِ، وَلَا خَالِصِهِ بِمَشُوبِهِ، وَلَا نِيئِهِ بِمَطْبُوخِهِ."]]},{"id":"um55_6","label":"بَابُ الرِّبَا · ٦","segs":[["matn","وَقَدْ نَهَى رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُزَابَنَةِ، وَهُوَ شِرَاءُ التَّمْرِ بِالتَّمْرِ فِي رُءُوسِ النَّخْلِ، وَرَخَّصَ فِي بَيْعِ الْعَرَايَا فِيمَا دُونَ خَمْسَةِ أَوْسُقٍ أَنْ تُبَاعَ بِخَرْصِهَا، يَأْكُلُهَا أَهْلُهَا رَطْبًا."]]}],"group":"كِتَابُ الْبُيُوعِ"},{"id":"um56","title":"بَابُ بَيْعِ الأُصُولِ وَالثِّمَارِ","units":[{"id":"um56_1","label":"بَابُ بَيْعِ الأُصُولِ وَالثِّمَارِ · ١","segs":[["matn","رُوِيَ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: «مَنْ بَاعَ نَخْلًا بَعْدَ أَنْ تُؤَبَّرَ، فَثَمَرَتُهَا لِلْبَائِعِ، إِلَّا أَنْ يَشْتَرِطَهَا الْمُبْتَاعُ.» وَكَذَلِكَ بَيْعُ الشَّجَرِ، إِذَا كَانَ ثَمَرُهُ بَادِيًا."]]},{"id":"um56_2","label":"بَابُ بَيْعِ الأُصُولِ وَالثِّمَارِ · ٢","segs":[["matn","فَإِنْ بَاعَ الأَرْضَ، وَفِيهَا زَرْعٌ، لَا يُحْصَدُ، إِلَّا مَرَّةً، فَهُوَ لِلْبَائِعِ مَا لَمْ يَشْتَرِطْهُ الْمُبْتَاعُ وَإِنْ كَانَ يُجَزُّ مَرَّةً بَعْدَ أُخْرَى، فَالأُصُولُ لِلْمُشْتَرِي، وَالْجُزَّةُ الظَّاهِرَةُ عِنْدَ الْبَيْعِ لِلْبَائِعِ."]]},{"id":"um56_3","label":"بَابُ بَيْعِ الأُصُولِ وَالثِّمَارِ · ٣","segs":[["matn","فَصْلٌ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعِ الثَّمَرَةِ حَتَّى يَبْدُوَ صَلَاحُهَا، وَلَوْ بَاعَ الثَّمَرَةِ بَعْدَ بُدُوِّ صَلَاحِهَا عَلَى التَّرْكِ إِلَى الْجُذَاذِ، جَازَ فَإِنْ أَصَابَتْهَا جَائِحَةٌ رَجَعَ بِهَا عَلَى الْبَائِعِ؛"]]},{"id":"um56_4","label":"بَابُ بَيْعِ الأُصُولِ وَالثِّمَارِ · ٤","segs":[["matn","لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «لَوْ بِعْتَ مِنْ أَخِيكَ ثَمَرًا، فَأَصَابَتْهُ جَائِحَةٌ، فَلَا يَحِلُّ لَكَ أَنْ تَأْخُذَ مِنْهُ شَيْئًا، بِمَ تَأْخُذُ مَالَ أَخِيكَ بِغَيْرِ حَقٍّ؟»"]]},{"id":"um56_5","label":"بَابُ بَيْعِ الأُصُولِ وَالثِّمَارِ · ٥","segs":[["matn","وَصَلَاحُ ثَمَرِ النَّخْلِ أَنْ يَحْمَرَّ أَوْ يَصْفَرّ وَالْعِنَبِ أَنْ يَتَمَوَّهَ، وَسَائِرُ الثَّمَرِ أَنْ يَبْدُوَ فِيهِ النُّضْجُ، وَيَطِيبَ أَكْلُهُ."]]}],"group":"كِتَابُ الْبُيُوعِ"},{"id":"um57","title":"بَابُ الْخِيَارِ","units":[{"id":"um57_1","label":"بَابُ الْخِيَارِ · ١","segs":[["matn","الْبَيِّعَانِ بِالْخِيَارِ مَا لَمْ يَتَفَرَّقَا بِأَبْدَانِهِمَا، فَإِنْ تَفَرَّقَا، وَلَمْ يَتْرُكْ أَحَدُهُمَا الْبَيْعَ، فَقَدْ وَجَبَ الْبَيْعُ، إِلَّا أَنْ يَشْتَرِطَ الْخِيَارَ لَهُمَا، أَوْ لِأَحَدُهُمَا مُدَّةً مَعْلُومَةً، فَيَكُونَانِ عَلَى شَرْطِهِمَا."]]},{"id":"um57_2","label":"بَابُ الْخِيَارِ · ٢","segs":[["matn","وَإِنْ طَالَتِ الْمُدَّةُ، إِلَّا أَنْ يَقْطَعَاهُ. وَإِنْ وَجَدَ أَحَدُهُمَا بِمَا اشْتَرَاهُ عَيْبًا لَمْ يَكُنْ عَلِمَهُ، فَلَهُ رَدُّهُ، أَوْ أَخْذُ أَرْشِ الْعَيْبِ."]]},{"id":"um57_3","label":"بَابُ الْخِيَارِ · ٣","segs":[["matn","وَمَا كَسَبَهُ الْمَبِيعُ، أَوْ حَدَثَ فِيهِ مِنْ نَمَاءٍ مُنْفَصِلٍ قَبْلَ عِلْمِهِ بِالْعَيْبِ، فَهُوَ لَهُ؛ لِأَنَّ الْخَرَاجَ بِالضَّمَانِ."]]},{"id":"um57_4","label":"بَابُ الْخِيَارِ · ٤","segs":[["matn","وَإِنْ تَلِفَتِ السِّلْعَةُ أَوْ عَتَقَ الْعَبْدُ، أَوْ تَعَذَّرَ رَدُّهُ، فَلَهُ أَرْشُ الْعَيْبِ، وَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ:"]]},{"id":"um57_5","label":"بَابُ الْخِيَارِ · ٥","segs":[["matn","«لَا تُصَرُّوا الإِبِلَ وَالْغَنَمَ، فَمَنِ ابْتَاعَهَا بَعْدَ ذَلِكَ، فَهُوَ بِخَيْرِ النَّظَرَيْنِ بَعْدَ أَنْ يَحْلُبَهَا، إِنْ رَضِيَهَا، أَمْسَكَهَا، وَإِنْ سَخِطَهَا، رَدَّهَا وَصَاعًا مِنْ تَمْرٍ.»"]]},{"id":"um57_6","label":"بَابُ الْخِيَارِ · ٦","segs":[["matn","فَإِنْ عَلِمَ بِتَصْرِيَتِهَا قَبْلَ حَلْبِهَا، رَدَّهَا، وَلَا شَيْءَ مَعَهَا، وَكَذَلِكَ كَلُّ مُدَلَّسٍ لَا يَعْلَمُ تَدْلِيسَهُ فَلَهُ رَدُّهُ، كَجَارِيَةٍ حَمَّرَ وَجْهَهَا، أَوْ سَوَّدَ شَعَرَهَا، أَوْ جَعَّدَهُ،"]]},{"id":"um57_7","label":"بَابُ الْخِيَارِ · ٧","segs":[["matn","أَوْ رَحًى ضَمَّ الْمَاءَ وَأَرْسَلَهُ عَلَيْهَا عِنْدَ عَرْضِهَا عَلَى الْمُشْتَرِي، وَكَذَلِكَ لَوْ وَصَفَ الْمَبِيعَ بِصِفَةٍ يَزِيدُ بِهَا ثَمَنِهِ، فَلَمْ يَجِدْهَا فِيهِ، كَصِنَاعَةٍ فِي الْعَبْدِ أَوْ."]]},{"id":"um57_8","label":"بَابُ الْخِيَارِ · ٨","segs":[["matn","كِتَابَةٍ، أَوْ أَنَّ الدَّابَةَ هِمْلَاجَةٌ، وَالْفَهْدَ صَيُودٌ أَوْ مُعَلَّمٌ، أَوْ أَنَّ الطَّائِرَ مُصَوِّتٌ، وَنَحْوُهُ."]]},{"id":"um57_9","label":"بَابُ الْخِيَارِ · ٩","segs":[["matn","وَلَوْ أَخْبَرَهُ بِثَمَنِ الْمَبِيعِ، فَزَادَ عَلَيْهِ، رَجَعَ عَلَيْهِ بِالزِّيَادَةِ، وَحَظِّهَا مِنَ الرِّبْحِ، إِنْ كَانَ مُرَابَحَةً، وَإِنْ بَانَ أَنَّهُ غَلِطَ عَلَى نَفْسِهِ،"]]},{"id":"um57_10","label":"بَابُ الْخِيَارِ · ١٠","segs":[["matn","خُيِّرَ الْمُشْتَرِي بَيْنَ رَدِّهِ وَإِعْطَائِهِ مَا غَلِطَ بِهِ، وَإِنْ بَانَ أَنَّهُ مُؤَجَّلٌ وَلَمْ يُخْبِرْهُ بِتَأْجِيلِهِ فَلَهُ الْخِيَارُ بَيْنَ رَدِّهِ وَإِمْسَاكِهِ."]]},{"id":"um57_11","label":"بَابُ الْخِيَارِ · ١١","segs":[["matn","وَإِنِ اخْتَلَفَ الْبَيِّعَانِ فِي قَدْرِ الثَّمَنِ، تَحَالَفَا وَلِكُلِّ وَاحِدٍ مِنْهُمَا الْفَسْخُ، إِلَّا أَنْ يَرْضَى بِمَا قَالَ صَاحِبُهُ."]]}],"group":"كِتَابُ الْبُيُوعِ"},{"id":"um58","title":"بَابُ السَّلَمِ","units":[{"id":"um58_1","label":"بَابُ السَّلَمِ · ١","segs":[["matn","عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، قَالَ: قَدِمَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ، وَهُمْ يُسْلِفُونَ فِي الثِّمَارِ السَّنَةَ وَالسَّنَتَيْنِ، فَقَالَ:"]]},{"id":"um58_2","label":"بَابُ السَّلَمِ · ٢","segs":[["matn","«مَنْ أَسْلَفَ فِي ثَمَرٍ فَلْيُسْلِفْ فِي كَيْلٍ مَعْلُومٍ، أَوْ وَزْنٍ مَعْلُومٍ، إِلَى أَجَلٍ مَعْلُومٍ» وَيَصِحُّ السَّلَمُ فِي كُلِّ مَا يَنْضَبِطُ بِالصِّفَةِ إِذَا ضَبَطَهُ بِهَا،"]]},{"id":"um58_3","label":"بَابُ السَّلَمِ · ٣","segs":[["matn","وَذَكَرَ قَدْرَهُ بِمَا يُقَدَّرُ بِهِ، مِنْ كَيْلٍ، أَوْ وَزْنٍ، أَوْ ذَرْعٍ، أَوْ عَدٍّ وَجَعَلَ لَهُ أَجَلاً مَعْلُومًا وَأَعْطَاهُ الثَّمَنَ قَبْلَ تَفَرُّقِهِمَا."]]},{"id":"um58_4","label":"بَابُ السَّلَمِ · ٤","segs":[["matn","وَيَجُوزُ السَّلَمُ فِي شَيْءٍ يَقْبِضُهُ أَجْزَاءً مُتَفَرِّقَةً فِي أَوْقَاتٍ مَعْلُومَةٍ، وَإِنْ أَسْلَمَ ثَمَنًا وَاحِدًا فِي شَيْئَيْنِ، لَمْ يَجُزْ حَتَّى يُبَيِّنُ ثَمَنَ كُلِّ جِنْسٍ وَمَنْ أَسْلَفَ فِي شَيْءٍ، لَمْ يَصْرِفْهُ إِلَى غَيْرِهِ."]]},{"id":"um58_5","label":"بَابُ السَّلَمِ · ٥","segs":[["matn","وَلَا يَصِحُّ بَيْعُ الْمُسْلَمِ فِيهِ قَبْلَ قَبْضِهِ، وَلَا الْحِوَالَةُ بِهِ، وَتَجُوزُ الإِقَالَةُ فِيهِ، أَوْ فِي بَعْضِهِ، لِأَنَّهَا فَسْخٌ."]]}],"group":"كِتَابُ الْبُيُوعِ"},{"id":"um59","title":"بَابُ الْقَرْضِ وَغَيْرِهِ","units":[{"id":"um59_1","label":"بَابُ الْقَرْضِ وَغَيْرِهِ · ١","segs":[["matn","عَنْ أَبِي رَافِعٍ: «أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اسْتَسْلَفَ مِنْ رَجُلٍ بَكْرًا، فَقَدِمَتْ عَلَيْهِ» إِبِلُ الصَّدَقَةِ، فَأَمَرَ أَبًا رَافِعٍ أَنْ يَقْضِيَ الرَّجُلَ بَكْرَهُ، فَرَجَعَ إِلَيْهِ أَبُو رَافِعٍ، فَقَالَ: لَمْ أَجِدْ فِيهَا، إِلَّا خِيَارًا رُبَاعِيًا."]]},{"id":"um59_2","label":"بَابُ الْقَرْضِ وَغَيْرِهِ · ٢","segs":[["matn","فَقَالَ: «أَعْطُوهُ فَإِنَّ خَيْرَ النَّاسِ أَحْسَنُهُمْ قَضَاءً». وَمَنِ اقْتَرَضَ شَيْئًا، فَعَلَيْهِ رَدُّ مِثْلِهِ وَيَجُوزُ أَنْ يَرُدَّ خَيْرًا مِنْهُ وَأَنْ يَقْتَرِضَ تَفَارِيقَ وَيَرُدَّ جُمْلَةً إِذَا لَمْ يَكُنْ شَرْطٌ وَإِنْ أَجَّلَهُ، لَمْ يَتَأَجَّلْ."]]},{"id":"um59_3","label":"بَابُ الْقَرْضِ وَغَيْرِهِ · ٣","segs":[["matn","وَلَا يَجُوزُ شَرْطُ شَيْءٍ لِيَنْتَفِعَ بِهِ الْمُقْرِضُ، إلَّا أَنْ يَشْتَرِطَ رَهْنًا، أَوْ كَفِيلاً وَلَا يُقْبَلُ هَدِيَّةُ الْمُقْتَرِضِ، إِلَّا أَنْ يَكُونَ بَيْنَهُمَا عَادَةً بِهَا، قَبْلَ الْقَرْضِ."]]}],"group":"كِتَابُ الْبُيُوعِ"},{"id":"um60","title":"بَابُ أَحْكَامِ الدَّيْنِ","units":[{"id":"um60_1","label":"بَابُ أَحْكَامِ الدَّيْنِ · ١","segs":[["matn","مَنْ لَزِمَهُ دَيْنٌ مُؤَجَّلٌ، لَمْ يُطَالَبْ بِهِ قَبْلَ أَجَلِهِ، وَلَمْ يُحْجَرْ عَلَيْهِ مِنْ أَجْلِهِ، وَلَمْ يَحِلَّ بِتَفْلِيسِهِ وَلَا بِمَوْتِهِ، إِذَا وَثَّقَهُ الْوَرَثَةُ بِرَهْنٍ، أَوْ كَفِيلٍ."]]},{"id":"um60_2","label":"بَابُ أَحْكَامِ الدَّيْنِ · ٢","segs":[["matn","وَإِنْ أَرَادَ سَفَرًا يَحِلُّ قَبْلَ مُدَّتِهِ، أَوِ الْغَزْوَ تَطَوُّعًا، فَلِغَرِيمِهِ مَنْعُهُ، إِلَّا أَنْ يُوَثِّقَ بِذَلِكَ."]]},{"id":"um60_3","label":"بَابُ أَحْكَامِ الدَّيْنِ · ٣","segs":[["matn","وَإِنْ كَانَ الدَّيْنُ حَالًّا عَلَى مُعْسِرٍ، وَجَبَ إِنْظَارُهُ، فَإِنِ ادَّعَى الإِعْسَارَ، حُلِّفَ، وَخُلِّيَ سَبِيلُهُ، إِلَّا أَنْ يُعْرَفَ لَهُ مَالٌ قَبْلَ ذَلِكَ، فَلَا يُقْبَلُ قَوْلُهُ، إِلَّا بِبَيِّنَةٍ، فَإِنْ كَانَ مُوسِرًا لَزِمَهُ وَفَاؤُهُ،"]]},{"id":"um60_4","label":"بَابُ أَحْكَامِ الدَّيْنِ · ٤","segs":[["matn","فَإِنْ أَبَى، حُبِسَ حَتَّى يُوَفِّيَهُ، فَإِنْ كَانَ مَالُهُ لَا يَفِي بِدَيْنِهِ كُلِّهِ، فَسَأَلَ غُرَمَاؤُهُ الْحَاكِمَ الْحَجْرَ عَلَيْهِ، لَزِمَهُ إِجَابَتُهُمْ، فَإِذَا حَجَرَ عَلَيْهِ، لَمْ يَجُزْ تَصَرُّفُهُ فِي مَالِهِ وَلَمْ يُقْبَلْ إِقْرَارُهُ عَلَيْهِ."]]},{"id":"um60_5","label":"بَابُ أَحْكَامِ الدَّيْنِ · ٥","segs":[["matn","وَيَتَوَلَّى الْحَاكِمُ قَضَاءَ دَيْنِهِ، وَيَبْدَأُ بِمَنْ لَهُ أَرْشُ جِنَايَةٍ مِنْ رَقِيقِهِ فَيَدْفَعُ إِلَى الْمَجْنِيِّ عَلَيْهِ أَقَلَّ الأَمْرَيْنِ مِنْ أَرْشِهَا أَوْ قِيمَةِ الْجَانِي، ثُمَّ بِمَنْ لَهُ رَهْنٌ، فَيَدْفَعُ إِلَيْهِ أَقَلَّ الأَمْرَيْنِ مِنْ دَيْنِهِ أَوْ ثَمَنِ رَهْنِهِ،"]]},{"id":"um60_6","label":"بَابُ أَحْكَامِ الدَّيْنِ · ٦","segs":[["matn","وَلَهُ أُسْوَةُ الْغُرَمَاءِ فِي بَقِيَّةِ دَيْنِهِ، ثُمَّ مَنْ وَجَدَ مَتَاعَهُ الَّذِي بَاعَهُ بِعَيْنِهِ لَمْ يَتْلَفْ بَعْضُهُ، وَلَمْ يَزِدْ زِيَادَةً مُتَّصِلَةً، وَلَمْ يَأْخُذْ مِنْ ثَمَنِهِ شَيْئًا، فَلَهُ أَخْذُهُ؛"]]},{"id":"um60_7","label":"بَابُ أَحْكَامِ الدَّيْنِ · ٧","segs":[["matn","لِقَوْلِ رَسُولِ اللهِ: صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «مَنْ أَدْرَكَ مَتَاعَهُ بِعَيْنِهِ عِنْدَ إِنْسَانٍ قَدْ أَفْلَسَ، فَهُوَ أَحَقُّ بِهِ مِنْ غَيْرِهِ» وَيُقَسَّمُ الْبَاقِي بَيْنَ الْغُرَمَاءِ عَلَى قَدْرِ دُيُونِهِمْ،"]]},{"id":"um60_8","label":"بَابُ أَحْكَامِ الدَّيْنِ · ٨","segs":[["matn","وَيُنْفَقُ عَلَى الْمُفْلِسِ وَعَلَى مَنْ تَلْزَمُهُ مُؤْنَتُهُ مِنْ مَالِهِ إِلَى أَنْ يَفْرُغَ مِنَ الْقِسْمَةِ، فَإِنْ وَجَبَ لَهُ حَقٌّ بِشَاهِدٍ فَأَبَى أَنْ يَحْلِفَ، لَمْ يَكُنْ لِغُرَمَائِهِ أَنْ يَحْلِفُوا."]]}],"group":"كِتَابُ الْبُيُوعِ"},{"id":"um61","title":"بَابُ الْحِوَالَةِ وَالضَّمَانِ","units":[{"id":"um61_1","label":"بَابُ الْحِوَالَةِ وَالضَّمَانِ · ١","segs":[["matn","وَمَنْ أُحِيلَ بِدَيْنِهِ عَلَى مَنْ عَلَيْهِ مِثْلُهُ، فَرَضِيَ، فَقَدْ بَرِئَ الْمُحِيلُ وَمَنْ أُحِيلَ عَلَى مَلِيءٍ، لَزِمَهُ أَنْ يَحْتَالَ؛ لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «إِذَا أُتْبِعَ أَحَدُكُمْ عَلَى مَلِيءٍ، فَلْيَتْبَعْ»."]]},{"id":"um61_2","label":"بَابُ الْحِوَالَةِ وَالضَّمَانِ · ٢","segs":[["matn","وَإِنْ ضَمِنَهُ عَنْهُ ضَامِنٌ، لَمْ يَبْرَأْ وَصَارَ الدَّيْنُ عَلَيْهِمَا، وَلِصَاحِبِهِ مُطَالَبَةُ مَنْ شَاءَ مِنْهُمَا، فَإِنِ اسْتَوْفَى مِنَ الْمَضْمُونِ عَنْهُ، أَوْ أَبْرَأَهُ، بَرِئَ ضَامِنُهُ، وَإِنْ أَبْرَأَ الضَّامِنَ، لَمْ يَبْرَأِ الأَصِيلُ، وَإِنِ اسْتَوْفَى مِنَ الضَّامِنِ، رَجَعَ عَلَيْهِ."]]},{"id":"um61_3","label":"بَابُ الْحِوَالَةِ وَالضَّمَانِ · ٣","segs":[["matn","وَمَنْ كَفَلَ بِإِحْضَارِ مَنْ عَلَيْهِ دَيْنٌ فَلَمْ يُحْضِرْهُ، لَزِمَهُ مَا عَلَيْهِ فَإِنْ مَاتَ، بَرِئَ كَفِيلُهُ."]]}],"group":"كِتَابُ الْبُيُوعِ"},{"id":"um62","title":"بَابُ الرَّهْنِ","units":[{"id":"um62_1","label":"بَابُ الرَّهْنِ · ١","segs":[["matn","وَكُلُّ مَا جَازَ بَيْعُهُ، جَازَ رَهْنُهُ وَمَا لَا، فَلَا وَلَا يَلْزَمُ إِلَّا بِالْقَبْضِ وَهُوَ نَقْلُهُ إِنْ كَانَ مَنْقُولاً، وَالتَّخْلِيَةُ فِيمَا سِوَاهُ، وَقَبْضُ أَمِينِ الْمُرْتَهِنِ يَقُومُ مَقَامَ قَبْضِهِ، وَالرَّهْنُ أَمَانَةٌ عِنْدَ الْمُرْتَهِنِ، أَوْ أَمِينِهِ، لَا يَضْمَنُهُ إِلَّا أَنْ يَتَعَدَّى،"]]},{"id":"um62_2","label":"بَابُ الرَّهْنِ · ٢","segs":[["matn","وَلَا يَنْتَفِعُ الْمُرْتَهِنُ بِشَيْءٍ مِنْهُ، إِلَّا مَا كَانَ مَرْكُوبًا أَوْ مَحْلُوبًا، فَلِلْمُرْتَهِنِ أَنْ يَرْكَبَ وَيَحْلُبَ بِمِقْدَارِ الْعَلَفِ وَلِلرَّاهِنِ غُنْمُهُ مِنْ غَلَّتِهِ، وَكَسْبِهِ وَنَمَائِهِ لَكِنْ يَكُونُ رَهْنًا مَعَهُ وَعَلَيْهِ غُرْمُهُ مِنْ مُؤْنَتِهِ، وَمَخْزَنِهِ، وَكَفَنِهِ إِنْ مَاتَ."]]},{"id":"um62_3","label":"بَابُ الرَّهْنِ · ٣","segs":[["matn","وَإِنْ أَتْلَفَهُ، أَوْ أَخْرَجَهُ مِنَ الرَّهْنِ بِعِتْقٍ، أَوِ اسْتِيلَادٍ، فَعَلَيْهِ قِيمَتُهُ تَكُونُ رَهْنًا مَكَانَهُ، وَإِنْ جَنَى عَلَيْهِ غَيْرُهُ فَهُوَ الْخَصْمُ فِيهِ، وَمَا قُبِضَ بِسَبَبِهِ، فَهُوَ رَهْنٌ، وَإِنْ جَنَى الرَّهْنُ، فَالْمَجْنِيُّ عَلَيْهِ أَحَقُّ بِرَقَبَتِهِ، فَإِنْ فَدَاهُ، فَهُوَ رَهْنٌ بِحَالِهِ."]]},{"id":"um62_4","label":"بَابُ الرَّهْنِ · ٤","segs":[["matn","وَإِذَا حَلَّ الدَّيْنُ فَلَمْ يُوَفِّهِ الرَّاهِنُ، بِيعَ، وَأُوفِيَ الْحَقُّ مِنْ ثَمَنِهِ وَبَاقِيهِ لِلرَّاهِنِ، وَإِذَا شُرِطَ الرَّهْنُ أَوِ الضَّمِينُ فِي بَيْعٍ، فَأَبَى الرَّاهِنُ أَنْ يُسَلِّمَهُ، وَأَبَى الضَّمِينُ أَنْ يَضْمَنَ خُيِّرَ الْبَائِعُ بَيْنَ الْفَسْخِ أَوْ إِقَامَتِهِ بِلَا رَهْنٍ وَلَا ضَمِينٍ."]]}],"group":"كِتَابُ الْبُيُوعِ"},{"id":"um63","title":"بَابُ الصُّلْحِ","units":[{"id":"um63_1","label":"بَابُ الصُّلْحِ · ١","segs":[["matn","وَمَنْ أَسْقَطَ بَعْضَ دَيْنِهِ أَوْ وَهَبَ غَرِيمَهُ بَعْضَ الْعَيْنِ الَّتِي فِي يَدِهِ، جَازَ مَا لَمْ يَجْعَلْ وَفَاءَ الْبَاقِي شَرْطًا فِي الْهِبَةِ وَالإِبْرَاءِ، أَوْ يَمْنَعْهُ حَقَّهُ إِلَّا بِذَلِكَ، أَوْ يَضَعَ بَعْضَ الْمُؤَجَّلِ؛ لِيُعَجِّلَ لَهُ الْبَاقِي."]]},{"id":"um63_2","label":"بَابُ الصُّلْحِ · ٢","segs":[["matn","وَيَجُوزُ اقْتِضَاءُ الذَّهَبِ عَنِ الْوَرِقِ، وَالْوَرِقِ عَنِ الذَّهَبِ إِذَا أَخَذَهَا بِسِعْرِ يَوْمِهَا، وَتَقَابَضَا فِي الْمَجْلِسِ."]]},{"id":"um63_3","label":"بَابُ الصُّلْحِ · ٣","segs":[["matn","وَمَنْ كَانَ لَهُ دَيْنٌ عَلَى غَيْرِهِ لَا يَعْلَمُهُ الْمُدَّعَى عَلَيْهِ، فَصَالَحَهُ عَلَى شَيْءٍ، جَازَ وَإِنْ كَانَ أَحَدُهُمَا يَعْلَمُ كَذِبَ نَفْسِهِ، فَالصُّلْحُ فِي حَقِّهِ بَاطِلٌ وَمَنْ كَانَ لَهُ حَقٌّ عَلَى رَجُلٍ لَا يَعْلَمَانِ قَدْرَهُ، فَاصْطَلَحَا عَلَيْهِ، جَازَ."]]}],"group":"كِتَابُ الْبُيُوعِ"},{"id":"um64","title":"بَابُ الْوَكَالَةِ","units":[{"id":"um64_1","label":"بَابُ الْوَكَالَةِ · ١","segs":[["matn","وَهِيَ جَائِزَةٌ فِي كُلِّ مَا تَجُوزُ النِّيَابَةُ فِيهِ إِذَا كَانَ الْمُوَكِّلُ وَالْوَكِيلُ مِمَّنْ يَصِحُّ ذَلِكَ مِنْهُ، وَهِيَ عَقْدٌ جَائِزٌ تَبْطُلُ بِمَوْتِ كُلِّ وَاحِدٍ مِنْهُمَا، وَفَسْخِهِ لَهَا، وَجُنُونِهِ، وَالْحَجْرِ عَلَيْهِ لِسَفَهٍ، وَكَذَلِكَ فِي كُلِّ عَقْدٍ جَائِزٍ كَالشَّرِكَةِ وَالْمُسَاقَاةِ وَالْمُزَارَعَةِ وَالْجَعَالَةِ وَالْمُسَابَقَةِ."]]},{"id":"um64_2","label":"بَابُ الْوَكَالَةِ · ٢","segs":[["matn","وَلَيْسَ لِلْوَكِيلِ أَنْ يَفْعَلَ إِلَّا مَا تَنَاوَلَهُ الإِذْنُ لَفْظًا أَوْ عُرْفًا، وَلَيْسَ لَهُ تَوْكِيلُ غَيْرِهِ وَلَا الشِّرَاءُ مِنْ نَفْسِهِ، وَلَا الْبَيْعُ لَهَا، إِلَّا بِإِذْنٍ، مُوَكِّلِهِ وَإِنِ اشْتَرَى لِإِنْسَانٍ مَا لَمْ يَأْذَنْ لَهُ فِيهِ، فَأَجَازَهُ، جَازَ، وَإِلَّا لَزِمَ مَنِ اشْتَرَاهُ."]]},{"id":"um64_3","label":"بَابُ الْوَكَالَةِ · ٣","segs":[["matn","وَالْوَكِيلُ أَمِينٌ، لَا ضَمَانَ عَلَيْهِ فِيمَا يَتْلَفُ، إِذَا لَمْ يَتَعَدَّ، وَالْقَوْلُ قَوْلُهُ فِي الرَّدِّ وَالتَّلَفِ وَنَفْيِ التَّعَدِّي وَإِذَا قَضَى الدَّيْنَ بِغَيْرِ بَيِّنَةٍ، ضَمِنَ، إِلَّا أَنْ يَقْضِيَهُ بِحَضْرَةِ الْمُوَكِّلِ."]]},{"id":"um64_4","label":"بَابُ الْوَكَالَةِ · ٤","segs":[["matn","وَيَجُوزُ التَّوْكِيلُ بِجُعْلٍ وَبِغَيْرِهِ، فَلَوْ قَالَ: بِعْ هَذَا بِعَشَرَةٍ، فَمَا زَادَ، فَلَكَ، صَحَّ."]]}],"group":"كِتَابُ الْبُيُوعِ"},{"id":"um65","title":"بَابُ الشَّرِكَةِ","units":[{"id":"um65_1","label":"بَابُ الشَّرِكَةِ · ١","segs":[["matn","وَهِيَ عَلَى أَرْبَعَةِ أَضْرُبٍ: شَرِكَةُ الْعِنَانِ: وَهِيَ: أَنْ يَشْتَرِكَا بِمَالَيْهِمَا وَبَدَنَيْهِمَا. وَشَرِكَةُ الْوُجُوهِ: وَهِيَ: أَنْ يَشْتَرِكَا فِيمَا يَشْتَرِيَانِ بِجَاهَيْهِمَا."]]},{"id":"um65_2","label":"بَابُ الشَّرِكَةِ · ٢","segs":[["matn","وَالْمُضَارَبَةُ: وَهِيَ: أَنْ يَدْفَعَ أَحَدُهُمَا إِلَى الآخَرِ مَالاً يتَّجِرُ فِيهِ وَيَشْتَرِكَانِ فِي رِبْحِهِ. وَشَرِكَةُ الأَبْدَانِ: وَهِيَ: أَنْ يَشْتَرِكَا فِيمَا يَكْسِبَانِ بِأَبْدَانِهِمَا مِنَ الْمُبَاحِ، إِمَّا بِصِنَاعَةٍ، أَوْ احْتِشَاشٍ، أَوِ اصْطِيَادٍ وَنَحْوِهِ؛"]]},{"id":"um65_3","label":"بَابُ الشَّرِكَةِ · ٣","segs":[["matn","لِمَا رُوِيَ عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: اشْتَرَكْتُ أَنَا وَسَعْدٌ وَعَمَّارٌ يَوْمَ بَدْرٍ، فَجَاءَ سَعْدٌ بِأَسِيرَيْنِ، وَلَمْ آتِ أَنَا وَعَمَّارٌ بِشَيْءٍ."]]},{"id":"um65_4","label":"بَابُ الشَّرِكَةِ · ٤","segs":[["matn","وَالرِّبْحُ فِي جَمِيعِ ذَلِكَ عَلَى مَا شَرَطَاهُ، وَالْوَضِيعَةُ عَلَى قَدْرِ الْمَالِ، وَلَا يَجُوزُ أَنْ يُجْعَلَ لِأَحَدُهُمَا دَرَاهِمُ مُعَيَّنَةٌ، وَلَا رِبْحُ بِشَيْءٍ مُعَيَّنٍ،"]]},{"id":"um65_5","label":"بَابُ الشَّرِكَةِ · ٥","segs":[["matn","وَالْحُكْمُ فِي الْمُسَاقَاةِ وَالْمُزَارَعَةِ، كَذَلِكَ، وَتُجْبَرُ الْوَضِيعَةُ مِنَ الرِّبْحِ، وَلَيْسَ لِأَحَدُهُمَا الْبَيْعُ بِنَسِيئَةٍ وَلَا أَخْذُ شَيْءٍ مِنَ الرِّبْحِ إِلَّا بِإِذْنِ الْآخَرِ."]]}],"group":"كِتَابُ الْبُيُوعِ"},{"id":"um66","title":"بَابُ الْمُسَاقَاةِ وَالْمُزَارَعَةِ","units":[{"id":"um66_1","label":"بَابُ الْمُسَاقَاةِ وَالْمُزَارَعَةِ · ١","segs":[["matn","تَجُوزُ الْمُسَاقَاةُ فِي كُلِّ شَجَرٍ لَهُ ثَمَرٌ بِجُزْءٍ مِنْ ثَمَرِهِ، مُشَاعٍ مَعْلُومٍ وَالْمُزَارَعَةُ فِي الأَرْضِ بِجُزْءٍ مِنْ زَرْعِهَا، سَوَاءٌ كَانَ الْبَذْرُ مِنْهُمَا،"]]},{"id":"um66_2","label":"بَابُ الْمُسَاقَاةِ وَالْمُزَارَعَةِ · ٢","segs":[["matn","أَوْ مِنْ أَحَدُهُمَا لِقَوْلِ ابْنِ عُمَرَ عَامَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَهْلَ خَيْبَرَ بِشَطْرِ مَا يَخْرُجُ مِنْهَا مِنْ زَرْعٍ وَثَمَرٍ، وَفِي لَفْظٍ: عَلَى أَنْ يَعْمُرُوهَا مِنْ أَمْوَالِهِمْ."]]},{"id":"um66_3","label":"بَابُ الْمُسَاقَاةِ وَالْمُزَارَعَةِ · ٣","segs":[["matn","وَعَلَى الْعَامِلِ مَا جَرَتِ الْعَادَةُ بِعَمَلِهِ، وَلَوْ دَفَعَ إِلَى رَجُلٍ دَابَّةً يَعْمَلُ عَلَيْهَا، وَمَا حَصَلَ بَيْنَهُمَا، جَازَ عَلَى قِيَاسِ ذَلِكَ."]]}],"group":"كِتَابُ الْبُيُوعِ"},{"id":"um67","title":"بَابُ إِحْيَاءِ الْمَوَاتِ","units":[{"id":"um67_1","label":"بَابُ إِحْيَاءِ الْمَوَاتِ · ١","segs":[["matn","وَهِيَ الأَرْضُ الدَّاثِرَةُ الَّتِي لَا يُعْرَفُ لَهَا مَالِكٌ، فَمَنْ أَحْيَاهَا مَلَكَهَا؛"]]},{"id":"um67_2","label":"بَابُ إِحْيَاءِ الْمَوَاتِ · ٢","segs":[["matn","لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «مَنْ أَحْيَا أَرْضًا مَيْتَةً، فَهِيَ لَهُ،» وَإِحْيَاؤُهَا عِمَارَتُهَا بِمَا تَتَهَيَّأُ بِهِ لِمَا يُرَادُ مِنْهَا، كَالتَّحْوِيطِ عَلَيْهَا، وَسَوْقِ الْمَاءِ إِلَيْهَا إِنْ أَرَادَهَا لِلزَّرْعِ، وْقَلْعِ أَشْجَارِهَا وَأَحْجَارِهَا الْمَانِعَةِ مِنْ غَرْسِهَا وَزَرْعِهَا."]]},{"id":"um67_3","label":"بَابُ إِحْيَاءِ الْمَوَاتِ · ٣","segs":[["matn","وَإِنْ حَفَرَ فِيهَا بِئْرًا، فَوَصَلَ إِلَى الْمَاءِ، مَلَكَ حَرِيمَهُ، وَهُوَ خَمْسُونَ ذِرَاعًا مِنْ كُلِّ جَانِبٍ، إِنْ كَانَتْ عَادِيَةً، وَحَرِيمُ الْبِئْرِ الْبَدِيءِ خَمْسَةٌ وَعِشْرُونَ ذِرَاعًا."]]}],"group":"كِتَابُ الْبُيُوعِ"},{"id":"um68","title":"بَابُ الْجُعَالَةِ","units":[{"id":"um68_1","label":"بَابُ الْجُعَالَةِ · ١","segs":[["matn","وَهِيَ أَنْ يَقُولَ: مَنْ رَدَّ لُقَطَتِي، أَوْ ضَالَّتِي، أَوْ بَنَى لِي هَذَا الْحَائِطَ، فَلَهُ كَذَا فَمَنْ فَعَلَ ذَلِكَ، اسْتَحَقَّ الْجُعْلَ؛"]]},{"id":"um68_2","label":"بَابُ الْجُعَالَةِ · ٢","segs":[["matn","لِمَا رَوَى أَبُو سَعِيدٍ أَنَّ قَوْمًا لُدِغَ رَجُلٌ مِنْهُمْ، فَأَتَوْا أَصْحَابَ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالُوا: هَلْ فِيكُمْ مِنْ رَاقٍ، فَقَالُوا: لَا، حَتَّى تَجْعَلُوا لَنَا شَيْئًا، فَجَعَلُوا لَهُمْ قَطِيعًا مِنَ الْغَنَمِ."]]},{"id":"um68_3","label":"بَابُ الْجُعَالَةِ · ٣","segs":[["matn","فَجَعَلَ رَجُلٍ مِنْهُمْ يَقْرَأُ بِفَاتِحَةِ الْكِتَابِ، وَيَرْقِي، وَيَتْفُلُ حَتَّى بَرَأَ، فَأَخَذُوا الْغَنَمَ، وَسَأَلُوا عَنْ ذَلِكَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: «وَمَا يُدْرِيكُمْ أَنَّهَا رُقْيَةٌ؟ خُذُوا وَاضْرِبُوا لِي مَعَكُمْ بِسَهْمٍ،» وَلَوْ الْتَقَطَ اللُّقَطَةَ قَبْلَ أَنْ يَبْلُغَهُ الْجُعْلُ، لَمْ يَسْتَحِقَّهُ."]]}],"group":"كِتَابُ الْبُيُوعِ"},{"id":"um69","title":"بَابُ اللُّقَطَةِ","units":[{"id":"um69_1","label":"بَابُ اللُّقَطَةِ · ١","segs":[["matn","وَهِيَ عَلَى ثَلَاثَةِ أَضْرُبٍ: أَحَدُهَا: مَا تَقِلُّ قِيمَتُهُ، فَيَجُوزُ أَخْذُهُ وَالِانْتِفَاعُ بِهِ مِنْ غَيْرِ تَعْرِيفٍ؛ لِقَوْلِ جَابِرٍ رَخَّصَ لَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْعَصَا وَالسَّوْطِ وَأَشْبَاهِهِ، يَلْتَقِطُهُ الرَّجُلُ يَنْتَفِعُ بِهِ."]]},{"id":"um69_2","label":"بَابُ اللُّقَطَةِ · ٢","segs":[["matn","الثَّانِي: الْحَيَوَانُ الَّذِي يَمْتَنِعُ بِنَفْسِهِ مِنْ صِغَارِ السِّبَاعِ، كَالإِبِلِ وَالْخَيْلِ، وَنَحْوِهَا، فَلَا يَجُوزُ أَخْذُهَا؛"]]},{"id":"um69_3","label":"بَابُ اللُّقَطَةِ · ٣","segs":[["matn","لِأَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سُئِلَ عَنْ ضَالَّةِ الإِبِلِ، فَقَالَ: «مَالَكَ وَلَهَا، دَعْهَا مَعَهَا حِذَاؤُهَا وَسِقَاؤُهَا، تَرِدُ الْمَاءَ، وَتَأْكُلُ الشَّجَرَ حَتَّى يَأْتِيَهَا رَبُّهَا» وَمَنْ أَخَذَ هَذَا لَمْ يَمْلِكْهُ، وَلَزِمَهُ ضَمَانُهُ، وَلَمْ يَبْرَأْ إِلَّا بِدَفْعِهِ إِلَى نَائِبِ الإِمَامِ."]]},{"id":"um69_4","label":"بَابُ اللُّقَطَةِ · ٤","segs":[["matn","الثَّالِثُ: مَا تَكْثُرُ قِيمَتُهُ مِنَ الأَثْمَانِ وَالْمَتَاعِ وَالْحَيَوَانِ الَّذِي لَا يَمْتَنِعُ مِنْ صِغَارِ السِّبَاعِ، فَيَجُوزُ أَخْذُهُ، وَيَجِبُ تَعْرِيفُهُ حَوْلاً، فِي مَجَامِعِ النَّاسِ، كَالأَسْوَاقِ وَأَبْوَابِ الْمَسَاجِدِ، فَمَتَى جَاءَ طَالِبُهُ، فَوَصَفَهُ، دَفَعَهُ إِلَيْهِ بِغَيْرِ بَيِّنَةٍ، وَإِنْ لَمْ يُعْرَفْ، فَهُوَ كَسَائِرِ مَالِهِ،"]]},{"id":"um69_5","label":"بَابُ اللُّقَطَةِ · ٥","segs":[["matn","وَلَا يَتَصَرَّفَ فِيهِ حَتَّى يَعْرِفَ وِعَاءَهُ، وَوِكَاءَهُ وَصِفَتَهُ، فَمَتَى جَاءَ طَالِبُهُ، فَوَصَفَهُ، دَفَعَ إِلَيْهِ أَوْ مِثْلَهُ إِنْ كَانَ قَدْ هَلَكَ، وَإِنْ كَانَ حَيَوَانًا يَحْتَاجُ إِلَى مُؤنَةٍ، أَوْ شَيْئًا يَخْشَى تَلَفَهُ، فَلَهُ أَكْلُهُ قَبْلَ التَّعْرِيفِ، أَوْ بَيْعُهُ، ثُمَّ يُعَرِّفُهُ؛"]]},{"id":"um69_6","label":"بَابُ اللُّقَطَةِ · ٦","segs":[["matn","لِمَا رَوَى زَيْدُ بْنُ خَالِدٍ قَالَ: سُئِلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ لُقَطَةِ الذَّهَبِ وَالْوَرِقِ، فَقَالَ: «اعْرِفْ وِكَاءَهَا وَعِفَاصَهَا ثُمَّ عَرِّفْهَا» سَنَةً، فَإِنْ جَاءَ طَالِبُهَا يَوْمًا مِنَ الدَّهْرِ، فَادْفَعْهَا إِلَيْهِ."]]},{"id":"um69_7","label":"بَابُ اللُّقَطَةِ · ٧","segs":[["matn","«وَسَأَلَهُ عَنِ الشَّاةِ، فَقَالَ:» خُذْهَا فَإِنَّمَا هِيَ لَكَ، أَوْ لِأَخِيكَ، أَوْ لِلذِّئْبِ، «وَإِنْ هَلَكَتِ الُّلقَطَةُ فِي حَوْلِ التَّعْرِيفِ مِنْ غَيْرِ تَعَدٍّ، فَلَا ضَمَانَ فِيهَا.»"]]},{"id":"um69_8","label":"بَابُ اللُّقَطَةِ · ٨","segs":[["matn","فَصْلٌ: هُوَ الطِّفْلُ الْمَنْبُوذُ، وَهُوَ مَحْكُومٌ بِحُرَّيَتِهِ، وَإِسْلَامِهِ، وَمَا وُجِدَ عِنْدَهُ مِنَ الْمَالِ، فَهُوَ لَهُ وَوِلَايَتُهُ لِمُلْتَقِطِهِ، إِذَا كَانَ مُسْلِمًا عَدْلاً وَنَفَقَتُهُ فِي بَيْتِ الْمَالِ،"]]},{"id":"um69_9","label":"بَابُ اللُّقَطَةِ · ٩","segs":[["matn","إِنْ لَمْ يَكُنْ مَعَهُ مَا يُنْفَقُ عَلَيْهِ، وَمَا خَلَّفَهُ فَهُوَ فَيْءٌ، وَمَنِ ادَّعَى نَسَبَهُ، أُلْحِقَ بِهِ، إِلَّا إِنْ كَانَ كَافِرًا، أُلْحِقَ بِهِ نَسَبًا، لَا دِينًا، وَلَمْ يُسَلَّمْ إِلَيْهِ."]]}],"group":"كِتَابُ الْبُيُوعِ"},{"id":"um70","title":"بَابُ السَّبْقِ","units":[{"id":"um70_1","label":"بَابُ السَّبْقِ · ١","segs":[["matn","وَتَجُوزُ الْمُسَابَقَةُ بِغَيْرِ جُعْلٍ فِي الأَشْيَاءِ كُلِّهَا، وَلَا تَجُوزُ بِجُعْلٍ، إِلَّا فِي الْخَيْلِ وَالإِبِلِ وَالسِّهَامِ لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «لَا سَبْقَ إِلَّا فِي نَصْلٍ، أَوْ خُفٍّ، أَوْ حَافِرٍ» فَإِنْ كَانَ الْجُعْلُ مِنْ غَيْرِ الْمُسْتَبِقَيْنِ،"]]},{"id":"um70_2","label":"بَابُ السَّبْقِ · ٢","segs":[["matn","جَازَ، وَهُوَ لِلسَّابِقِ مِنْهُمَا، وَإِنْ كَانَ مِنْ أَحَدُهُمَا، فَسَبَقَ الْمُخْرِجُ، أَوْ جَاءَا مَعًا، أَحْرَزَ سَبْقَهُ، وَلَا شَيْءَ لَهُ سِوَاهُ، وَإِنْ سَبَقَ الآخَرُ أَخَذَهُ، وَإِنْ أَخْرَجَا جَمِيعًا، لَمْ يَجُزْ، إِلَّا أَنْ يُدْخِلَا بَيْنَهُمَا مُحَلِّلَا يُكَافِئُ فَرَسُهُ فَرَسَيْهِمَا،"]]},{"id":"um70_3","label":"بَابُ السَّبْقِ · ٣","segs":[["matn","أَوْ بَعِيرُهُ بَعِيرَيْهِمِا، أَوْ رَمْيُهُ رَمْيَهُمَا لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «مَنْ أَدْخَلَ فَرَسًا بَيْنَ فَرَسَيْنِ، وَهُوَ لَا يَأْمَنُ أَنْ يُسْبَقَ، فَلَيْسَ بِقِمَارٍ. وَمَنْ أَدْخَلَ فَرَسًا بَيْنَ فَرَسَيْنِ، وَقَدْ أَمِنَ أَنْ يُسْبَقَ فَهُوَ قِمَارٌ» فَإِنْ سَبَقَهُمَا،"]]},{"id":"um70_4","label":"بَابُ السَّبْقِ · ٤","segs":[["matn","أَحْرَزَ سَبَقَيْهِمِا، وَإِنْ سَبَقَ أَحَدُهُمَا، أَحْرَزَ سَبَقَ نَفْسِهِ وَأَخَذَ سَبَقَ صَاحِبِهِ، وَلَا بُدَّ مِنْ تَحْدِيدِ الْمَسَافَةِ، وَبَيَانِ الغَايَةِ، وَقَدْرِ الإِصَابَةِ، وَصِفَتِهَا، وَعَدَدِ الرِّشْقِ، وَإِنَّمَا تَكُونُ الْمُسَابَقَةُ فِي الرَّمْيِ عَلَى الإِصَابَةِ، لَا عَلَى الْبُعْدِ."]]}],"group":"كِتَابُ الْبُيُوعِ"},{"id":"um71","title":"بَابُ الْوَدِيعَةِ","units":[{"id":"um71_1","label":"بَابُ الْوَدِيعَةِ · ١","segs":[["matn","وَهِيَ أَمَانَةٌ، عِنْدَ الْمُودَعِ، لَا ضَمَانَ عَلَيْهِ فِيهَا إِلَّا أَنْ يَتَعَدَّى."]]},{"id":"um71_2","label":"بَابُ الْوَدِيعَةِ · ٢","segs":[["matn","وَإِنْ لَمْ يَحْفَظْهَا فِي حِرْزِ مِثْلِهَا، أَوْ مِثْلِ الْحِرْزِ الَّذِي أُمِرَ بِإِحْرَازِهَا فِيهِ، أَوْ تَصَرَّفَ فِيهَا لِنَفْسِهِ، أَوْ خَلَطَهَا بِمَا لَا تَتَمَيَّزُ مِنْهُ، أَوْ أَخْرَجَهَا لِيُنْفِقَهَا ثُمَّ رَدَّهَا،"]]},{"id":"um71_3","label":"بَابُ الْوَدِيعَةِ · ٣","segs":[["matn","أَوْ كَسَرَ خَتْمَ كِيسِهَا، أَوْ جَحَدَهَا، ثُمَّ أَقَرَّ بِهَا، أَوِ امْتَنَعَ مِنْ رَدِّهَا عِنْدَ طَلَبِهَا مَعَ إِمْكَانِهِ، ضَمِنَهَا، وَإِنْ قَالَ: مَا أَوْدَعْتَنِي، ثُمَّ ادَّعَى تَلَفَهَا، أَوْ رَدَّهَا، لَمْ يُقْبَلْ مِنْهُ."]]},{"id":"um71_4","label":"بَابُ الْوَدِيعَةِ · ٤","segs":[["matn","وَإِنْ قَالَ: مَالَكَ عِنْدِي شَيْءٌ، ثُمَّ ادَّعَى رَدَّهَا، أَوْ تَلَفَهَا، قُبِلَ. وَالْعَارِيَةُ مَضْمُونُةٌ، وَإِنْ لَمْ يَتَعَدَّ فِيهَا المُسْتَعِيرُ."]]}],"group":"كِتَابُ الْبُيُوعِ"},{"id":"um72","title":"كِتَابُ الْإِجَارَةِ","units":[{"id":"um72_1","label":"كِتَابُ الْإِجَارَةِ · ١","segs":[["matn","وَهِيَ عَقْدٌ عَلَى الْمَنَافِعِ، لَازِمٌ مِنَ الطَّرَفَيْنِ، لَا يَمْلِكُ أَحَدُهُمَا فَسْخَهَا، وَلَا تَنْفَسِخُ بِمَوْتِهِ وَلَا جُنُونِهِ، وَتَنْفَسِخُ بِتَلَفِ الْعَيْنِ الْمَعْقُودِ عَلَيْهَا، أَوِ انْقِطَاعِ نَفْعِهَا، وَلِلْمُسْتَأْجِرِ فَسْخَهَا بِالْعَيْبِ قَدِيمًا كَانَ أَوْ حَادِثًا، وَلَا تَصِحُّ إِلَّا عَلَى نَفْعٍ مَعْلُومٍ،"]]},{"id":"um72_2","label":"كِتَابُ الْإِجَارَةِ · ٢","segs":[["matn","إِمَّا بِالْعُرْفِ، كَسُكْنَى دَارٍ، أَوْ بِالْوَصْفِ، كَخِيَاطَةِ ثَوْبٍ مُعَيَّنٍ، أَوْ بِنَاءِ حَائِطٍ، أَوْ حَمْلِ شَيْءٍ إِلَى مَوْضِعٍ مُعَيَّنٍ، وَضَبْطِ ذَلِكَ بِصِفَاتِهِ، أَوْ مَعْرِفَةِ أُجْرَتِهِ، وَإِنْ وَقَعَتْ عَلَى عَيْنٍ، فَلَا بُدَّ مِنْ مَعْرِفَتِهَا."]]},{"id":"um72_3","label":"كِتَابُ الْإِجَارَةِ · ٣","segs":[["matn","وَمَنِ اسْتَأْجَرَ شَيْئًا فَلَهُ أَنْ يُقِيمَ مَقَامَهُ مَنْ يَسْتَوْفِيهِ بِإِجَارَتِهِ أَوْ غَيْرِهَا، إِذَا كَانَ مِثْلَهُ أَوْ دُونَهُ، وَإِنِ اسْتَأْجَرَ أَرْضًا لِزَرْعٍ،"]]},{"id":"um72_4","label":"كِتَابُ الْإِجَارَةِ · ٤","segs":[["matn","فَلَهُ زَرْعَ مَا هُوَ أَقَلُّ مِنْهُ ضَرَرًا فَإِنْ زَرَعَ مَا هُوَ أَكْثَرُ مِنْهُ ضَرَرًا أَوْ يُخَالِفُ ضَرَرُهُ ضَرَرَهُ، فَعَلَيْهِ أُجْرَةُ الْمِثْلِ."]]},{"id":"um72_5","label":"كِتَابُ الْإِجَارَةِ · ٥","segs":[["matn","وَإِنِ اكْتَرَى إِلَى مَوْضِعٍ فَجَاوَزَهُ أَوْ لِحَمْلِ شَيْءٍ فَزَادَ عَلَيْهِ، فَعَلَيْهِ أُجْرَةُ الْمِثْلِ لِلزَّائِدِ، وَضَمَانُ الْعَيْنِ إِنْ تَلِفَتْ، وَإِنْ تَلِفَتِ مِنْ غَيْرِ تَعَدٍّ فَلَا ضَمَانَ عَلَيْهِ."]]},{"id":"um72_6","label":"كِتَابُ الْإِجَارَةِ · ٦","segs":[["matn","وَلَا ضَمَانَ عَلَى الأَجِيرِ الَّذِي يُؤَجِّرُ نَفْسَهُ مُدَّةً بِعَيْنِهَا فِيمَا يَتْلَفُ فِي يَدِهِ مِنْ غَيْرِ تَفْرِيطٍ، وَلَا عَلَى حَجَّامٍ أَوْ خَتَّانٍ أَوْ طَبِيبٍ إِذَا عُرِفَ مِنْهُ حِذْقٌ فِي الصَّنْعَةِ، وَلَمْ تَجْنِ أَيْدِيهِمْ، وَلَا عَلَى الرَّاعِي إِذَا لَمْ يَتَعَدَّ."]]},{"id":"um72_7","label":"كِتَابُ الْإِجَارَةِ · ٧","segs":[["matn","وَيَضْمَنُ الْقَصَّارُ وَالْخَيَّاطُ وَنَحْوُهُمَا مِمَّنْ يَتَقَبَّلُ الْعَمَلَ مَا تَلِفَ بِعَمَلِهِ، دُونَ مَا تَلِفَ مِنْ حِرْزِهِ."]]}],"group":"كِتَابُ الْإِجَارَةِ"},{"id":"um73","title":"بَابُ الْغَصْبِ","units":[{"id":"um73_1","label":"بَابُ الْغَصْبِ · ١","segs":[["matn","وَهُوَ اسْتِيلَاءُ الإِنْسَانِ عَلَى مَالِ غَيْرِهِ، بِغَيْرِ حَقٍّ. مَنْ غَصَبَ شَيْئًا، فَعَلَيْهِ رَدُّهُ، وَأُجْرَةُ مِثْلِهِ إِنْ كَانَ لَهُ أُجْرَةٌ مُدَّةَ مَقَامِهِ فِي يَدِهِ وَإِنْ نَقَصَ فَعَلَيْهِ أَرْشُ نَقْصِهِ."]]},{"id":"um73_2","label":"بَابُ الْغَصْبِ · ٢","segs":[["matn","وَإِنْ جَنَى الْمَغْصُوبُ فَأَرْشُ جِنَايَتِهِ عَلَيْهِ سَوَاءٌ جَنَى عَلَى سَيِّدِهِ أَوْ أَجْنَبِيٍّ، وَإِنْ جَنَى عَلَيْهِ أَجْنَبِيٌّ فَلِسَيِّدِهِ تَضْمِينُ مَنْ شَاءَ مِنْهُمَا."]]},{"id":"um73_3","label":"بَابُ الْغَصْبِ · ٣","segs":[["matn","وَإِنْ زَادَ الْمَغْصُوبُ رَدَّهُ بِزِيَادَتِهِ، سَوَاءٌ كَانَتْ مُتَّصِلَةً أَوْ مُنْفَصِلَةً، وَإِنْ زَادَ أَوْ نَقَصَ رَدَّهُ بِزِيَادَتِهِ وَضَمِنَ نَقْصَهُ، سَوَاءٌ زَادَ بِفِعْلِهِ أَوْ بِغَيْرِ فِعْلِهِ، فَلَوْ نَجَرَ الْخَشَبَةَ بَابًا أَوْ عَمِلَ الْحَدِيدَ إِبْرًا رَدَّهُمَا بِزِيَادَتِهِمَا وَضَمِنَ نَقْصَهُمَا إِنْ نَقَصَا،"]]},{"id":"um73_4","label":"بَابُ الْغَصْبِ · ٤","segs":[["matn","وَلَوْ غَصَبَ قُطْنًا فَغَزَلَهُ أَوْ غَزْلاً فَنَسَجَهُ، أَوْ ثَوْبًا فَقَصَرَهُ أَوْ فَصَّلَهُ وَخَاطَهُ، أَوْ حَبًّا فَصَارَ زَرْعًا، أَوْ نَوًى فَصَارَ شَجَرًا، أَوْ بَيْضًا فَصَارَ فِرَاخًا، فَكَذَلِكَ، وَإِنْ غَصَبَ عَبْدًا فَزَادَ فِي بَدَنِهِ أَوْ بِتَعْلِيمِهِ ثُمَّ ذَهَبَتِ الزِّيَادَةُ، رَدَّهُ وَقِيمَةَ الزِّيَادَةِ."]]},{"id":"um73_5","label":"بَابُ الْغَصْبِ · ٥","segs":[["matn","وَإِنْ تَلِفَ الْمَغْصُوبُ أَوْ تَعَذَّرَ رَدُّهُ، فَعَلَيْهِ مِثْلُهُ إِنْ كَانَ مَكِيلاً أَوْ مَوْزُونًا، وَقِيمَتُهُ إِنْ لَمْ يَكُنْ كَذَلِكَ، ثُمَّ إِنْ قَدَرَ عَلَى رَدِّهِ، رَدَّهُ وَيَأْخُذُ الْقِيمَةَ."]]},{"id":"um73_6","label":"بَابُ الْغَصْبِ · ٦","segs":[["matn","وَإِنْ خَلَطَ الْمَغْصُوبَ بِمَا لَا يَتَمَيَّزُ بِهِ جِنْسِهِ، فَعَلَيْهِ مِثْلُهُ مِنْهُ، وَإِنْ خَلَطَهُ بِغَيْرِ جِنْسِهِ، فَعَلَيْهِ مِثْلُهُ مِنْ حَيْثُ شَاءَ."]]},{"id":"um73_7","label":"بَابُ الْغَصْبِ · ٧","segs":[["matn","وَإِنْ غَصَبَ أَرْضًا، فَغَرَسَهَا، أُخِذَ بِقَلْعِ غَرْسِهِ وَرَدِّهَا وَأَرْشِ نَقْصِهَا وَأُجْرَتِهَا وَإِنْ زَرَعَهَا وَأَخَذَ الْغَاصِبُ الزَّرْعَ رَدَّهَا وَأُجْرَتَهَا، وَإِنْ أَدْرَكَ مَالِكُهَا الزَّرْعَ قَبْلَ حَصَادِهِ خُيِّرَ بَيْنَ ذَلِكَ وَبَيْنَ أَخْذِ الزَّرْعِ بِقِيمَتِهِ."]]},{"id":"um73_8","label":"بَابُ الْغَصْبِ · ٨","segs":[["matn","وَإِنْ غَصَبَ جَارِيَةً، فَوَطِئَهَا وَأَوْلَدَهَا، لَزِمَهُ الْحَدُّ، وَرَدُّهَا وَرَدُّ وَلَدِهَا، وَمَهْرُ مِثْلِهَا وَأَرْشُ نَقْصِهَا وَأُجْرَةُ مِثْلِهَا، وَإِنْ بَاعَهَا فَوَطِئَهَا الْمُشْتَرِي وَهُوَ لَا يَعْلَمُ فَعَلَيْهِ مَهْرُهَا وَقِيمَةُ وَلَدِهَا إِنْ أَوْلَدَهَا، وَأُجْرَةُ مِثْلِهَا، وَيَرْجِعُ بِذَلِكَ كُلِّهِ عَلَى الْغَاصِبِ."]]}],"group":"كِتَابُ الْإِجَارَةِ"},{"id":"um74","title":"بَابُ الشُّفْعَةِ","units":[{"id":"um74_1","label":"بَابُ الشُّفْعَةِ · ١","segs":[["matn","وَهُوَ اسْتِحْقَاقُ الإِنْسَانِ انْتِزَاعَ حِصَّةِ شَرِيكِهِ مِنْ يَدِ مُشْتَرِيهَا. وَلَا تَجِبُ إِلَّا بِشُرُوطٍ سَبْعَةٍ: أَحَدُهَا: الْبَيْعُ، فَلَا تَجِبُ فِي مَوْهُوبٍ، وَلَا مَوْقُوفٍ، وَلَا عِوَضِ خُلْعٍ، وَلَا صَدَاقٍ."]]},{"id":"um74_2","label":"بَابُ الشُّفْعَةِ · ٢","segs":[["matn","الثَّانِي: أَنْ يَكُونَ عَقَارًا، أَوْ مَا يَتَّصِلُ بِهِ مِنَ الْبِنَاءِ وَالْغِرَاسِ."]]},{"id":"um74_3","label":"بَابُ الشُّفْعَةِ · ٣","segs":[["matn","الثَّالِثُ: أَنْ يَكُونَ شِقْصًا مُشَاعًا، فَأَمَّا الْمَقْسُومُ الْمَحْدُودُ، فَلَا شُفْعَةَ فِيهِ، لِقَوْلِ جَابِرٍ قَضَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالشُّفْعَةِ فِي كُلِّ مَا لَمْ يُقْسَمْ، فَإِذَا وَقَعَتِ الْحُدُودُ، وَصُرِّفَتِ الطُّرُقُ، فَلَا شُفْعَةَ."]]},{"id":"um74_4","label":"بَابُ الشُّفْعَةِ · ٤","segs":[["matn","الرَّابِعُ: أَنْ يَكُونَ مِمَّا يَنْقَسِمُ، فَأَمَّا مَا لَا يَنْقَسِمُ، فَلَا شُفْعَةَ فِيهِ."]]},{"id":"um74_5","label":"بَابُ الشُّفْعَةِ · ٥","segs":[["matn","الْخَامِسُ: أَنْ يَأْخُذَ الشِّقْصَ كُلَّهُ، فَإِنْ طَلَبَ بَعْضَهُ سَقَطَتْ شُفْعَتُهُ، وَلَوْ كَانَ لَهُ شَفِيعَانِ، فَالشُّفْعَةُ بَيْنَهُمَا عَلَى قَدْرِ سِهَامِهَمَا فَإِنْ تَرَكَ أَحَدُهُمَا شُفْعَتَهُ، لَمْ يَكُنْ لِلآخَرِ إِلَّا أَخْذُ الْكُلِّ، أَوِ التَّرْكِ."]]},{"id":"um74_6","label":"بَابُ الشُّفْعَةِ · ٦","segs":[["matn","السَّادِسُ: إِمْكَانُ أَدَاءِ الثَّمَنِ، فَإِنْ عَجِزَ عَنْهُ، أَوْ عَنْ بَعْضِهِ، سَقَطَتْ شُفْعَتُهُ، وَإِذَا كَانَ الثَّمَنُ مِثْلِيًّا، فَعَلَيْهِ مِثْلُهُ، وَإِنْ لَمْ يَكُنْ مِثْلِيًّا، فَعَلَيْهِ قِيمَتُهُ، وَإِنِ اخْتَلَفَا فِي قَدْرِهِ، وَلَا بَيِّنَةَ لَهُمَا، فَالْقَوْلُ قَوْلُ الْمُشْتَرِي مَعَ يَمِينِهِ."]]},{"id":"um74_7","label":"بَابُ الشُّفْعَةِ · ٧","segs":[["matn","السَّابِعُ: الْمُطَالَبَةُ بِهَا عَلَى الْفَوْرِ سَاعَةَ يَعْلَمُ، فَإِنْ أَخَّرَهَا، بَطَلَتْ شُفْعَتُهُ إِلَّا أَنْ يَكُونَ عَاجِزًا عَنْهَا؛"]]},{"id":"um74_8","label":"بَابُ الشُّفْعَةِ · ٨","segs":[["matn","لِغَيْبَةٍ أَوْ حَبْسٍ، أَوْ مَرَضٍ، أَوْ صِغَرٍ، فَيَكُونُ عَلَى شُفْعَتِهِ مَتَى قَدَرَ عَلَيْهَا إلَّا أَنَّهُ إِنْ أَمْكَنَهُ الإِشْهَادُ عَلَى الطَّلَبِ بِهَا، فَلَمْ يُشْهِدْ،"]]},{"id":"um74_9","label":"بَابُ الشُّفْعَةِ · ٩","segs":[["matn","بَطَلَتْ شُفْعَتُهُ، فَإِنْ لَمْ يَعْلَمْ حَتَّى تَبَايَعَ ثَلَاثَةٌ فَأَكْثَرُ فَلَهُ مُطَالَبَةُ مَنْ شَاءَ مِنْهُمْ، فَإِنْ أَخَذَ مِنَ الأَوَّلِ رَجَعَ عَلَيْهِ الثَّانِي بِمَا أُخِذَ مِنْهُ،"]]},{"id":"um74_10","label":"بَابُ الشُّفْعَةِ · ١٠","segs":[["matn","وَالثَّالِثُ عَلَى الثَّانِي، وَمَتَى أَخَذَهُ، وَفِيهِ غَرْسٌ، أَوْ بِنَاءٌ لِلْمُشْتَرِي، أَعْطَاهُ الشَّفِيعُ قِيمَتَهُ، إِلَّا أَنْ يَخْتَارَ الْمُشْتَرِي قَلْعَهُ مِنْ غَيْرِ ضَرَرٍ فِيهِ،"]]},{"id":"um74_11","label":"بَابُ الشُّفْعَةِ · ١١","segs":[["matn","وَإِنْ كَانَ فِيهِ زَرْعٌ أَوْ ثَمَرٌ بَادٍ، فَهُوَ لِلْمُشْتَرِي يَبْقَى إِلَى الْحَصَادِ أَوِ الْجِذَاذِ، وَإِنِ اشْتَرَى شِقْصًا وَسَيْفًا فِي عَقْدٍ وَاحِدٍ، فَلِلشَّفِيعِ أَخْذُ الشِّقْصِ بِحِصَّتِهِ."]]}],"group":"كِتَابُ الْإِجَارَةِ"},{"id":"um75","title":"كِتَابُ الْوَقْفِ","units":[{"id":"um75_1","label":"كِتَابُ الْوَقْفِ · ١","segs":[["matn","وَهُوَ: تَحْبِيسُ الأَصْلِ، وَتَسْبِيلُ الثَّمَرَةِ. وَيَجُوزُ فِي كُلِّ عَيْنٍ يَجُوزُ بَيْعُهَا، وَيُنْتَفَعُ بِهَا دَائِمًا مَعَ بَقَاءِ عَيْنِهَا وَلَا يَصِحُّ فِي غَيْرِ ذَلِكَ، مِثْلُ الأَثْمَانِ وَالْمَطْعُومَاتِ وَالرِّيَاحِينَ، وَلَا يَصِحُّ إِلَّا عَلَى بِرٍّ أَوْ مَعْرُوفٍ،"]]},{"id":"um75_2","label":"كِتَابُ الْوَقْفِ · ٢","segs":[["matn","مِثْلُ مَا رُوِيَ عَنْ عُمَرَ أَنَّهُ قَالَ: يَا رَسُولَ اللهِ، إِنِّي أَصَبْتُ مَالاً بِخَيْبَرَ لَمْ أُصِبْ مَالاً قَطُّ هُوَ أَنْفَسُ عِنْدِي مِنْهُ، فَمَا تَأْمُرُنِي فِيهِ؟"]]},{"id":"um75_3","label":"كِتَابُ الْوَقْفِ · ٣","segs":[["matn","قَالَ: «إِنْ شِئْتَ حَبَّسْتَ أَصْلَهَا، وَتَصَدَّقْتَ بِهَا، غَيْرَ أَنَّهَا لَا يُبَاعُ أَصْلُهَا وَلَا يُوهَبُ وَلَا يُورَثُ» قَالَ: فَتَصَدَّقَ بِهَا عُمَرُ فِي الْفُقَرَاءِ وَفِي الْقُرْبَى وَفِي الرِّقَابِ، وَفِي سَبِيلِ اللهِ وَابْنِ السَّبِيلِ وَالضَّيْفِ."]]},{"id":"um75_4","label":"كِتَابُ الْوَقْفِ · ٤","segs":[["matn","وَلَا جُنَاحَ عَلَى مَنْ وَلِيَهَا أَنْ يَأْكُلَ مِنْهَا بِالْمَعْرُوفِ، وَيُطْعِمَ صَدِيقًا غَيْرَ مُتَمَوِّلٍ فِيهِ."]]},{"id":"um75_5","label":"كِتَابُ الْوَقْفِ · ٥","segs":[["matn","وَيَصِحُّ الْوَقْفُ بِالْقَوْلِ وَالْفِعْلِ الدَّالِّ عَلَيْهِ، مِثْلُ أَنْ يَبْنِيَ مَسْجِدًا وَيَأْذَنَ فِي الصَّلَاةِ فِيهِ، أَوْ سِقَايَةً وَيُشَرِّعَهَا لِلنَّاسِ."]]},{"id":"um75_6","label":"كِتَابُ الْوَقْفِ · ٦","segs":[["matn","وَلَا يَجُوزُ بَيْعُهُ إِلَّا أَنْ تَتَعَطَّلَ مَنَافِعُهُ بِالْكُلِّيَةِ، فَيُبَاعُ وَيُشْتَرَى بِهِ مَا يَقُومُ مَقَامَهُ، وَالْفَرَسُ الْحَبِيسُ إِذَا لَمْ يَصْلُحْ لِلْغَزْوِ، بِيعَ وَاشْتُرِيَ بِهِ مَا يَصْلُحُ لِلْجِهَادِ وَالْمَسْجِدُ إِذَا لَمْ يَنْتَفِعُ بِهِ فِي مَكَانِهِ، بِيعَ وَنُقِلَ إِلَى مَكَانٍ يَنْتَفِعُ بِهِ."]]},{"id":"um75_7","label":"كِتَابُ الْوَقْفِ · ٧","segs":[["matn","وَيُرْجَعُ فِي الْوَقْفِ وَمَصْرِفِهِ وَشُرُوطِهِ وَتَرْتِيبِهِ، وَإِدْخَالِ مَنْ شَاءَ بِصِفَةٍ وَإِخْرَاجِهِ بِهَا وَكَذَلِكَ النَّاظِرُ فِيهِ، وَالنَّفَقَةُ عَلَيْهِ، إِلَى شَرْطِ الْوَاقِفِ فَلَوْ وَقَفَ عَلَى وَلَدِ فُلَانٍ ثُمَّ عَلَى الْمَسَاكِينِ، كَانَ الذَّكَرُ وَالأُنْثَى بِالسَّوِيَّةِ،"]]},{"id":"um75_8","label":"كِتَابُ الْوَقْفِ · ٨","segs":[["matn","إِلَّا أَنْ يُفَضِّلَ بَعْضَهُمْ فَإِذَا لَمْ يَبْقَ مِنْهُمْ أَحَدٌ رَجَعَ إِلَى الْمَسَاكِينِ، وَمَتَى كَانَ الْوَقْفُ عَلَى مَنْ يُمْكِنُ حَصْرُهُمْ،"]]},{"id":"um75_9","label":"كِتَابُ الْوَقْفِ · ٩","segs":[["matn","لَزِمَ اسْتِيعَابُهُمْ بِهِ، وَالتَّسْوِيَّةُ بَيْنَهُمْ إِذَا لَمْ يُفَضِّلْ بَعْضَهُمْ وَإِنْ لَمْ يُمْكِنْ حَصْرُهُمْ، جَازَ تَفْضِيلُ بَعْضِهِمْ عَلَى بَعْضٍ، وَتَخْصِيصُ وَاحِدٍ مِنْهُمْ بِهِ."]]}],"group":"كِتَابُ الْوَقْفِ"},{"id":"um76","title":"بَابُ الْهِبَةِ","units":[{"id":"um76_1","label":"بَابُ الْهِبَةِ · ١","segs":[["matn","وَهِيَ: تَمْلِيكُ الْمَالِ فِي الْحَيَاةِ بِغَيْرِ عِوَضٍ، وَتَصِحُّ بِالإِيجَابِ وَالْقَبُولِ، وَالْعَطِيَّةِ الْمُقْتَرِنَةِ بِمَا يَدُلُّ عَلَيْهَا، وَتَلْزَمُ بِالْقَبْضِ، وَلَا يَجُوزُ الرُّجُوعُ فِيهَا إِلَّا الْأَبَ لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ:"]]},{"id":"um76_2","label":"بَابُ الْهِبَةِ · ٢","segs":[["matn","«لَا يَحِلُّ لِأَحَدٍ أَنْ يُعْطِي عَطِيَّةً فَيَرْجِعُ فِيهَا، إِلَّا الْوَالِدَ فِيمَا يُعْطِي وَلَدَهُ،» وَالْمَشْرُوعُ فِي عَطِيَّةِ الأَوْلَادِ أَنْ يُسَوِّيَ بَيْنَهُمْ عَلَى قَدْرِ مِيرَاثِهِمْ، لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «اتَّقُوا اللهَ وَاعْدِلُوا بَيْنَ أَوْلَادِكُمْ»."]]},{"id":"um76_3","label":"بَابُ الْهِبَةِ · ٣","segs":[["matn","إِذَا قَالَ لِرَجُلٍ: أَعْمَرْتُكَ دَارِي، أَوْ: هِيَ لَكَ عُمْرَى فَهِيَ لَهُ وَلِوَرَثَتِهِ مِنْ بَعْدِهِ، وَإِنْ قَالَ: سُكْنَاهَا لَكَ عُمُرَكَ، فَلَهُ أَخْذُهَا مَتَى شَاءَ."]]}],"group":"كِتَابُ الْوَقْفِ"},{"id":"um77","title":"بَابُ عَطِيَّةِ الْمَرِيضِ","units":[{"id":"um77_1","label":"بَابُ عَطِيَّةِ الْمَرِيضِ · ١","segs":[["matn","تَبَرُّعَاتُ الْمَرِيضِ مَرَضَ الْمَوْتِ الْمَخُوفِ، وَمَنْ هُوَ فِي الْخَوْفِ كَالْمَرِيضِ، كَالْوَاقِفِ بَيْنَ الصَّفَّيْنِ عِنْدَ الْتِقَاءِ الْقِتَالِ، وَمَنْ قُدِّمَ لِيُقْتَلَ،"]]},{"id":"um77_2","label":"بَابُ عَطِيَّةِ الْمَرِيضِ · ٢","segs":[["matn","وَرَاكِبِ الْبَحْرِ حَالَ هَيَجَانِهِ، وَمَنْ وَقَعَ الطَّاعُونُ بِبَلَدِهِ إِذَا اتَّصَلَ بِهِمُ الْمَوْتُ، حُكْمُهَا حُكْمُ وَصِيَّتِهِ فِي سِتَّةِ أَحْكَامٍ: أَحَدُهَا: أَنَّهَا لَا تَجُوزُ لِأَجْنَبِيٍّ؛"]]},{"id":"um77_3","label":"بَابُ عَطِيَّةِ الْمَرِيضِ · ٣","segs":[["matn","بِزِيَادَةٍ عَلَى الثُّلُثِ، وَلَا لِوَارِثٍ بِشَيْءٍ إِلَّا بِإِجَازَةِ الْوَرَثَةِ، لِمَا رُوِيَ أَنَّ رَجُلاً أَعْتَقَ سِتَّةَ مَمْلُوكِينَ عِنْدَ مَوْتِهِ، لَمْ يَكُنْ لَهُ مَالٌ غَيْرُهُمْ، فَدَعَا بِهِمُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَجَزَّأَهُمْ أَثْلَاثاً، فَأَعْتَقَ اثْنَيْنِ، وَأَرَقَّ أَرْبَعَةً."]]},{"id":"um77_4","label":"بَابُ عَطِيَّةِ الْمَرِيضِ · ٤","segs":[["matn","الثَّانِي: أَنَّ الْحُرِّيَّةَ تُجَمَعُ فِي بَعْضِ الْعَبِيدِ بِالْقُرْعَةِ، إِذَا لَمْ يَفِ الثُّلُثُ بِالْجَمِيعِ؛ لِلْخَبَرِ. الثَّالِثُ: أَنَّهُ إِذَا أَعْتَقَ عَبْدًا غَيْرَ مُعَيَّنٍ، أَوْ مُعَيَّنًا فَأَشْكَلَ، أُخْرِجَ بِالْقُرْعَةِ."]]},{"id":"um77_5","label":"بَابُ عَطِيَّةِ الْمَرِيضِ · ٥","segs":[["matn","الرَّابِعُ: أَنَّهُ يُعْتَبَرُ خُرُوجُهَا مِنَ الثُّلُثِ حَالَ الْمَوْتِ، فَلَوْ أَعْتَقَ عَبْدًا لَا مَالَ لَهُ سِوَاهُ، أَوْ تَبَرَّعَ بِهِ، ثُمَّ مَلَكَ عِنْدَ الْمَوْتِ ضِعْفَ قِيمَتِهِ، تَبَيَّنَا أَنَّهُ عَتَقَ كُلُّهُ حِينَ إِعْتَاقِهِ،"]]},{"id":"um77_6","label":"بَابُ عَطِيَّةِ الْمَرِيضِ · ٦","segs":[["matn","وَكَانَ مَا كَسَبَهُ بَعْدَ ذَلِكَ لَهُ، وَإِنْ صَارَ عَلَيْهِ دَيْنٌ يَسْتَغْرِقُهُ، لَمْ يَعْتِقْ مِنْهُ شَيْءٌ، وَلَا يَصِحُّ تَبَرُّعُهُ بِهِ، وَلَوْ وَصَّى لَهُ بِشَيْءٍ، فَلَمْ يَأْخُذْهُ الْمُوصَى لَهُ زَمَانًا، قُوِّمَ عَلَيْهِ وَقْتَ الْمَوْتِ لَا وَقْتَ الأَخْذِ."]]},{"id":"um77_7","label":"بَابُ عَطِيَّةِ الْمَرِيضِ · ٧","segs":[["matn","الْخَامِسُ: أَنَّ كَوْنَهُ وَارِثًا يُعْتَبَرُ حَالَةَ الْمَوْتِ فِيهِمَا، فَلَوْ أَعْطَى أَخَاهُ أَوْ وَصَّى لَهُ وَلَا لَهُ وَلَدٌ فَوُلِدَ لَهُ ابْنٌ، صَحَّتِ الْعَطِيَّةُ وَالْوَصِيَّةُ، وَلَوْ كَانَ لَهُ ابْنٌ فَمَاتَ، بَطَلَتَا."]]},{"id":"um77_8","label":"بَابُ عَطِيَّةِ الْمَرِيضِ · ٨","segs":[["matn","السَّادِسُ: أَنَّهُ لَا يُعْتَبَرُ رَدُّ الْوَرَثَةِ وَإِجَازَتُهُمْ إِلَّا بَعْدَ الْمَوْتِ فِيهِمَا."]]},{"id":"um77_9","label":"بَابُ عَطِيَّةِ الْمَرِيضِ · ٩","segs":[["matn","وَتُفَارِقُ الْعَطِيَّةُ الْوَصِيَّةَ فِي أَحْكَامٍ أَرْبَعَةٍ: أَحَدُهَا: أَنَّ الْعَطِيَّةَ تَنْفُذُ مِنْ حِينِهَا، فَلَوْ أَعْتَقَ عَبْدًا أَوْ أَعْطَاهُ إِنْسَانًا، صَارَ الْمُعْتَقُ حُرًّا، وَمَلَكَهُ الْمُعْطَى وَكَسْبُهُ لَهُ،"]]},{"id":"um77_10","label":"بَابُ عَطِيَّةِ الْمَرِيضِ · ١٠","segs":[["matn","وَلَوْ وَصَّى بِهِ، أَوْ دَبَّرَهُ، لَمْ يَعْتِقْ، وَلَمْ يَمْلِكْهُ الْمُوصَى لَهُ إِلَّا بَعْدَ الْمَوْتِ وَمَا كَسَبَ أَوْ حَدَثَ فِيهِ مِنْ نَمَاءٍ مُنْفَصِلٍ، فَهُوَ لِلْوَرَثَةِ."]]},{"id":"um77_11","label":"بَابُ عَطِيَّةِ الْمَرِيضِ · ١١","segs":[["matn","الثَّانِي: أَنَّ الْعَطِيَّةَ يُعْتَبَرُ قَبُولُهَا وَرَدُّهَا حِينَ وُجُودِهَا، كَعَطِيَّةِ الصَّحِيحِ، وَالْوَصِيَّةُ لَا يُعْتَبَرُ قَبُولُهَا وَلَا رَدُّهَا إِلَّا بَعْدَ مَوْتِ الْمُوصِي."]]},{"id":"um77_12","label":"بَابُ عَطِيَّةِ الْمَرِيضِ · ١٢","segs":[["matn","الثَّالِثُ: أَنَّهَا تَقَعُ لَازِمَةً، لَا يَمْلِكُ الْمُعْطِي الرُّجُوعَ فِيهَا وَالْوَصِيَّةُ لَهُ الرُّجُوعُ فِيهَا مَتَى شَاءَ."]]},{"id":"um77_13","label":"بَابُ عَطِيَّةِ الْمَرِيضِ · ١٣","segs":[["matn","الرَّابِعُ: أَنْ يُبْدَأَ بِالأَوَّلِ فَالأَوَّلِ مِنْهَا إِذَا ضَاقَ الثُّلُثُ عَنْ جَمِيعِهَا، وَالْوَصِيَّةُ يُسَوَّى بَيْنَ الأَوَّلِ مِنْهَا وَالْآخِرِ وَيَدْخُلُ النَّقْصُ عَلَى كُلِّ وَاحِدٍ بِقَدْرِ وَصِيَّتِهِ، سَوَاءٌ كَانَ فِيهَا عِتْقٌ أَوْ لَمْ يَكُنْ، وَكَذَلِكَ الْحُكْمُ فِي الْعَطَايَا إِذَا وَقَعَتْ دُفْعَةً وَاحِدَةً."]]}],"group":"كِتَابُ الْوَقْفِ"},{"id":"um78","title":"كِتَابُ الْوَصَايَا","units":[{"id":"um78_1","label":"كِتَابُ الْوَصَايَا · ١","segs":[["matn","رُوِيَ عَنْ سَعْدٍ قَالَ: قُلْتُ: يَا رَسُولَ اللهِ قَدْ بَلَغَ بِيَ الْجَهْدُ مَا تَرَى، وَأَنَا ذُو مَالٍ وَلَا يَرِثُنِي إِلَّا ابْنَةُ، أَفَأَتَصَدَّقُ بِثُلُثَيْ مَالِي؟ قَالَ: «لَا،» قُلْتُ: فَالشَّطْرُ؟"]]},{"id":"um78_2","label":"كِتَابُ الْوَصَايَا · ٢","segs":[["matn","قَالَ: «لَا،» قُلْتُ: فَالثُّلُثُ؟ قَالَ: «الثُّلُثُ وَالثُّلُثُ كَثِيرٌ، إِنَّكَ أَنْ تَدَعَ وَرَثَتَكَ أَغْنِيَاءَ خَيْرٌ مِنْ أَنْ تَدَعَهُمْ عَالَةً يَتَكَفَّفُونَ النَّاسَ،» وَيُسْتَحَبُّ لِمَنْ تَرَكَ خَيْرًا الْوَصِيَّةُ بِخُمُسِ مَالِهِ."]]},{"id":"um78_3","label":"كِتَابُ الْوَصَايَا · ٣","segs":[["matn","وَتَصِحُّ الْوَصِيَّةُ وَالتَّدْبِيرُ، مِنْ كُلِّ مَنْ تَصِحُّ هِبَتُهُ، وَمِنَ الصَّبِيِّ الْعَاقِلِ، وَالْمَحْجُورِ عَلَيْهِ لِسَفَهٍ وَلِكُلِّ مَنْ تَصِحُّ الْهِبَةُ لَهُ، وَلِلْحَمْلِ إِذَا عُلِمَ أَنَّهُ كَانَ مَوْجُودًا حِينَ الْوَصِيَّةِ لَهُ."]]},{"id":"um78_4","label":"كِتَابُ الْوَصَايَا · ٤","segs":[["matn","وَتَصِحُّ بِكُلِّ مَا فِيهِ نَفْعٌ مُبَاحٌ، كَكَلْبِ الصَّيْدِ وَالْغَنَمِ، وَبِمَا فِيهِ نَفْعٌ مِنَ النَّجَاسَاتِ، وَبِالْمَعْدُومِ، كَالَّذِي تَحْمِلُ أَمَتُهُ أَوْ شَجَرَتُهُ."]]},{"id":"um78_5","label":"كِتَابُ الْوَصَايَا · ٥","segs":[["matn","وَتَصِحُّ بِمَا لَا يَقْدِرُ عَلَى تَسْلِيمِهِ، كَالطَّيْرِ فِي الْهَوَاءِ وَالسَّمَكِ فِي الْمَاءِ، وَبِمَا لَا يَمْلِكُهُ، كَمِائَةِ دِرْهَمٍ لَا يَمْلِكُهَا، وَبِغَيْرِ مُعَيَّنٍ، كَعَبْدٍ مِنْ عَبِيدِهِ، وَيُعْطِيهِ الْوَرَثَةُ مِنْهُمْ مَا شَاءُوا وَبِالْمَجْهُولِ كَحَظٍّ مِنْ مَالِهِ، أَوْ جُزْءٍ، وَيُعْطِيهِ الْوَرَثَةُ مَا شَاءُوا."]]},{"id":"um78_6","label":"كِتَابُ الْوَصَايَا · ٦","segs":[["matn","وَإِنْ وَصَّى لَهُ بِمِثْلِ نَصِيبِ أَحَدِ وَرَثَتِهِ، فَلَهُ مِثْلُ أَقَلِّهِمْ نَصِيبًا، يُزَادُ عَلَى الْفَرِيضَةِ، فَلَوْ خَلَّفَ ثَلَاثَةَ بَنِينَ وَوَصَّى بِمِثْلِ نَصِيبِ أَحَدِهِمْ، فَلَهُ الرُّبُعُ،"]]},{"id":"um78_7","label":"كِتَابُ الْوَصَايَا · ٧","segs":[["matn","فَإِنْ كَانَ مَعَهُمْ ذُو فَرْضٍ كَأُمٍّ، صَحَّحْتَ مَسْأَلَةَ الْوَرَثَةِ بِدُونِ الْوَصِيَّةِ مِنْ ثَمَانِيَةَ عَشَرَ، وَزِدْتَ عَلَيْهَا بِمِثْلِ نَصِيبِ ابْنٍ، فَصَارَتْ مِنْ ثَلَاثَةٍ وَعِشْرِينَ."]]},{"id":"um78_8","label":"كِتَابُ الْوَصَايَا · ٨","segs":[["matn","وَلَوْ وَصَّى بِمِثْلِ نَصِيبِ أَحَدِهِمْ، وَلِآخَرَ بِسُدُسِ بَاقِي الْمَالِ، جَعَلْتَ صَاحِبَ سُدُسِ الْبَاقِي كَذِي فَرْضٍ وَصَحَّحْتَهَا كَالَّتِي قَبْلَهَا،"]]},{"id":"um78_9","label":"كِتَابُ الْوَصَايَا · ٩","segs":[["matn","فَإِنْ كَانَتْ وَصِيَّةُ الثَّانِي بِسُدُسِ بَاقِي الثُّلُثِ صَحَّحْتَهَا كَمَا قُلْنَا سَوَاءً، ثُمَّ زِدْتَ عَلَيْهَا مِثْلَيْهَا، فَتُصِيرُ تِسْعَةً وَسِتِّينَ، تُعْطِي صَاحِبَ السُّدُسِ سَهْمًا وَاحِدًا، وَالْبَاقِي بَيْنَ الْبَنِينَ وَالْوَصِيِّ الآخَرِ أَرْبَاعًا،"]]},{"id":"um78_10","label":"كِتَابُ الْوَصَايَا · ١٠","segs":[["matn","وَإِنْ زَادَ الْبَنُونَ عَلَى ثَلَاثَةٍ، زِدْتَ صَاحِبَ سُدُسِ الْبَاقِي بِقَدْرِ زِيَادَتِهِمْ، فَإِنْ كَانُوا أَرْبَعَةً، أَعْطَيْتَهُ مِمَّا صَحَّتْ مِنْهُ الْمَسْأَلَةُ سَهْمَيْنِ، وَإِنْ كَانُوا خَمْسَةً،"]]},{"id":"um78_11","label":"كِتَابُ الْوَصَايَا · ١١","segs":[["matn","فَلَهُ ثَلَاثَةٌ، وَإِنْ كَانَتِ الْوَصِيَّةُ بِثُلُثِ بَاقِي الرُّبُعِ وَالْبَنُونَ أَرْبَعَةٌ، فَلَهُ سَهْمٌ وَاحِدٌ، وَإِنْ زَادَ الْبَنُونَ عَلَى أَرْبَعَةٍ، زِدْتَهُ بِكُلِّ وَاحِدٍ سَهْمًا."]]},{"id":"um78_12","label":"كِتَابُ الْوَصَايَا · ١٢","segs":[["matn","وَإِنْ وَصَّى بِضِعْفِ نَصِيبِ وَارِثٍ أَوْ ضِعْفَيْهِ، فَلَهُ مِثْلَا نَصِيبِهِ وَثَلَاثَةُ أَضْعَافٍ ثَلَاثَةُ أَمْثَالِهِ. وَإِنْ وَصَّى بِجُزْءِ مُشَاعٍ، كَثُلُثٍ أَوْ رُبُعٍ، أَخَذْتَهُ مِنْ مَخْرَجِهِ، وَقَسَمْتَ الْبَاقِي عَلَى الْوَرَثَةِ."]]},{"id":"um78_13","label":"كِتَابُ الْوَصَايَا · ١٣","segs":[["matn","وَإِنْ وَصَّى بِجُزْأَيْنِ كَثُلُثٍ وَرُبُعٍ، أَخَذْتَهُمَا مِنْ مَخْرَجِهِمَا، وَهُوَ اثْنَا عَشَرَ وَقَسَمْتَ الْبَاقِي عَلَى الْوَرَثَةِ، فَإِنْ رَدُّوا، جَعَلْتَ سِهَامَ الْوَصِيَّةِ ثُلُثَ الْمَالِ، وَلِلْوَرَثَةِ ضِعْفُ ذَلِكَ."]]},{"id":"um78_14","label":"كِتَابُ الْوَصَايَا · ١٤","segs":[["matn","وَإِنْ وَصَّى بِمُعَيَّنٍ مِنْ مَالِهِ، فَلَمْ يَخْرُجْ مِنَ الثُّلُثِ، فَلِلْمُوصَى لَهُ قَدْرُ الثُّلُثِ إِلَّا أَنْ يُجِيزَ الْوَرَثَةُ."]]},{"id":"um78_15","label":"كِتَابُ الْوَصَايَا · ١٥","segs":[["matn","وَإِنْ زَادَتِ الْوَصَايَا عَلَى الْمَالِ، كَرَجُلٍ وَصَّى بِثُلُثِ مَالِهِ لِرَجُلٍ، وَلِآخَرَ بِجَمِيعِهِ ضَمَمْتَ الثُّلُثَ إِلَى الْمَالِ، فَصَارَ أَرْبَعَةَ أَثْلَاثٍ وَقَسَمْتَ التَّرِكَةَ بَيْنَهُمَا عَلَى أَرْبَعَةِ إِنْ أُجِيزَتْ لَهُمَا، وَالثُّلُثُ عَلَى أَرْبَعَةٍ إِنْ رُدَّ عَلَيْهِمَا."]]},{"id":"um78_16","label":"كِتَابُ الْوَصَايَا · ١٦","segs":[["matn","وَلَوْ وَصَّى بِمُعَيَّنٍ لِرَجُلٍ، ثُمَّ وَصَّى بِهِ لِآخَرَ، أَوْ أَوْصَى إِلَى رَجُلٍ ثُمَّ أَوْصَى إِلَى آخَرَ، فَهُوَ بَيْنَهُمَا، وَإِنْ قَالَ: مَا أَوْصَيْتُ بِهِ لِلأَوَّلِ، فَهُوَ لِلثَّانِي، بَطَلَتْ وَصِيَّةُ الأَوَّلِ."]]},{"id":"um78_17","label":"كِتَابُ الْوَصَايَا · ١٧","segs":[["matn","فَصْلٌ: إِذَا بَطَلَتِ الْوَصِيَّةُ أَوْ بَعْضُهَا، رَجَعَ إِلَى الْوَرَثَةِ، فَلَوْ وَصَّى أَنْ يُشْتَرَى عَبْدُ زَيْدٍ بِمِائَةٍ فَيُعْتَقُ، فَمَاتَ، أَوْ لَمْ يَبِعْهُ سَيِّدُهُ،"]]},{"id":"um78_18","label":"كِتَابُ الْوَصَايَا · ١٨","segs":[["matn","فَالْمِائَةُ لِلْوَرَثَةِ، وَإِنْ وَصَّى بِمِئَةٍ تُنْفَقُ عَلَى فَرَسٍ حَبِيسٍ، فَمَاتَ، الْفَرَسُ فَهِيَ لِلْوَرَثَةِ، وَلَوْ وَصَّى أَنْ يَحُجَّ عَنْهُ زَيْدٌ بِأَلْفٍ فَلَمْ يَحُجَّ، فَهِيَ لِلْوَرَثَةِ،"]]},{"id":"um78_19","label":"كِتَابُ الْوَصَايَا · ١٩","segs":[["matn","وَإِنْ قَالَ الْمُوصَى لَهُ: أَعْطُونِي الزَّائِدَ عَلَى نَفَقَةِ الْحَجِّ، لَمْ يُعْطَ شَيْئاً، وَلَوْ مَاتَ الْمُوصَى لَهُ قَبْلَ مَوْتِ الْمُوصِي أَوْ رَدَّ الْوَصِيَّةَ،"]]},{"id":"um78_20","label":"كِتَابُ الْوَصَايَا · ٢٠","segs":[["matn","رُدَّتْ إِلَى الْوَرَثَةِ، وَلَوْ وَصَّى لِحَيٍّ وَمَيِّتٍ، فَلِلْحَيِّ نِصْفُ الْوَصِيَّةِ، وَلَوْ وَصَّى لِوَارِثِهِ وَلِأَجْنَبِيٍّ بِثُلُثِ مَالِهِ، فَلِلأَجْنَبِيِّ السُّدُسُ، وَيُوقَفُ سُدُسُ الْوَارِثِ عَلَى الإِجَازَةِ."]]}],"group":"كِتَابُ الْوَصَايَا"},{"id":"um79","title":"بَابُ الْمُوصَى إِلَيْهِ","units":[{"id":"um79_1","label":"بَابُ الْمُوصَى إِلَيْهِ · ١","segs":[["matn","تَجُوزُ الْوَصِيَّةُ إِلَى كُلِّ مُسْلِمٍ، عَاقِلٍ، عَدْلٍ، مِنَ الذُكُورِ وَالإِنَاثِ، بِمَا يَجُوزُ لِلْمُوصِي فِعْلُهُ، مِنْ قَضَاءِ دُيُونِهِ وَتَفْرِيقِ وَصِيَّتِهِ، وَالنَّظَرِ فِي أَمْرِ أَطْفَالِهِ."]]},{"id":"um79_2","label":"بَابُ الْمُوصَى إِلَيْهِ · ٢","segs":[["matn","وَمَتَى أَوْصَى إِلَيْهِ بِوِلَايَةِ أَطْفَالِهِ أَوْ مَجَانِينِهِ، ثَبَتَتْ وِلَايَتُهُ عَلَيْهِمْ، وَنَفَذَ تَصَرُّفُهُ لَهُمْ بِمَا لَهُمْ فِيهِ الْحَظُّ مِنَ الْبَيْعِ وَالشِّرَاءِ، وَقَبُولِ مَا يُوهَبُ لَهُمْ،"]]},{"id":"um79_3","label":"بَابُ الْمُوصَى إِلَيْهِ · ٣","segs":[["matn","وَالإِنْفَاقِ عَلَيْهِمْ، وَعَلَى مَنْ تَلْزِمُهُمْ مَؤُونَتُهُ بِالْمَعْرُوفِ، وَالتِّجَارَةِ لَهُمْ، وَدَفْعِ أَمْوَالِهِمْ مُضَارَبَةً بِجُزْءٍ مِنَ الرِّبْحِ، وَإِنِ اتَّجَرَ لَهُمْ، بِنَفْسِهِ فَلَيْسَ لَهُ مِنَ الرِّبْحِ شَيْءٌ."]]},{"id":"um79_4","label":"بَابُ الْمُوصَى إِلَيْهِ · ٤","segs":[["matn","وَلَهُ أَنْ يَأْكُلَ مِنْ مَالِهِمْ عِنْدَ الْحَاجَةِ بِقَدْرِ عَمَلِهِ وَلَا غُرْمَ عَلَيْهِ، وَلَا يَأْكُلُ إِذَا كَانَ غَنِيًّا؛ لِقَوْلِ اللهِ تَعَالَى: ﴿وَمَنْ كَانَ غَنِيًّا فَلْيَسْتَعْفِفْ وَمَنْ كَانَ فَقِيرًا فَلْيَأْكُلْ بِالْمَعْرُوفِ﴾."]]},{"id":"um79_5","label":"بَابُ الْمُوصَى إِلَيْهِ · ٥","segs":[["matn","وَلَيْسَ لَهُ أَنْ يُوصِي بِمَا أُوصِيَ إِلَيْهِ بِهِ، وَلَا أَنْ يَبِيعَ وَيَشْتَرِيَ مِنْ مَالِهِمْ لِنَفْسِهِ، وَيَجُوزُ ذَلِكَ لِلْأَبِ، فَلَا يَلِي مَالَ الصَّبِيِّ وَالْمَجْنُونِ إِلَّا الأَبُ، أَوْ وَصِيُّهُ، أَوِ الْحَاكِمُ."]]},{"id":"um79_6","label":"بَابُ الْمُوصَى إِلَيْهِ · ٦","segs":[["matn","فَصْلٌ: وَلِوَلِيِّهِمْ أَنْ يَأْذَنَ لِلْمُمَيِّزِ مِنَ الصِّبْيَانِ بِالتَّصَرُّفِ لِيَخْتَبِرَ رُشْدَهُ، وَالرُّشْدُ: هُنَا الصَّلَاحُ فِي الْمَالِ، فَمَنْ آنَسَ رُشْدَهُ دَفَعَ إِلَيْهِ مَالَهُ إِذَا بَلَغَ، وَأَشْهَدَ عَلَيْهِ، ذَكَرًا كَانَ أَوْ أُنْثَى، فَإِنْ عَاوَدَ السَّفَهَ،"]]},{"id":"um79_7","label":"بَابُ الْمُوصَى إِلَيْهِ · ٧","segs":[["matn","أُعِيدَ عَلَيْهِ الْحَجْرُ، وَلَا يَنْظُرُ فِي مَالِهِ إِلَّا الْحَاكِمُ، وَلَا يَنْفَكُّ عَنْهُ الْحَجْرُ إِلَّا بِحُكْمِهِ، وَلَا يُقْبَلُ إِقْرَارُهُ فِي الْمَالِ، وَيُقْبَلُ فِي الْحُدُودِ وَالْقِصَاصِ وَالطَّلَاقِ، فَإِنْ طَلَّقَ أَوْ أَعْتَقَ، نَفَذَ طَلَاقُهُ دُونَ إِعْتَاقِهِ."]]},{"id":"um79_8","label":"بَابُ الْمُوصَى إِلَيْهِ · ٨","segs":[["matn","فَصْلٌ: وَإِذَا أَذِنَ السَّيِّدُ لِعَبْدِهِ فِي التِّجَارَةِ، صَحَّ بَيْعُهُ وَشِرَاؤُهُ وَإِقْرَارُهُ، وَلَا يَنْفُذُ تَصَرُّفُهُ إِلَّا فِي قَدْرِ مَا أَذِنَ لَهُ فِيهِ، وَإِنْ رَآهُ سَيِّدُهُ أَوْ وَلِيُّهُ يَتَصَرَّفُ فَلَمْ يَنْهَهُ، لَمْ يَصِرْ بِهَذَا مَأْذُونًا لَهُ."]]}],"group":"كِتَابُ الْوَصَايَا"},{"id":"um80","title":"كِتَابُ الْفَرَائِضِ","units":[{"id":"um80_1","label":"كِتَابُ الْفَرَائِضِ · ١","segs":[["matn","وَهِيَ قِسْمَةُ الْمِيرَاثِ، وَالْوَارِثُ ثَلَاثَةُ أَقْسَامٍ: ذُو فَرْضٍ، وَعَصَبَةٌ، وَذُو رَحِمٍ، فَذُو الْفَرْضِ عَشَرَةٌ: الزَّوْجَانِ، وَالأَبَوَانِ، وَالْجَدُّ، وَالْجَدَّةُ، وَالْبَنَاتُ، وَبَنَاتُ الِابْنِ، وَالأَخَوَاتُ وَالإِخْوَةُ مِنَ الأُمِّ،"]]},{"id":"um80_2","label":"كِتَابُ الْفَرَائِضِ · ٢","segs":[["matn","فَلِلزَّوْجِ النِّصْفُ إِذَا لَمْ يَكُنْ لِلْمَيِّتَةِ وَلَدٌ، فَإِنْ كَانَ لَهَا وَلَدٌ، فَلَهُ الرُّبُعُ، وَلَهَا الرُّبُعُ وَاحِدَةً كَانَتْ أَوْ أَرْبَعًا، إِذَا لَمْ يَكُنْ لَهُ وَلَدٌ، فَإِنْ كَانَ لَهُ وَلَدٌ، فَلَهُنَّ الثُّمُنُ."]]},{"id":"um80_3","label":"كِتَابُ الْفَرَائِضِ · ٣","segs":[["matn","فَصْلٌ: وَلِلأَبِ ثَلَاثَةُ أَحْوَالٍ: حَالٌ لَهُ السُّدُسُ، وَهِيَ مَعَ ذُكُورِ الْوَلَدِ، وَحَالٌ يَكُونُ عَصَبَةً، وَهِيَ مَعَ عَدِمِ الْوَلَدِ، وَحَالٌ لَهُ الأَمْرَانِ، مَعَ إِنَاثِ الْوَلَدِ."]]},{"id":"um80_4","label":"كِتَابُ الْفَرَائِضِ · ٤","segs":[["matn","فَصْلٌ: وَالْجَدُّ كَالأَبِ فِي أَحْوَالِهِ، وَلَهُ حَالٌ رَابِعٌ، وَهُوَ مَعَ الإِخْوَةِ وَالأَخَوَاتِ لِلأَبَوَيْنِ أَوْ لِلأَبِ، فَلَهُ الأَحَظُّ مِنْ مُقَاسَمَتِهِمْ كَأَخٍ،"]]},{"id":"um80_5","label":"كِتَابُ الْفَرَائِضِ · ٥","segs":[["matn","أَوْ ثُلُثُ جَمِيعِ الْمَالِ، فَإِنْ كَانَ مَعَهُمْ ذُو فَرْضٍ، أَخَذَ فَرْضَهُ، ثُمَّ كَانَ لِلْجَدِّ الأَحَظُّ مِنَ الْمُقَاسَمَةِ أَوْ ثُلُثُ الْبَاقِي أَوْ سُدُسُ جَمِيعِ الْمَالِ،"]]},{"id":"um80_6","label":"كِتَابُ الْفَرَائِضِ · ٦","segs":[["matn","وَوَلَدُ الْأَبَوَيْنِ كَوَلَدِ الْأَبِ فِي هَذَا إِذَا انْفَرَدُوا، فَإِنِ اجْتَمَعُوا، عَادَّ وَلَدُ الأَبَوَيْنِ الْجَدَّ بِوَلَدِ الأَبِ، ثُمَّ أَخَذُوا مَا حَصَلَ لَهُمْ،"]]},{"id":"um80_7","label":"كِتَابُ الْفَرَائِضِ · ٧","segs":[["matn","إِلَّا أَنْ يَكُونَ وَلَدُ الأَبَوَيْنِ أُخْتًا وَاحِدَةً فَتَأْخُذُ النِّصْفَ وَمَا فَضَلَ فَلِوَلَدِ الْأَبِ، فَإِنْ لَمْ يَفْضُلْ عَنِ الْفَرْضِ إِلَّا السُّدُسَ أَخَذَهُ الْجَدُّ وَسَقَطَ الإِخْوَةُ."]]},{"id":"um80_8","label":"كِتَابُ الْفَرَائِضِ · ٨","segs":[["matn","إِلَّا فِي الأَكْدَرِيَّةِ، وَهِيَ: زَوْجٌ وَأُمٌّ وَأُخْتٌ وَجَدٌّ، فَإِنَّ لِلزَّوْجِ النِّصْفَ، وَلِلأُمِّ الثُّلُثَ، وَلِلْجَدِّ السُّدُسَ، وَلِلأُخْتِ النِّصْفَ، ثُمَّ يُقْسَمُ نِصْفُ الْأُخْتِ وَسُدُسُ الْجَدِّ بَيْنَهُمَا عَلَى ثَلَاثَةٍ، فَتَصِحُّ مِنْ سَبْعَةٍ وَعِشْرِينَ،"]]},{"id":"um80_9","label":"كِتَابُ الْفَرَائِضِ · ٩","segs":[["matn","وَلَا يَعُولُ مِنْ مَسَائِلِ الْجَدِّ سِوَاهَا، وَلَا يُفْرَضُ لِأُخْتٍ مَعَ جَدٍّ فِي غَيْرِهَا، وَلَوْ لَمْ يَكُنْ فِيهَا زَوْجٌ، كَانَ لِلأُمِّ الثُّلُثُ، وَالْبَاقِي بَيْنَ الأُخْتِ وَالْجَدِّ عَلَى ثَلَاثَةٍ، وَتُسَمَّى: الْخَرْقَاءَ؛"]]},{"id":"um80_10","label":"كِتَابُ الْفَرَائِضِ · ١٠","segs":[["matn","لِكَثْرَةِ اخْتِلَافِ الصَّحَابَةِ رَضِيَ اللهُ عَنْهُمْ فِيهَا، وَلَوْ كَانَ مَعَهُمْ أُخْتٌ أَوْ أُخْتٌ لِأَبٍ صَحَّتْ مِنْ أَرْبَعَةٍ وَخَمْسِينَ، وَتُسَمَّى: مُخْتَصَرَةَ زَيْدٍ،"]]},{"id":"um80_11","label":"كِتَابُ الْفَرَائِضِ · ١١","segs":[["matn","فَإِنْ كَانَ مَعَهُمْ أَخٌ آخَرُ مِنْ أَبٍ، صَحَّتْ مِنْ تِسْعِينَ، وَتُسَمَّى: تِسْعِينِيَّةَ زَيْدٍ، وَلَا خِلَافَ فِي إِسْقَاطِ الإِخْوَةِ مِنَ الأُمِّ وَبَنِي الإِخْوَةِ."]]},{"id":"um80_12","label":"كِتَابُ الْفَرَائِضِ · ١٢","segs":[["matn","فَصْلٌ: وَلِلأُمِّ أَرْبَعَةُ أَحْوَالٍ، حَالٌ: لَهَا السُّدُسُ، وَهِيَ مَعَ الْوَلَدِ، أَوِ الِاثْنَيْنِ فَصَاعِدًا مِنَ الإِخْوَةِ وَالأَخَوَاتِ، وَحَالٌ: لَهَا ثُلُثُ الْبَاقِي بَعْدَ فَرْضِ أَحَدِ الزَّوْجَيْنِ، وَهِيَ مَعَ الْأَبِ وَأَحَدِ الزَّوْجَيْنِ،"]]},{"id":"um80_13","label":"كِتَابُ الْفَرَائِضِ · ١٣","segs":[["matn","وَحَالٌ: لَهَا ثُلُثُ الْمَالِ، وَهِيَ فِيمَا عَدَا ذَلِكَ، وَحَالٌ رَابِعٌ: وَهِيَ إِذَا كَانَ وَلَدُهَا مَنْفِيًّا بِاللِّعَانِ أَوْ كَانَ وَلَدَ زِنًا، فَتَكُونُ عَصَبَتُهُ فَإِنْ لَمْ تَكُنْ، فَعَصَبَتُهَا عَصَبَةٌ."]]},{"id":"um80_14","label":"كِتَابُ الْفَرَائِضِ · ١٤","segs":[["matn","فَصْلٌ: وَلِلْجَدَّةِ إِذَا لَمْ تَكُنْ أُمٌّ السُّدُسُ، وَاحِدَةً كَانَتْ أَوْ أَكْثَرَ، إِذَا تَحَاذَيْنَ، فَإِنْ كَانَ بَعْضُهُنَّ أَقْرَبُ مِنْ بَعْضٍ، فَهُوَ لِقُرْبَاهُنَّ، وَتَرِثُ الْجَدَّةُ وَابْنُهَا حَيٌّ، وَلَا يَرِثُ أَكْثَرُ مِنْ ثَلَاثِ جَدَّاتٍ، أُمُّ الأُمِّ،"]]},{"id":"um80_15","label":"كِتَابُ الْفَرَائِضِ · ١٥","segs":[["matn","وَأُمُّ الأَبِ، وَأُمُّ الْجَدِّ، وَمَنْ كَانَ مِنْ أُمَّهَاتِهِنَّ وَإِنْ عَلَوْنَ، وَلَا تَرِثُ جَدَّةٌ تُدْلِي بِأَبٍ بَيْنَ أُمَّيْنِ، وَلَا بِأَبٍ أَعْلَى مِنَ الْجَدِّ، فَإِنْ خَلَّفَ جَدَّتَيْ أُمِّهِ وَجَدَّتَيْ أَبِيهِ، سَقَطَتْ أُمُّ أَبِي أُمِّهِ، وَالْمِيرَاثُ لِلثَّلَاثِ الْبَاقِيَاتِ."]]},{"id":"um80_16","label":"كِتَابُ الْفَرَائِضِ · ١٦","segs":[["matn","فَصْلٌ: وَلِلْبِنْتِ النِّصْفُ، وَلِلْبِنْتَيْنِ فَصَاعِدًا الثُّلُثَانِ، وَبَنَاتُ الِابْنِ بِمَنْزِلَتِهِنَّ إِذَا عَدِمْنَ، فَإِنِ اجْتَمَعْنَ، سَقَطَ بَنَاتُ الِابْنِ، إِلَّا أَنْ يَكُونَ مَعَهُنَّ أَوْ أَنْزَلَ مِنْهُنَّ ذَكَرٌ، فَيُعَصِّبُهُنَّ فِيمَا بَقِيَ،"]]},{"id":"um80_17","label":"كِتَابُ الْفَرَائِضِ · ١٧","segs":[["matn","وَإِنْ كَانَتْ بِنْتٌ وَاحِدَةٌ وَبَنَاتُ ابْنٍ، فَلِلْبِنْتِ النِّصْفُ، وَلِبَنَاتِ الِابْنِ، وَاحِدَةً كَانَتْ أَوْ أَكْثَرَ مِنْ ذَلِكَ، السُّدُسُ تَكْمِلَةَ الثُّلُثَيْنِ، إِلَّا أَنْ يَكُونَ مَعَهُنَّ ذَكَرٌ فَيُعَصِّبَهُنَّ، فِيمَا بَقِيَ."]]},{"id":"um80_18","label":"كِتَابُ الْفَرَائِضِ · ١٨","segs":[["matn","فَصْلٌ: وَالْأَخَوَاتُ مِنَ الْأَبَوَيْنِ كَالْبَنَاتِ فِي فَرْضِهِنَّ، وَالأَخَوَاتُ مِنَ الأَبِ مَعَهُنَّ، كَبَنَاتِ الِابْنِ مَعَ الْبَنَاتِ سَوَاءٌ، وَلَا يُعَصِّبُهُنَّ إِلَّا أَخُوهُنَّ، وَالأَخَوَاتُ مَعَ الْبَنَاتِ عَصَبَةٌ لَهُنَّ مَا فَضَلَ،"]]},{"id":"um80_19","label":"كِتَابُ الْفَرَائِضِ · ١٩","segs":[["matn","وَلَيْسَتْ لَهُنَّ مَعَهُنَّ فَرِيضَةٌ مُسَمَّاةٌ لِقَوْلِ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ فِي بِنْتٍ وَبِنْتِ ابْنٍ وَأُخْتٍ: أَقْضِي فِيهَا بِقَضَاءِ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِلْبِنْتِ النِّصْفُ، وَلِبِنْتِ الِابْنِ السُّدُسُ، وَمَا بَقِيَ فَلِلْأُخْتِ."]]},{"id":"um80_20","label":"كِتَابُ الْفَرَائِضِ · ٢٠","segs":[["matn","وَالإِخْوَةُ وَالأَخَوَاتُ مِنَ الأُمِّ سَوَاءٌ، ذُكُورُهُمْ وَإِنَاثُهُمْ لِوَاحِدِهِمُ السُّدُسُ، وَلِلِاثْنَيْنِ السُّدُسَانِ، فَإِنْ كَانُوا أَكْثَرَ مِنْ ذَلِكَ فَهُمْ شُرَكَاءُ فِي الثُّلُثِ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"um81","title":"بَابُ الْحَجْبِ","units":[{"id":"um81_1","label":"بَابُ الْحَجْبِ · ١","segs":[["matn","يَسْقُطُ وَلَدُ الأَبَوَيْنِ بِثَلَاثَةٍ: بِالِابْنِ، وَابْنِهِ، وَالأَبِ، وَيَسْقُطُ وَلَدُ الأَبِ بِهَؤُلَاءِ الثَّلَاثَةِ وَبِالأَخِ مِنَ الأَبَوَيْنِ، وَيَسْقُطُ وَلَدُ الأُمِّ بِأَرْبَعَةٍ: بِالْوَلَدِ ذَكَرًا أَوْ أُنْثَى، وَوَلَدِ الِابْنِ، وَالأَبِ، وَالْجَدِّ، وَيَسْقُطُ الْجَدِّ بِالأَبِ، وَكُلُّ جَدٍّ بِمَنْ هُوَ أَقْرَبُ مِنْهُ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"um82","title":"بَابُ الْعَصَبَاتِ","units":[{"id":"um82_1","label":"بَابُ الْعَصَبَاتِ · ١","segs":[["matn","وَهُمْ: كُلُّ ذَكَرٍ يُدْلِي بِنَفْسِهِ أَوْ بِذَكَرٍ آخَرَ، إِلَّا الزَّوْجَ وَالْمُعْتِقَةَ وَعَصَبَاتِهَا، وَأَحَقُّهُمْ بِالْمِيرَاثِ أَقْرَبُهُمْ، وَأَقْرَبُهُمُ الِابْنُ، ثُمَّ ابْنُهُ، وَإِنْ نَزَلَ، ثُمَّ الأَبُ، ثُمَّ أَبُوهُ وَإِنْ عَلَا،"]]},{"id":"um82_2","label":"بَابُ الْعَصَبَاتِ · ٢","segs":[["matn","مَا لَمْ يَكُنْ إِخْوَةٌ، ثَمَّ بَنُو الأَبِ، ثُمَّ بَنُوهُمْ، وَإِنْ نَزَلُوا، ثُمَّ بَنُو الْجَدِّ، ثُمَّ بَنُوهُمْ، وَعَلَى هَذَا لَا يَرِثُ بَنُو أَبٍ أَعْلَى مَعَ بَنِي أَبٍ أَدْنَى مِنْهُ وَإِنْ نَزَلُوا،"]]},{"id":"um82_3","label":"بَابُ الْعَصَبَاتِ · ٣","segs":[["matn","وَأَوْلَى كُلِّ بَنِي أَبٍ أَقْرَبُهُمْ إِلَيْهِ، فَإِنِ اسْتَوَتْ دَرَجَاتُهُمْ فَأَوْلَاهُمْ مَنْ كَانَ لِأَبَوَيْنِ، وَأَرْبَعَةٌ مِنْهُمْ يُعَصِّبُونَ أَخَوَاتِهِمْ وَيَقْتَسِمُونَ مَا وَرِثُوا ﴿لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ﴾ وَهُمُ: الِابْنُ، وَابْنُهُ،"]]},{"id":"um82_4","label":"بَابُ الْعَصَبَاتِ · ٤","segs":[["matn","وَالأَخُ مِنَ الأَبَوَيْنِ أَوْ مِنَ الأَبِ، وَمَنْ عَدَاهُمْ يَنْفَرِدُ الذُّكُورُ بِالْمِيرَاثِ، كَبَنِي الإِخْوَةِ وَالأَعْمَامِ وَبَنِيهِمْ، وَإِذَا انْفَرَدَ الْعَصَبَةُ، وَرِثَ الْمَالَ كُلَّهُ، فَإِنْ كَانَ مَعَهُ ذُو فَرْضٍ بَدَأَ بِهِ، وَكَانَ الْبَاقِي لِلْعَصَبَةِ؛"]]},{"id":"um82_5","label":"بَابُ الْعَصَبَاتِ · ٥","segs":[["matn","لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «أَلْحِقُوا الْفَرَائِضَ بِأَهْلِهَا، فَمَا بَقِيَ، فَلِأَوْلَى رَجُلٍ ذَكَرٍ،» فَإِنِ اسْتَغْرَقَتِ الْفُرُوضُ الْمَالَ، سَقَطَ الْعَصَبَةُ،"]]},{"id":"um82_6","label":"بَابُ الْعَصَبَاتِ · ٦","segs":[["matn","كَزَوْجٍ وَأُمٌّ وَإِخْوَةٌ لِأُمٍّ وَإِخْوَةٌ لِأَبَوَيْنِ، فَلِلزَّوْجِ النِّصْفُ، وَلِلأُمِّ السُّدُسُ، وَلِلإِخْوَةِ لِلأُمِّ الثُّلُثُ وَيَسْقُطُ الإِخْوَةُ لِلأَبَوَيْنِ، وَتُسَمَّى: الْمُشْتَرَكَةَ وَالْحِمَارِيَّةَ، وَلَوْ كَانَ مَكَانَهُمْ أَخَوَاتٌ، لَكَانَ لَهُنَّ الثُّلُثَانِ،"]]},{"id":"um82_7","label":"بَابُ الْعَصَبَاتِ · ٧","segs":[["matn","وَتُعُولُ إِلَى عَشَرَةٍ، وَتُسَمَّى: أُمَّ الْفُرُوخِ، وَإِذَا كَانَ الْوَلَدُ خُنْثَى اعْتُبِرَ بِمَبَالِهِ، فَإِنْ بَالَ مِنْ ذَكَرِهِ، فَهُوَ رَجُلٌ، وَإِنْ بَالَ مِنْ فَرْجِهِ،"]]},{"id":"um82_8","label":"بَابُ الْعَصَبَاتِ · ٨","segs":[["matn","فَهُوَ امْرَأَةٌ، وَإِنْ بَالَ بَيْنَهُمَا وَاسْتَوَيَا، فَهُوَ مُشْكِلٌ، لَهُ نِصْفُ مِيرَاثٍ ذَكَرٍ وَنِصْفُ مِيرَاثِ أُنْثَى، وَكَذَلِكَ الْحُكْمُ فِي دِيَتِهِ وَجُرْحِهِ وَغَيْرِهِمَا، وَلَا يُنْكَحُ بِحَالٍ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"um83","title":"بَابُ ذَوِي الأَرْحَامِ","units":[{"id":"um83_1","label":"بَابُ ذَوِي الأَرْحَامِ · ١","segs":[["matn","وَهُمْ: كُلُّ قَرَابَةٍ لَيْسَ بِعَصَبَةٍ وَلَا ذِي فَرْضٍ، وَلَا مِيرَاثَ لَهُمْ مَعَ عَصَبَةٍ وَلَا ذِي فَرْضٍ، إِلَّا مَعَ أَحَدِ الزَّوْجَيْنِ، فَإِنَّ لَهُمْ مَا فَضَلَ عَنْهُ مِنْ غَيْرِ حَجْبٍ وَلَا مُعَاوَلَةٍ،"]]},{"id":"um83_2","label":"بَابُ ذَوِي الأَرْحَامِ · ٢","segs":[["matn","وَيَرِثُونَ بِالتَّنْزِيلِ، فَيُجْعَلُ كُلُّ إِنْسَانٍ مِنْهُمْ بِمَنْزِلَةِ مَنْ أَدْلَى بِهِ، فَوَلَدُ الْبَنَاتِ وَوَلَدُ بَنَاتِ الِابْنِ وَالأَخَوَاتِ بِمَنْزِلَةِ أُمَّهَاتِهِمِ، وَبَنَاتُ الإِخْوَةِ وَالأَعْمَامِ،"]]},{"id":"um83_3","label":"بَابُ ذَوِي الأَرْحَامِ · ٣","segs":[["matn","وَبَنُو الإِخْوَةِ مِنَ الأُمِّ كَآبَائِهِمْ، وَالْعَمَّاتُ وَالْعَمُّ مِنَ الأُمِّ كَالأَبِ، وَالأَخْوَالُ وَالْخَالَاتُ وَأَبُو الأُمِّ كَالأُمِّ، فَإِنْ كَانَ مَعَهُمْ اثْنَانِ فَصَاعِدًا مِنْ جِهَةٍ وَاحِدَةٍ فَأَسْبَقُهُمْ إِلَى الْوَارِثِ أَحَقُّهُمْ،"]]},{"id":"um83_4","label":"بَابُ ذَوِي الأَرْحَامِ · ٤","segs":[["matn","فَإِنِ اسْتَوَوْا قَسَمْتَ الْمَالَ بَيْنَ مَنْ أَدْلَوْا بِهِ، وَجَعَلْتَ مَالَ كُلِّ وَاحِدٍ مِنْهُمْ لِمَنْ أَدْلَى بِهِ، وَسَاوَيْتَ بَيْنَ الذُّكُورِ وَالْإِنَاثِ إِذَا اسْتَوَتْ جِهَاتُهُمْ مِنْهُ."]]},{"id":"um83_5","label":"بَابُ ذَوِي الأَرْحَامِ · ٥","segs":[["matn","فَلَوْ خَلَّفَ ابْنَ بِنْتٍ وَبِنْتَ بِنْتٍ أُخْرَى، وَابْنَا وَبِنْتَ بِنْتٍ أُخْرَى، قَسَمْتَ الْمَالَ بَيْنَ الْبَنَاتِ عَلَى ثَلَاثَةٍ، ثُمَّ جَعَلْتَهُ لِأَوْلَادِهِنَّ، لِلِابْنِ الثُّلُثُ وَلِلْبِنْتِ الثُّلُثُ، وَلِلِابْنِ وَالْبِنْتِ الْأُخْرَى الثُّلُثُ الْبَاقِي بَيْنَهُمَا نِصْفَيْنِ."]]},{"id":"um83_6","label":"بَابُ ذَوِي الأَرْحَامِ · ٦","segs":[["matn","وَإِنْ خَلَّفَ ثَلَاثَ عَمَّاتٍ مُتَفَرِّقَاتٍ، وَثَلَاثَ خَالَاتٍ مُتَفَرِّقَاتٍ فَالثُّلُثُ بَيْنَ الْخَالَاتِ عَلَى خَمْسَةٍ، وَالثُّلُثَانِ بَيْنَ الْعَمَّاتِ عَلَى خَمْسَةٍ، وَتَصِحُّ مِنْ خَمْسَةَ عَشَرَ،"]]},{"id":"um83_7","label":"بَابُ ذَوِي الأَرْحَامِ · ٧","segs":[["matn","وَإِنِ اخْتَلَفَتْ جِهَاتُ ذَوِي الأَرْحَامِ، نَزَلَّتَ الْبَعِيدَ حَتَّى يَلْحَقَ بِوَارِثِهِ، ثُمَّ قَسَمْتَ عَلَى مَا ذَكَرْنَا، وَالْجِهَاتُ ثَلَاثٌ: الْبُنُوَّةُ، وَالأُمُومُةُ، وَالأُبُوَّةُ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"um84","title":"بَابُ أُصُولِ الْمَسَائِلِ","units":[{"id":"um84_1","label":"بَابُ أُصُولِ الْمَسَائِلِ · ١","segs":[["matn","وَهِيَ سَبْعَةٌ: فَالنِّصْفُ مِنَ اثْنَيْنِ، وَالثُّلُثُ وَالثُّلُثَانِ مِنَ ثَلَاثَةٍ وَالرُّبُعُ وَحْدَهُ أَوْ مَعَ النِّصْفِ مِنْ أَرْبَعَةٍ، وَالثُّمُنُ وَحْدَهُ أَوْ مَعَ النِّصْفِ مِنْ ثَمَانِيَةٍ، فَهَذِهِ الأَرْبَعَةُ لَا عَوْلَ فِيهَا، وَإِذَا كَانَ مَعَ النِّصْفِ ثُلُثٌ أَوْ ثُلُثَانِ أَوْ سُدُسٌ،"]]},{"id":"um84_2","label":"بَابُ أُصُولِ الْمَسَائِلِ · ٢","segs":[["matn","فَهِيَ مِنْ سِتَّةٍ، وَتَعُولُ إِلَى عَشَرَةٍ، وَإِنْ كَانَ مَعَ الرُّبُعِ أَحَدُ هَذِهِ الثَّلَاثَةِ، فَهِيَ مِنِ اثْنَيْ عَشَرَ، وَتَعُولُ إِلَى سَبْعَةَ عَشَرَ، وَإِنْ كَانَ مَعَ الثُّمُنِ سُدُسٌ أَوْ ثُلُثَانِ، فَهِيَ مِنْ أَرْبَعَةٍ وَعِشْرِينَ، وَتَعُولُ إِلَى سَبْعَةٍ وَعِشْرِينَ."]]},{"id":"um84_3","label":"بَابُ أُصُولِ الْمَسَائِلِ · ٣","segs":[["matn","بَابُ الرَّدِّ وَإِنْ لَمْ تَسْتَغْرِقِ الْفُرُوضُ الْمَالَ، وَلَمْ يَكُنْ عَصَبَةٌ، فَالْبَاقِي يُرَدُّ عَلَيْهِمْ عَلَى قَدْرِ فُرُوضِهِمْ، إِلَّا الزَّوْجَيْنِ، فَإِنِ اخْتَلَفَتْ فُرُوضُهُمْ،"]]},{"id":"um84_4","label":"بَابُ أُصُولِ الْمَسَائِلِ · ٤","segs":[["matn","أَخَذْتَ سِهَامَهُمْ مِنْ أَصْلِ سِتَّةٍ، ثُمَّ جَعَلْتَ عَدَدَ سِهَامِهِمْ مِنْ أَصْلِ مَسْأَلَتِهِمْ، فَإِنِ انْكَسَرَ عَلَى بَعْضِهِمْ، ضَرَبْتَهُ فِي عَدَدِ سِهَامِهِمْ،"]]},{"id":"um84_5","label":"بَابُ أُصُولِ الْمَسَائِلِ · ٥","segs":[["matn","وَإِنْ كَانَ مَعَهُمْ أَحَدُ الزَّوْجَيْنِ أَعْطَيْتَهُ سَهْمَهُ مِنْ أَصْلِ مَسْأَلَتِهِ، وَقَسَمْتَ الْبَاقِيَ عَلَى مَسْأَلَةِ أَهْلِ الرَّدّ، فَإِنِ انْقَسَمَ،"]]},{"id":"um84_6","label":"بَابُ أُصُولِ الْمَسَائِلِ · ٦","segs":[["matn","وَإِلَّا ضَرَبْتَ مَسْأَلَةَ أَهْلِ الرَّدِّ فِي مَسْأَلَةِ الزَّوْجِ، ثُمَّ تُصَحِّحُ بَعْدَ ذَلِكَ عَلَى مَا سَنَذْكُرُهُ، وَلَيْسَ فِي مَسْأَلَةٍ يَرِثُ فِيهَا عَصَبَةٌ عَوْلٌ وَلَا رَدٌّ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"um85","title":"بَابُ تَصْحِيحِ الْمَسَائِلِ","units":[{"id":"um85_1","label":"بَابُ تَصْحِيحِ الْمَسَائِلِ · ١","segs":[["matn","إِذَا انْكَسَرَ سَهْمُ فَرِيقٍ عَلَيْهِمْ، ضَرَبْتَ عَدَدَهُمْ، أَوْ وَفْقَهُ إِنْ وَافَقَ سِهَامَهُمْ فِي أَصْلِ مَسْأَلَتِهِمْ أَوْ عَوْلِهَا إِنْ عَالَتْ، أَوْ نَقْصِهَا إِنْ نَقَصَتْ،"]]},{"id":"um85_2","label":"بَابُ تَصْحِيحِ الْمَسَائِلِ · ٢","segs":[["matn","ثُمَّ يَصِيرُ لِكُلِّ وَاحِدٍ مِنْهُمْ مِثْلُ مَا كَانَ لِجَمِيعِهِمْ أَوْ وَفْقُهُ، وَإِنِ انْكَسَرَ عَلَى فَرِيقَيْنِ فَأَكْثَرَ، وَكَانَتْ مُمَاثِلَةً أَجْزَأَكَ أَحَدُهُمَا وَإِنْ كَانَتْ مُتَنَاسِبَةً،"]]},{"id":"um85_3","label":"بَابُ تَصْحِيحِ الْمَسَائِلِ · ٣","segs":[["matn","أَجْزَأَكَ أَكْثَرُهَا، فَإِنْ تَبَايَنَتْ ضَرَبْتَ بَعْضَهَا فِي بَعْضٍ، وَإِنْ تَوَافَقَتْ، ضَرَبْتَ وَفْقَ أَحَدُهُمَا فِي الآخَرِ، ثُمَّ وَفَّقْتَ بَيْنَ مَا بَلَغَ وَبَيْنَ الثَّالِثِ وَضَرَبْتَهُ أَوْ وَفْقَهُ فِي الثَّالِثِ،"]]},{"id":"um85_4","label":"بَابُ تَصْحِيحِ الْمَسَائِلِ · ٤","segs":[["matn","ثُمَّ ضَرَبْتَهُ فِي المَسْأَلَةِ، ثُمَّ كُلُّ مَنْ لَهُ شَيْءٌ مِنْ المَسْأَلَةِ مَضْرُوبٌ فِي العَدَدِ الَّذِي ضَرَبْتَهُ فِي المَسْأَلَةِ."]]},{"id":"um85_5","label":"بَابُ تَصْحِيحِ الْمَسَائِلِ · ٥","segs":[["matn","بَابُ المُنَاسَخَاتِ إِذَا لَمْ تُقْسَمْ تَرِكَةُ المَيِّتِ حَتَّى مَاتَ بَعْضُ وَرَثَتِهِ، وَكَانَ وَرَثَةُ الثَّانِي يَرِثُونَهُ عَلَى حَسْبِ مِيرَاثِهِمْ مِنَ الأَوَّلِ،"]]},{"id":"um85_6","label":"بَابُ تَصْحِيحِ الْمَسَائِلِ · ٦","segs":[["matn","قَسَمْتَ التَّرِكَةَ عَلَى وَرَثَةِ الثَّانِي وَأَجْزَأَكَ، وَإِنِ اخْتَلَفَ مِيرَاثُهُمْ، صَحَّحْتَ مَسْأَلَةَ الثَّانِي، وَقَسَمْتَ عَلَيْهَا سِهَامَهُ مِنَ الأُولَى، فَإِنِ انْقَسَمَ، صَحَّتِ المَسْأَلَتَانِ مِمَّا صَحَّتْ مِنْهُ الأُولَى،"]]},{"id":"um85_7","label":"بَابُ تَصْحِيحِ الْمَسَائِلِ · ٧","segs":[["matn","وَإِنْ لَمْ تَنْقَسِمْ ضَرَبْتَ الثَّانِيَةَ، أَوْ وَفْقَهَا فِي الأُولَى، ثُمَّ كُلُّ مَنْ لَهُ شَيْءٌ مِنَ الأُولَى أَخَذَهُ مَضْرُوبًا فِي الثَّانِيَةِ أَوْ وَفْقَهَا،"]]},{"id":"um85_8","label":"بَابُ تَصْحِيحِ الْمَسَائِلِ · ٨","segs":[["matn","وَمَنْ لَهُ شَيْءٌ فِي الثَّانِيَةِ أَخَذَهُ مَضْرُوبًا فِي سِهَامِ الْمَيِّتِ الثَّانِي: أَوْ وَفْقَهَا، ثُمَّ تَفْعَلُ فِيمَا زَادَ مِنَ المَسَائِلِ كَذَلِكَ، أَيْضًا."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"um86","title":"بَابُ مَوَانِعِ المِيرَاثِ","units":[{"id":"um86_1","label":"بَابُ مَوَانِعِ المِيرَاثِ · ١","segs":[["matn","وَهِيَ ثَلَاثَةٌ: أَحَدُهَا: اخْتِلَافُ الدِّينِ، فَلَا يَرِثُ أَهْلُ مِلَّةٍ أَهْلَ مِلَّةٍ أُخْرَى لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «لَا يَرِثُ المُسْلِمُ الكَافِرَ، وَلَا الكَافِرُ المُسْلِمَ»."]]},{"id":"um86_2","label":"بَابُ مَوَانِعِ المِيرَاثِ · ٢","segs":[["matn","وَلِقَوْلِهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «لَا يَتَوَارَثُ أَهْلُ مِلَّتَيْنِ شَتَّى» وَالْمُرْتَدُّ لَا يَرِثُ أَحَدًا، وَإِنْ مَاتَ فَمَالُهُ فَيْءٌ."]]},{"id":"um86_3","label":"بَابُ مَوَانِعِ المِيرَاثِ · ٣","segs":[["matn","الثَّانِي: الرِّقُّ، فَلَا يَرِثُ العَبْدُ أَحَدًا، وَلَا لَهُ مَالٌ يُورَثُ وَمَنْ كَانَ بَعْضُهُ حُرًّا، وَرِثَ وَوُرِثَ. وَحَجَبَ بِقَدْرِ مَا فِيهِ مِنَ الْحُرِّيَّةِ."]]},{"id":"um86_4","label":"بَابُ مَوَانِعِ المِيرَاثِ · ٤","segs":[["matn","الثَّالِثُ: القَتْلُ، فَلَا يَرِثُ القَاتِلُ المَقْتُولَ بِغَيْرِ حَقٍّ، وَإِنْ قَتَلَهُ بِحَقٍّ كَالقَتْلِ حَدًّا، أَوْ قِصَاصًا، أَوْ قَتْلِ العَادِلِ البَاغِيَ، عَلَيْهِ، فَلَا يُمْنَعْ مِيرَاثُهُ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"um87","title":"بَابُ مَسَائِلَ شَتَّى","units":[{"id":"um87_1","label":"بَابُ مَسَائِلَ شَتَّى · ١","segs":[["matn","إِذَا مَاتَ عَنْ حَمْلٍ يَرِثُهُ، وَقَفْتَ مِيرَاثَ اثْنَيْنِ ذَكَرَيْنِ إِنْ كَانَ مِيرَاثُهُمَا أَكْثَرَ، وَإِلَّا مِيرَاثَ أُنْثَيَيْنِ، وَتُعْطِي كُلَّ وَارِثٍ اليَقِينَ، وَتَقِفُ البَاقِيَ حَتَّى يَتَبَيَّنَ."]]},{"id":"um87_2","label":"بَابُ مَسَائِلَ شَتَّى · ٢","segs":[["matn","وَإْنَ كَانَ فِي الوَرَثَةِ مَفْقُودٌ لَا يُعْلَمُ خَبَرُهُ، أَعْطَيْتَ كُلَّ وَارِثٍ اليَقِينَ، وَوَقَفْتَ البَاقِيَ حَتَّى يُعْلَمَ حَالُهُ، إِلَّا أَنْ يُفْقَدَ فِي مَهْلَكَةٍ أَوْ مِنْ بَيْنِ أَهْلِهِ، فَيُنْتَظَرُ أَرْبَعَ سِنِينَ ثُمَّ يُقْسَمُ."]]},{"id":"um87_3","label":"بَابُ مَسَائِلَ شَتَّى · ٣","segs":[["matn","وَإِنْ طَلَّقَ المَرِيضُ فِي مَرَضِ المَوْتِ المَخُوفِ امْرَأَتَهُ، طَلَاقًا يُتَّهَمُ فِيهِ لِقَصْدِ حِرْمَانِهَا عَنِ المِيرَاثَ، لَمْ يَسْقُطْ مِيرَاثُهَا، مَا دَامَتْ فِي عِدَّتِهِ، وَإِنْ كَانَ الطَّلَاقُ رَجْعِيًّا، تَوَارَثَا فِي العِدَّةِ، سَوَاءٌ كَانَ فِي الصِّحَّةِ أَوِ فِي الْمَرَضِ."]]},{"id":"um87_4","label":"بَابُ مَسَائِلَ شَتَّى · ٤","segs":[["matn","وَإِنْ أَقَرَّ الوَرَثَةُ كُلُّهُمْ بِمُشَارِكٍ لَهُمْ فِي المِيرَاثِ فَصَدَّقَهُمْ، أَوْ كَانَ صَغِيرًا مَجْهُولَ النَّسَبِ، ثَبَتَ نَسَبُهُ وَإِرْثُهُ، وَإِنْ أَقَرَّ بِهِ بَعْضُهُمْ، لَمْ يَثْبُتْ نَسَبُهُ، وَلَهُ فَضْلُ مَا فِي يَدِ الْمُقِرِّ عَنْ مِيرَاثِهِ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"um88","title":"بَابُ الوَلَاءِ","units":[{"id":"um88_1","label":"بَابُ الوَلَاءِ · ١","segs":[["matn","الوَلَاءُ لِمَنْ أَعْتَقَ، وَإِنِ اخْتَلَفَ دِينُهُمَا؛ لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «إِنَّمَا الوَلَاءُ لِمَنْ أَعْتَقَ،» وَإِنْ عَتَقَ عَلَيْهِ بِرَحِمٍ أَوْ كِتَابَةٍ أَوْ تَدْبِيرٍ أَوِ اسْتِيلَادٍ، فَلَهُ عَلَيْهِ الوَلَاءُ،"]]},{"id":"um88_2","label":"بَابُ الوَلَاءِ · ٢","segs":[["matn","وَعَلَى أَوْلَادِهِ مِنْ حُرَّةٍ مُعْتَقَةٍ أَوْ أَمَةٍ وَعَلَى مُعْتِقِيهِ وَمُعْتَقِي أَوْلَادِهِ وَأَوْلَادِهِمْ وَمُعْتِقِيهِمْ أَبَدًا مَا تَنَاسَلُوا، وَيَرِثُهُمْ إِذَا لَمْ يَكُنْ لَهُ مَنْ يَحْجُبُهُ عَنْ مِيرَاثِهِمْ، ثُمَّ عَصَبَاتُهُ مِنْ بَعْدِهِ."]]},{"id":"um88_3","label":"بَابُ الوَلَاءِ · ٣","segs":[["matn","وَمَنْ قَالَ: أَعْتِقْ عَبْدَكَ عَنِّي وَعَلَيَّ ثَمَنُهُ فَفَعَلَ، فَعَلَى الآمِرِ ثَمَنُهُ، وَلَهُ وَلَاؤُهُ، وَإِنْ لَمْ يَقُلْ: عَنِّي، فَالثَّمَنُ عَلَيْهِ وَالوَلَاءُ لِلْمُعْتِقِ، وَمَنْ أَعْتَقَ عَبْدَهُ عَنْ حَيٍّ بِلَا أَمْرِهِ أَوْ عَنْ مَيِّتٍ، فَالوَلَاءُ لِلْمُعْتِقِ، وَإِنْ أَعْتَقَهُ عَنْهُ بِأَمْرِهِ."]]},{"id":"um88_4","label":"بَابُ الوَلَاءِ · ٤","segs":[["matn","فَالوَلَاءُ لِلْمُعْتَقِ عَنْهُ بِأَمْرِهِ، وَإِذَا كَانَ أَحَدُ الزَّوْجَيْنِ الحُرَّيْنِ حُرَّ الأَصْلِ، فَلَا وَلَاءَ عَلَى وَلَدِهَمَا، وَإِنْ كَانَ أَحَدُهُمَا، رَقِيقًا، تَبِعَ الوَلَدُ الأُمَّ فِي حُرِّيَّتِهَا وَرِقِّهَا فَإِنْ كَانَتِ الأُمُّ رَقِيقَةً، فَوَلَدُهَا رَقِيقٌ لِسَيِّدِهَا، فَإِنْ أَعْتَقَهُمْ، فَوَلَاؤُهُمْ لَهُ لَا يَخْرُجُ عَنْهُ بِحَالٍ،"]]},{"id":"um88_5","label":"بَابُ الوَلَاءِ · ٥","segs":[["matn","وَإِنْ كَانَ الأَبُ رَقِيقًا وَالأُمُّ مُعْتَقَةً، فَأَوْلَادُهَا أَحْرَارٌ وَعَلَيْهِمُ الوَلَاءُ لِمَوْلَى أُمِّهِمْ، فَإِنْ أَعْتَقَ الْعَبْدَ سَيِّدُهُ ثَبَتَ لَهُ عَلَيْهِ الْوَلَاءُ، وَجَرَّ إِلَيْهِ وَلَاءَ أَوْلَادِهِ، وَإِنِ اشْتَرَى أَبًاهُ، عَتَقَ عَلَيْهِ، وَلَهُ وَلَاؤُهُ وَوَلَاءُ إِخْوَتِهِ، وَيَبْقَى وَلَاؤُهُ لِمَوَالِي أُمِّهِ؛"]]},{"id":"um88_6","label":"بَابُ الوَلَاءِ · ٦","segs":[["matn","لِأَنَّهُ لَا يَجُرُّ وَلَاءَ نَفْسِهِ فَإِنْ اشْتَرَى أَبُوهُمْ عَبْدًا فَأَعْتَقَهُ ثُمَّ مَاتَ الأَبُ فَمِيرَاثُهُ بَيْنَ أَوْلَادِهِ لِلذَّكَرِ مِثْلُ حَظِّ الأُنْثَيَيْنِ، وَإِذَا مَاتَ عَتِيقُهُ بَعْدَهُ، فَمِيرَاثُهُ لِلذُّكُورِ دُونَ الإِنَاثِ، وَلَوِ اشْتَرَى الذُّكُورُ وَالإِنَاثُ أَبًاهُمْ فَعَتَقَ عَلَيْهِمْ،"]]},{"id":"um88_7","label":"بَابُ الوَلَاءِ · ٧","segs":[["matn","ثُمَّ اشْتَرَى أَبُوهُمْ عَبْدًا فَأَعْتَقَهُ، ثُمَّ مَاتَ الأَبُ، ثُمَّ مَاتَ عَتِيقُهُ، فَمِيرَاثُهُمَا عَلَى مَا ذَكَرْنَا فِي الَّتِي قَبْلَهَا، وَإِنْ مَاتَ الذُّكُورُ قَبْلَ مَوْتِ العَتِيقِ، وَرِثَ الإِنَاثُ مِنْ مَالِهِ بِقَدْرِ مَا أَعْتَقْنَ مِنْ أَبِيهِنَّ،"]]},{"id":"um88_8","label":"بَابُ الوَلَاءِ · ٨","segs":[["matn","ثُمَّ يُقْسَمُ البَاقِي بَيْنَهُنَّ وَبَيْنَ مُعْتِقِ الأُمِّ، فَإِنِ اشْتَرَيْنَ نِصْفَ الأَبِ، وَكَانُوا ذَكَرَيْنِ وَأُنْثَيَيْنِ، فَلَهُنَّ خَمْسَةُ أَسْدَاسِ الْمِيرَاثِ، وَلِمُعِتِقِ الأُمِّ السُّدُسُ لِأَنَّ لَهُنَّ نِصْفَ الوَلَاءِ، وَالبَاقِي بَيْنَهُنَّ وَبَيْنَ مُعْتِقِ الأُمِّ أَثْلَاثاً، فَإِنِ اشْتَرَى ابْنُ المُعْتَقَةِ عَبْدًا فَأَعْتَقَهُ،"]]},{"id":"um88_9","label":"بَابُ الوَلَاءِ · ٩","segs":[["matn","ثُمَّ اشْتَرَى العَبْدُ أَبًا مُعْتِقِهِ، فَأَعْتَقَهُ جَرَّ وَلَاءَ مُعْتِقِهِ، وَصَارَ كُلُّ وَاحِدٍ مِنْهُمُا مَوْلَى الآخَرِ، وَلَوْ أَعْتَقَ الحَرْبِيُّ عَبْدًا، فَأَسْلَمَ وَسَبَاهُ العَبْدُ وَأَخْرَجَهُ إِلَى دَارِ الإِسْلَامِ، ثُمَّ أَعْتَقَهُ، صَارَ كُلُّ وَاحِدٍ مِنْهُمَا مَوْلَى الآخَرِ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"um89","title":"بَابُ المِيرَاثِ بِالْوَلَاءِ","units":[{"id":"um89_1","label":"بَابُ المِيرَاثِ بِالْوَلَاءِ · ١","segs":[["matn","الوَلَاءُ لَا يُورَثُ، وَإِنَّمَا يَرِثُ بِهِ أَقْرَبُ عَصَبَاتِ المُعْتِقِ، وَلَا يَرِثُ النِّسَاءُ مِنَ الوَلَاءِ، إِلَا مَا أَعْتَقْنَ، أَوْ أَعْتَقَهُ مَنْ أَعْتَقْنَ،"]]},{"id":"um89_2","label":"بَابُ المِيرَاثِ بِالْوَلَاءِ · ٢","segs":[["matn","وَكَذَلِكَ كُلُّ ذِي فَرْضٍ إِلَّا الأَبَ وَالجَدَّ لَهُمَا السُّدُسُ مَعَ الِابْنِ وَابْنِهِ، وَالوَلَاءُ لِلْكُبْرِ، فَلَوْ مَاتَ الْمُعْتِقُ وَخَلَّفَ ابْنَيْنِ وَعَتِيقَهُ،"]]},{"id":"um89_3","label":"بَابُ المِيرَاثِ بِالْوَلَاءِ · ٣","segs":[["matn","فَمَاتَ أَحَدُ الِابْنَيْنِ عَنْ ابْنٍ، ثُمَّ مَاتَ عَتِيقُهُ، فَمَالُهُ لِابْنِ المُعْتِقِ، وَإِنْ مَاتَ الَابْنَانِ بَعْدَهُ وَقَبْلَ الْمَوْلَى وَخَلَّفَ أَحَدُهُمَا ابْنَا وَالْآخَرُ تِسْعَةً، فَوَلَاؤُهُ بَيْنَهُمْ عَلَى عَدَدِهِمْ، لِكُلِّ وَاحِدٍ عَشَرَةٌ، وَإِذَا أَعْتَقَتِ المَرْأَةُ عَبْدًا ثُمَّ مَاتَتْ، فَوَلَاؤُهُ لِابْنِهَا وَعَقْلُهُ عَلَى عَصَبَتِهَا،"]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"um90","title":"بَابُ العِتْقِ","units":[{"id":"um90_1","label":"بَابُ العِتْقِ · ١","segs":[["matn","وَهُوَ: تَحْرِيرُ العَبْدِ، وَيَحْصُلُ بِالقَوْلِ وَالفِعْلِ. فَأَمَّا القَوْلُ، فَصَرِيحُهُ لَفْظُ العِتْقِ وَالتَّحْرِيرِ، وَمَا تَصَرَّفَ مِنْهُمَا، فَمَتَى أَتَى بِذَلِكَ، حَصَلَ العِتْقُ وَإِنْ لَمْ يَنْوِهِ، وَمَا عَدَا هَذَا مِنَ الأَلْفَاظِ الْمُحْتَمِلَةِ لِلْعِتْقِ كِنَايَةٌ، لَا يَعْتِقُ بِهَا إِلَّا إِذَا كَانَ نَوَى."]]},{"id":"um90_2","label":"بَابُ العِتْقِ · ٢","segs":[["matn","وَأَمَّا الفِعْلُ، فَمَنْ مَلَكَ ذَا رَحِمٍ مَحْرَمٍ عَتَقَ عَلَيْهِ، وَمَنْ أَعْتَقَ جُزْءًا مِنْ عَبْدٍ مُشَاعًا أَوْ مُعَيَّنًا، عَتَقَ كُلُّهُ، وَإِنْ أَعْتَقَ ذَلِكَ مِنْ عَبْدٍ مُشْتَرَكٍ،"]]},{"id":"um90_3","label":"بَابُ العِتْقِ · ٣","segs":[["matn","وَهُوَ مُوسِرٌ بِقِيمَةِ نَصِيبِ شَرِيكِهِ، عَتَقَ كُلُّهُ وَقُوِّمَ عَلَيْهِ نَصِيبُ شَرِيكِهِ، وَلَهُ وَلَاؤُهُ وَإِنْ كَانَ مُعْسِرًا، لَمْ يَعْتِقْ إِلَّا حِصَّتُهُ؛"]]},{"id":"um90_4","label":"بَابُ العِتْقِ · ٤","segs":[["matn","لِقَوْلِ رَسُولِ اللهِ: صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «مَنْ أَعْتَقَ شِرْكًا لَهُ فِي عَبْدٍ فَكَانَ لَهُ مَا يَبْلُغُ ثَمَنَ العَبْدِ، قُوِّمَ عَلَيْهِ قِيمَةَ عَدْلٍ، فَأَعْطَى شُرَكَاءَهُ حِصَصَهُمْ وَعَتَقَ عَلَيْهِ العَبْدُ، وَإِلَّا فَقَدْ عَتَقَ مِنْهُ مَا عَتَقَ»."]]},{"id":"um90_5","label":"بَابُ العِتْقِ · ٥","segs":[["matn","وَإِنْ مَلَكَ جُزْءًا مِنْ ذِي رَحِمِهِ، عَتَقَ عَلَيْهِ بَاقِيهِ إِنْ كَانَ مُوسِرًا، إِلَّا أَنْ يَمْلِكَهُ بِالْمِيرَاثِ، فَلَا يَعْتِقُ عَلَيْهِ إِلَّا مَا مَلَكَ."]]},{"id":"um90_6","label":"بَابُ العِتْقِ · ٦","segs":[["matn","فَصْلٌ: وَإِذَا قَالَ لِعَبْدِهِ: أَنْتَ حُرٌّ، فِي وَقْتٍ سَمَّاهُ، أَوْ عَلَّقَ عِتْقَهُ عَلَى شَرْطٍ، يَعْتِقُ إِذَا جَاءَ ذَلِكَ الوَقْتُ أَوْ وُجِدَ الشَّرْطُ، وَلَمْ يَعْتِقْ قَبْلَهُ، وَلَا يَمْلِكُ إِبْطَالَهُ بِالقَوْلِ، وَلَهُ بَيْعُهُ وَهِبَتُهُ وَالتَّصَرُّفُ فِيهِ، وَمَتَى عَادَ إِلَيْهِ، عَادَ الشَّرْطُ."]]},{"id":"um90_7","label":"بَابُ العِتْقِ · ٧","segs":[["matn","وَإِنْ كَانَتْ الأَمَةُ حَامِلاً حِينَ التَّعْلِيقِ أَوْ وُجِدَ الشَّرْطُ، عَتَقَ حَمْلُهَا، وَإِنْ حَمَلَتْ وَوَضَعَتْ فِيمَا بَيْنَهُمَا، لَمْ يَعْتِقْ وَلَدُهَا."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"um91","title":"بَابُ التَّدْبِيرِ","units":[{"id":"um91_1","label":"بَابُ التَّدْبِيرِ · ١","segs":[["matn","وَإِذَا قَالَ لِعَبْدِهِ: أَنْتَ حُرٌّ بَعْدَ مَوْتِي، أَوْ قَدْ دَبَّرْتُكَ، أَوْ أَنْتَ مُدَبَّرٌ صَارَ مُدَبَّرًا، يَعْتِقُ بِمَوْتِ سَيِّدِهِ، إِنْ حَمَلَهُ الثُّلُثُ، وَلَا يَعْتِقُ مَا زَادَ إِلَّا بِإِجَازَةِ الوَرَثَةِ، وَلِسَيِّدِهِ بَيْعُهُ وَهِبَتُهُ وَوَطْءُ الجَارِيَةِ، وَمَتَى مَلَكَهُ بَعْدُ، عَادَ تَدْبِيرُهُ."]]},{"id":"um91_2","label":"بَابُ التَّدْبِيرِ · ٢","segs":[["matn","وَمَا وَلَدَتِ الْمُدَبَّرَةُ، وَالْمُكَاتَبَةُ، وَأُمُّ الوَلَدِ مِنْ غَيْرِ سَيِّدِهَا، فَلَهُ حُكْمُهَا."]]},{"id":"um91_3","label":"بَابُ التَّدْبِيرِ · ٣","segs":[["matn","وَيَجُوزُ تَدْبِيرُ المُكَاتَبُ وَكِتَابَةُ المُدَبَّرِ، فَإِنْ أَدَّى، عَتَقَ، وَإِنْ مَاتَ سَيِّدُهُ قَبْلَ أَدَائِهِ، عَتَقَ إِنْ حَمَلَ الثُّلُثُ مَا بَقِيَ عَلَيْهِ مِنْ كِتَابَتِهِ، وَإِلَّا عَتَقَ مِنْهُ بِقَدْرِ الثُّلُثِ، وَسَقَطَ مِنَ الكِتَابَةِ بِقَدْرِ مَا عَتَقَ، وَكَانَ عَلَى الكِتَابَةِ بِمَا بَقِيَ."]]},{"id":"um91_4","label":"بَابُ التَّدْبِيرِ · ٤","segs":[["matn","وَإِنِ اسْتَوْلَدَ مُدَبَّرَتَهُ بَطَلَ تَدْبِيرُهَا، وَإِنْ أَسْلَمَ مُدَبَّرُ الكَافِرِ أَوْ أُمُّ وَلَدِهِ، حِيلَ بَيْنَهُ وَبَيْنَهُمَا، وَيُنْفِقُ عَلَيْهِمَا مِنْ كَسْبِهِمَا، وَإِنْ لَمْ يَكُنْ لَهُمَا كَسْبٌ، أُجِبرَ عَلَى نَفَقَتِهِمَا، فَإِنْ أَسْلَمَ، رُدَّا إِلَيْهِ، وَإِنْ مَاتَ عُتِقَا."]]},{"id":"um91_5","label":"بَابُ التَّدْبِيرِ · ٥","segs":[["matn","وَإِنْ دَبَّرَ شِرْكًا لَهُ فِي عَبْدٍ وَهُوَ مُوسِرٌ، لَمْ يَعْتِقْ عَلَيْهِ سِوَى مَا أَعْتَقَهُ، وَإِنْ أَعْتَقَهُ فِي مَرَضِ مَوْتِهِ وَثُلُثُهُ يَحْتَمِلُ بَاقِيَهُ، عَتَقَ جَمِيعُهُ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"um92","title":"بَابُ المُكَاتَبِ","units":[{"id":"um92_1","label":"بَابُ المُكَاتَبِ · ١","segs":[["matn","وَالْمُكَاتَبَةُ: شِرَاءُ العَبْدِ نَفْسَهُ مِنْ سَيِّدِهِ بِمَالٍ فِي ذِمَّتِهِ، وَإِذَا ابْتَغَاهَا العَبْدُ المُكْتَسِبُ الصَّدُوقُ مِنْ سَيِّدِهِ."]]},{"id":"um92_2","label":"بَابُ المُكَاتَبِ · ٢","segs":[["matn","اسْتُحِبَّ لَهُ إِجَابَتُهُ إِلَيْهَا؛ لِقَوْلِ اللهِ تَعَالَى: ﴿وَالَّذِينَ يَبْتَغُونَ الْكِتَابَ مِمَّا مَلَكَتْ أَيْمَانُكُمْ فَكَاتِبُوهُمْ إِنْ عَلِمْتُمْ فِيهِمْ خَيْرًا﴾."]]},{"id":"um92_3","label":"بَابُ المُكَاتَبِ · ٣","segs":[["matn","وَيُجْعَلُ الْمَالُ عَلَيْهِ مُنَجَّمًّا، فَمَتَى أَدَّاهَا، عَتَقَ، وَيُعْطَى مِمَّا كُوتِبَ عَلَيْهِ الرُّبُعُ؛ لِقَوْلِ اللهِ تَعَالَى: ﴿وَآتُوهُمْ مِنْ مَالِ اللَّهِ الَّذِي آتَاكُمْ﴾ قَالَ عَلِيٌّ رَضِيَ اللهُ عَنْهُ: هُوَ الرُّبُعُ."]]},{"id":"um92_4","label":"بَابُ المُكَاتَبِ · ٤","segs":[["matn","وَالمُكَاتَبُ عَبْدٌ مَا بَقِيَ عَلَيْهِ دِرْهَمٌ، إِلَّا أَنَّهُ يَمْلِكُ البَيْعَ وَالشِّرَاءَ وَالسَّفَرَ، وَكُلُّ مَا فِيهِ مَصْلَحَةُ مَالِهِ، وَلَيْسَ لَهُ التَّبَرُّعُ وَلَا التَّزَوُّجُ وَلَا التَّسَرِّي، إِلَّا بِإِذْنِ سَيِّدِهِ."]]},{"id":"um92_5","label":"بَابُ المُكَاتَبِ · ٥","segs":[["matn","وَلَيْسَ لِسَيِّدِهِ اسْتِخْدَامُهُ وَلَا أَخْذُ شَيْءٍ مِنْ مَالِهِ، وَمَتَى أَخَذَ مِنْهُ شَيْئًا أَوْ جَنَى عَلَيْهِ أَوْ عَلَى مَالِهِ، فَعَلَيْهِ غَرَامَتُهُ، وَيَجْرِي الرِّبَا بَيْنَهُمَا، كَالأَجَانِبِ، إِلَّا أَنَّهُ لَا بَأْسَ أَنْ يُعَجِّلَ لِسَيِّدِهِ، وَيَضَعُ عَنْهُ بَعْضَ كِتَابَتِهِ."]]},{"id":"um92_6","label":"بَابُ المُكَاتَبِ · ٦","segs":[["matn","وَلَيْسَ لَهُ وَطْءُ مُكَاتَبَتِهِ، وَلَا بِنْتِهَا وَلَا جَارِيَتِهَا، فَإِنْ فَعَلَ، فَعَلَيْهِ مَهْرُ مِثْلِهَا، وَإِنْ وَلَدَتْ مِنْهُ، صَارَتْ أُمَّ وَلَدٍ، فَإِنْ أَدَّتْ عَتَقَتْ، وَإِنْ مَاتَ سَيِّدُهَا قَبْلَ أَدَائِهَا، عَتَقَتْ، وَمَا فِي يَدِهَا لَهَا إِلَّا أَنْ تَكُونَ قَدْ عَجَزَتْ."]]},{"id":"um92_7","label":"بَابُ المُكَاتَبِ · ٧","segs":[["matn","وَيَجُوزُ بَيْعُ الْمُكَاتَبِ؛ لِأَنَّ عَائِشَةَ رَضِيَ اللهُ عَنْهَا اشْتَرَتْ بَرِيرَةَ وَهِيَ مُكَاتَبَةٌ، بِأَمْرِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ."]]},{"id":"um92_8","label":"بَابُ المُكَاتَبِ · ٨","segs":[["matn","وَيَكُونُ فِي يَدِ مُشْتَرِيهِ مُبْقًى عَلَى مَا بَقِيَ مِنْ كِتَابَتِهِ، فَإِنْ أَدَّى، عَتَقَ وَوَلَاؤُهُ لِمُشْتَرِيهِ، وَإِنْ عَجَزَ، فَهُوَ عَبْدٌ."]]},{"id":"um92_9","label":"بَابُ المُكَاتَبِ · ٩","segs":[["matn","وَإِنِ اشْتَرَى المُكَاتَبَانِ كُلُّ وَاحِدٍ مِنْهُمَا الآخَرَ، صَحَّ شِرَاءُ الأَوَّلِ وَبَطَلَ شِرَاءُ الثَّانِي، فَإِنْ جُهِلَ الأَوَّلُ مِنْهُمَا، بَطَلَ البَيْعَانِ."]]},{"id":"um92_10","label":"بَابُ المُكَاتَبِ · ١٠","segs":[["matn","وَإِنْ مَاتَ المُكَاتَبُ، بَطَلَتِ الْكِتَابَةُ وَإِنْ مَاتَ السَّيِّدُ قَبْلَهُ، فَهُوَ عَلَى كِتَابَتِهِ يُؤَدِّي إِلَى الوَرَثَةِ، وَوَلَاؤُهُ لِمُكَاتِبِهِ."]]},{"id":"um92_11","label":"بَابُ المُكَاتَبِ · ١١","segs":[["matn","وَالكِتَابَةُ عَقْدٌ لَازِمٌ لَيْسَ لِأَحَدُهُمَا فَسْخُهَا، وَإِنْ حَلَّ نَجْمٌ فَلَمْ يُؤَدِّهِ، فَلِسَيِّدِهِ تَعْجِيزُهُ، وَإِذَا جَنَى الْمُكَاتَبُ، بُدِئَ بِجِنَايَتِهِ، وَإِنِ اخْتَلَفَ هُوَ وَسَيِّدُهُ فِي الكِتَابَةِ، أَوْ عِوَضِهَا، أَوِ التَّدْبِيرِ، أَوِ الِاسْتِيلَادِ، فَالقَوْلُ قَوْلُ السَّيِّدِ مَعَ يَمِينِهِ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"um93","title":"بَابُ أَحْكَامِ أُمَّهَاتِ الأَوْلَادِ","units":[{"id":"um93_1","label":"بَابُ أَحْكَامِ أُمَّهَاتِ الأَوْلَادِ · ١","segs":[["matn","إِذَا حَمَلَتِ الأَمَةُ مِنْ سَيِّدِهَا فَوَضَعَتْ مَا يَتَبَيَّنُ فِيهِ شَيْءٌ مِنْ خَلْقِ الإِنْسَانِ، صَارَتْ لَهُ بِذَلِكَ أُمُ وَلَدٍ."]]},{"id":"um93_2","label":"بَابُ أَحْكَامِ أُمَّهَاتِ الأَوْلَادِ · ٢","segs":[["matn","تَعْتِقُ بِمَوْتِهِ، وَإِنْ لَمْ يَمْلِكْ غَيْرَهَا، وَمَا دَامَ حَيًّا، فَهِيَ أَمَتُهُ، أَحْكَامُهَا أَحْكَامُ الإِمَاءِ، فِي حِلِّ وَطْئِهَا وَمِلْكِ مَنَافِعِهَا وَكَسْبِهَا وَسَائِرِ الأَحْكَامِ،"]]},{"id":"um93_3","label":"بَابُ أَحْكَامِ أُمَّهَاتِ الأَوْلَادِ · ٣","segs":[["matn","إِلَّا أَنَّهُ لَا يَمْلِكُ بَيْعَهَا وَلَا رَهْنَهَا وَلَا سَائِرَ مَا يَنْقُلُ المِلْكَ فِيهَا أَوْ يُرَادُ لَهُ، وَتَجُوزُ الوَصِيَّةُ لَهَا وَإِلَيْهَا."]]},{"id":"um93_4","label":"بَابُ أَحْكَامِ أُمَّهَاتِ الأَوْلَادِ · ٤","segs":[["matn","فَإِنْ قَتَلَتْ سَيِّدَهَا عَمْدًا، فَعَلَيْهَا القِصَاصُ، وَإِنْ قَتَلَتْهُ خَطَأً، فَعَلَيْهَا قِيمَةُ نَفْسِهَا، وَتَعْتِقُ فِي الحَالَيْنِ. وَإِنْ وَطِئَ أَمَةَ غَيْرِهِ بِنِكَاحٍ ثُمَّ مَلَكَهَا حَامِلاً، عَتَقَ الجَنِينُ، وَلَهُ بَيْعُهَا."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"um94","title":"كِتَابُ النِّكَاحِ","units":[{"id":"um94_1","label":"كِتَابُ النِّكَاحِ · ١","segs":[["matn","النِّكَاحُ مِنْ سُنَنِ الْمُرْسَلِينَ، وَهُوَ أَفْضَلُ مِنَ التَّخَلِّي مِنْهُ لِنَفْلِ الْعِبَادَةِ، لِأَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَدَّ عَلَى عُثْمَانَ بْنِ مَظْعُونٍ التَّبَتُّلَ،"]]},{"id":"um94_2","label":"كِتَابُ النِّكَاحِ · ٢","segs":[["matn","وَقَالَ: «يَا مَعْشَرَ الشَّبَابِ مَنِ اسْتَطَاعَ مِنْكُمُ البَاءَةَ فَلْيَتَزَوَّجَ، فَإِنَّهُ أَغَضُّ لِلْبَصَرِ، وَأَحْصَنُ لِلْفَرْجِ، وَمَنْ لَمْ يَسْتَطِعْ فَعَلَيْهِ بِالصَّوْمِ فَإِنَّهُ لَهُ وِجَاءٌ»."]]},{"id":"um94_3","label":"كِتَابُ النِّكَاحِ · ٣","segs":[["matn","وَمَنْ أَرَادَ خِطْبَةَ امْرَأَةٍ، فَلَهُ النَّظَرُ مِنْهَا إِلَى مَا يَظْهَرُ عَادَةً، كَوَجْهِهَا وَكَفَّيْهَا وَقَدَمَيْهَا، وَلَا يَخْطُبُ الرَّجُلُ عَلَى خِطْبَةِ أَخِيهِ إِلَّا أَنْ لَا يُسْكَنَ إِلَيْهِ."]]},{"id":"um94_4","label":"كِتَابُ النِّكَاحِ · ٤","segs":[["matn","وَلَا يَجُوزُ التَّصْرِيحُ بِخِطْبَةِ مُعْتَدَّةٍ، وَيَجُوزُ التَّعْرِيضُ بِخِطْبَةِ البَائِنِ خَاصَّةً، فَيَقُولُ: لَا تُفَوِّتِينِي بِنَفْسِكِ، وَأَنَا فِي مِثْلِكِ لَرَاغِبٌ، وَنَحْوَ ذَلِكَ."]]},{"id":"um94_5","label":"كِتَابُ النِّكَاحِ · ٥","segs":[["matn","وَلَا يَنْعَقِدُ النِّكَاحُ إِلَّا بِإِيجَابٍ مِنَ الوَلِيِّ أَوْ نَائِبِهِ، فَيَقُولُ: أَنْكَحْتُكَ أَوْ زَوَّجْتُكَ، وَقَبُولِ مِنَ الزَّوْجِ أَوْ نَائِبِهِ، فَيَقُولُ: قَبَلْتُ أَوْ تَزَوَّجْتُ."]]},{"id":"um94_6","label":"كِتَابُ النِّكَاحِ · ٦","segs":[["matn","وَيُسْتَحَبُّ أَنْ يَخْطُبَ قَبْلَ العَقْدِ بِخِطْبَةِ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: عَلَّمَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ التَّشَهُّدَ فِي الْحَاجَةِ: إِنَّ الحَمْدَ لِلَّهِ نَحْمَدُهُ،"]]},{"id":"um94_7","label":"كِتَابُ النِّكَاحِ · ٧","segs":[["matn","وَنَسْتَعِينُهُ، وَنَسْتَغْفِرُهُ، وَنَتُوبُ إِلَيْهِ وَنَعُوذُ بِاللهِ مِنْ شُرُورِ أَنْفُسِنَا وَمِنْ سَيِّئاتِ أَعْمَالِنَا، مَنْ يَهْدِ اللهُ فَلَا مُضِلَّ لَهُ، وَمَنْ يُضْلِلْ، فَلَا هَادِيَ لَهُ."]]},{"id":"um94_8","label":"كِتَابُ النِّكَاحِ · ٨","segs":[["matn","وَأَشْهَدُ أَنْ لَا إِلهَ إِلَّا اللهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، وَيَقْرَأُ ثَلَاثَ آيَاتٍ: ﴿اتَّقُوا اللَّهَ حَقَّ تُقَاتِهِ﴾ ﴿وَاتَّقُوا اللَّهَ الَّذِي تَسَاءَلُونَ بِهِ وَالْأَرْحَامَ﴾ ﴿اتَّقُوا اللَّهَ وَقُولُوا قَوْلًا سَدِيدًا يُصْلِحْ لَكُمْ أَعْمَالَكُمْ﴾. وَيُسْتَحَبُّ إِعْلَانُ النِّكَاحِ، وَالضَّرْبُ عَلَيْهِ بِالدُّفِّ لِلنِّسَاءِ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"um95","title":"بَابُ وِلَايَةِ النِّكَاحِ","units":[{"id":"um95_1","label":"بَابُ وِلَايَةِ النِّكَاحِ · ١","segs":[["matn","لَا نِكَاحَ إِلَّا بِوَلِيٍّ وَشَاهِدَيْنِ مِنَ الْمُسْلِمِينَ، وَأَوْلَى النَّاسِ بِتَزْوِيجِ الحُرَّةِ أَبُوهَا، ثُمَّ أَبُوهُ وَإِنْ عَلَا،"]]},{"id":"um95_2","label":"بَابُ وِلَايَةِ النِّكَاحِ · ٢","segs":[["matn","ثُمَّ ابْنُهَا ثُمَّ ابْنُهُ وَإِنْ نَزَلَ ثُمَّ الأَقْرَبُ فَالأَقْرَبُ مِنْ عَصَبَاتِهَا، ثُمَّ مُعْتِقُهَا، ثُمَّ الأَقْرَبُ فَالأَقْرَبُ مِنْ عَصَبَاتِهِ، ثُمَّ السُّلْطَانُ، وَوَكِيلُ كُلِّ وَاحِدٍ مِنْ هَؤُلَاءِ يَقُومُ مَقَامَهُ."]]},{"id":"um95_3","label":"بَابُ وِلَايَةِ النِّكَاحِ · ٣","segs":[["matn","وَلَا يَصِحُّ تَزْوِيجُ أَبْعَدَ مَعَ وُجُودِ أَقْرَبَ إِلَّا أَنْ يَكُونَ صَبِيًّا، أَوْ زَائِلَ العَقْلِ، أَوْ مُخَالِفًا لِدِينِهَا، أَوْ عَاضِلاً لَهَا، أَوْ غَائِبًا غَيْبَةً بَعِيدَةً."]]},{"id":"um95_4","label":"بَابُ وِلَايَةِ النِّكَاحِ · ٤","segs":[["matn","وَلَا وِلَايَةَ لِأَحَدٍ عَلَى مُخَالِفٍ لِدِينِهِ إِلَّا الْمُسْلِمُ إِذَا كَانَ سُلْطَانًا، أَوْ سَيِّدَ أَمَةٍ."]]},{"id":"um95_5","label":"بَابُ وِلَايَةِ النِّكَاحِ · ٥","segs":[["matn","فَصْلٌ: وَلِلأَبِ تَزْوِيجُ أَوْلَادِهِ الصِّغَارِ، ذُكُورِهِمْ وَإِنَاثِهِمْ، وَبَنَاتِهِ الأَبْكَارِ بِغَيْرِ إِذْنِهِمْ، وَيُسْتَحَبُّ اسْتِئْذَانُ البَالِغَةِ، وَلَيْسَ لَهُ تَزْوِيجُ البَالِغِ مِنْ بَنِيهِ وَبَنَاتِهِ الثُّيَّبِ إِلَّا بِإِذْنِهِمْ، وَلَيْسَ لِسَائِرِ الأَوْلِيَاءِ تَزْوِيجُ صَغِيرٍ وَلَا صَغِيرَةٍ، وَلَا تَزْوِيجُ كَبِيرَةٍ إِلَّا بِإِذْنِهَا."]]},{"id":"um95_6","label":"بَابُ وِلَايَةِ النِّكَاحِ · ٦","segs":[["matn","وَإِذْنُ الثَّيِّبِ الكَلَامُ، وَإِذْنُ البِكْرِ الصُّمَاتُ؛ لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «الأيِّمُ أَحَقُّ بِنَفْسِهَا مِنْ وَلِيِّهَا، وَالْبِكْرُ تُسْتَأْذَنُ فِي نَفْسِهَا، وَإِذْنُهَا صُمَاتُهَا»."]]},{"id":"um95_7","label":"بَابُ وِلَايَةِ النِّكَاحِ · ٧","segs":[["matn","وَلَيْسَ لِوَلِيِّ امْرَأَةٍ تَزْوِيجُهَا بِغَيْرِ كُفْئِهَا وَالعَرَبُ بَعْضُهُمْ لِبَعْضٍ أَكْفَاءٌ، وَلَيْسَ العَبْدُ كُفْئًا لِحُرَّةٍ، وَلَا الْفَاجِرُ كُفْئًا لِعَفِيفَةٍ."]]},{"id":"um95_8","label":"بَابُ وِلَايَةِ النِّكَاحِ · ٨","segs":[["matn","وَمَنْ أَرَادَ أَنْ يَنْكِحَ امْرَأَةً هُوَ وَلِيُّهَا، فَلَهُ أَنْ يَتَزَوَّجَهَا مِنْ نَفْسِهِ بِإِذْنِهَا، وَإِنْ زَوَّجَ أَمَتَهُ عَبْدَهُ الصَّغِيرَ، جَازَ أَنْ يَتَوَلَّى طَرْفَيْ العَقْدِ، وَإِنْ قَالَ لِأَمَتِهِ: أَعْتَقْتُكَ وَجَعَلْتُ عِتْقَكَ صَدَاقَكَ بِحَضْرَةِ شَاهِدَيْنِ، ثَبَتَ العِتْقُ وَالنِّكَاحُ؛"]]},{"id":"um95_9","label":"بَابُ وِلَايَةِ النِّكَاحِ · ٩","segs":[["matn","لِأَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَعْتَقَ صَفِيَّةَ وَجَعَلَ عِتْقَهَا صَدَاقَهَا."]]},{"id":"um95_10","label":"بَابُ وِلَايَةِ النِّكَاحِ · ١٠","segs":[["matn","فَصْلٌ: وَلِلسَّيِّدِ تَزْوِيجُ إِمَائِهِ كُلِّهِنَّ، وَعَبِيدِهِ الصِّغَارِ بِغَيْرِ إِذْنِهِمْ وَلَهُ تَزْوِيجُ أَمَةِ مُوَلِّيَتِهِ بِإِذْنِ سَيِّدَتِهَا، وَلَا يَمْلِكُ إِجْبَارَ عَبْدِهِ الكَبِيرِ عَلَى النِّكَاحِ."]]},{"id":"um95_11","label":"بَابُ وِلَايَةِ النِّكَاحِ · ١١","segs":[["matn","وَأَيُّمَا عَبْدٍ تَزَوَّجَ بِغَيْرِ إِذْنِ مَوَالِيهِ فَهُوَ عَاهِرٌ، فَإِنْ دَخَلَ بِهَا فَمَهْرُهَا فِي رَقَبَتِهِ، كَجِنَايَتِهِ، إِلَّا أَنْ يَفْدِيَهُ السَّيِّدُ بِأَقَلَّ مِنْ قِيمَتِهِ أَوِ الْمَهْرِ."]]},{"id":"um95_12","label":"بَابُ وِلَايَةِ النِّكَاحِ · ١٢","segs":[["matn","وَمَنْ نَكَحَ أَمَةً عَلَى أَنَّهَا حُرَّةً ثُمَّ عَلِمَ فَلَهُ فَسْخُ النِّكَاحِ وَلَا مَهْرَ عَلَيْهِ إِنْ فَسَخَ قَبْلَ الدِّخُولِ، وَإِنْ أَصَابَهَا، فَلَهَا مَهْرُهَا، وَإِنْ أَوْلَدَهَا، فَوَلَدُهُ حُرٌّ يَفْدِيهِ بِقِيمَتِهِ،"]]},{"id":"um95_13","label":"بَابُ وِلَايَةِ النِّكَاحِ · ١٣","segs":[["matn","وَيَرْجِعُ بِمَا غَرِمَ عَلَى مَنْ غَرَّهُ، وَيُفَرَّقُ بَيْنَهُمَا، إِنْ لَمْ يَكُنْ مِمَّنْ يَجُوزُ لَهُ نِكَاحُ الإِمَاءِ، فَإِنْ كَانَ مِمَّنْ يَجُوزُ لَهُ ذَلِكَ فَرَضِيَ فَمَا وَلَدَتْ بَعْدَ الرِّضَا، فَهُوَ رَقِيقٌ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"um96","title":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ","units":[{"id":"um96_1","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ١","segs":[["matn","وَهُنَّ الأُمُّهَاتُ، وَالبَنَاتُ، وَالأَخَوَاتُ، وَبَنَاتُ الإِخْوَةِ، وَبَنَاتُ الأَخَوَاتِ، وَالعَمَّاتُ، وَالخَالَاتُ، وَأُمُّهَاتُ النِّسَاءِ، وَحَلَائِلُ الآبَاءِ، وَالْأَبْنَاءِ، وَالرَّبَائِبُ الْمَدْخُولُ بِأُمَّهَاتِهِنَّ."]]},{"id":"um96_2","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ٢","segs":[["matn","وَيَحْرُمُ مِنَ الرَّضَاعِ مَا يَحْرُمُ مِنَ النَّسَبِ، وَبَنَاتُ الْمُحَرَّمَاتُ مُحَرَّمَاتٌ، إِلَّا بَنَاتِ العَمَّاتِ وَالخَالَاتِ."]]},{"id":"um96_3","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ٣","segs":[["matn","وَأُمَّهَاتِ النِّسَاءِ، وَحَلَائِلِ الآبَاءِ وَالأَبْنَاءِ، وَأُمُّهَاتُهُنَّ مُحَرَّمَاتٌ، إلَّا البَنَاتِ وَالرَّبَائِبَ، وَحَلَائِلَ الآبَاءِ وَالأَبْنَاءِ، وَمَنْ وَطِئَ امْرَأَةً حَلَالاً أَوْ حَرَامًا حَرُمَتْ عَلَى أَبِيهِ وَابْنِهِ، وَحَرُمَتْ عَلَيْهِ أُمُّهَاتُهَا وَبَنَاتُهَا."]]},{"id":"um96_4","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ٤","segs":[["matn","فَصْلٌ: وَيَحْرُمُ الجَمْعُ بَيْنَ الأُخْتَيْنِ، وَبَيْنَ المَرْأَةِ وَعَمَّتِهَا وَخَالَتِهَا؛ لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «لَا يُجْمَعُ بَيْنَ المَرْأَةِ وَعَمَّتِهَا، وَلَا بَيْنَهَا وَبَيْنَ خَالَتِهَا»."]]},{"id":"um96_5","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ٥","segs":[["matn","وَلَا يَجُوزُ لِلْحُرِّ أَنْ يَجْمَعَ بَيْنَ أَكْثَرَ مِنْ أَرْبَعِ نِسْوَةٍ، وَلَا لِلْعَبْدِ أَنْ يَجْمَعَ إِلَّا اثْنَتَيْنِ، فَإِنْ جَمَعَ بَيْنَ مَنْ لَا يَجُوزُ الجَمْعُ بَيْنَهُ فِي عَقْدٍ وَاحِدٍ، فَسَدَ، الْعَقْدُ وَإِنْ كَانَ فِي عَقْدَيْنِ لَمْ يَصِحَّ الثَّانِي مِنْهُمَا."]]},{"id":"um96_6","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ٦","segs":[["matn","وَلَوْ أَسْلَمَ كَافِرٌ وَتَحْتَهُ أُخْتَانِ، اخْتَارَ مِنْهُمَا وَاحِدَةً، وَإِنْ كَانَتَا أُمًّا وَبِنْتًا وَلَمْ يَدْخُلْ بِالأُمِّ فَسَدَ نِكَاحُهَا وَحْدَهَا، وَإِنْ كَانَ قَدْ دَخَلَ بِهَا، فَسَدَ نِكَاحُهُمَا وَحُرِّمَتَا عَلَى التَّأْبِيدِ،"]]},{"id":"um96_7","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ٧","segs":[["matn","وَإِنْ أَسْلَمَ وَتَحْتَهُ أَكْثَرُ مِنْ أَرْبَعٍ، نِسْوَةٍ أَمْسَكَ مِنْهُنَّ أَرْبَعًا وَفَارَقَ سَائِرَهُنَّ، سَوَاءٌ كَانَ مَنْ أَمْسَكَ مِنْهُنَّ أَوَّلَ مَنْ عَقَدَ عَلَيْهَا أَوْ آخِرَهُنَّ، وَكَذَلِكَ الْعَبْدُ فَإِذَا أَسْلَمَ وَتَحْتَهُ أَكْثَرُ مِنِ اثْنَتَيْنِ."]]},{"id":"um96_8","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ٨","segs":[["matn","وَمَنْ طَلَّقَ امْرَأَةً فَنَكَحَ أُخْتَهَا أَوْ خَالَتَهَا أَوْ خَامِسَةً فِي عِدَّتِهَا، لَمْ يَصِحَّ، سَوَاءٌ كَانَ الطَّلَاقُ رَجْعِيًّا أَوْ بَائِنًا."]]},{"id":"um96_9","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ٩","segs":[["matn","وَيَجُوزُ أَنْ يَمْلِكَ أُخْتَيْنِ، وَلَهُ وَطْءُ إِحْدَاهُمَا، فَمَتَى وَطِئَهَا، حَرُمَتْ عَلَيْهِ أُخْتُهَا حَتَّى تَحْرُمَ المَوْطُوءَةُ بِتَزْوِيجٍ أَوْ إِخْرَاجٍ عَنْ مِلْكِهِ وَيَعْلَمُ أَنَّهَا غَيْرُ حَامِلٍ،"]]},{"id":"um96_10","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ١٠","segs":[["matn","فَإِذَا وَطِئَ الثَّانِيَةَ ثُمَّ عَادَتِ الأُولَى إِلَى مِلْكِهِ، لَمْ تَحِلَّ لَهُ حَتَّى تَحْرُمَ الْأُخْرَى وَعَمَّةُ الأَمَةِ وَخَالَتُهَا فِي هَذَا كَأُخْتِهَا."]]},{"id":"um96_11","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ١١","segs":[["matn","وَلَيْسَ لِلْمُسْلِمِ وَإِنْ كَانَ عَبْدًا نِكَاحُ أَمَةٍ كَافِرَةٍ، وَلَا لِحُرٍّ نِكَاحُ أَمَةٍ مُسْلِمَةٍ إِلَّا أَنْ لَا يَجِدَ طَوْلَ حُرَّةٍ، وَلَا ثَمَنَ أَمَةٍ، وَيَخَافُ العَنَتَ، وَلَهُ نِكَاحُ أَرْبَعٍ إِذَا كَانَ الشَّرْطَانِ فِيهِ قَائِمَيْنِ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"um97","title":"كِتَابُ الرَّضَاعِ","units":[{"id":"um97_1","label":"كِتَابُ الرَّضَاعِ · ١","segs":[["matn","حُكْمُ الرَّضَاعِ حُكْمُ النَّسَبِ فِي التَّحْرِيمِ وَالْمَحْرَمِيَّةِ، فَمَتَى أَرْضَعَتِ الْمَرْأَةُ طِفْلاً، صَارَ ابْنَا لَهَا، وَلِلرَّجُلِ الَّذِي ثَابَ اللَّبَنُ بِوَطْئِهِ، فَيَحْرُمُ عَلَيْهِ كُلُّ مَنْ يَحْرُمُ عَلَى ابْنِهَا مِنَ النَّسَبِ، وَإِنْ أَرْضَعَتْ طِفْلَةً،"]]},{"id":"um97_2","label":"كِتَابُ الرَّضَاعِ · ٢","segs":[["matn","صَارَتْ بِنْتًا لَهُمَا تَحْرُمُ عَلَى كُلِّ مَنْ تَحْرُمُ عَلَيْهِ ابْنَتُهُمَا مِنَ النَّسَبِ لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ:"]]},{"id":"um97_3","label":"كِتَابُ الرَّضَاعِ · ٣","segs":[["matn","«يَحْرُمُ مِنَ الرَّضَاعَةِ مَا يَحْرُمُ مِنَ النَّسَبِ،» وَالْمُحَرِّمُ مِنَ الرَّضَاعِ مَا دَخَلَ الحَلْقَ مِنَ اللَّبَنِ، سَوَاءٌ دَخَلَ بِارْتِضَاعٍ مِنَ الثَّدْيِ، أَوْ وَجُورٍ، أَوْ سَعُوطٍ، مَحْضًا كَانَ، أَوْ مَشُوبًا إِذَا لَمْ يُسْتَهْلَكْ."]]},{"id":"um97_4","label":"كِتَابُ الرَّضَاعِ · ٤","segs":[["matn","وَلَا يَحْرُمُ إِلَّا بِشُرُوطٍ ثَلَاثَةٍ: أَحَدُهَا: أَنْ يَكُونَ لَبَنُ امْرَأَةٍ، بَكْرًا كَانَتْ أَوْ ثَيِّباً، فِي حَيَاتِهَا أَوْ بَعْدَ مَوْتِهَا، فَأَمَّا لَبَنُ البَهِيمَةِ أَوِ الرَّجُلِ أَوِ الخُنْثَى المُشْكِلِ، فَلَا يُحَرِّمُ شَيْئاً."]]},{"id":"um97_5","label":"كِتَابُ الرَّضَاعِ · ٥","segs":[["matn","الثَّانِي: أَنْ يَكُونَ فِي الْحَوْلَيْنِ؛ لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «لَا يُحَرِّمُ مِنَ الرَّضَاعِ إِلَّا مَا فَتَقَ الأَمْعَاءَ وَكَانَ قَبْلَ الفِطَامِ»."]]},{"id":"um97_6","label":"كِتَابُ الرَّضَاعِ · ٦","segs":[["matn","الثَّالِثُ: أَنْ يَرْتَضِعَ خَمْسَ رَضَعَاتٍ؛ لِقَوْلِ عَائِشَةِ أُنْزِلَ فِي القُرْآنِ عَشْرُ رَضَعَاتٍ يُحَرِّمْنَ، فَنُسِخَ مِنْ ذَلِكَ خَمْسٌ فَصَارَ إِلَى خَمْسِ رَضَعَاتٍ مَعْلُومَاتٍ يُحَرِّمْنَ، فَتُوُفِّيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَالأَمْرُ عَلَى ذَلِكَ."]]},{"id":"um97_7","label":"كِتَابُ الرَّضَاعِ · ٧","segs":[["matn","وَلَبَنُ الفَحْلِ مُحَرِّمٌ، فَإِذَا كَانَ لِرَجُلٍ امْرَأَتَانِ فَأَرْضَعَتْ إِحْدَاهُمَا بِلَبَنِهِ طِفْلاً وَالْأُخْرَى طِفْلَةً صَارَا أَخَوَيْنِ لِأَنَّ اللِّقَاحَ وَاحِدٌ،"]]},{"id":"um97_8","label":"كِتَابُ الرَّضَاعِ · ٨","segs":[["matn","وَإِنْ أَرْضَعَتْ إِحْدَاهُمَا بِلَبَنِهِ طِفْلَةً ثَلَاثَ رَضَعَاتٍ، ثُمَّ أَرْضَعَتْهَا الْأُخْرَى رَضْعَتَيْنِ صَارَتْ بِنْتًا لَهُ دُونَهُمَا فَلَوْ كَانَتِ الطِّفْلَةُ زَوْجَةً لَهُ انْفَسَخَ نِكَاحُهَا، وَلَزِمَهُ نِصْفُ مَهْرِهَا،"]]},{"id":"um97_9","label":"كِتَابُ الرَّضَاعِ · ٩","segs":[["matn","وَيَرْجِعُ بِهِ عَلَيْهِمَا أَخْمَاسًا وَلَمْ يَنْفَسِخْ نِكَاحُهُمَا وَلَوْ أَرْضَعَتْ إِحْدَى امْرَأَتَيْهِ الطِّفْلَةَ خَمْسَ رَضَعَاتٍ، ثَلَاثاً مِنْ لَبَنِهِ، وَاثْنَتَيْنِ مِنْ لَبَنِ غَيْرِهِ،"]]},{"id":"um97_10","label":"كِتَابُ الرَّضَاعِ · ١٠","segs":[["matn","صَارَتْ أُمًّا لَهَا وَحَرُمَتَا عَلَيْهِ، وَحَرُمَتِ الطِّفْلَةُ عَلَى الرَّجُلِ الآخَرِ عَلَى التَّأْبِيدِ، وَإِنْ لَمْ تَكُنِ الطِّفْلَةُ امْرَأَةً لَهُ، لَمْ يَنْفَسِخْ نِكَاحُ الْمُرْضِعَةِ."]]},{"id":"um97_11","label":"كِتَابُ الرَّضَاعِ · ١١","segs":[["matn","وَلَوْ تَزَوَّجَتِ الْمَرْأَةُ طِفْلاً، فَأَرْضَعَتْهُ خَمْسَ رَضَعَاتٍ، حَرُمَتْ عَلَيْهِ، وَانْفَسَخَ نِكَاحُهَا، وَحَرُمَتْ عَلَى صَاحِبِ اللَّبَنِ تَحْرِيمًا مُؤَبَّدًا؛ لِأَنَّهَا صَارَتْ مِنْ حَلَائِلِ أَبْنَائِهِ."]]},{"id":"um97_12","label":"كِتَابُ الرَّضَاعِ · ١٢","segs":[["matn","فَصْلٌ: وَلَوْ تَزَوَّجَ رَجُلٌ كَبِيرَةً وَلَمْ يَدْخُلْ بِهَا، وَصَغِيرَةً، فَأَرْضَعَتِ الكَبِيرَةُ الصَّغِيرَةَ، حَرُمَتِ الكَبِيرَةُ، وَثَبَتَ نِكَاحُ الصّغِيرَةِ."]]},{"id":"um97_13","label":"كِتَابُ الرَّضَاعِ · ١٣","segs":[["matn","وَإِنْ كَانَتَا صَغِيرَتَيْنِ، فَأَرْضَعَتْهُمَا الْكُبْرَى حَرُمَتِ الْكُبْرَى وَانْفَسَخَ نِكَاحُ الصَّغِيرَتَيْنِ، وَلَهُ نِكَاحُ مَنْ شَاءَ مِنَ الصَّغِيرَتَيْنِ، وَإِنْ كُنَّ ثَلَاثاً فَأَرْضَعَتْهُنَّ مُتَفَرِّقَاتٍ حَرُمَتِ الْكُبْرَى وَانْفَسَخَ نِكَاحُ الْمُرْضَعَتَيْنِ أَوَّلاً، وَثَبَتَ نِكَاحُ الثَّالِثَةِ، وَإِنْ أَرْضَعَتْ إِحْدَاهُنَّ مُنْفَرِدَةً وَاثْنَتَيْنِ بَعْدَهَا مَعًا، انْفَسَخَ نِكَاحُ الثَّلَاثِ،"]]},{"id":"um97_14","label":"كِتَابُ الرَّضَاعِ · ١٤","segs":[["matn","وَلَهُ نِكَاحُ مَنْ شَاءَ مِنْهُنَّ مُنْفَرِدَةً، وَإِنْ كَانَ دَخَلَ بِالْكُبْرَى حَرُمَ- الْكُلُّ عَلَيْهِ عَلَى الْأَبَدِ، وَلَا مَهْرَ لِلْكُبْرَى إِنْ كَانَ لَمْ يَدْخُلْ بِهَا، وَإِنْ كَانَ قَدْ دَخَلَ بِهَا، فَلَهَا مَهْرُهَا، وَعَلَيْهِ نِصْفُ مَهْرِ الأَصَاغِرِ، يَرْجِعُ بِهِ عَلَى الْكُبْرَى."]]},{"id":"um97_15","label":"كِتَابُ الرَّضَاعِ · ١٥","segs":[["matn","وَلَوْ دَبَّتِ الصُّغْرَى عَلَى الْكُبْرَى وَهِيَ نَائِمَةٌ، فَارْتَضَعَتْ مِنْهَا خَمْسَ رَضَعَاتٍ، حَرَّمَتْهَا عَلَى الزَّوْجِ، وَلَهَا نِصْفُ مَهْرِهَا يَرْجِعُ بِهِ عَلَى الصُّغْرَى إِنْ كَانَ قَبْلَ الدُّخُولِ، وَإِنْ كَانَ بَعْدَهُ، فَلَهَا مَهْرُهَا كُلُّهُ، لَا يَرْجِعُ بِهِ عَلَى أَحَدٍ، وَلَا مَهْرَ لِلصُّغْرَى."]]},{"id":"um97_16","label":"كِتَابُ الرَّضَاعِ · ١٦","segs":[["matn","وَلَوْ نَكَحَ امْرَأَةً، ثُمَّ قَالَ: هِيَ أُخْتِي مِنَ الرَّضَاعِ، انْفَسَخَ نِكَاحُهَا وَلَهَا الْمَهْرُ إِنْ كَانَ دَخَلَ بِهَا، وَنِصْفُ الْمَهْرِ إِنْ كَانَ لَمْ يَدْخُلْ بِهَا وَلَمْ تُصَدِّقْهُ،"]]},{"id":"um97_17","label":"كِتَابُ الرَّضَاعِ · ١٧","segs":[["matn","وَإِنْ صَدَّقَتْهُ قَبْلَ الدُّخُولِ فَلَا شَيْءَ لَهَا، وَإِنْ كَانَتْ هِيَ الَّتِي قَالَتْ: هُوَ أَخِي مِنَ الرَّضَاعِ، فَأَكْذَبَهَا وَلَا بَيِّنَةَ لَهَا، فَهِيَ امْرَأَتُهُ فِي الحُكْمِ."]]}],"group":"كِتَابُ الرَّضَاعِ"},{"id":"um98","title":"بَابُ نِكَاحِ الْكُفَّارِ","units":[{"id":"um98_1","label":"بَابُ نِكَاحِ الْكُفَّارِ · ١","segs":[["matn","لَا يَحِلُّ لِمُسْلِمَةٍ نِكَاحُ كَافِرٍ بِحَالٍ، وَلَا لِمُسْلِمٍ نِكَاحُ كَافِرَةٍ، إِلَّا الحُرَّةَ الكِتَابِيَّةَ."]]},{"id":"um98_2","label":"بَابُ نِكَاحِ الْكُفَّارِ · ٢","segs":[["matn","وَمَتَى أَسْلَمَ زَوْجُ الْكِتَابِيَّةِ، أَوْ أَسْلَمَ الزَّوْجَانِ الكَافِرَانِ مَعًا، فَهُمَا عَلَى نِكَاحِهِمَا، وَإِنْ أَسْلَمَ أَحَدُهُمَا، غَيْرُ زَوْجِ الْكِتَابِيَّةِ، أَوِ ارْتَدَّ أَحَدُ الزَّوْجَيْنِ المُسْلِمَيْنِ،"]]},{"id":"um98_3","label":"بَابُ نِكَاحِ الْكُفَّارِ · ٣","segs":[["matn","قَبْلَ الدُّخُولِ انْفَسَخَ النِّكَاحُ فِي الْحَالِ، وَإِنْ كَانَ ذَلِكَ بَعْدَ الدُّخُولِ، فَأَسْلَمَ الكَافِرُ مِنْهُمَا فِي عِدَّتِهَا، فَهُمَا عَلَى نِكَاحِهِمَا، وَإِلَّا تَبَيَّنَا أَنَّ النِّكَاحَ انْفَسَخَ مُنْذُ اخْتَلَفَ دِينُهُمُا."]]},{"id":"um98_4","label":"بَابُ نِكَاحِ الْكُفَّارِ · ٤","segs":[["matn","وَمَا سُمِّيَ لَهَا وَهُمَا كَافِرَانِ فَقَبَضَتْهُ فِي كُفْرِهِمَا فَلَا شَيْءَ لَهَا غَيْرَهُ، وَإِنْ كَانَ حَرَامًا، وَإِنْ لَمْ تَقْبِضْهُ وَهُوَ حَرَامٌ، فَلَهَا مَهْرُ مِثْلِهَا، أَوْ نِصْفُهُ حَيْثُ وَجَبَ ذَلِكَ."]]},{"id":"um98_5","label":"بَابُ نِكَاحِ الْكُفَّارِ · ٥","segs":[["matn","فَصْلٌ: وَإِنْ أَسْلَمَ الحُرُّ وَتَحْتَهُ إِمَاءُ فَأَسْلَمْنَ مَعَهُ، وَكَانَ فِي حَالِ اجْتِمَاعِهِمْ عَلَى الإِسْلَامِ مِمَّنْ لَا يَحِلُّ لَهُ نِكَاحُ الإِمَاءِ، انْفَسَخَ نِكَاحُهُنَّ، وَإِنْ كَانَ مِمَّنْ يَحِلُّ لَهُ نِكَاحُهُنَّ، أَمْسَكَ مِنْهُنَّ مَنْ تَعُفُّهُ، وَفَارَقَ سَائِرَهُنَّ."]]}],"group":"كِتَابُ الرَّضَاعِ"},{"id":"um99","title":"بَابُ الشُّرُوطِ فِي النِّكَاحِ","units":[{"id":"um99_1","label":"بَابُ الشُّرُوطِ فِي النِّكَاحِ · ١","segs":[["matn","إِذَا اشْتَرَطَتِ الْمَرْأَةُ دَارَهَا، أَوْ بَلَدَهَا، أَوْ أَنْ لَا يَتَزَوَّجَ عَلَيْهَا، أَوْ لَا يَتَسَرَّى، فَلَهَا شَرْطُهَا، وَإِنْ لَمْ يَفِ بِهِ فَلَهَا فَسْخُ النِّكَاحِ؛ لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «إِنَّ أَحَقَّ الشُّرُوطِ أَنْ تُوَفُّوا بِهَا مَا اسْتَحْلَلْتُمْ بِهِ الفُرُوجَ»."]]},{"id":"um99_2","label":"بَابُ الشُّرُوطِ فِي النِّكَاحِ · ٢","segs":[["matn","وَنَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ نِكَاحِ الْمُتْعَةِ، وَهُوَ أَنْ يَتَزَوَّجَهَا إِلَى أَجَلٍ وَإِنْ شَرَطَ يُطَلِّقَهَا فِي وَقْتٍ بِعَيْنِهِ، لَمْ يَصِحَّ كَذَلِكَ وَنَهَى عَنِ الشِّغَارِ،"]]},{"id":"um99_3","label":"بَابُ الشُّرُوطِ فِي النِّكَاحِ · ٣","segs":[["matn","وَهُوَ أَنْ يُزَوِّجَ الرَّجُلُ ابْنَتَهُ عَلَى أَنْ يُزَوِّجَهُ الْآخَرُ ابْنَتَهُ وَلَا صَدَاقَ بَيْنَهُمَا، وَلَعَنَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمُحَلِّلَ وَالْمُحَلَّلَ لَهُ، وَهُوَ أَنْ يَتَزَوَّجَ الْمُطَلَّقَةَ ثَلَاثاً؛ لِيُحِلَّهَا لِمُطَلِّقِهَا."]]}],"group":"كِتَابُ الرَّضَاعِ"},{"id":"um100","title":"بَابُ العُيُوبِ الَّتِي يُفْسَخُ بِهَا النِّكَاحُ","units":[{"id":"um100_1","label":"بَابُ العُيُوبِ الَّتِي يُفْسَخُ بِهَا النِّكَاحُ · ١","segs":[["matn","مَتَى وَجَدَ أَحَدُ الزَّوْجَيْنِ الآخَرَ مَمْلُوكاً، أَوْ مَجْنُوناً، أَوْ أَبْرَصَ، أَوْ مَجْذُومًا، أَوْ وَجَدَ الرَّجُلُ الْمَرْأَةَ رَتْقَاءَ، أَوْ وَجَدَتْهُ مَجْبُوباً، فَلَهُ فَسْخُ النِّكَاحِ، إِنْ لَمْ يَكُنْ عَلِمَ ذَلِكَ، قَبْلَ الْعَقْدِ وَلَا يَجُوزُ الفَسْخُ إِلَّا بِحُكْمِ حَاكِمٍ."]]},{"id":"um100_2","label":"بَابُ العُيُوبِ الَّتِي يُفْسَخُ بِهَا النِّكَاحُ · ٢","segs":[["matn","وَإِنْ ادَّعَتِ الْمَرْأَةُ أَنْ زَوْجَهَا عِنِّينٌ لَا يَصِلُ إِلَيْهَا، فَاعْتَرَفَ أَنَّهُ لَمْ يُصِبْهَا أُجِّلَ سَنَةً مُنْذُ تُرَافِعُهُ، فَإِنْ لَمْ يُصِبْهَا، خُيِّرَتْ فِي الْمَقَامِ مَعَهُ أَوْ فِرَاقِهِ،"]]},{"id":"um100_3","label":"بَابُ العُيُوبِ الَّتِي يُفْسَخُ بِهَا النِّكَاحُ · ٣","segs":[["matn","فَإِنْ اخْتَارَتْ فِرَاقَهَ، فَرَّقَ الحَاكِمُ بَيْنَهُمَا، إِلَّا أَنْ تَكُونَ قَدْ عَلِمَتْ عُنَّتَهُ قَبْلَ نِكَاحِهَا، أَوْ قَالَتْ: رَضِيتُ بِهِ عِنِّينًا فِي وَقْتٍ،"]]},{"id":"um100_4","label":"بَابُ العُيُوبِ الَّتِي يُفْسَخُ بِهَا النِّكَاحُ · ٤","segs":[["matn","وَإِنْ عَلِمَتْ بَعْدَ العَقْدِ وَسَكَتَتْ عَنِ الْمُطَالَبَةِ، لَمْ يَسْقُطْ حَقُّهَا، وَإِنْ قَالَ: قَدْ عَلِمَتْ عُنَّتِي وَرَضِيَتْ بِي بَعْدَ عِلْمِهَا، فَأَنْكَرَتْهُ فَالقَوْلُ قَوْلُهَا، وَإِنْ أَصَابَهَا مَرَّةً،"]]},{"id":"um100_5","label":"بَابُ العُيُوبِ الَّتِي يُفْسَخُ بِهَا النِّكَاحُ · ٥","segs":[["matn","لَمْ يَكُنْ عِنَّيْنًا، وَإِنِ ادَّعَى ذَلِكَ فَأَنْكَرَتْهُ، فَإِنْ كَانَتْ عَذْرَاءَ، أُرِيَتِ النِّسَاءَ الثِّقَاتِ وَرُجِعَ إِلَى قَوْلِهِنَّ، فَإِنْ كَانَتْ ثَيِّباً، فَالقَوْلُ قَوْلُهُ مَعَ يَمِينِهِ."]]},{"id":"um100_6","label":"بَابُ العُيُوبِ الَّتِي يُفْسَخُ بِهَا النِّكَاحُ · ٦","segs":[["matn","فَصْلٌ: وَإِنْ عَتَقَتِ الْمَرْأَةُ وَزَوْجُهَا عَبْدٌ، خُيِّرَتْ فِي الْمُقَامِ مَعَهُ أَوْ فِرَاقِهِ وَلَهَا فِرَاقُهُ مِنْ غَيْرِ حُكْمِ حَاكِمٍ، فَإِنْ أُعْتِقَ قَبْلَ اخْتِيَارِهَا أَوْ وَطْئِهَا بَطَلَ خِيَارُهَا، وَإِنْ أُعْتِقَ بَعْضُهَا، أَوْ عَتَقَتْ كُلُّهَا وَزَوْجُهَا حُرٌّ، فَلَا خِيَارَ لَهَا."]]}],"group":"كِتَابُ الرَّضَاعِ"},{"id":"um101","title":"كِتَابُ الصَّدَاقِ","units":[{"id":"um101_1","label":"كِتَابُ الصَّدَاقِ · ١","segs":[["matn","وَكُلُّ مَا جَازَ أَنْ يَكُونَ ثَمَناً، جَازَ أَنْ يَكُونَ صَدَاقاً، قَلِيلاً كَانَ أَوْ كَثِيرًا، لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِلَّذِي قَالَ لَهُ:"]]},{"id":"um101_2","label":"كِتَابُ الصَّدَاقِ · ٢","segs":[["matn","زَوِّجْنِي هَذِهِ الْمَرْأَةَ إِنْ لَمْ يَكُنْ لَكَ بِهَا حَاجَةٌ، قَالَ: «التَمِسْ وَلَوْ خَاتَمًا مِنْ حَدِيدٍ،» فَإِذَا زَوَّجَ الرَّجُلُ ابْنَتَهُ بِأَيِّ صَدَاقٍ جَازَ، وَلَا يَنْقُصُهَا غَيْرَ الأَبِ مِنْ مَهْرِ مِثْلِهَا إِلَّا بِرِضَاهَا،"]]},{"id":"um101_3","label":"كِتَابُ الصَّدَاقِ · ٣","segs":[["matn","فَإِذَا أَصْدَقَهَا عَبْدًا بِعَيْنِهِ فَوَجَدَتْهُ مَعِيبًا، خُيِّرَتْ بَيْنَ أَرْشِهِ وَرَدِّهِ أَوْ أَخْذِ قِيمَتِهِ، وَإِنْ وَجَدَتْهُ مَغْصُوبًا أَوْ حُرًّا، فَلَهَا قِيمَتُهُ، وَإِنْ كَانَتْ عَالِمَةً بِحُرِّيَّتِهِ أَوْ غَصْبِهِ حِينَ العَقْدِ،"]]},{"id":"um101_4","label":"كِتَابُ الصَّدَاقِ · ٤","segs":[["matn","فَلَهَا مَهْرُ مِثْلِهَا، وَإِنْ تَزَوَّجَهَا عَلَى أَنْ يَشْتَرِيَ لَهَا عَبْدًا بِعَيْنِهِ، فَلَمْ يَبِعْهُ سَيِّدُهُ أَوْ طَلَبَ بِهِ أَكْثَرَ مِنْ قِيمَتِهِ، فَلَهَا قِيمَتُهُ."]]},{"id":"um101_5","label":"كِتَابُ الصَّدَاقِ · ٥","segs":[["matn","فَصْلٌ: فَإِنْ تَزَوَّجَهَا بِغَيْرِ صَدَاقٍ، صَحَّ، فَإِنْ طَلَّقَهَا قَبْلَ الدُّخُولِ، لَمْ يَكُنْ لَهَا إِلَّا الْمُتْعَةَ، عَلَى الْمُوسِعِ قَدَرُهُ وَعَلَى الْمُقْتِرِ قَدَرُهُ، وَأَعْلَاهَا خَادِمٌ، وَأَدْنَاهَا كِسْوَةٌ تَجُوزُ لَهَا الصَّلَاةُ فِيهَا."]]},{"id":"um101_6","label":"كِتَابُ الصَّدَاقِ · ٦","segs":[["matn","وَإِنْ مَاتَ أَحَدُهُمَا قَبْلَ الدُّخُولِ وَالفَرْضِ، فَلَهَا مَهْرُ نِسَائِهَا، لَا وَكْسَ وَلَا شَطَطَ، وَلِلْبَاقِي مِنْهُمَا الْمِيرَاثُ، وَعَلَيْهَا الْعِدَّةُ لِأَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَضَى فِي بَرْوَعَ بِنْتِ وَاشِقٍ،"]]},{"id":"um101_7","label":"كِتَابُ الصَّدَاقِ · ٧","segs":[["matn","لَمَّا مَاتَ زَوْجُهَا، وَلَمْ يَدْخُلْ بِهَا وَلَمْ يَفْرِضْ لَهَا: أَنَّ لَهَا مَهْرَ نِسَائِهَا، لَا وَكْسَ وَلَا شَطَطَ، وَلَهَا الْمِيرَاثُ، وَعَلَيْهَا العِدَّةُ."]]},{"id":"um101_8","label":"كِتَابُ الصَّدَاقِ · ٨","segs":[["matn","وَلَوْ طَالَبَتْهُ قَبْلَ الدُّخُولِ أَنْ يَفْرِضَ لَهَا، فَلَهَا ذَلِكَ، فَإِنْ فَرَضَ لَهَا مَهْرَ نِسَائِهَا أَوْ أَكْثَرَ، فَلَيْسَ لَهَا غَيْرُهُ، وَكَذَلِكَ إِنْ فَرَضَ لَهَا أَقَلَّ مِنْهُ فَرَضِيَتْ."]]},{"id":"um101_9","label":"كِتَابُ الصَّدَاقِ · ٩","segs":[["matn","وَكُلُّ فُرْقَةٍ جَاءَتْ مِنَ الْمَرْأَةِ، قَبْلَ الدُّخُولِ، كَإِسْلَامِهَا، أَوِ ارْتِدَادِهَا، أَوْ رَضَاعِهَا أَوْ ارْتِضَاعِهَا، أَوْ فَسْخٍ لِعَيْبِهَا أَوْ فَسْخٍ لِعَيْبِهِ، أَوْ إِعْسَارِهِ، أَوْ أَعْتَقَهَا يَسْقُطُ بِهِ مَهْرُهَا."]]},{"id":"um101_10","label":"كِتَابُ الصَّدَاقِ · ١٠","segs":[["matn","وَإِنْ جَاءَتْ مِنَ الزَّوْجِ، كَطَلَاقِهِ وَخُلْعِهِ، يَتَنَصَّفُ مَهْرُهَا بَيْنَهُمَا، إِلَّا أَنْ يَعْفُوَ لَهَا عَنْ نِصْفِهِ أَوْ تَعْفُوَ هِيَ عَنْ حَقِّهَا وَهِيَ رَشِيدَةٌ، فيُكْمَلُ الصَّدَاقُ لِلآخَرِ، وَإِنْ جَاءَتْ مِنْ أَجْنَبِيٍّ، فَعَلَى الزَّوْجِ نِصْفُ الْمَهْرِ، يَرْجِعُ بِهِ عَلَى مَنْ فَرَّقَ بَيْنَهُمَا."]]},{"id":"um101_11","label":"كِتَابُ الصَّدَاقِ · ١١","segs":[["matn","وَمَتَى تَنَصَّفَ الْمَهْرُ وَكَانَ مُعَيَّنًا بَاقِيًا لَمْ تَتَغَيَّرْ قِيمَتُهُ، صَارَ بَيْنَهُمَا نِصْفَيْنِ، وَإِنْ زَادَ زِيَادَةُ مُنْفَصِلَةً، كَغَنَمٍ وَلَدَتْ، فَالزِّيَادَةُ لَهَا وَالغَنَمُ بَيْنَهُمَا، وَإِنْ زَادَتْ زِيَادَةً مُتَّصِلَةً، مِثْلُ إِنْ سَمِنَتِ الغَنَمُ،"]]},{"id":"um101_12","label":"كِتَابُ الصَّدَاقِ · ١٢","segs":[["matn","خُيِّرَتْ بَيْنَ دَفْعِ نِصْفِهَا زَائِدًا وَبَيْنَ دَفْعِ نِصْفِ قِيمَتِهَا يَوْمَ الْعَقْدِ، وَإِنْ نَقَصَتْ، فَلَهَا الخِيَارُ بَيْنَ أَخْذِ نِصْفِهِ نَاقِصًا وَبَيْنَ أَخْذِ نِصْفِ قِيمَتِهِ يَوْمَ الْعَقْدِ، وَإِنْ تَلِفَتْ، فَلَهَا نِصْفُ قِيمَتِهَا يَوْمَ الْعَقْدِ."]]},{"id":"um101_13","label":"كِتَابُ الصَّدَاقِ · ١٣","segs":[["matn","وَمَتَى دَخَلَ بِهَا، اسْتَقَرَّ الْمَهْرُ وَلَمْ يَسْقُطْ بِشَيْءٍ، وَإِنْ خَلَا بِهَا بَعْدَ العَقْدِ، وَقَالَ لَمْ أَطَأْهَا، وَصَدَّقَتْهُ، اسْتَقَرَّ الْمَهْرُ وَوَجَبَتِ العِدَّةُ."]]},{"id":"um101_14","label":"كِتَابُ الصَّدَاقِ · ١٤","segs":[["matn","وَإِنِ اخْتَلَفَ الزَّوْجَانِ فِي الصَّدَاقِ أَوْ قَدْرِهِ، فَالقَوْلُ قَوْلُ مَنْ يَدَّعِي مَهْرَ المِثْلِ مَعَ يَمِينِهِ."]]}],"group":"كِتَابُ الصَّدَاقِ"},{"id":"um102","title":"بَابُ مُعَاشَرَةِ النِّسَاءِ","units":[{"id":"um102_1","label":"بَابُ مُعَاشَرَةِ النِّسَاءِ · ١","segs":[["matn","وَعَلَى كُلِّ وَاحِدٍ مِنَ الزَّوْجَيْنِ مَعَاشَرَةُ صَاحِبِهِ بِالْمَعْرُوفِ، وَأَدَاءُ حَقِّهِ الْوَاجِبِ إِلَيْهِ مِنْ غَيْرِ مَطْلٍ وَلَا إِظْهَارِ الْكَرَاهِيَةِ لِبَذْلِهِ."]]},{"id":"um102_2","label":"بَابُ مُعَاشَرَةِ النِّسَاءِ · ٢","segs":[["matn","وَحَقُّهُ عَلَيْهَا تَسْلِيمُ نَفْسِهَا إِلَيْهِ، وَطَاعَتُهُ فِي الِاسْتِمْتَاعِ مَتَى أَرَادَ مَا لَمْ يَكُنْ لَهَا عُذْرٌ، وَإِذَا فَعَلَتْ ذَلِكَ، فَلَهَا عَلَيْهِ قَدْرُ كِفَايَتِهَا مِنَ النَّفَقَةِ، وَالكِسْوَةِ وَالمَسْكَنِ، بِمَا جَرَتْ بِهِ عَادَةُ أَمْثَالِهَا،"]]},{"id":"um102_3","label":"بَابُ مُعَاشَرَةِ النِّسَاءِ · ٣","segs":[["matn","فَإِنْ مَنَعَهَا ذَلِكَ أَوْ بَعْضَهُ، وَقَدَرَتْ لَهُ عَلَى مَالٍ، أَخَذَتْ مِنْهُ قَدْرَ كِفَايَتِهَا وَكِفَايَةَ وَلَدِهَا بِالْمَعْرُوفِ، لِمَا رُوِيَ أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لِهِنْدٍ حِينَ قَالَتْ لَهُ:"]]},{"id":"um102_4","label":"بَابُ مُعَاشَرَةِ النِّسَاءِ · ٤","segs":[["matn","إِنَّ أَبًا سُفْيَانَ رَجُلٌ شَحِيحٌ وَلَيْسَ يُعْطِينِي مِنَ النَّفَقَةِ مَا يَكْفِينِي وَوَلَدِي، فَقَالَ: «خُذِي مَا يَكْفِيكِ وَوَلَدَكِ بِالْمَعْرُوفِ،» فَإِنْ لَمْ تَقْدِرْ عَلَى الأَخْذِ لِعُسْرَتِهِ، أَوْ مَنَعَهَا، فَاخْتَارَتْ فِرَاقَهُ، فَرَّقَ الحَاكِمُ بَيْنَهُمَا،"]]},{"id":"um102_5","label":"بَابُ مُعَاشَرَةِ النِّسَاءِ · ٥","segs":[["matn","سَوَاءٌ كَانَ الزَّوْجُ صَغِيرًا أَوْ كَبِيرًا وَإِنْ كَانَتْ صَغِيرَةً لَا يُمْكِنُ الِاسْتِمْتَاعُ بِهَا، أَوْ لَمْ تُسَلِّمْ إِلَيْهِ، أَوْ لَمْ تُطِعْهُ فِيمَا يَجِبُ لَهُ عَلَيْهَا، أَوْ سَافَرَتْ بِغَيْرِ إِذْنِهِ، أَوْ بِإِذْنِهِ فِي حَاجَتِهَا، فَلَا نَفَقَةَ لَهَا عَلَيْهِ."]]},{"id":"um102_6","label":"بَابُ مُعَاشَرَةِ النِّسَاءِ · ٦","segs":[["matn","فَصْلٌ: وَلَهَا عَلَيْهِ الْمَبِيتُ عِنْدَهَا لَيْلَةً مِنْ كُلِّ أَرْبَعٍ إِنْ كَانَتْ حُرَّةً، وَمِنْ كُلِّ ثَمَانٍ إِنْ كَانَتْ أَمَةً، إِذَا لَمْ يَكُنْ لَهُ عُذْرٌ، وَإِصَابَتُهَا مَرَّةً فِي كُلِّ أَرْبَعَةِ أَشْهُرٍ،"]]},{"id":"um102_7","label":"بَابُ مُعَاشَرَةِ النِّسَاءِ · ٧","segs":[["matn","إِذَا لَمْ يَكُنْ عُذْرٌ، فَإِنْ آلَى مِنْهَا أَكْثَرَ مِنْ أَرْبَعَةِ أَشْهُرٍ، فَتَرَبَّصَتْ أَرْبَعَةَ أَشْهُرٍ، ثُمَّ رَافَعَتْهُ إِلَى الحَاكِمِ، فَأَنْكَرَ الإِيلَاءَ، أَوْ مُضِيَّ الأَرْبَعَةِ أَوِ ادَّعَى أَنَّهُ أَصَابَهَا وَكَانَتْ ثَيِّباً،"]]},{"id":"um102_8","label":"بَابُ مُعَاشَرَةِ النِّسَاءِ · ٨","segs":[["matn","فَالْقَوْلُ قَوْلُهُ مَعَ يَمِينِهِ، وَإِنْ أَقَرَّ بِذَلِكَ، أُمِرَ بِالفَيْئَةِ، عِنْدَ طَلَبِهَا وَهِيَ الجِمَاعُ، فَإِنْ فَاءَ، فَإِنَّ اللهَ غَفُورٌ رَحِيمٌ، فَإِنْ لَمْ يَفِئْ، أُمِرَ بِالطَّلَاقِ، فَإِنْ طَلَّقَ، وَإِلَّا طَلَّقَ الحَاكِمُ عَلَيْهِ،"]]},{"id":"um102_9","label":"بَابُ مُعَاشَرَةِ النِّسَاءِ · ٩","segs":[["matn","ثُمَّ إِنْ رَاجَعَهَا، أَوْ تَرَكَهَا حَتَّى بَانَتْ، فَتَزَوَّجَهَا وَقَدْ بَقِيَ أَكْثَرُ مِنْ مُدَّةِ الإِيلَاءَ، وُقِفَ لَهَا كَمَا وَصَفَتْ، وَمَنْ عَجَزَ عَنِ الفَيْئَةِ عِنْدَ طَلَبِهَا، فَلْيَقُلْ: مَتَى قَدَرْتُ جَامَعْتُهَا، وَيُؤَخَّرُ حَتَّى يَقْدِرُ عَلَيْهَا."]]},{"id":"um102_10","label":"بَابُ مُعَاشَرَةِ النِّسَاءِ · ١٠","segs":[["matn","بَابُ القَسْمِ وَالنُّشُوزِ وَعَلَى الرَّجُلِ الْعَدْلُ بَيْنَ نِسَائِهِ فِي القَسْمِ، وَعِمَادُهُ اللَّيْلُ، فَيَقْسِمُ لِلأَمَةِ لَيْلَةً، وَلِلْحُرَّةِ لَيْلَتَيْنِ، وَإِنْ كَانَتْ كِتَابِيَّةً، وَلَيْسَ عَلَيْهِ الْمُسَاوَاةُ فِي الْوَطْءِ بَيْنَهُنَّ وَلَيْسَ لَهُ البَدَاءَةُ فِي القَسْمِ بِإِحْدَاهُنَّ،"]]},{"id":"um102_11","label":"بَابُ مُعَاشَرَةِ النِّسَاءِ · ١١","segs":[["matn","وَلَا السَّفَرُ بِهَا إِلَّا بِقُرْعَةٍ، فَإِنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا أَرَادَ سَفَرًا، أَقْرَعَ بَيْنَ نِسَائِهِ فَأَيَّتُهُنَّ خَرَجَ سَهْمُهَا، خَرَجَ بِهَا مَعَهُ."]]},{"id":"um102_12","label":"بَابُ مُعَاشَرَةِ النِّسَاءِ · ١٢","segs":[["matn","وَلِلْمَرْأَةِ أَنْ تَهِبَ حَقَّهَا مِنَ القَسْمِ لِبَعْضِ ضَرَّاتِهَا بِإِذْنِ زَوْجِهَا، أَوْ لَهُ فَيَجْعَلُهُ لِمَنْ شَاءَ مِنْهُنَّ؛ لِأَنَّ سَوْدَةَ وَهَبَتْ يَوْمَهَا لِعَائِشَةَ، فَكَانَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْسِمُ لِعَائِشَةَ يَوْمَهَا وَيَوْمَ سَوْدَةَ."]]},{"id":"um102_13","label":"بَابُ مُعَاشَرَةِ النِّسَاءِ · ١٣","segs":[["matn","وَإِذَا أَعْرَسَ عَلَى بِكْرٍ، أَقَامَ عِنْدَهَا سَبْعًا، ثُمَّ دَارَ، وَإِنْ أَعْرَسَ عَلَى ثَيِّبٍ أَقَامَ عِنْدَهَا ثَلَاثاً، لِقَوْلِ أَنَسٍ: مِنَ السُّنَّةِ إِذَا تَزَوَّجَ البِكْرَ عَلَى الثَّيِّبِ،"]]},{"id":"um102_14","label":"بَابُ مُعَاشَرَةِ النِّسَاءِ · ١٤","segs":[["matn","أَنْ يُقِيمَ عِنْدَهَا سَبْعًا، وَإِذَا تَزَوَّجَ الثَّيِّبَ عَلَى البِكْرِ، أَقَامَ عِنْدَهَا ثَلَاثاً، وَإِنْ أَحَبَّتِ الثَّيِّبُ أَنْ يُقِيمَ عِنْدَهَا سَبْعًا،"]]},{"id":"um102_15","label":"بَابُ مُعَاشَرَةِ النِّسَاءِ · ١٥","segs":[["matn","فَعَلَ، وَقَضَاهُنَّ لِلْبَوَاقِي، لِأَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَمَّا تَزَوَّجَ أُمَّ سَلَمَةَ، أَقَامَ عِنْدَهَا ثَلَاثاً، ثُمَّ قَالَ: «لَيْسَ بِكِ هَوَانٌ عَلَى أَهْلِكِ إِنْ شِئْتِ أَقَمْتُ عِنْدَكِ ثَلَاثًا خَالِصَةً لَكِ، وَإِنْ شِئْتِ سَبَّعْتُ لَكِ، وَإِنْ سَبَّعْتُ لَكِ سَبَّعْتُ لِنِسَائِي»."]]},{"id":"um102_16","label":"بَابُ مُعَاشَرَةِ النِّسَاءِ · ١٦","segs":[["matn","فَصْلٌ: وَيُسْتَحَبُّ التَّسَتُّرُ عِنْدَ الجِمَاعِ، وَأَنْ يَقُولَ مَا رَوَاهُ ابْنُ عَبَّاسٍ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ:"]]},{"id":"um102_17","label":"بَابُ مُعَاشَرَةِ النِّسَاءِ · ١٧","segs":[["matn","«لَوْ أَنَّ أَحَدَكُمْ إِذَا أَتَى أَهْلَهُ قَالَ: بِسْمِ اللهِ، اللهُمَّ جَنِّبْنَا الشّيْطَانَ، وَجَنِّبِ الشَّيْطَانَ مَا رَزَقْتَنَا، فَقُضِيَ بَيْنَهُمَا وَلَدٌ، لَمْ يَضُرَّهُ الشَّيْطُانُ أَبَدَا»."]]},{"id":"um102_18","label":"بَابُ مُعَاشَرَةِ النِّسَاءِ · ١٨","segs":[["matn","فَصْلٌ: وَإِنْ خَافَتِ الْمَرْأَةُ مِنْ زَوْجِهَا نُشُوزًا أَوْ إِعْرَاضًا، فَلَا بَأْسَ أَنْ تَسْتَرْضِيَهُ بِإِسْقَاطِ بَعْضِ حُقُوقِهَا، كَمَا فَعَلَتْ سَوْدَةُ حِينَ خَافَتْ أَنْ يُطَلِّقَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ."]]},{"id":"um102_19","label":"بَابُ مُعَاشَرَةِ النِّسَاءِ · ١٩","segs":[["matn","وَإِنْ خَافَ الرَّجُلُ نُشُوزَ امْرَأَتِهِ، وَعَظَهَا، فَإِنْ أَظْهَرَتْ نُشُوزًا، هَجَرَهَا فِي المَضْجَعِ، فَإِنْ لَمْ يَرْدَعْهَا ذَلِكَ، فَلَهُ أَنْ يَضْرِبَهَا ضَرْبًا غَيْرَ مُبَرِّحٍ."]]},{"id":"um102_20","label":"بَابُ مُعَاشَرَةِ النِّسَاءِ · ٢٠","segs":[["matn","وَإِنْ خِيفَ الشِّقَاقُ بَيْنَهُمَا، بَعَثَ الحَاكِمُ حَكَمًا مِنْ أَهْلِهِ وَحَكَمًا مِنْ أَهْلِهَا، مَأْمُونَيْنِ، يَجْمَعَانِ إِنْ رَأَيَا أَوْ يُفَرِّقَانِ فَمَا فَعَلَا مِنْ ذَلِكَ لَزِمَهُمَا."]]},{"id":"um102_21","label":"بَابُ مُعَاشَرَةِ النِّسَاءِ · ٢١","segs":[["matn","بَابُ الخُلْعِ وَإِذَا كَانَتِ الْمَرْأَةُ مُبْغِضَةً لِلرَّجُلِ وَخَافَتْ أَنْ لَا تُقِيمَ حُدُودَ اللهِ فِي طَاعَتِهِ، فَلَهَا أَنْ تَفْتَدِيَ نَفْسَهَا مِنْهُ بِمَا تَرَاضَيَا عَلَيْهِ."]]},{"id":"um102_22","label":"بَابُ مُعَاشَرَةِ النِّسَاءِ · ٢٢","segs":[["matn","وَيُسْتَحَبُّ أَنْ لَا يَأْخُذَ مِنْهَا أَكْثَرَ مِمَّا أَعْطَاهَا، فَإِذَا خَلَعَهَا أَوْ طَلَّقَهَا بِعَوْضٍ، بَانَتْ مِنْهُ، وَلَمْ يَلْحَقْهَا طَلَاقُهُ بَعْدَ ذَلِكَ، وَلَوْ وَاجَهَهَا بِهِ."]]},{"id":"um102_23","label":"بَابُ مُعَاشَرَةِ النِّسَاءِ · ٢٣","segs":[["matn","وَيَجُوزُ الخُلْعُ بِكُلِّ مَا يَجُوزُ أَنْ يَكُونَ صَدَاقًا، وَبِالْمَجْهُولِ، فَلَوْ قَالَتْ: اخْلَعْنِي بِمَا فِي يَدِي مِنَ الدَّرَاهِمِ، أَوْ مَا فِي بَيْتِي مِنَ الْمَتَاعِ فَفَعَلَ، صَحَّ، وَلَهُ مَا فِيهِمَا، فَإِنْ لَمْ يَكُنْ فِيهِمَا شَيْءٌ، فَلَهُ ثَلَاثَةُ دَرَاهِمَ، وَأَقَلُّ مَا يُسَمَّى مَتَاعًا."]]},{"id":"um102_24","label":"بَابُ مُعَاشَرَةِ النِّسَاءِ · ٢٤","segs":[["matn","وَإِنْ خَالَعَهَا عَلَى عَبْدٍ، مُعَيَّنٍ فَخَرَجَ مَعِيبًا، فَلَهُ أَرْشُهُ أَوْ رَدُّهُ وَأَخْذُ قِيمَتِهِ، وَإِنْ خَرَجَ مَغْصُوبًا أَوْ حُرًّا، فَلَهُ قِيمَتُهُ."]]},{"id":"um102_25","label":"بَابُ مُعَاشَرَةِ النِّسَاءِ · ٢٥","segs":[["matn","وَيَصِحُّ الخُلْعُ مِنْ كُلِّ مَنْ يَصِحُّ طَلَاقُهُ، وَلَا يَصِحُّ بَذْلُ العِوَضِ، إِلَّا مِمَّنْ يَصِحُّ تَصَرُّفُهُ فِي الْمَالِ."]]}],"group":"كِتَابُ الصَّدَاقِ"},{"id":"um103","title":"كِتَابُ الطَّلَاقِ","units":[{"id":"um103_1","label":"كِتَابُ الطَّلَاقِ · ١","segs":[["matn","وَلَا يَصِحُّ الطَّلَاقُ إِلَّا مِنْ زَوْجٍ، مُكَلَّفٍ، مُخْتَارٍ، وَلَا يَصِحُّ طَلَاقُ الْمُكْرَهِ، وَلَا زَائِلِ العَقْلِ، إِلَّا السَّكْرَانَ."]]},{"id":"um103_2","label":"كِتَابُ الطَّلَاقِ · ٢","segs":[["matn","وَيَمْلِكُ الحُرُّ ثَلَاثَ تَطْلِيقَاتٍ، وَالعَبْدُ اثْنَتَيْنِ، سَوَاءٌ كَانَ تَحْتَهُ حُرَّةً أَوْ أَمَةً، فَمَتَى اسْتَوْفَى عَدَدَ طَلَاقِهِ، لَمْ تَحِلَّ لَهُ حَتَّى تَنْكِحَ زَوْجًا غَيْرَهُ،"]]},{"id":"um103_3","label":"كِتَابُ الطَّلَاقِ · ٣","segs":[["matn","نِكَاحًا صَحِيحًا، وَيَطَأَهَا، لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِامْرَأَةِ رِفَاعَةَ: «لَعَلَّكِ تُرِيدِينَ أَنْ تَرْجِعِي إِلَى رِفَاعَةَ؟ لَا، حَتَّى تَذُوقِي عُسَيْلَتَهُ وَيَذُوقَ عُسَيْلَتَكِ»."]]},{"id":"um103_4","label":"كِتَابُ الطَّلَاقِ · ٤","segs":[["matn","وَلَا يَحِلُّ جَمْعُ الثَّلَاثِ، وَلَا طَلَاقَ الْمَدْخُولِ بِهَا فِي حَيْضِهَا أَوْ فِي طُهْرٍ أَصَابَهَا فِيهِ، لِمَا رَوَى ابْنُ عُمَرَ أَنَّهُ طَلَّقَ امْرَأَةً لَهُ وَهِيَ حَائِضٌ،"]]},{"id":"um103_5","label":"كِتَابُ الطَّلَاقِ · ٥","segs":[["matn","فَذَكَرَ ذَلِكَ عُمَرُ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: «مُرْهُ فَلْيُرَاجِعْهَا ثُمَّ يَمْسِكُهَا حَتَّى تَطْهُرَ ثُمَّ تَحِيضَ ثُمَّ تَطْهُرَ، فَإِنْ بَدَا لَهُ أَنْ يُطَلِّقَهَا، فَلْيُطَلِّقْهَا قَبْلَ أَنْ يَمَسَّهَا»."]]},{"id":"um103_6","label":"كِتَابُ الطَّلَاقِ · ٦","segs":[["matn","وَالسُّنَّةُ فِي الطَّلَاقِ أَنْ يُطَلِّقَهَا فِي طُهْرٍ لَمْ يُصِبْهَا فِيهِ وَاحِدَةً، ثُمَّ يَدَعَهَا حَتَّى تَنْقَضِيَ عِدَّتُهَا، فَمَتَى قَالَ لَهَا: أَنْتِ طَالِقٌ لِلسُّنَّةِ، وَهِيَ فِي طُهْرٍ لَمْ يُصِبْهَا فِيهِ، طَلُقَتْ، وَإِنْ كَانَتْ فِي طُهْرٍ أَصَابَهَا فِيهِ أَوْ حَيْضٍ،"]]},{"id":"um103_7","label":"كِتَابُ الطَّلَاقِ · ٧","segs":[["matn","لَمْ تَطْلُقْ حَتَّى تَطْهُرَ مِنَ حَيْضَةٍ وَإِنْ قَالَ لَهَا: أَنْتِ طَالِقٌ لِلْبِدْعَةِ، وَهِيَ حَائِضٌ أَوْ فِي طُهْرٍ أَصَابَهَا فِيهِ، طَلُقَتْ، وَإِنْ لَمْ تَكُنْ كَذَلِكَ، لَمْ تَطْلُقْ حَتَّى يُصِيبَهَا أَوْ تَحِيضَ."]]},{"id":"um103_8","label":"كِتَابُ الطَّلَاقِ · ٨","segs":[["matn","فَأَمَّا غَيْرُ الْمَدْخُولِ بِهَا، وَالحَامِلُ الَّتِي تَبَيَّنَ حَمْلُهَا، وَالآيِسَةُ وَالَّتِي لَمْ تَحِضْ، فَلَا سُنَّةَ لِطَلَاقِهَا وَلَا بِدْعَةَ، فَمَتَى قَالَ لَهَا: أَنْتِ طَالِقٌ لِلسُّنَّةِ أَوْ لِلْبِدْعَةِ، طَلُقَتْ فِي الْحَالِ."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"um104","title":"بَابُ صَرِيحِ الطَّلَاقِ وَكِنَايَتِهِ","units":[{"id":"um104_1","label":"بَابُ صَرِيحِ الطَّلَاقِ وَكِنَايَتِهِ · ١","segs":[["matn","صَرِيحُهُ: لَفْظُ الطَّلَاقِ، وَمَا تَصَرَّفَ مِنْهُ، كَقَوْلِهِ: أَنْتِ طَالِقٌ أَوْ مُطَلَّقَةٌ وَطَلَّقْتُكِ، فَمَتَى أَتَى بِهِ بِصَرِيحِ الطَّلَاقِ طَلُقَتْ وَإِنْ لَمْ يَنْوِهِ، وَمَا عَدَاهُ مِمَّا يَحْتَمْلُ الطَّلَاقَ، فَكِنَايَةٌ لَا يَقَعُ بِهِ الطَّلَاقُ إِلَّا أَنْ يَنْوِيَهُ، فَلَوْ قِيلَ لَهُ: أَلَكَ امْرَأَةٌ؟"]]},{"id":"um104_2","label":"بَابُ صَرِيحِ الطَّلَاقِ وَكِنَايَتِهِ · ٢","segs":[["matn","قَالَ: لَا، يَنْوِي الكَذِبَ، لَمْ تَطْلُقْ، فَإِنْ قَالَ: طَلَّقْتُهَا، طَلُقَتْ وَإِنْ نَوَى الكَذِبَ، وَإِنْ قَالَ لِامْرَأَتِهِ: أَنْتِ خَلِيَّةٌ، أَوْ بَرِيَّةٌ، أَوْ بَائِنٌ، أَوْ بَتَّةٌ، أَوْ بَتْلَةٌ، يَنْوِي بِهَا طَلَاقَهَا طَلُقَتْ ثَلَاثاً."]]},{"id":"um104_3","label":"بَابُ صَرِيحِ الطَّلَاقِ وَكِنَايَتِهِ · ٣","segs":[["matn","إِلَّا أَنْ يَنْوِيَ دُونَهَا، وَمَا عَدَا هَذَا يَقَعُ بِهِ وَاحِدَةً إِلَّا أَنْ يَنْوِيَ ثَلَاثاً، وَإِنْ خَيَّرَ امْرَأَتَهُ، فَاخْتَارَتْ نَفْسَهَا، طَلُقَتْ وَاحِدَةً،"]]},{"id":"um104_4","label":"بَابُ صَرِيحِ الطَّلَاقِ وَكِنَايَتِهِ · ٤","segs":[["matn","وَإِنْ لَمْ تَخْتَرْ أَوِ اخْتَارَتْ زَوْجَهَا، لَمْ يَقَعْ شَيْءٌ، قَالَتْ عَائِشَةٌ قَدْ خَيَّرَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، أَفَكَانَ طَلَاقاً؟."]]},{"id":"um104_5","label":"بَابُ صَرِيحِ الطَّلَاقِ وَكِنَايَتِهِ · ٥","segs":[["matn","وَلَيْسَ لَهَا أَنْ تَخْتَارَ إِلَّا فِي الْمَجْلِسِ، إِلَّا أَنْ يَجْعَلُهُ لَهَا فِيمَا بَعْدَهُ، وَإِنْ قَالَ أَمْرُكَ بِيَدِكِ، أَوْ طَلِّقِي نَفْسَكِ، فَهُوَ فِي يَدِهَا، مَا لَمْ يَفْسَخَ أَوْ يَطَأَ."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"um105","title":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ","units":[{"id":"um105_1","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · ١","segs":[["matn","يَصِحُّ تَعْلِيقُ الطَّلَاقِ وَالْعَتَاقَةِ بِشَرْطٍ بَعْدَ النِّكَاحِ وَالْمِلْكِ، وَلَا يَصِحُّ قَبْلَهُ، فَلَوْ قَالَ: إِنْ تَزَوَّجْتُ فُلَانَةً، فَهِيَ طَالِقٌ، أَوْ مَلَكْتُهَا، فَهِيَ حُرَّةٌ، فَتَزَوَّجَهَا أَوْ مَلَكَهَا، لَمْ تَطْلُقْ، وَلَمْ تَعْتِقْ."]]},{"id":"um105_2","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · ٢","segs":[["matn","وَأَدَوَاتُ الشَّرْطِ سِتٌّ: إِنْ، وَإِذَا، وَأَيُّ، وَمَتَى، وَمَنْ وَكُلَّمَا. وَلَيْسَ فِيهَا مَا يَقْتَضِي التِّكْرَارَ إِلَّا كُلَّمَا."]]},{"id":"um105_3","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · ٣","segs":[["matn","وَكُلُّهَا إِذَا كَانَتْ مُثْبَتَةً، ثَبَتَ حُكْمُهَا، عِنْدَ وُجُودِ شَرْطِهَا، فَإِذَا قَالَ: إِنْ قُمْتِ فَأَنْتِ طَالِقٌ، فَقَامَتْ، طَلُقَتْ، وَانْحَلَّ شَرْطُهُ، وَإِنْ قَالَ: كُلَّمَا قُمْتِ، فَأَنْتِ طَالِقٌ، طَلُقَتْ كُلَّمَا قَامَتْ."]]},{"id":"um105_4","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · ٤","segs":[["matn","وَإِنْ كَانَتْ نَافِيَةً، كَقَوْلِهِ: إِنْ لَمْ أُطَلِّقْكِ، فَأَنْتِ طَالِقٌ، كَانَتْ عَلَى التَّرَاخِي، إِذَا لَمْ يَنْوِ وَقْتًا بِعَيْنِهِ فَلَا يَقَعُ الطَّلَاقُ إِلَّا فِي آخِرِ أَوْقَاتِ الإِمْكَانِ."]]},{"id":"um105_5","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · ٥","segs":[["matn","وَسَائِرُ الأَدَوَاتِ عَلَى الفَوْرِ، فَإِذَا قَالَ: مَتَى لَمْ أُطَلِّقْكِ، فَأَنْتِ طَالِقٌ، وَلَمْ يُطَلِّقْهَا، طَلُقَتْ فِي الحَالِ، وَإِنْ قَالَ: كُلَّمَا لَمْ أَطَلِّقْكِ، فَأَنْتِ طَالِقٌ،"]]},{"id":"um105_6","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · ٦","segs":[["matn","فَمَضَى زَمَنٌ يُمْكِنُ طَلَاقُهَا فِيهِ ثَلَاثاً وَلَمْ يُطَلِّقْهَا، طَلُقَتْ ثَلَاثاً إِنْ كَانَتْ مَدْخُولاً بِهَا، وَإِنْ قَالَ: كُلَّمَا وَلَدْتِ وَلَدًا، فَأَنْتِ طَالِقٌ، فَوَلَدَتْ تَوْأَمَيْنِ، طَلُقَتْ بِالأَوَّلِ، وَبَانَتْ بِالثَّانِي؛"]]},{"id":"um105_7","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · ٧","segs":[["matn","لِانْقِضَاءِ عِدَّتِهَا بِهِ، وَلَمْ تَطْلُقْ بِهِ، وَإِنْ قَالَ: إِنْ حِضْتِ، فَأَنْتِ طَالِقٌ، طَلُقَتْ بِأَوَّلِ الحَيْضِ، فَإِنْ تَبَيَّنَ أَنَّهُ لَيْسَ بِحَيْضٍ، لَمْ تَطْلُقْ فَإِنْ قَالَتْ:"]]},{"id":"um105_8","label":"بَابُ تَعْلِيقِ الطَّلَاقِ بِالشُّرُوطِ · ٨","segs":[["matn","قَدْ حِضْتُ، فَكَذَّبَهَا، طَلُقَتْ، وَإِنْ قَالَ: قَدْ حِضْتِ، وَكَذَّبَتْهُ طَلُقَتْ بِإِقْرَارِهِ، فَإِنْ قَالَ: إِنْ حِضْتِ، فَأَنْتِ وَضَرَّتُكِ طَالِقَتَانِ، فَإِنْ قَالَتْ قَدْ حِضْتُ، فَكَذَّبَهَا، طَلُقَتْ دُونَ ضَرَّتِهَا."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"um106","title":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ وَغَيْرُهُ","units":[{"id":"um106_1","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ وَغَيْرُهُ · ١","segs":[["matn","الْمَرْأَةُ إِذَا لَمْ يُدْخَلْ بِهَا تُبِينُهَا الطَّلْقَةُ، وَتُحَرِّمُهَا الثَّلَاثُ مِنَ الحُرِّ، وَالِاثْنَتَانِ مِنَ العَبْدِ، إِذَا وَقَعَتْ مَجْمُوعَةً، كَقَوْلِهِ: أَنْتِ طَالِقٌ ثَلَاثاً، أَوْ أَنْتِ طَالِقٌ وَطَالِقٌ وَطَالِقٌ، وَإِنْ أَوْقَعَهُ مُرَتَّباً، كَقَوْلِهِ: أَنْتِ طَالِقٌ فَطَالِقٌ،"]]},{"id":"um106_2","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ وَغَيْرُهُ · ٢","segs":[["matn","أَوْ ثُمَّ طَالِقٌ، أَوْ طَالِقٌ بَلْ طَالِقٌ، أَوْ أَنْتِ طَالِقٌ أَنْتِ طَالِقٌ، وَإِنْ طَلَّقْتُكِ، فَأَنْتِ طَالِقٌ، ثُمَّ طَلَّقَهَا، أَوْ كُلَّمَا طَلَّقْتُكِ، فَأَنْتِ طَالِقٌ، أَوْ كُلَّمَا لَمْ أُطَلِّقْكِ، فَأَنْتِ طَالِقٌ، وَأَشْبَاهَ هَذَا، لَمْ يَقَعْ بِهَا إِلَّا وَاحِدَةً."]]},{"id":"um106_3","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ وَغَيْرُهُ · ٣","segs":[["matn","وَإِنْ كَانَتْ مَدْخُولاً بِهَا وَقَعَ بِهَا، جَمِيعُ مَا أَوْقَعَهُ. وَمَنْ شَكَّ فِي الطَّلَاقِ أَوْ عَدَدِهِ، أَوِ الرَّضَاعِ أَوْ عَدَدِهِ، بَنَى عَلَى اليَقِينِ."]]},{"id":"um106_4","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ وَغَيْرُهُ · ٤","segs":[["matn","وَإِنْ قَالَ لِنِسَائِهِ: إِحْدَاكُنَّ طَالِقٌ، وَلَمْ يَنْوِ وَاحِدَةً بِعَيْنِهَا، خَرَجَتْ بِالقُرْعَةِ."]]},{"id":"um106_5","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ وَغَيْرُهُ · ٥","segs":[["matn","وَإِنْ طَلَّقَ جُزْءًا مِنِ امْرَأَتِهِ مُشَاعًا أَوْ مُعَيَّناً، كَإِصْبَعِهَا أَوْ يَدِهَا، طَلُقَتْ كُلُّهَا، إِلَّا الظُّفُرَ وَالسِّنَّ وَالشَّعْرَ وَالرِّيقَ وَالدَّمْعَ وَنَحْوَهُ لَا تَطْلُقُ بِهِ."]]},{"id":"um106_6","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ وَغَيْرُهُ · ٦","segs":[["matn","وَإِنْ قَالَ: أَنْتِ طَالِقٌ نِصْفَ تَطْلِيقَةٍ، أَوْ أَقَلَّ مِنْ هَذَا، طَلُقَتْ وَاحِدَةً."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"um107","title":"بَابُ الرَّجْعَةِ","units":[{"id":"um107_1","label":"بَابُ الرَّجْعَةِ · ١","segs":[["matn","إِذَا طَلَّقَ امْرَأَتَهُ، بَعْدَ الدُّخُولِ بِغَيْرِ عِوَضٍ، أَقَلَّ مِنْ ثَلَاثٍ، أَوِ الْعَبْدُ أَقَلَّ مِنَ اثْنَتَيْنِ، فَلَهُ رَجْعَتُهَا مَا دَامَتْ فِي الْعِدَّةِ؛ لِقَوْلِ اللهِ تَعَالَى: ﴿وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِي ذَلِكَ إِنْ أَرَادُوا إِصْلَاحًا﴾."]]},{"id":"um107_2","label":"بَابُ الرَّجْعَةِ · ٢","segs":[["matn","وَالرَّجْعَةُ: أَنْ يَقُولَ لِرَجُلَيْنِ مِنَ الْمُسْلِمِينَ: اشْهَدَا أَنَّنِي قَدْ رَاجَعْتُ زَوْجَتِي أَوْ رَدَدْتُهَا أَوْ أَمْسَكْتُهَا، مِنْ غَيْرِ وَلِيٍّ، وَلَا صَدَاقٍ يَزِيدُهُ، وَلَا رِضَائِهَا وَإِنْ وَطِئَهَا، كَانَ رَجْعَةً."]]},{"id":"um107_3","label":"بَابُ الرَّجْعَةِ · ٣","segs":[["matn","وَالرَّجْعِيَّةُ زَوْجَةٌ، يَلْحَقُهَا الطَّلَاقُ وَالظِّهَارُ، وَلَهَا التَّزَيُّنُ لِزَوْجِهَا وَالتَّشَرُّفُ لَهُ، وَلَهُ وَطْؤُهَا وَالخَلْوَةُ وَالسَّفَرُ بِهَا."]]},{"id":"um107_4","label":"بَابُ الرَّجْعَةِ · ٤","segs":[["matn","وَإِذَا ارْتَجَعَهَا، عَادَتْ عَلَى مَا بَقِيَ مِنْ طَلَاقِهَا، وَلَوْ تَرَكَهَا حَتَّى بَانَتْ ثُمَّ نَكَحَتْ زَوْجًا غَيْرَهُ، ثُمَّ بَانَتْ مِنْهُ، وَتَزَوَّجَهَا الأَوَّلُ، رَجَعَتْ إِلَيْهِ عَلَى مَا بَقِيَ مِنْ طَلَاقِهَا."]]},{"id":"um107_5","label":"بَابُ الرَّجْعَةِ · ٥","segs":[["matn","وَإِذَا اخْتَلَفَا فِي انْقِضَاءِ عِدَّتِهَا، فَالقَوْلُ قَوْلُهَا مَعَ يَمِينِهَا إِذَا ادَّعَتْ مِنْ ذَلِكَ مُمْكِنًا، وَإِنِ ادَّعَى الزَّوْجُ بَعْدَ انْقِضَاءِ عِدَّتِهَا أَنَّهُ قَدْ رَاجَعَهَا فِي عِدَّتِهَا،"]]},{"id":"um107_6","label":"بَابُ الرَّجْعَةِ · ٦","segs":[["matn","فَأَنْكَرَتْهُ، فَالقَوْلُ قُولُهَا وَإِنْ كَانَتْ لَهُ بَيِّنَةٌ، حُكِمَ لَهُ بِهَا، فَإِنْ كَانَتْ قَدْ تَزَوَّجَتْ، رُدَّتْ إِلَيْهِ، سَوَاءٌ كَانَ دَخَلَ بِهَا الثَّانِي أَوْ لَمْ يَدْخُلْ، بِهَا."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"um108","title":"بَابُ العِدَّةِ","units":[{"id":"um108_1","label":"بَابُ العِدَّةِ · ١","segs":[["matn","وَلَا عِدَّةَ عَلَى مَنْ فَارَقَهَا زَوْجُهَا فِي الحَيَاةِ قَبْلَ المَسِيسِ؛ وَالْخَلْوَةِ؛ لِقَوْلِ اللَّهِ تَعَالَى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نَكَحْتُمُ الْمُؤْمِنَاتِ ثُمَّ طَلَّقْتُمُوهُنَّ مِنْ قَبْلِ أَنْ تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَا﴾."]]},{"id":"um108_2","label":"بَابُ العِدَّةِ · ٢","segs":[["matn","وَالْمُعْتَدَّاتُ يَنْقَسِمْنَ أَرْبَعَةَ أَقْسَامٍ: إِحْدَاهُنَّ: أَوْلَاتُ الأَحْمَالِ فَعِدَّتُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ، وَلَوْ كَانَتْ حَامِلاً بِتَوْأَمَيْنِ لَمْ تَنْقَضِ عِدَّتُهَا حَتَّى تَضَعَ الثَّانِيَ مِنْهُمَا، وَالحَمْلُ الَّذِي تَنْقَضِيَ بِهِ العِدَّةُ وَتَصِيرُ بِهِ الأَمَةُ أُمَّ وَلَدٍ، مَا يَتَبَيَّنَ فِيهِ خَلْقِ الإِنْسَانِ."]]},{"id":"um108_3","label":"بَابُ العِدَّةِ · ٣","segs":[["matn","الثَّانِي: اللَّاتِي تُوُفِّيَ أَزْوَاجُهُنَّ، يَتَرَبَّصْنَ بِأَنْفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا، وَالإِمَاءُ عَلَى النِّصْفِ مِنْ ذَلِكَ، وَمَا قَبْلَ الْمَسِيسِ وَمَا بَعْدَهُ سَوَاءٌ."]]},{"id":"um108_4","label":"بَابُ العِدَّةِ · ٤","segs":[["matn","الثَّالِثُ: الْمُطَلَّقَاتُ مِنْ ذَوَاتِ القُرُوءِ، يَتَرَبَّصْنَ بِأَنْفُسِهِنَّ ثَلَاثَةَ قُرُوءٍ، وَقُرْءُ الأَمَةِ حَيْضَتَانِ. الرَّابِعُ: اللَّائِي يَئِسْنَ مِنَ الْمَحِيضِ، فَعِدَّتُهُنَّ ثَلَاثَةَ أَشْهُرٍ، وَاللَّائِي لَمْ يَحِضْنَ، وَالْأَمَةُ شَهْرَانِ."]]},{"id":"um108_5","label":"بَابُ العِدَّةِ · ٥","segs":[["matn","وَيُشْرَعُ التَّرَبُّصُ مَعَ العِدَّةِ فِي ثَلَاثَةِ مَوَاضِعَ: أَحَدُهَا: إِذَا ارْتَفَعَ حَيْضُ الْمَرْأَةِ لَا تَدْرِي مَا رَفَعَهُ، فَإِنَّهَا تَتَرَبَّصُ تِسْعَةَ أَشْهُرٍ، ثُمَّ تَعْتَدُّ عِدَّةَ الآيِسَاتِ، وَإِنْ عَرَفَتْ مَا رَفَعَ الحَيْضَ، لَمْ تَزَلْ فِي عِدَّةٍ حَتَّى يَعُودَ الحَيْضُ، فَتَعْتَدَّ بِهِ."]]},{"id":"um108_6","label":"بَابُ العِدَّةِ · ٦","segs":[["matn","الثَّانِي: امْرَأَةُ المَفْقُودِ الَّذِي فُقِدَ فِي مَهْلَكَةٍ، أَوْ مِنْ بَيْنِ أَهْلِهِ، فَلَمْ يُعْلَمْ خَبَرُهُ. تَتَرَبَّصُ أَرْبَعَ سِنِينَ، ثُمَّ تَعْتَدُّ لِلْوَفَاةِ."]]},{"id":"um108_7","label":"بَابُ العِدَّةِ · ٧","segs":[["matn","وَإِنْ فُقِدَ فِي غَيْرِ هَذَا، كَالْمُسَافِرِ لِلتِّجَارَةِ وَنَحْوِهَا لَمْ تَنْكِحْ حَتَّى تَتَيَقَّنَ مَوْتَهُ."]]},{"id":"um108_8","label":"بَابُ العِدَّةِ · ٨","segs":[["matn","الثَّالِثُ: إِذَا ارْتَابَتِ الْمَرْأَةُ بَعْدَ انْقِضَاءِ عِدَّتِهَا؛ لِظُهُورِ أَمَارَاتِ الحَمْلِ، لَمْ تَنْكِحْ حَتَّى تَزُولَ الرِّيبَةُ، فَإِنْ نَكَحَتْ لَمْ يَصِحَّ النِّكَاحُ، وَإِنِ ارْتَابَتْ بَعْدَ نِكَاحِهَا،"]]},{"id":"um108_9","label":"بَابُ العِدَّةِ · ٩","segs":[["matn","لَمْ يَبْطُلْ نِكَاحُهَا إِلَّا إِذَا عَلِمَتْ أَنَّهَا نَكَحَتْ وَهِيَ حَامِلٌ، وَمَتَى نَكَحَتِ الْمُعْتَدَّةُ فَنِكَاحُهَا بَاطِلٌ وَيُفَرَّقُ بَيْنَهُمَا، وَإِنْ فُرِّقَ بَيْنَهُمَا قَبْلَ الدُّخُولِ، أَتَمَّتْ عِدَّةَ الأَوْلِ،"]]},{"id":"um108_10","label":"بَابُ العِدَّةِ · ١٠","segs":[["matn","وَإِنْ كَانَ بَعْدَ الدُّخُولِ، بَنَتْ عَلَى عِدَّةِ الأَوَّلِ، مِنْ حِينِ دَخَلَ بِهَا الثَّانِي، وَاسْتَأْنَفَتِ العِدَّةَ لِلثَّانِي، وَلَهُ نِكَاحُهَا بَعْدَ انْقِضَاءِ العِدَّتَيْنِ، وَإِنْ أَتَتْ بِوَلَدٍ مِنْ أَحَدُهُمَا،"]]},{"id":"um108_11","label":"بَابُ العِدَّةِ · ١١","segs":[["matn","انقَضَتْ بِهِ عِدَّتُهُ، وَاعْتَدَّتْ لِلآخَرِ، وَإِنْ أَمْكَنَ أَنْ يَكُونَ مِنْهُمَا، أُرِيَ القَافَةَ، فَأُلْحِقَ بِمَنْ أَلْحَقُوهُ مِنْهُمَا، وَانْقَضَتْ بِهِ عِدَّتُهَا مِنْهُ، وَاعْتَدَّتْ لِلآخَرِ."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"um109","title":"بَابُ الإِحْدَادِ","units":[{"id":"um109_1","label":"بَابُ الإِحْدَادِ · ١","segs":[["matn","وَهُوَ وَاجِبٌ، عَلَى مَنْ تُوُفِّيَ عَنْهَا زَوْجُهَا، وَهُوَ: اجْتِنَابُ الزِّينَةِ وَالطِّيبِ وَالْكُحْلِ بِالإِثْمِدِ، وَلُبْسِ الثِّيَابِ الْمَصْبُوغَةِ لِلتَّحْسِينِ، لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ:"]]},{"id":"um109_2","label":"بَابُ الإِحْدَادِ · ٢","segs":[["matn","«لَا تَحِدُّ امْرَأَةٌ عَلَى مَيِّتٍ فَوْقَ ثَلَاثٍ، إِلَّا عَلَى زَوْجٍ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا،» وَلَا تَلْبَسُ ثَوْبًا مَصْبُوغًا إِلَّا ثَوْبَ عَصَبٍ،"]]},{"id":"um109_3","label":"بَابُ الإِحْدَادِ · ٣","segs":[["matn","وَلَا تَكْتَحِلُ، وَلَا تَمَسُّ طِيبًا، إِلَّا إِذَا اغْتَسَلَتْ، نُبْذَةً مِنْ قُسْطٍ أَوْ أَظْفَارٍ، وَعَلَيْهَا الْمَبِيتُ فِي مَنْزِلِهَا الَّذِي وَجَبَتْ عَلَيْهَا العِدَّةُ وَهِيَ سَاكِنَةٌ فِيهِ، إِذَا أَمْكَنَهَا ذَلِكَ، فَإِنْ خَرَجَتْ لِسَفَرٍ أَوْ حَجٍّ؛"]]},{"id":"um109_4","label":"بَابُ الإِحْدَادِ · ٤","segs":[["matn","فَتُوُفِّيَ زَوْجُهَا وَهِيَ قَرِيبَةٌ، رَجَعَتْ لِتَعْتَدَّ فِي بَيْتِهَا، وَإِنْ تَبَاعَدَتْ مَضَتْ فِي سَفَرِهَا، وَالْمُطَلَّقَةُ ثَلَاثاً مِثْلُهَا، إِلَّا فِي الِاعْتِدَادِ فِي بَيْتِهَا."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"um110","title":"بَابُ نَفَقَةِ المُعْتَدَّاتِ","units":[{"id":"um110_1","label":"بَابُ نَفَقَةِ المُعْتَدَّاتِ · ١","segs":[["matn","وَهِيَ ثَلَاثَةُ أَقْسَامٍ: أَحَدُهَا: الرَّجْعِيَّةُ، وَمَنْ يُمْكِنُ زَوْجُهَا إِمْسَاكَهَا، فَلَهَا النَّفَقَةُ وَالسُّكْنَى، وَلَوْ أَسْلَمَ زَوْجُ الكَافِرَةِ أَوِ ارْتَدَّتْ امْرَأَةُ المُسْلِمِ فَلَا نَفَقَةَ لَهُمَا، وَإِنْ أَسْلَمَتِ امْرَأَةُ الْكَافِرِ، أَوِ ارْتَدَّ زَوْجُ الْمُسْلِمَةِ بَعْدَ الدُّخُولِ، فَلَهُمَا نَفَقَةُ الْعِدَّةِ."]]},{"id":"um110_2","label":"بَابُ نَفَقَةِ المُعْتَدَّاتِ · ٢","segs":[["matn","الثَّانِي: البَائِنُ فِي الحَيَاةِ بِطَلَاقٍ أَوْ فَسْخٍ فَلَا سُكْنَى لَهَا بِحَالٍ، وَلَهَا النَّفَقَةُ إِنْ كَانَتْ حَامِلاً، وَإِلَّا فَلَا. الثَّالِثُ: الَّتِي تُوُفِّيَ عَنْهَا زَوْجُهَا فَلَا نَفَقَةَ لَهَا وَلَا سُكْنَى."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"um111","title":"بَابُ اسْتِبْرَاءِ الإِمَاءِ","units":[{"id":"um111_1","label":"بَابُ اسْتِبْرَاءِ الإِمَاءِ · ١","segs":[["matn","وَهُوَ وَاجِبٌ فِي ثَلَاثَةِ مَوَاضِعَ: أَحَدُهَا: مَنْ مَلَكَ أَمَةً، لَمْ يُصِبْهَا حَتَّى يَسْتَبْرِئَهَا. الثَّانِي: أُمُّ الوَلَدِ وَالأَمَةُ الَّتِي يَطَؤُهَا سَيِّدُهَا، لَا يَجُوزُ لَهُ تَزْوِيجُهَا حَتَّى يَسْتَبْرِئَهَا."]]},{"id":"um111_2","label":"بَابُ اسْتِبْرَاءِ الإِمَاءِ · ٢","segs":[["matn","الثَّالِثُ: إِذَا أَعْتَقَهُمَا سَيِّدُهُمَا أَوْ عَتَقَا بِمَوْتِهِ، لَمْ يَنْكِحَا حَتَّى يَسْتَبْرِئَا أَنْفُسَهُمَا."]]},{"id":"um111_3","label":"بَابُ اسْتِبْرَاءِ الإِمَاءِ · ٣","segs":[["matn","وَالِاسْتِبْرَاءُ فِي جَمِيعِ ذَلِكَ بِوَضْعِ الحَمْلِ إِنْ كَانَتْ حَامِلاً، أَوْ حَيْضَةٍ إِنْ كَانَتْ تَحِيضُ، أَوْ شَهْرٍ إِنْ كَانَتْ آيِسَةً أَوْ مِنَ اللَّائِي لَمْ يَحِضْنَ، أَوْ عَشْرَةِ أَشْهُرٍ إِنِ ارْتَفَعَ حَيْضُهَا لَا تَدْرِي مَا رَفَعَهُ."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"um112","title":"كِتَابُ الظِّهَارِ","units":[{"id":"um112_1","label":"كِتَابُ الظِّهَارِ · ١","segs":[["matn","وَهُوَ: أَنْ يَقُولَ لِامْرَأَتِهِ: أَنْتِ عَلَيَّ كَظَهْرِ أُمِّي، أَوْ مَنْ تَحْرُمُ عَلَيْهِ عَلَى التَّأْبِيدِ."]]},{"id":"um112_2","label":"كِتَابُ الظِّهَارِ · ٢","segs":[["matn","أَوْ يَقُولَ: أَنْتِ عَلَيَّ كَأَبِي، يُرِيدُ تَحْرِيمَهَا بِهِ، فَلَا تَحِلُّ لَهُ حَتَّى يُكَفِّرَ، بِتَحْرِيرِ رَقَبَةٍ مِنْ قَبْلِ أَنْ يَتَمَاسَّا، فَمَنْ لَمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ فَمَنْ لَمْ يَسْتَطِعْ، فَإِطْعَامُ سِتِّينَ مِسْكِينًا."]]},{"id":"um112_3","label":"كِتَابُ الظِّهَارِ · ٣","segs":[["matn","وَحُكْمُهَا وَصِفَتُهَا كَكَفَّارَةِ الجِمَاعِ فِي شَهْرِ رَمَضَانَ، فَإِنْ وَطِئَ قَبْلَ التَّكْفِيرِ، عَصَى، وَلِزَمَتْهُ الكَفَّارَةُ الْمَذْكُورَةُ. وَمَنْ ظَاهَرَ مِنْ امْرَأَتِهِ مِرَارًا، وَلَمْ يُكَفِّرْ، فَكَفَّارَةٌ وَاحِدَةٌ."]]},{"id":"um112_4","label":"كِتَابُ الظِّهَارِ · ٤","segs":[["matn","وَإِنْ ظَاهَرَ مِنْ نِسَائِهِ بِكَلِمَةٍ وَاحِدَةٍ فَكَفَّارَةٌ وَاحِدَةٌ، وَإِنْ ظَاهَرَ مِنْهُنَّ بِكَلِمَاتٍ، فَعَلَيْهِ كَفَّارَةٌ لِكُلِّ وَاحِدَةٍ."]]},{"id":"um112_5","label":"كِتَابُ الظِّهَارِ · ٥","segs":[["matn","وَإِنْ ظَاهَرَ مِنْ أَمَتِهِ أَوْ حَرَّمَهَا، أَوْ حَرَّمَ شَيْئًا مُبَاحًا، أَوْ ظَاهَرَتِ الْمَرْأَةُ مِنْ زَوْجِهَا أَوْ حَرَّمَتْهُ، لَمْ يَحْرُمْ، وَكَفَّارَتُهُ كَفَّارَةُ يَمِينٍ."]]},{"id":"um112_6","label":"كِتَابُ الظِّهَارِ · ٦","segs":[["matn","وَالْعَبْدُ كَالْحُرِّ فِي الكَفَّارَةِ سَوَاءٌ، إِلَّا أَنَّهُ لَا يُكَفِّرُ إِلَّا بِالصِّيَامِ."]]}],"group":"كِتَابُ الظِّهَارِ"},{"id":"um113","title":"كِتَابُ اللِّعَانِ","units":[{"id":"um113_1","label":"كِتَابُ اللِّعَانِ · ١","segs":[["matn","إِذَا قَذَفَ الرَّجُلُ امْرَأَتَهُ، الْبَالِغَةَ، العَاقِلَةَ، الْحُرَّةَ، الْعَفِيفَةَ الْمُسْلِمَةَ بِالزِّنَا، لَزِمَهُ الحَدُّ، إِنْ لَمْ يُلَاعِنْ. وَإِنْ كَانَتْ ذِمِّيَّةً أَوْ أَمَةً، فَعَلَيْهِ التَّعْزِيرُ، إِنْ لَمْ يُلَاعِنْ، وَلَا يُعَرَّضُ لَهُ حَتَّى تُطَالِبُهُ."]]},{"id":"um113_2","label":"كِتَابُ اللِّعَانِ · ٢","segs":[["matn","وَاللِّعَانُ أَنْ يَقُولَ بِحَضْرَةِ الحَاكِمِ أَوْ نَائِبِهِ، أَشْهَدُ بِاللهِ إِنِّي لَمِنَ الصَّادِقِينَ، فِيمَا رَمَيْتُ بِهِ امْرَأَتِي هَذِهِ مِنَ الزِّنَا وَيُشِيرُ إِلَيْهَا، فَإِنْ لَمْ تَكُنْ حَاضِرَةً سَمَّاهَا وَنَسَبَهَا، ثُمَّ يُوقَفُ عِنْدَ الخَامِسَةِ،"]]},{"id":"um113_3","label":"كِتَابُ اللِّعَانِ · ٣","segs":[["matn","فَيُقَالُ لَهُ: اتَّقِ اللهَ فَإِنَّهَا المُوجِبَةُ، وَعَذَابُ الدُّنْيَا أَهْوَنُ مِنْ عَذَابِ الآخِرَةِ، فَإِنْ أَبَى إِلَّا أَنْ يُتِمَّ فَلْيَقُلْ: وَإِنَّ لَعْنَةَ اللهِ عَلَيْهِ إِنْ كَانَ مِنَ الكَاذِبِينَ فِيمَا رَمَيْتُ بِهِ امْرَأَتِي هَذِهِ مِنَ الزِّنَا."]]},{"id":"um113_4","label":"كِتَابُ اللِّعَانِ · ٤","segs":[["matn","وَيَدْرَأُ عَنْهَا العَذَابَ: أَنْ تَشْهَدَ أَرْبَعَ شَهَادَاتٍ بِاللهِ إِنَّهُ لَمِنَ الْكَاذِبِينَ فِيمَا رَمَانِي بِهِ مِنَ الزِّنَا، ثُمَّ تُوقَفُ عِنْدَ الخَامِسَةِ تُخَوَّفُ كَمَا يُخَوَّفُ الرَّجُلُ،"]]},{"id":"um113_5","label":"كِتَابُ اللِّعَانِ · ٥","segs":[["matn","فَإِنْ أَبَتْ إِلَّا أَنْ تُتِمَّ، فَلْتَقُلْ: وَإِنَّ غَضَبَ اللهِ عَلَيْهَا إِنْ كَانَ مِنَ الصَّادِقِينَ فِيمَا رَمَانِي بِهِ زَوْجِي هَذَا مِنَ الزِّنَا."]]},{"id":"um113_6","label":"كِتَابُ اللِّعَانِ · ٦","segs":[["matn","ثُمَّ يَقُولُ الحَاكِمُ: قَدْ فَرَّقْتُ بَيْنَكُمَا، فَتَحْرُمُ عَلَيْهِ تَحْرِيمًا مُؤَبَّدًا. وَإِنْ كَانَ بَيْنَهُمَا وَلَدٌ فَنَفَاهُ انْتَفَى عَنْهُ، سَوَاءٌ كَانَ حَمْلاً أَوْ مَوْلُودًا، مَا لَمْ يَكُنْ أَقَرَّ بِهِ،"]]},{"id":"um113_7","label":"كِتَابُ اللِّعَانِ · ٧","segs":[["matn","أَوْ وَجَدَ مِنْهُ مَا يَدُلُّ عَلَى الإِقْرَارِ لِمَا رَوَى ابْنُ عُمَرَ أَنَّ رَجُلاً لَاعَنَ امْرَأَتَهُ وَانْتَفَى مِنْ وَلَدِهَا، فَفَرَّقَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْنَهُمَا، وَأَلْحَقَ الوَلَدَ بِالأُمِّ."]]},{"id":"um113_8","label":"كِتَابُ اللِّعَانِ · ٨","segs":[["matn","فَصْلٌ: وَمَنْ وَلَدَتِ امْرَأَتُهُ أَوْ أَمَتُهُ الَّتِي أَقَرَّ بِوَطْئِهَا وَلَدًا يُمْكِنُ كَوْنُهُ مِنْهُ، لَحِقَهُ نَسَبُهُ، لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «الوَلَدُ لِلْفِرَاشِ وَلِلْعَاهِرِ الحَجَرُ،» وَلَا يَنْتَفِي وَلَدُ الْمَرْأَةِ إِلَّا بِاللِّعَانِ، وَلَا وَلَدُ الأَمَةِ إِلَّا بِدَعْوَى عَدَمِ اسْتِبْرَائِهَا."]]},{"id":"um113_9","label":"كِتَابُ اللِّعَانِ · ٩","segs":[["matn","وَإِنْ لَمْ يُمْكِنْ كَوْنُهُ مِنْهُ، مِثْلَ أَنْ تَلِدَ أَمَتُهُ لِأَقَلَّ مِنْ سِتَّةِ أَشْهُرٍ مُنْذُ وَطْئِهَا، أَوِ امْرَأَتُهُ لِأَقَلَّ مِنْ ذَلِكَ مُنْذُ أَمْكَنَ اجْتِمَاعُهُمَا، وَلَوْ كَانَ الزَّوْجُ مِمَّنْ لَا يُولَدُ لِمِثْلِهِ، كَمَنْ لَهُ دُونَ عَشْرِ سِنِينَ، أَوِ الخَصِيِّ وَالْمَجْبُوبِ لَمْ يَلْحَقْهُ."]]},{"id":"um113_10","label":"كِتَابُ اللِّعَانِ · ١٠","segs":[["matn","فَصْلٌ: وَإِذَا وَطِئَ رَجُلَانِ امْرَأَةً فِي طُهْرٍ وَاحِدٍ بِشُبْهَةٍ، أَوْ وَطِئَ رَجُلَانِ شَرِيكَانِ أَمَتَهَمَا فِي طُهْرٍ وَاحِدٍ، فَأَتَتْ بِوَلَدٍ، أَوِ ادَّعَى نَسَبَ مَجْهُولِ النَّسَبِ رَجُلَانِ، أُرِيَ الْقَافَةَ مَعَهُمَا أَوْ مَعَ أَقَارِبِهِمَا، فَأُلْحِقَ بِمَنْ أَلْحَقُوهُ مِنْهُمَا،"]]},{"id":"um113_11","label":"كِتَابُ اللِّعَانِ · ١١","segs":[["matn","فَإِنْ أَلْحَقُوهُ بِهِمَا لَحِقَ بِهِمَا، وَإِنْ أَشْكَلَ أَمْرُهُ، أَوْ تَعَارَضَ قَوْلُ القَافَةِ، أَوْ لَمْ يُوجَدْ قَافَةٌ، تُرِكَ حَتَّى يَبْلُغَ، فَيُلْحَقَ بِمَنِ انْتَسَبَ إِلَيْهِ مِنْهُمَا، وَلَا يُقْبَلُ قَوْلُ القَائِفِ إِلَّا أَنْ يَكُونَ عَدْلاً، مُجَرَّباً فِي الإِصَابَةِ."]]}],"group":"كِتَابُ اللِّعَانِ"},{"id":"um114","title":"بَابُ الحَضَانَةِ","units":[{"id":"um114_1","label":"بَابُ الحَضَانَةِ · ١","segs":[["matn","أَحَقُّ النَّاسِ بِالطِّفْلِ أُمُّهُ، ثُمَّ أُمُّهَاتُهَا وَإِنْ عَلَوْنَ، ثُمَّ الأَبُ، ثُمَّ أُمَّهَاتُهُ، ثُمَّ الجَدُّ، ثُمَّ أُمَّهَاتُهُ، ثُمَّ الأُخْتُ مِنَ الأَبَوَيْنِ، ثُمَّ الأُخْتُ مِنَ الأَبِ، ثُمَّ الأُخْتُ مِنَ الأُمِّ،"]]},{"id":"um114_2","label":"بَابُ الحَضَانَةِ · ٢","segs":[["matn","ثُمَّ الْخَالَةُ ثُمَّ العَمَّةُ، ثُمَّ الأَقْرَبُ فَالأَقْرَبُ مِنَ النِّسَاءِ، ثُمَّ عَصَبَاتُهُ الأَقْرَبُ فَالأَقْرَبُ، وَلَا حَضَانَةَ لِرَقِيقٍ، وَلَا فَاسِقٍ، وَلَا امْرَأَةٍ مُزَوَّجَةٍ لِأَجْنَبِيٍّ مِنَ الطِّفْلِ، فَإِنْ زَالَتِ الْمَوَانِعُ مِنْهُمْ، عَادَ حَقُّهُمْ مِنَ الْحَضَانَةِ."]]},{"id":"um114_3","label":"بَابُ الحَضَانَةِ · ٣","segs":[["matn","وَإِذَا بَلَغَ الغُلَامُ سَبْعَ سِنِينَ، خُيِّرَ بَيْنَ أَبَوَيْهِ، فَكَانَ عِنْدَ مَنِ اخْتَارَ مِنْهُمَا، وَإِذَا بَلَغَتِ الْجَارِيَةُ سَبْعًا، فَأَبُوهَا أَحَقُّ بِهَا."]]},{"id":"um114_4","label":"بَابُ الحَضَانَةِ · ٤","segs":[["matn","وَعَلَى الأَبِ أَنْ يَسْتَرْضِعَ لِوَلَدِهِ، إِلَّا أَنْ تَشَاءَ الأُمُّ أَنْ تُرْضِعَهُ بِأَجْرِ مِثْلِهَا، فَتَكُونُ أَحَقَّ بِهِ مِنْ غَيْرِهَا، سَوَاءٌ كَانَتْ فِي حِبَالِ الزَّوْجِ أَوْ مُطَلَّقَةً، فَإِنْ لَمْ يَكُنْ لَهُ أَبٌ وَلَا مَالٌ، فَعَلَى وَرَثَتِهِ أَجْرُ رَضَاعِهِ، عَلَى قَدْرِ مِيرَاثِهِمْ مِنْهُ."]]}],"group":"كِتَابُ اللِّعَانِ"},{"id":"um115","title":"بَابُ نَفَقَةِ الأَقَارِبِ وَالْمَمَالِيكِ","units":[{"id":"um115_1","label":"بَابُ نَفَقَةِ الأَقَارِبِ وَالْمَمَالِيكِ · ١","segs":[["matn","وَعَلَى الإِنْسَانِ نَفَقَةُ وَالِدَيْهِ وَإِنْ عَلَوْا، وَأَوْلَادِهِ وَإِنْ سَفَلُوا، وَمَنْ يَرِثُهُ بِفَرْضٍ أَوْ تَعْصِيبٍ، إِذَا كَانُوا فُقَرَاءَ، وَلَهُ مَالٌ يُنْفِقُ عَلَيْهِمْ."]]},{"id":"um115_2","label":"بَابُ نَفَقَةِ الأَقَارِبِ وَالْمَمَالِيكِ · ٢","segs":[["matn","وَإِنْ كَانَ لِلْفَقِيرِ وَارِثَانِ فَأَكْثَرَ، فَنَفَقَتُهُ عَلَيْهِمْ عَلَى قَدْرِ مِيرَاثِهِمْ، مِنْهُ، إِلَّا الِابْنَ فَإِنَّ نَفَقَتَهُ عَلَى أَبِيهِ خَاصَّةً."]]},{"id":"um115_3","label":"بَابُ نَفَقَةِ الأَقَارِبِ وَالْمَمَالِيكِ · ٣","segs":[["matn","وَعَلَى مُلَاكِ الْمَمْلُوكِينَ الإِنْفَاقُ عَلَيْهِمْ، وَمَا يَحْتَاجُونَ إِلَيْهِ مِنْ مُؤْنَةٍ وَكِسْوَةٍ فَإِنْ لَمْ يَفْعَلُوا، أُجْبِرُوا عَلَى بَيْعِهِمْ، إِذَا طَلَبُوا ذَلِكَ."]]}],"group":"كِتَابُ اللِّعَانِ"},{"id":"um116","title":"بَابُ الوَلِيمَةِ","units":[{"id":"um116_1","label":"بَابُ الوَلِيمَةِ · ١","segs":[["matn","وَهِيَ: دَعْوَةُ العُرْسِ، وَهِيَ مُسْتَحَبَّةٌ؛ لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِعَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ حِينَ أَخْبَرَهُ أَنَّهُ تَزَوَّجَ: «بَارَكَ اللهُ لَكَ، أَوْلِمْ وَلَوْ بِشَاةٍ،» وَالإِجَابَةُ إِلَيْهَا وَاجِبَةٌ؛"]]},{"id":"um116_2","label":"بَابُ الوَلِيمَةِ · ٢","segs":[["matn","لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «وَمَنْ لَمْ يَجِبْ فَقَدْ عَصَى اللهَ وَرَسُولَهُ،» وَمَنْ لَمْ يُحِبَّ أَنْ يَطْعَمَ، دَعَا وَانْصَرَفَ."]]},{"id":"um116_3","label":"بَابُ الوَلِيمَةِ · ٣","segs":[["matn","وَالنِّثَارُ وَالتِقَاطُهُ مُبَاحٌ مَعَ الكَرَاهَةِ، وَإِنْ قُسِّمَ عَلَى الحَاضِرِينَ، كَانَ أَوْلَى."]]}],"group":"كِتَابُ اللِّعَانِ"},{"id":"um117","title":"كِتَابُ الأَطْعِمَةِ","units":[{"id":"um117_1","label":"كِتَابُ الأَطْعِمَةِ · ١","segs":[["matn","وَهِيَ نَوْعَانِ: حَيَوَانٌ وَغَيْرُهُ، فَأَمَّا غَيْرُ الحَيَوَانِ، فَكُلُّهُ مُبَاحٌ، إِلَّا مَا كَانَ نَجِسًا أَوْ مُضِرًّا، كَالسُّمُومِ، وَالأَشْرِبَةُ كُلُّهَا مُبَاحَةٌ إِلَّا مَا أَسْكَرَ،"]]},{"id":"um117_2","label":"كِتَابُ الأَطْعِمَةِ · ٢","segs":[["matn","فَإِنَّهُ يَحْرُمُ قَلِيلُهُ وَكَثِيرُهُ مِنْ أَيِّ شَيْءٍ كَانَ، لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «كُلُّ مُسْكِرٍ حَرَامٌ، وَمَا أَسْكَرَ مِنْهُ الْفَرَقُ فَمِلْءُ الكَفِّ مِنْهُ حَرَامٌ»."]]},{"id":"um117_3","label":"كِتَابُ الأَطْعِمَةِ · ٣","segs":[["matn","وَإِنْ تَخَلَّلَتِ الخَمْرُ، طَهُرَتْ وَحَلَّتْ، وَإِنْ خُلِّلَتْ، لَمْ تَطْهُرْ."]]},{"id":"um117_4","label":"كِتَابُ الأَطْعِمَةِ · ٤","segs":[["matn","فَصْلٌ: وَالحَيَوَانِ قِسْمَانِ: بَحْرِيٌّ وَبَرِّيٌّ، فَأَمَّا البَحْرِيُّ، فَكُلُّهُ حَلَالٌ، إِلَّا الحَيَّةَ، وَالضِّفْدَعَ، وَالتِّمْسَاحَ، وَأَمَّا البَرِّيُّ فَيَحْرُمُ مِنْهُ كُلُّ ذِي نَابٍ مِنَ السِّبَاعِ،"]]},{"id":"um117_5","label":"كِتَابُ الأَطْعِمَةِ · ٥","segs":[["matn","وَكُلُّ ذِي مِخْلَبٍ مِنَ الطَّيْرِ، كَالنُّسُورِ وَالرَّخَمِ وَغُرَابِ الْبَيْنِ الْأَبْقَعِ وَالحُمُرُ الأَهْلِيَّةُ، وَالبِغَالُ، وَمَا يَأْكُلُ الجِيَفَ مِنَ الطَّيْرِ، وَمَا يَسْتَخْبِثُ مِنَ الحَشَرَاتِ، كَالفَأْرِ وَنَحْوِهَا، إِلَّا اليَرْبُوعَ وَالضَّبَّ؛"]]},{"id":"um117_6","label":"كِتَابُ الأَطْعِمَةِ · ٦","segs":[["matn","لِأَنَّهُ أُكِلَ عَلَى مَائِدَةِ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَنْظُرُ، وَقِيلَ لَهُ: أَحَرَامٌ هُوَ؟"]]},{"id":"um117_7","label":"كِتَابُ الأَطْعِمَةِ · ٧","segs":[["matn","قَالَ: «لَا» وَمَا عَدَا هَذَا مُبَاحٌ، وَيُبَاحُ أَكْلُ الخَيْلِ وَالضَبُعِ؛ لِأَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَذِنَ فِي لُحُومِ الخَيْلِ، وَسَمَّى الضَّبُعَ صَيْدًا."]]}],"group":"كِتَابُ الأَطْعِمَةِ"},{"id":"um118","title":"بَابُ الذَّكَاةِ","units":[{"id":"um118_1","label":"بَابُ الذَّكَاةِ · ١","segs":[["matn","يُبَاحُ كَلُّ مَا فِي البَحْرِ بِغَيْرِ ذَكَاةٍ؛ لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي البَحْرِ: «الحِلُّ مَيْتَتُهُ» إِلَّا مَا يَعِيشُ فِي البَرِّ، فَلَا يَحِلُّ حَتَّى يُذَكَّى، إِلَّا السَّرَطَانَ وَنَحْوَهُ، وَلَا يُبَاحُ مِنَ الْبَرِّيِّ شَيْءٌ بِغَيْرِ ذَكَاةٍ، إِلَّا الجَرَادَ وَشِبْهَهُ."]]},{"id":"um118_2","label":"بَابُ الذَّكَاةِ · ٢","segs":[["matn","وَالذَّكَاةُ تَنْقَسِمُ ثَلَاثَةَ أَقْسَامٍ: نَحْرٍ، وَذَبْحٍ، وَعَقْرٍ. وَيُسْتَحَبُّ نَحْرُ الإِبِلِ، وَذَبْحُ مَا سِوَاهَا، فَإِنْ نَحَرَ مَا يُذْبَحُ أَوْ ذُبِحَ مَا يُنْحَرُ، فَجَائِزٌ، وَيُشْتَرَطُ لِلذَّكَاةِ كُلِّهَا ثَلَاثَةُ شُرُوطٍ: أَحَدُهَا:"]]},{"id":"um118_3","label":"بَابُ الذَّكَاةِ · ٣","segs":[["matn","أَهْلِيَّةُ الْمُذَكِّي، وَهُوَ أَنْ يَكُونَ عَاقِلاً، قَادِرًا عَلَى الذَّبْحِ مُسْلِمًا أَوْ كِتَابِيًّا، فَأَمَّا الطِّفْلُ وَالْمَجْنُونُ وَالسَّكْرَانُ وَالكَافِرُ الَّذِي لَيْسَ بِكِتَابِيٍّ فَلَا تَحِلُّ ذَبِيحَتُهُ."]]},{"id":"um118_4","label":"بَابُ الذَّكَاةِ · ٤","segs":[["matn","الثَّانِي: أَنْ يَذْكُرَ اسْمَ اللَّهِ تَعَالَى عِنْدَ الذَّبْحِ، وَإِرْسَالِ الآلَةِ فِي الصَّيْدِ، إِنْ كَانَ نَاطِقًا، وَإِنْ كَانَ أَخْرَسَ، أَشَارَ إِلَى السَّمَاءِ،"]]},{"id":"um118_5","label":"بَابُ الذَّكَاةِ · ٥","segs":[["matn","فَإِنْ تَرَكَ التَّسْمِيَّةَ عَلَى الذَّبِيحَةِ عَامِدًا، لَمْ تَحِلَّ، وَإِنْ تَرَكَهَا سَاهِيًا، حَلَّتْ، وَإِنْ تَرَكَهَا عَلَى الصَّيْدِ، لَمْ يَحِلَّ، عَمْدًا كَانَ أَوْ سَهْوًا."]]},{"id":"um118_6","label":"بَابُ الذَّكَاةِ · ٦","segs":[["matn","الثَّالِثُ: أَنْ يَذَكِّيَ بِمُحَدَّدٍ، سَوَاءٌ كَانَ مِنْ حَدِيدٍ أَوْ حَجَرٍ أَوْ قَصَبٍ أَوْ غَيْرِهِ، إِلَّا السِّنَّ وَالظُفْرَ؛ لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «مَا أَنْهَرَ الدَّمَ وَذُكِرَ اسْمُ اللهِ عَلَيْهِ، فَكُلْ، لَيْسَ السِّنَّ وَالظُّفْرَ»."]]},{"id":"um118_7","label":"بَابُ الذَّكَاةِ · ٧","segs":[["matn","وَيُعْتَبَرُ فِي الصَّيْدِ أَنْ يَصِيدَ بِمُحَدَّدٍ أَوْ يُرْسِلَ جَارِحًا فَيَجْرَحَ الصَّيْدَ، فَإِنْ قَتَلَ الصَّيْدَ بِحَجَرٍ، أَوْ بُنْدُقٍ أَوْ شَبَكَةٍ، أَوْ قَتَلَ الجَارِحُ الصَّيْدَ بِصَدْمَتِهِ أَوْ خَنْقِهِ أَوْ رَوْعَتِهِ،"]]},{"id":"um118_8","label":"بَابُ الذَّكَاةِ · ٨","segs":[["matn","لَمْ يَحِلَّ، وَإِنْ صَادَ بِالْمِعْرَاضِ، أَكَلَ مَا قُتِلَ بِحَدِّهِ دُونَ مَا قُتِلَ بِعَرْضِهِ، وَإِنْ نَصَبَ الْمَنَاجِيلَ لِلصَّيْدِ وَسَمَّى، فَعَقَرَتِ الصَّيْدَ أَوْ قَتَلَتْهُ، حَلَّ."]]},{"id":"um118_9","label":"بَابُ الذَّكَاةِ · ٩","segs":[["matn","فَصْلٌ: وَيُشْتَرَطُ فِي الذَّبْحِ وَالنَّحْرِ خَاصَّةً شَرْطَانِ: أَحَدُهُمَا: أَنْ يَكُونَ فِي الحَلْقِ وَاللَّبَّةِ، فَيَقْطَعُ الحُلْقُومَ وَالْمَرِيءَ، وَمَا لَا تَبْقَى الحَيَاةُ مَعَ قَطْعِهِ."]]},{"id":"um118_10","label":"بَابُ الذَّكَاةِ · ١٠","segs":[["matn","الثَّانِي: أَنْ يَكُونَ فِي الْمَذْبُوحِ حَيَاةٌ يُذْهِبُهَا الذَّبْحُ، فَإِنْ لَمْ يَكُنْ فِيهِ إِلَّا كَحَيَاةِ المَذْبُوحِ، وَمَا أُبِينَتْ حَشْوَتُهُ، لَمْ يَحِلَّ بِالذَّبْحِ وَلَا النَّحْرِ، وَإِنْ لَمْ يَكُنْ كَذَلِكَ، حَلَّ؛"]]},{"id":"um118_11","label":"بَابُ الذَّكَاةِ · ١١","segs":[["matn","لِمَا رَوَى كَعْبُ قَالَ: كَانَتْ لَنَا غَنَمٌ تَرْعَى بِسَلْعٍ، فَأَبْصَرَتْ جَارِيَةٌ لَنَا شَاةً مَوْتَى فَكَسَرَتْ حَجَراً، فَذَبَحَتْهَا بِهِ، فَسُئِلَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ، فَأَمَرَ بِأَكْلِهَا."]]},{"id":"um118_12","label":"بَابُ الذَّكَاةِ · ١٢","segs":[["matn","وَأَمَّا العَقْرُ، فَهُوَ: القَتْلُ بِجُرْحٍ فِي غَيْرِ الحَلْقِ وَاللَّبَّةِ، وَيُشْرَعُ فِي كُلِّ حَيَوَانٍ مَعْجُوزٍ عَنْهُ مِنَ الصَّيْدِ وَالأَنْعَامِ؛"]]},{"id":"um118_13","label":"بَابُ الذَّكَاةِ · ١٣","segs":[["matn","لِمَا رَوَى أَبُو رَافِعٍ أَنَّ بَعِيرًا نَدَّ فَأَعْيَاهُمْ، فَأَهْوَى إِلَيْهِ رَجُلٌ بِسَهْمٍ فَحَبَسَهُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «إِنَّ لِهَذِهِ الْبَهَائِمِ أَوَابِدَ كَأَوَابِدِ الوَحْشِ، فَمَا غَلَبَكُمْ مِنْهَا، فَاصْنَعُوا بِهِ هَكَذَا»."]]},{"id":"um118_14","label":"بَابُ الذَّكَاةِ · ١٤","segs":[["matn","وَلَوْ تَرَدَّى بَعِيرٌ فِي بِئْرٍ فَتَعَذَّرَ نَحْرُهُ، فَجُرِحَ فِي أَيِّ مَوْضِعٍ مِنْ جَسَدِهِ، فَمَاتَ بِهِ، حَلَّ أَكْلُهُ."]]}],"group":"كِتَابُ الأَطْعِمَةِ"},{"id":"um119","title":"كِتَابُ الصَّيْدِ","units":[{"id":"um119_1","label":"كِتَابُ الصَّيْدِ · ١","segs":[["matn","كُلُّ مَا أَمْكَنَ ذَبْحُهُ مِنَ الصَّيْدِ، لَمْ يُبَحْ إِلَّا بِذَبْحِهِ، وَمَا تَعَذَّرَ ذَبْحُهُ فَمَاتَ بِعَقْرِهِ، حَلَّ بِشُرُوطٍ سِتَّةٍ، ذَكَرْنَا مِنْهَا ثَلَاثَةٌ فِي الذَّكَاةِ."]]},{"id":"um119_2","label":"كِتَابُ الصَّيْدِ · ٢","segs":[["matn","وَالرَّابِعُ: أَنْ يَكُونَ الجَارِحُ الصَّائِدُ مُعَلَّمًا، وَهُوَ: مَا يَسْتَرْسِلُ إِذَا أُرْسِلَ، وَيُجِيبُ إِذَا دُعِيَ، وَيُعْتَبَرُ فِي الكَلْبِ وَالفَهْدِ خَاصَّةً، أَنَّهُ إِذَا أَمْسَكَ لَمْ يَأْكُلْ، وَلَا يُعْتَبَرُ ذَلِكَ فِي الطَّائِرِ."]]},{"id":"um119_3","label":"كِتَابُ الصَّيْدِ · ٣","segs":[["matn","الخَامِسُ: أَنْ يُرْسَلَ الصَّائِدُ الْآلَةَ، فَإِنِ اسْتَرْسَلَ الْكَلْبُ بِنَفْسِهِ، لَمْ يُبَحْ صَيْدُهُ."]]},{"id":"um119_4","label":"كِتَابُ الصَّيْدِ · ٤","segs":[["matn","السَّادِسُ: أَنْ يَقْصِدَ الصَّيْدَ، فَإِنْ أَرْسَلَ سَهْمَهُ، لِيُصِيبَ بِهِ غَرَضًا أَوْ كَلْبَهُ وَلَا يَرَى صَيْدًا، فَأَصَابَ صَيْدًا، لَمْ يُبَحْ."]]},{"id":"um119_5","label":"كِتَابُ الصَّيْدِ · ٥","segs":[["matn","وَمَتَى شَارَكَ فِي الصَّيْدِ مَا لَا يُبَاحُ قَتْلُهُ، مِثْلَ أَنْ يُشَارِكَ كَلْبَهُ أَوْ سَهْمَهُ كَلْبٌ أَوْ سَهْمٌ لَا يَعْلَمُ مُرْسِلَهُ، أَوْ لَا يَعْلَمُ أَنَّهُ سُمِّيَ عَلَيْهِ،"]]},{"id":"um119_6","label":"كِتَابُ الصَّيْدِ · ٦","segs":[["matn","أَوْ رَمَاهُ بِسَهْمٍ مَسْمُومٍ يُعِينُ عَلَى قَتْلِهِ، أَوْ غَرِقَ فِي الْمَاءِ، أَوْ وَجَدَ بِهِ أَثَرًا غَيْرَ أَثَرِ السَّهْمِ أَوِ الكَلْبِ، يُحْتَمَلُ أَنَّهُ مَاتَ بِهِ، لَمْ يَحِلَّ؛"]]},{"id":"um119_7","label":"كِتَابُ الصَّيْدِ · ٧","segs":[["matn","لِمَا رَوَى عَدِيُّ بْنُ حَاتِمٍ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ:"]]},{"id":"um119_8","label":"كِتَابُ الصَّيْدِ · ٨","segs":[["matn","«إِذَا أَرْسَلْتَ كَلْبَكَ الْمُعَلَّمَ، وَذَكَرْتَ اسْمَ اللهِ عَلَيْهِ، فَأَمْسَكَ عَلَيْكَ، فَأَدْرَكْتَهُ حَيًّا فَاذْبَحْهُ، وَإِنْ قَتَلَ وَلَمْ يَأْكُلْ مِنْهُ، فَكُلْهُ،"]]},{"id":"um119_9","label":"كِتَابُ الصَّيْدِ · ٩","segs":[["matn","فَإِنَّ أَخْذَ الكَلْبِ لَهُ ذَكَاةٌ، فَإِنْ أَكَلَ فَلَا تَأْكُلْ، فَإِنِّي أَخَافُ أَنْ يَكُونَ إِنَّمَا أَمْسَكَ عَلَى نَفْسِهِ، وَإِنْ خَالَطَهَا كِلَابٌ مِنْ غَيْرِهَا، فَلَا تَأْكُلْ،"]]},{"id":"um119_10","label":"كِتَابُ الصَّيْدِ · ١٠","segs":[["matn","فَإِنَّكَ إِنَّمَا سَمَّيْتَ عَلَى كَلْبِكَ وَلَمْ تُسَمِّ عَلَى غَيْرِهِ، وَإِذَا أَرْسَلْتَ سَهْمَكَ، فَاذْكُرِ اسْمَ اللهِ عَلَيْهِ، وَإِنْ غَابَ عَنْكَ يَوْمًا أَوْ يَوْمَيْنِ وَلَمْ تَجِدْ فِيهِ إِلَّا أَثَرَ سَهْمِكَ،"]]},{"id":"um119_11","label":"كِتَابُ الصَّيْدِ · ١١","segs":[["matn","فَكُلْهُ إِنْ شِئْتَ، وَإِنْ وَجَدْتَهُ غَرِيقًا فِي الْمَاءِ، فَلَا تَأْكُلْ فَإِنَّكَ لَا تَدْرِي الْمَاءُ قَتَلَهُ أَوْ قَتَلَهُ سَهْمُكَ»."]]}],"group":"كِتَابُ الصَّيْدِ"},{"id":"um120","title":"بَابُ الْمُضْطَرِّ","units":[{"id":"um120_1","label":"بَابُ الْمُضْطَرِّ · ١","segs":[["matn","وَمَنِ اضْطُرَّ فِي مَخْمَصَةٍ، فَلَمْ يَجِدْ إِلَّا مُحَرَّمًا، فَلَهُ أَنْ يَأْكُلَ مِنْهُ مَا يَسُدُّ رَمَقَهُ. وَإِنْ وَجَدَ مُتَّفَقًا عَلَى تَحْرِيمِهِ وُمُخْتَلَفًا فِيهِ، أَكَلَ مِنَ الْمُخْتَلَفِ فِيهِ."]]},{"id":"um120_2","label":"بَابُ الْمُضْطَرِّ · ٢","segs":[["matn","فَإِنْ لَمْ يَجِدْ إِلَّا طَعَامًا لِغَيْرِهِ، بِهِ مِثْلُ ضَرُورَتِهِ، لَمْ يُبَحْ لَهُ أَخْذُهُ، وَإِنْ كَانَ مُسْتَغْنِيًا عَنْهُ، أَخَذَهُ مِنْهُ بِثَمَنِهِ،"]]},{"id":"um120_3","label":"بَابُ الْمُضْطَرِّ · ٣","segs":[["matn","فَإِنْ مَنَعَهُ مِنْهُ، أَخَذَهُ قَهْرًا، وَضَمِنَهُ لَهُ مَتَى قَدِرَ، فَإِنْ قُتِلَ الْمَضْطَرُّ، فَهُوَ شَهِيدٌ، وَعَلَى قَاتِلِهِ ضَمَانُهُ، وَإِنْ قُتِلَ الْمَانِعُ، فَلَا ضَمَانَ فِيهِ."]]},{"id":"um120_4","label":"بَابُ الْمُضْطَرِّ · ٤","segs":[["matn","وَلَا يُبَاحُ التَّدَاوِي بِمُحَرَّمٍ، وَلَا شُرْبُ الخَمْرِ لِمَنْ عَطِشَ، وَيُبَاحُ دَفْعُ الغُصَّةِ بِهَا، إِذَا لَمْ يَجِدْ مَائِعًا غَيْرَهَا."]]}],"group":"كِتَابُ الصَّيْدِ"},{"id":"um121","title":"بَابُ النَّذْرِ","units":[{"id":"um121_1","label":"بَابُ النَّذْرِ · ١","segs":[["matn","مَنْ نَذَرَ طَاعَةً، لَزِمَهُ فِعْلُهَا؛ لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «مَنْ نَذَرَ أَنْ يُطِيعَ اللهَ، فَلْيُطِعْهُ،» فَإِنْ كَانَ لَا يُطِيقُهَا كَشَيْخٍ نَذَرَ صِيَامًا لَا يُطِيقُهُ، فَعَلَيْهِ كَفَّارَةُ يَمِينٍ؛"]]},{"id":"um121_2","label":"بَابُ النَّذْرِ · ٢","segs":[["matn","لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «مَنْ نَذَرَ نَذْرًا لَا يُطِيقُهُ، فَكَفَّارَتُهُ كَفَّارَةُ يَمِينٍ»."]]},{"id":"um121_3","label":"بَابُ النَّذْرِ · ٣","segs":[["matn","وَمَنْ نَذَرَ الْمَشْيَ إِلَى بَيْتِ اللهِ الْحَرَامِ، لَمْ يَجْزِهِ الْمَشْيُ إِلَّا فِي حَجٍّ أَوْ عُمْرَةٍ، فَإِنْ عَجَزَ عَنِ الْمَشْيِ، رَكِبَ وَكَفَّرَ."]]},{"id":"um121_4","label":"بَابُ النَّذْرِ · ٤","segs":[["matn","وَإِنْ نَذَرَ صَوْمًا مُتَتَابِعًا، فَعَجَزَ عَنِ التَّتَابُعِ، صَامَ مُتَفَرِّقًا، وَكَفَّرَ، وَإِنْ تَرَكَ التَّتَابُعَ لِعُذْرٍ فِي أَثْنَائِهِ، خُيِّرَ بَيْنَ اسْتِئْنَافِهِ وَبَيْنَ الْبِنَاءِ وَالتَّكْفِيرِ، وَإِنْ تَرَكَهُ لِغَيْرِ عُذْرٍ وَجَبَ اسْتِئْنَافُهُ."]]},{"id":"um121_5","label":"بَابُ النَّذْرِ · ٥","segs":[["matn","وَإِنْ نَذَرَ مُعَيَّنًا، فَأَفْطَرَ فِي بَعْضِهِ، أَتَمَّهُ وَقَضَى، وَكَفَّرَ بِكُلِّ حَالٍ. وَإِنْ نَذَرَ وَجَبَ، وَإِنْ نَذَرَ رَقَبَةً، فَهِيَ الَّتِي تُجْزِئُ عَنِ الْوَاجِبِ، إِلَّا أَنْ يَنْوِيَ رَقَبَةً بِعَيْنِهَا."]]},{"id":"um121_6","label":"بَابُ النَّذْرِ · ٦","segs":[["matn","وَلَا نَذْرَ فِي مَعْصِيَةٍ، وَلَا مُبَاحٍ، فِيمَا لَا يَمْلِكُ ابْنُ آدَمَ وَلَا فِيمَا قَصَدَ بِهِ الْيَمِينَ؛"]]},{"id":"um121_7","label":"بَابُ النَّذْرِ · ٧","segs":[["matn","لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «لَا نَذْرَ فِي مَعْصِيَةٍ اللَّهِ، وَلَا فِيمَا لَا يَمْلِكُ ابْنُ آدَمَ» وَقَالَ: «لَا نَذْرَ إِلَّا فِيمَا ابْتُغِيَ بِهِ وَجْهُ اللهِ سُبْحَانَهُ»."]]},{"id":"um121_8","label":"بَابُ النَّذْرِ · ٨","segs":[["matn","وَإِنْ جَمَعَ فِي النَّذْرِ بَيْنَ الطَّاعَةِ وَغَيْرِهَا، فَعَلَيْهِ الْوَفَاءُ بِالطَّاعَةِ وَحْدَهَا؛"]]},{"id":"um121_9","label":"بَابُ النَّذْرِ · ٩","segs":[["matn","لِمَا رَوَى ابْنُ عَبَّاسٍ قَالَ: أَبْصَرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَجُلاً قَائِمًا فَسَأَلَ عَنْهُ، فَقَالُوا: أَبُو إِسْرَائِيلَ، نَذَرَ أَنْ يَقُومَ فِي الشَّمْسِ وَلَا يَقْعُدَ وَلَا يَسْتَظِلَّ وَلَا يَتَكَلَّمَ، وَيَصُومَ، فَقَالَ: «مُرُوهُ فَلْيَتَكَلَّمْ وَلْيَسْتَظِلَّ وَلْيَقْعُدْ وَلْيُتِمَّ صَوْمَهُ»."]]},{"id":"um121_10","label":"بَابُ النَّذْرِ · ١٠","segs":[["matn","وَإِنْ قَالَ: لِلَّهِ عَلَيَّ نَذْرٌ، وَلَمْ يُسَمِّهِ، فَعَلَيْهِ كَفَّارَةُ يَمِينٍ."]]}],"group":"كِتَابُ الصَّيْدِ"},{"id":"um122","title":"كِتَابُ الأَيْمَانِ","units":[{"id":"um122_1","label":"كِتَابُ الأَيْمَانِ · ١","segs":[["matn","وَمَنْ حَلَفَ أَنْ لَا يَفْعَلَ شَيْئًا، فَفَعَلَهُ، أَوْ لَيَفْعَلَنَّهُ فِي وَقْتٍ، فَلَمْ يَفْعَلْهُ فِيهِ، فَعَلَيْهِ كَفَّارَةٌ، يَمِينٍ إِلَّا أَنْ يَقُولَ: إِنْ شَاءَ اللهُ مُتَّصِلاً بِيَمِينِهِ، أَوْ يَفْعَلَهُ مُكْرَهًا أَوْ نَاسِيًا، فَلَا كَفَّارَةَ عَلَيْهِ."]]},{"id":"um122_2","label":"كِتَابُ الأَيْمَانِ · ٢","segs":[["matn","وَلَا كَفَّارَةَ فِي الْحَلْفِ عَلَى مَاضٍ، سَوَاءٌ تَعَمَّدَ الْكَذِبَ أَوْ ظَنَّهُ كَمَا حَلَفَ، فَلَمْ يَكُنْ، وَلَا فِي اليَمِينِ الجَارِيَةِ عَلَى لِسَانِهِ مِنْ غَيْرِ قَصْدٍ إِلَيْهَا، كَقَوْلِهِ فِي عَرْضِ حَدِيثِهِ: لَا وَاللهِ، وَبَلَى وَاللهِ؛"]]},{"id":"um122_3","label":"كِتَابُ الأَيْمَانِ · ٣","segs":[["matn","لِقَوْلِ اللهِ تَعَالَى: ﴿لَا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ﴾."]]},{"id":"um122_4","label":"كِتَابُ الأَيْمَانِ · ٤","segs":[["matn","وَلَا تَجِبُ الْكَفَّارَةُ إِلَّا فِي الْيَمِينِ بِاللهِ تَعَالَى، أَوِ اسْمٍ مِنْ أَسْمَائِهِ، أَوْ صِفَةٍ مِنْ صِفَاتِ ذَاتِهِ، كَعِلْمِهِ، وَكَلَامِهِ، وَعِزَّتِهِ، وَقُدْرَتِهِ، وَعَظَمَتِهِ، وَعَهْدِهِ، وَمِيثَاقِهِ، وَأَمَانَتِهِ، إِلَّا فِي النَّذْرِ الَّذِي يُقْصَدُ بِهِ الْيَمِينُ، فَإِنَّ كَفَّارَتَهُ كَفَّارَةُ يَمِينٍ."]]},{"id":"um122_5","label":"كِتَابُ الأَيْمَانِ · ٥","segs":[["matn","وَلَوْ حَلَفَ بِهَذَا كُلِّهِ، وَالْقُرْآنِ جَمِيعِهِ فَحَنِثَ، أَوْ كَرَّرَ الْيَمِينَ عَلَى شَيْءٍ وَاحِدٍ قَبْلَ التَّكْفِيرِ، أَوْ حَلَفَ عَلَى أَشْيَاءَ بِيَمِينٍ وَاحِدَةٍ، لَمْ يَلْزَمْهُ أَكْثَرُ مِنْ كَفَّارَةٍ، وَإِنْ حَلَفَ أَيْمَانًا عَلَى شَيْءٍ فَعَلَيْهِ لِكُلِّ يَمِينٍ كَفَّارَتُهَا."]]},{"id":"um122_6","label":"كِتَابُ الأَيْمَانِ · ٦","segs":[["matn","وَمَنْ تَأَوَّلَ فِي يَمِينِهِ، فَلَهُ تَأْوِيلُهُ، إِلَّا أَنْ يَكُونَ ظَالِمًا، فَلَا يَنْفَعُهُ تَأْوِيلُهُ؛ لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «يَمِينُكَ عَلَى مَا يُصَدِّقُكَ بِهِ صَاحِبُكَ»."]]}],"group":"كِتَابُ الأَيْمَانِ"},{"id":"um123","title":"بَابُ جَامِعِ الأَيْمَانِ","units":[{"id":"um123_1","label":"بَابُ جَامِعِ الأَيْمَانِ · ١","segs":[["matn","وَيُرْجَعُ فِيهَا إِلَى النِّيَّةِ، فِيمَا يَحْتَمِلُهُ اللَّفْظُ، فَإِذَا حَلَفَ لَا يُكَلِّمَ رَجُلاً، يُرِيدُ وَاحِدًا بِعَيْنِهِ، أَوْ لَا يَتَغَدَّى، يُرِيدُ غَدَاءً بِعَيْنِهِ، اخْتَصَّتْ يَمِينُهُ بِهِ،"]]},{"id":"um123_2","label":"بَابُ جَامِعِ الأَيْمَانِ · ٢","segs":[["matn","وَإِنْ حَلَفَ لَا يَشْرَبُ لَهُ الْمَاءَ مِنَ الْعَطَشِ، يُرِيدُ قَطْعَ مِنَّتِهِ، حَنِثَ بِكُلِّ مَا فِيهِ مِنَّةٌ، وَإِنْ حَلَفَ لَا يَلْبَسُ ثَوْبًا مِنْ غَزْلِهَا، يُرِيدُ قَطْعَ مِنَّتِهَا، فَبَاعَهُ وَانتَفَعَ بِثَمَنِهِ، حَنِثَ."]]},{"id":"um123_3","label":"بَابُ جَامِعِ الأَيْمَانِ · ٣","segs":[["matn","وَإِنْ حَلَفَ لَيَقْضِيَنَّهُ حَقَّهُ غَدًا، يُرِيدُ أَنْ لَا يَتَجَاوَزَهُ، فَقَضَاهُ الْيَوْمَ، لَمْ يَحْنَثْ، وَإِنْ حَلَفَ لَا يَبِيعَ ثَوْبَهُ إِلَّا بِمِئَةٍ، فَبَاعَهُ بِأَكْثَرَ مِنْهَا، لَمْ يَحْنَثْ، إِذَا أَرَادَ أَنْ لَا يَنْقُصَهُ عَنْ مِئَةٍ."]]},{"id":"um123_4","label":"بَابُ جَامِعِ الأَيْمَانِ · ٤","segs":[["matn","وَإِنْ حَلَفَ لَيَتَزَوَجَنَّ عَلَى امْرَأَتِهِ، يُرِيدُ غَيْظَهَا، لَمْ يَبَرَّ إِلَّا بِتَزَوُّجٍ يَغِيظُهَا بِهِ وَإِنْ حَلَفَ لَيَضْرِبَنَّهَا، يُرِيدُ تَأْلِيمَهَا، لَمْ يَبَرَّ إِلَّا بِضَرْبٍ يُؤْلِمُهَا، وَإِنْ حَلَفَ لَيَضْرِبَنَّهَا عَشْرَةَ أَسْوَاطٍ، فَجَمَعَهَا فَضَرَبَهَا ضَرْبَةً وَاحِدَةً، لَمْ يَبَرَّ."]]},{"id":"um123_5","label":"بَابُ جَامِعِ الأَيْمَانِ · ٥","segs":[["matn","فَإِنْ عَدِمَتِ النِّيَّةُ، رَجَعَ إِلَى سَبَبِ الْيَمِينِ وَمَا هَيَّجَهَا، فَيَقُومُ مَقَامَ نِيَّتِهِ، لِدِلَالَتِهِ عَلَيْهَا، فَإِنْ عُدِمَ ذَلِكَ، حُمِلَتْ يَمِينُهُ عَلَى ظَاهِرِ لَفْظِهِ فَإِنْ كَانَ لَهُ عُرْفٌ شَرْعِيٌّ، كَالصَّلَاةِ وَالزَّكَاةِ، حُمِلَتْ يَمِينُهُ عَلَيْهِ، وَتَنَاوَلَتْ صَحِيحَهُ، وَلَوْ حَلَفَ لَا يَبِيعُ،"]]},{"id":"um123_6","label":"بَابُ جَامِعِ الأَيْمَانِ · ٦","segs":[["matn","فَبَاعَ بَيْعًا فَاسِدًا، لَمْ يَحْنَثْ، إِلَّا أَنْ يُضِيفَهُ إِلَى مَا لَا يَصِحُّ بَيْعُهُ، كَالْحُرِّ وَالْخَمْرِ، فَتَتَنَاوَلَ يَمِينُهُ صُورَةَ الْبَيْعِ، وَإِنْ لَمْ يَكُنْ لَهُ عُرْفٌ شَرْعِيٌّ وَكَانَ لَهُ عُرْفٌ فِي الْعَادَةِ، كَالرَّاوِيَةِ وَالظَّعِينَةِ، حُمِلَتْ يَمِينُهُ عَلَيْهِ، فَلَوْ حَلَفَ لَا يَرْكَبُ دَابَّةً،"]]},{"id":"um123_7","label":"بَابُ جَامِعِ الأَيْمَانِ · ٧","segs":[["matn","فَيَمِينُهُ عَلَى الْخَيْلِ وَالْبِغَالِ وَالْحَمِيرِ، وَإِنْ حَلَفَ لَا يَشَمُّ الرَّيْحَانَ، فَيَمِينُهُ عَلَى الْفَارِسِي، وَإِنْ حَلَفَ لَا يَأْكُلُ شِوَاءً، حَنِثَ بِأَكْلِ اللَّحْمِ دُونَ غَيْرِهِ، وَالشِّوَاءُ: هُوَ اللَّحْمُ الْمَشْوِيُّ وَإِنْ حَلَفَ لَا يَطَأُ امْرَأَتَهُ، حَنِثَ بِجِمَاعِهَا، وَإِنْ حَلَفَ لَا يَطَأُ دَارًا،"]]},{"id":"um123_8","label":"بَابُ جَامِعِ الأَيْمَانِ · ٨","segs":[["matn","حَنِثَ بِدُخُولِهَا كَيْفَ مَا كَانَ، وَإِنْ حَلَفَ لَا يَأْكُلُ لَحْمًا وَلَا رَأْسًا وَلَا بَيْضًا، فَيَمِينُهُ عَلَى كُلِّ لَحْمٍ وَرَأْسِ كُلِّ حَيَوَانٍ وَبَيْضِهِ، وَالأُدْمُ كُلُّ مَا جَرَتِ الْعَادَةُ بِأَكْلِ الْخُبْزِ بِهِ، مِنْ مَائِعٍ وَجَامِدٍ، كَاللَّحْمِ، وَالْبَيْضِ، وَالْمِلْحِ، وَالْجُبْنِ، وَالزَّيْتُونِ."]]},{"id":"um123_9","label":"بَابُ جَامِعِ الأَيْمَانِ · ٩","segs":[["matn","وَإِنْ حَلَفَ لَا يَسْكُنُ دَارًا، تَنَاوَلَ مَا يُسَمَّى سَكَنًا، فَإِنْ كَانَ سَاكِنًا بِهَا، فَأَقَامَ بَعْدَمَا أَمْكَنَهُ الْخُرُوجُ مِنْهَا، حَنِثَ، وَإِنْ قَامَ لِنَقْلِ قُمَاشِهِ، أَوْ كَانَ لَيْلاً، فَأَقَامَ حَتَّى يَصْبَحَ، أَوْ خَافَ عَلَى نَفْسِهِ، فَأَقَامَ حَتَّى أَمِنَ، لَمْ يَحْنَثْ."]]}],"group":"كِتَابُ الأَيْمَانِ"},{"id":"um124","title":"بَابُ كَفَّارَةِ الْيَمِينِ","units":[{"id":"um124_1","label":"بَابُ كَفَّارَةِ الْيَمِينِ · ١","segs":[["matn","وَكَفَّارَتُهَا: ﴿إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلَاثَةِ أَيَّامٍ﴾."]]},{"id":"um124_2","label":"بَابُ كَفَّارَةِ الْيَمِينِ · ٢","segs":[["matn","وَهُوَ مُخَيَّرٌ بَيْنَ تَقْدِيمِ الْكَفَّارَةِ عَلَى الْحِنْثِ أَوْ تَأْخِيرُهَا عَنْهُ؛ لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «مَنْ حَلَفَ عَلَى يَمِينٍ فَرَأَى غَيْرَهَا خَيْرًا مِنْهَا فَلْيُكَفِّرْ عَنْ يَمِينِهِ وَلْيَأْتِ الَّذِي هُوَ خَيْرٌ،» وَرُوِيَ: «فَلْيَأْتِ الَّذِي هُوَ خَيْرٌ، وَلْيُكَفِّرْ عَنْ يَمِينِهِ»."]]},{"id":"um124_3","label":"بَابُ كَفَّارَةِ الْيَمِينِ · ٣","segs":[["matn","وَيُجْزِئُهُ فِي الْكِسْوَةِ مَا تَجُوزُ الصَّلَاةُ فِيهِ، لِلرَّجُلِ ثَوْبٌ، وَلِلْمَرْأَةِ دِرْعٌ وَخِمَارٌ."]]},{"id":"um124_4","label":"بَابُ كَفَّارَةِ الْيَمِينِ · ٤","segs":[["matn","وَيُجْزِئُهُ أَنْ يُطْعِمَ خَمْسَةَ مَسَاكِينَ، وَيَكْسُوَ خَمْسَةً، وَلَوْ أَعْتَقَ نِصْفَ رَقَبَةٍ أَوْ أَطْعَمَ خَمْسَةً، أَوْ كَسَاهُمْ، أَوْ أَعْتَقَ نِصْفَ عَبْدَيْنِ، لَمْ يُجْزِهِ."]]},{"id":"um124_5","label":"بَابُ كَفَّارَةِ الْيَمِينِ · ٥","segs":[["matn","وَلَا يُكَفِّرُ الْعَبْدُ إِلَّا بِالصِّيَامِ، وَيُكَفِّرُ بِالصَّوْمِ مَنْ لَمْ يَجِدْ مَا يُكَفِّرُ بِهِ، فَاضِلاً عَنْ مُؤْنَتِهِ، وَمُؤْنَةِ عِيَالِهِ وَقَضَاءِ دَيْنِهِ."]]},{"id":"um124_6","label":"بَابُ كَفَّارَةِ الْيَمِينِ · ٦","segs":[["matn","وَلَا يَلْزَمُهُ أَنْ يَبِيعَ فِي ذَلِكَ شَيْئًا يَحْتَاجُ إِلَيْهِ مِنْ مَسْكَنٍ، وَخَادِمٍ، وَأَثَاثٍ، وَكُتُبٍ، وَآنِيَةٍ، وَبِضَاعَةٍ يَخْتَلُّ رِبْحُهَا الْمُحْتَاجُ إِلَيْهِ. وَمَنْ أَيْسَرَ بَعْدَ شُرُوعِهِ فِي الصَّوْمِ، لَمْ يَلْزَمْهُ الِانْتِقَالُ عَنْهُ."]]},{"id":"um124_7","label":"بَابُ كَفَّارَةِ الْيَمِينِ · ٧","segs":[["matn","وَمَنْ لَمْ يَجِدْ إِلَّا مِسْكِينًا وَاحِدًا، رَدَّدَ عَلَيْهِ عَشَرَةَ أَيَّامٍ."]]}],"group":"كِتَابُ الأَيْمَانِ"},{"id":"um125","title":"كِتَابُ الْجِنَاياتِ","units":[{"id":"um125_1","label":"كِتَابُ الْجِنَاياتِ · ١","segs":[["matn","القَتْلُ بِغَيْرِ حَقٍّ يَنْقَسِمُ إِلَى ثَلَاثَةَ أَقْسَامٍ: أَحَدُهَا: العَمْدُ وَهُوَ: أَنْ يَقْتُلَهُ بِجُرْحٍ، أَوْ فِعْلٍ يَغْلِبُ عَلَى الظَّنِّ أَنَّهُ يَقْتُلُهُ، كَضَرْبِهِ بِمُثَقَّلٍ كَبِيرٍ،"]]},{"id":"um125_2","label":"كِتَابُ الْجِنَاياتِ · ٢","segs":[["matn","أَوْ تَكْرِيرِهِ بِصَغِيرٍ، أَوْ إِلْقَائِهِ مِنْ شَاهِقٍ، أَوْ خَنْقِهِ أَوْ تَحْرِيقِهِ، أَوْ تَغْرِيقِهِ، أَوْ سَقْيِهِ سُمًّا، أَوِ الشَّهَادَةِ عَلَيْهِ زُورًا بِمَا يُوجِبُ قَتْلَهُ،"]]},{"id":"um125_3","label":"كِتَابُ الْجِنَاياتِ · ٣","segs":[["matn","أَوِ الحُكْمَ عَلَيْهِ بِهِ، أَوْ نَحْوِ هَذَا، قَاصِدًا، عَالِمًا بِكَوْنِ الْمَقْتُولِ آدَمِيًّا مَعْصُومًا، فَهَذَا يُخَيَّرُ الوَلِيُّ فِيهِ بَيْنَ القَوَدِ وَالدِّيَةِ، لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ:"]]},{"id":"um125_4","label":"كِتَابُ الْجِنَاياتِ · ٤","segs":[["matn","«مَنْ قُتِلَ لَهُ قَتِيلٌ، فَهُوَ بِخَيْرِ النَّظَرَيْنِ، إِمَّا أَنْ يُقْتَلَ، وَإِمَّا أَنْ يُفْدَى،» وَإِنْ صَالَحَ القَاتِلُ عَنِ الْقَوَدِ بِأَكْثَرَ مِنْ دِيَةٍ جَازَ."]]},{"id":"um125_5","label":"كِتَابُ الْجِنَاياتِ · ٥","segs":[["matn","الثَّانِي: شِبْهُ العَمْدِ، وَهُوَ: أَنْ يَتَعَمَّدَ الْجِنَايَةَ عَلَيْهِ بِمَا لَا يَقْتُلُهُ غَالِبًا، فَلَا قَوَدَ فِيهِ، وَالدِّيَةُ عَلَى العَاقِلَةِ."]]},{"id":"um125_6","label":"كِتَابُ الْجِنَاياتِ · ٦","segs":[["matn","الثَّالِثُ: الخَطَأُ وَهُوَ نَوْعَانِ: أَحَدُهُمَا: أَنْ يَفْعَلَ مَا لَا يُرِيدُ بِهِ الْمَقْتُولَ، فَيُفْضِي إِلَى قَتْلِهِ، أَوْ يَتَسَبَّبَ إِلَى قَتْلِهِ بِحَفْرِ بِئْرٍ أَوْ نَحْوِهِ وَقَتْلُ النَّائِمِ وَالصَّبِيِّ وَالْمَجْنُونِ، فَحُكْمُهُ حُكْمُ شِبْهِ العَمْدِ."]]},{"id":"um125_7","label":"كِتَابُ الْجِنَاياتِ · ٧","segs":[["matn","النَّوْعُ الثَّانِي: أَنْ يَقْتُلَ مُسْلِمًا فِي دَارِ الحَرْبِ يَظُنُّهُ حَرْبِيًّا، أَوْ يَقْصِدَ رَمْيَ صَفِّ الكُفَّارِ، فَيُصِيبُ سَهْمُهُ مُسْلِمًا، فَفِيهِ كَفَّارَةٌ بِلَا دِيَةٍ؛ لِقَوْلِ اللهِ تَعَالَى: ﴿فَإِنْ كَانَ مِنْ قَوْمٍ عَدُوٍّ لَكُمْ وَهُوَ مُؤْمِنٌ فَتَحْرِيرُ رَقَبَةٍ مُؤْمِنَةٍ﴾."]]}],"group":"كِتَابُ الْجِنَاياتِ"},{"id":"um126","title":"بَابُ شُرُوطِ وُجُوبِ القِصَاصِ وَاسْتِيفَائِهِ","units":[{"id":"um126_1","label":"بَابُ شُرُوطِ وُجُوبِ القِصَاصِ وَاسْتِيفَائِهِ · ١","segs":[["matn","وَيُشْتَرَطُ لِوُجُوبِهِ أَرْبَعَةُ شُرُوطٍ: أَحَدُهَا: كَوْنُ القَاتِلِ مُكَلَّفًا، فَأَمَّا الصَّبِيُّ وَالْمَجْنُونُ فَلَا قِصَاصَ عَلَيْهِمَا."]]},{"id":"um126_2","label":"بَابُ شُرُوطِ وُجُوبِ القِصَاصِ وَاسْتِيفَائِهِ · ٢","segs":[["matn","الثَّانِي: كَوْنُ الْمَقْتُولِ مَعْصُومًا، فَإِنْ كَانَ حَرْبِيًّا، أَوْ مُرْتَدًّا، أَوْ قَاتِلاً فِي الُمَحَارَبَةِ، أَوْ زَانِيًا مُحْصَنًا، أَوْ قَتْلُهُ دَفْعًا عَنْ نَفْسِهِ، أَوْ مَالِهِ، أَوْ حُرْمَتِهِ، فَلَا ضَمَانَ فِيهِ."]]},{"id":"um126_3","label":"بَابُ شُرُوطِ وُجُوبِ القِصَاصِ وَاسْتِيفَائِهِ · ٣","segs":[["matn","الثَّالِثُ: كَوْنُ الْمَقْتُولِ مُكَافِئًا لِلْجَانِي فَيُقْتَلُ الحُرُّ المُسْلِمُ بِالحُرِّ المُسْلِمِ، ذَكَرًا كَانَ أَوْ أُنْثَى، وَلَا يُقْتَلُ حُرٌّ بِعَبْدٍ، وَلَا مُسْلِمٌ بِكَافِرٍ؛"]]},{"id":"um126_4","label":"بَابُ شُرُوطِ وُجُوبِ القِصَاصِ وَاسْتِيفَائِهِ · ٤","segs":[["matn","لِقَوْلِ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «لَا يُقْتَلُ مُؤْمِنٌ بِكَافِرٍ،» وَيُقْتَلُ الذِّمِّيُّ بِالذِّمِّيِّ وَيُقْتَلُ الذِّمِّيُّ بِالْمُسْلِمِ، وَيُقْتَلُ الْعَبْدُ بِالْعَبْدِ، وَيُقْتَلُ الْحُرُّ بِالحُرِّ."]]},{"id":"um126_5","label":"بَابُ شُرُوطِ وُجُوبِ القِصَاصِ وَاسْتِيفَائِهِ · ٥","segs":[["matn","الرَّابِعُ: أَنْ لَا يَكُونَ أَبًاًّ لِلْمَقْتُولِ، فَلَا يُقْتَلُ وَالِدٌ بِوَلَدِهِ وَإِنْ سَفَلَ، وَالأَبَوَانِ فِي هَذَا سَوَاءٌ، وَلَوْ كَانَ وَلِيُّ الدَّمِ وَلَدًا، أَوْ لَهُ فِيهِ حَقٌّ وَإِنْ قَلَّ، لَمْ يَجِبِ القَوَدُ."]]},{"id":"um126_6","label":"بَابُ شُرُوطِ وُجُوبِ القِصَاصِ وَاسْتِيفَائِهِ · ٦","segs":[["matn","فَصْلٌ: وَيُشْتَرَطُ لِجَوَازِ اسْتِيفَائِهِ شُرُوطٌ ثَلَاثَةٌ: أَحَدُهَا: أَنْ يَكُونَ لِمُكَلَّفٍ، فَإِنْ كَانَ لِغَيْرِهِ، أَوْ لَهُ فِيهِ حَقٌّ وَإِنْ قَلَّ، لَمْ يَجُزِ اسْتِيفَاؤُهُ، وَإِنِ اسْتَوْفَى غَيْرُ الْمُكَلَّفِ حَقَّهُ بِنَفْسِهِ، أَجْزَأَ ذَلِكَ."]]},{"id":"um126_7","label":"بَابُ شُرُوطِ وُجُوبِ القِصَاصِ وَاسْتِيفَائِهِ · ٧","segs":[["matn","الثَّانِي: اتِّفَاقُ جَمِيعِ الْمُسْتَحِقِّينَ عَلَى اسْتِيفَائِهِ، فَإِنْ لَمْ يَأْذَنْ فِيهِ بَعْضُهُمْ، أَوْ كَانَ فِيهِمْ غَائِبٌ، لَمْ يَجُزِ اسْتِيفَاؤُهُ، فَإِنِ اسْتَوْفَاهُ بَعْضُهُمْ،"]]},{"id":"um126_8","label":"بَابُ شُرُوطِ وُجُوبِ القِصَاصِ وَاسْتِيفَائِهِ · ٨","segs":[["matn","فَلَا قِصَاصَ عَلَيْهِ، وَعَلَيْهِ بَقِيَّةُ دِيَتِهِ لَهُ، وَلِشُرَكَائِهِ حَقُّهُمْ فِي تَرِكَةِ الْجَانِي، وَيَسْتَحِقُّ القِصَاصَ كُلُّ مَنْ يَرِثُ الْمَالَ عَلَى قَدْرِ مَوَارِيثِهِمْ."]]},{"id":"um126_9","label":"بَابُ شُرُوطِ وُجُوبِ القِصَاصِ وَاسْتِيفَائِهِ · ٩","segs":[["matn","الثَّالِثُ: الأَمْنُ مِنَ التَّعَدِّي فِي الِاسْتِيفَاءِ، فَلَوْ كَانَ الجَانِي حَامِلاً، لَمْ يَجُزِ اسْتِيفَاءُ الْقِصَاصِ مِنْهَا فِي نَفْسٍ وَلَا جُرْحٍ، وَلَا اسْتِيفَاءُ حَدٍّ مِنْهَا، حَتَّى تَضَعَ وَلَدَهَا، وَيَسْتَغْنِيَ عَنْهَا."]]},{"id":"um126_10","label":"بَابُ شُرُوطِ وُجُوبِ القِصَاصِ وَاسْتِيفَائِهِ · ١٠","segs":[["matn","فَصْلٌ: وَيَسْقُطُ بَعْدَ وُجُوبِهِ بِأُمُورٍ ثَلَاثَةٍ: أَحَدُهَا: العَفْوُ عَنْهُ، أَوْ عَنْ بَعْضِهِ، فَإِنْ عَفَا بَعْضُ الوَرَثَةِ عَنْ حَقِّهِ أَوْ عَنْ بَعْضِهِ،"]]},{"id":"um126_11","label":"بَابُ شُرُوطِ وُجُوبِ القِصَاصِ وَاسْتِيفَائِهِ · ١١","segs":[["matn","سَقَطَ كُلُّهُ، وَلِلْبَاقِينَ حَقُّهُمْ مِنَ الدِّيَةِ، وَإِنْ كَانَ العَفْوُ عَلَى مَالٍ، فَلَهُ حَقُّهُ مِنَ الدِّيَةِ، وَإِلَّا فَلَيْسَ لَهُ إِلَّا الثَّوْابُ. الثَّانِي: أَنْ يَرِثَ القَاتِلُ، أَوْ بَعْضِ وَلَدِهِ شَيْئًا مِنْ دَمِهِ."]]},{"id":"um126_12","label":"بَابُ شُرُوطِ وُجُوبِ القِصَاصِ وَاسْتِيفَائِهِ · ١٢","segs":[["matn","الثَّالِثُ: أَنْ يَمُوتَ القَاتِلُ، فَيَسْقُطُ، وَتَجِبُ الدِّيَةُ فِي تَرِكَتِهِ، وَلَوْ قَتَلَ وَاحِدٌ اثْنَيْنِ عَمْدًا، فَاتَّفَقَ أَوْلِيَاؤُهُمَا عَلَى قَتْلِهِ بِهِمَا، قُتِلَ بِهِمَا وَإِنْ تَشَاحُّوا فِي الِاسْتِيفَاءِ قُتِلَ بِالأَوَّلِ، وَلِلثَّانِي الدِّيَةُ، فَإِنْ سَقَطَ قِصَاصُ الأَوَّلِ، فَلِأَوْلِيَاءِ الثَّانِي اسْتِيفَاؤُهُ."]]},{"id":"um126_13","label":"بَابُ شُرُوطِ وُجُوبِ القِصَاصِ وَاسْتِيفَائِهِ · ١٣","segs":[["matn","وَيُسْتَوْفَى القِصَاصُ بِالسَّيْفِ فِي العُنُقِ، وَلَا يُمَثَّلُ بِهِ، إِلَّا أَنْ يَفْعَلَ شَيْئًا، فَيُفْعَلُ بِهِ مِثْلُهُ."]]}],"group":"كِتَابُ الْجِنَاياتِ"},{"id":"um127","title":"بَابُ الِاشْتِرَاكِ فِي القَتْلِ","units":[{"id":"um127_1","label":"بَابُ الِاشْتِرَاكِ فِي القَتْلِ · ١","segs":[["matn","وَتُقْتَلُ الجَمَاعَةُ بِالوَاحِدِ، فَإِنْ تَعَذَّرَ قَتْلُ أَحَدِهِمْ؛ لِأُبُوَّتِهِ، أَوْ عَدَمِ مُكَافَأَتِهِ لِلْقَتِيلِ أَوِ العَفْوِ عَنْهُ، قُتِلَ شُرَكَاؤُهُ، وَإِنْ كَانَ بَعْضُهُمْ غَيْرَ مُكَلَّفٍ، أَوْ خَاطِئًا، لَمْ يَجِبِ القَوَدُ عَلَى وَاحِدٍ مِنْهُمْ."]]},{"id":"um127_2","label":"بَابُ الِاشْتِرَاكِ فِي القَتْلِ · ٢","segs":[["matn","وَإِنْ أَكْرَهَ رَجُلٌ رَجُلاً عَلَى القَتْلِ، فَقَتَلَ، أَوْ جَرَحَ أَحَدُهُمَا جُرْحًا وَالآخَرُ مِئَةً، أَوْ قَطَعَ أَحَدُهُمَا مِنَ الكُوعِ وَالآخَرُ مِنَ الْمِرْفَقِ، فَهُمَا قَاتِلَانِ، وَعَلَيْهِمَا القِصَاصُ، وَإِنْ وَجَبَتِ الدِّيَةُ، اسْتَوَيَا فِيهَا."]]},{"id":"um127_3","label":"بَابُ الِاشْتِرَاكِ فِي القَتْلِ · ٣","segs":[["matn","وَإِنْ ذَبَحَهُ أَحَدُهُمَا، ثُمَّ قَطَعَ الآخَرُ يَدَهُ، أَوْ قَدَّهُ نِصْفَيْنِ، فَالقَاتِلُ الأَوَّلُ، وَإِنْ قَطَعَهُ أَحَدُهُمَا، ثُمَّ ذَبَحَهُ الثَّانِي، قُطِعَ القَاطِعُ، وَذُبِحَ الذَّابِحُ."]]},{"id":"um127_4","label":"بَابُ الِاشْتِرَاكِ فِي القَتْلِ · ٤","segs":[["matn","وَإِنْ أَمَرَ مَنْ يَعْلَمُ تَحْرِيمَ القَتْلِ بِهِ، فَقَتَلَ، فَالقِصَاصُ عَلَى الْمُبَاشِرِ، وَيُؤَدَّبُ الآمِرُ، وَإِنْ أَمَرَ مَنْ لَا يَعْلَمُ تَحْرِيمَهُ بِهِ، أَوْ لَا يُمَيِّزُ، فَالقِصَاصُ عَلَى الآمِرِ."]]},{"id":"um127_5","label":"بَابُ الِاشْتِرَاكِ فِي القَتْلِ · ٥","segs":[["matn","وَإِنْ أَمْسَكَ إِنْسَاناً لِلْقَتْلِ، فَقُتِلَ، قُتِلَ القَاتِلُ، وَحُبِسَ الْمُمْسِكُ حَتَّى يَمُوتَ."]]}],"group":"كِتَابُ الْجِنَاياتِ"},{"id":"um128","title":"بَابُ القَوَدِ فِي الجُرُوحِ","units":[{"id":"um128_1","label":"بَابُ القَوَدِ فِي الجُرُوحِ · ١","segs":[["matn","يَجِبُ القَوَدُ فِي كُلِّ عُضْوٍ بِمِثْلِهِ، فَتُؤْخَذُ العَيْنُ بِالعَيْنِ، وَالأَنْفُ بِالأَنْفِ، وَكُلُّ وَاحِدٍ مِنَ الجَفْنِ وَالشَّفَةِ، وَالِّلسَانِ وَالسِّنِّ، وَاليَدِ وَالرِّجْلِ، وَالذَّكَرِ، وَالأُنْثَيَيْنِ بِمِثْلِهِ، وَكَذَلِكَ كُلُّ مَا أَمْكَنَ القِصَاصُ فِيهِ."]]},{"id":"um128_2","label":"بَابُ القَوَدِ فِي الجُرُوحِ · ٢","segs":[["matn","وَيُعْتَبَرُ كَوْنُ الْمَجْنِيِّ عَلَيْهِ مُكَافِئًا لِلْجَانِي، وَكَوْنُ الجِنَايَةِ عَمْدًا، وَالأَمْنُ مِنَ التَّعَدِّي، بِأَنْ يُقْطَعَ مِنْ مِفْصَلٍ، أَوْ حَدٍّ يَنْتَهِي إِلَيْهِ، كَالْمُوضِحَةِ الَّتِي تَنْتَهِي إِلَى الْعَظْمِ فَأَمَّا كَسْرُ العِظَامِ، وَالقَطْعُ مِنَ السَّاعِدِ وَالسَّاقِ، فَلَا قَوَدَ فِيهِ."]]},{"id":"um128_3","label":"بَابُ القَوَدِ فِي الجُرُوحِ · ٣","segs":[["matn","وَلَا فِي الجَائِفَةِ، وَلَا فِي شَيْءٍ مِنْ شِجَاجِ الرَّأْسِ، إِلَّا الْمُوضِحَةِ، إِلَّا أَنْ يَرْضَى بِمَا فَوْقَ المُوضِحَةِ بِمُوضِحَةٍ، وَلَا قَوَدَ فِي الأَنْفِ إِلَّا مِنَ الْمَارِنِ، وَهُوَ مَا لَانَ مِنْهُ."]]},{"id":"um128_4","label":"بَابُ القَوَدِ فِي الجُرُوحِ · ٤","segs":[["matn","وَيُشْتَرَطُ التَّسَاوِي فِي الِاسْمِ وَالْمَوْضِعِ، فَلَا تُؤْخَذُ وَاحِدَةٌ مِنَ اليُمْنَى وَالْيُسْرَى وَالعُلْيَا وَالسُّفْلَى إِلَّا بِمِثْلِهَا، وَلَا تُؤْخَذُ إِصْبَعٌ وَلَا أَنْمُلَةٌ وَلَا سِنٌّ إِلَّا بِمِثْلِهَا، وَلَا تُؤْخَذُ كَامِلَةُ الأَصَابِعِ بِنَاقِصَةٍ، وَلَا صَحِيحَةٌ بِشَلَّاءَ، وَتُؤْخَذُ النَّاقِصَةُ بِالكَامِلَةِ، وَالشَّلَّاءُ بِالصَّحِيحَةِ إِذَا أُمِنَ التَّلَفُ."]]},{"id":"um128_5","label":"بَابُ القَوَدِ فِي الجُرُوحِ · ٥","segs":[["matn","فَصْلٌ: إِذَا قَطَعَ بَعْضَ لِسَانِهِ أَوْ مَارِنِهِ أَوْ شَفَتِهِ أَوْ حَشَفَتِهِ أَوْ أُذُنِهِ، أُخِذَ مِثْلُهُ، يُقَدَّرُ بِالأَجْزَاءِ، كَالنِّصْفِ وَالثُّلُثِ وَنَحْوِهِمَا، وَإِنْ أُخِذَتْ دِيَتُهُ، أُخِذَ بِالقِسْطِ مِنْهَا، وَإِنْ كُسِرَتْ بَعْضُ سِنِّهِ، بُرِدَ مِنْ سِنِّ الجَانِي مِثْلُهُ، إِذَا أُمِنَ انْقِلَاعُهَا."]]},{"id":"um128_6","label":"بَابُ القَوَدِ فِي الجُرُوحِ · ٦","segs":[["matn","وَلَا يُقْتَصُّ مِنَ السِّنِّ حَتَّى يَيْأَسَ مِنْ عَوْدِهَا، وَلَا مِنَ الجُرْحِ حَتَّى يَبْرَأَ. وَسِرَايَةُ القَوَدِ مُهْدَرَةٌ، وَسِرَايَةُ الجِنَايَةِ مَضْمُونَةٌ بِالقِصَاصِ وَالدِّيَةِ، إِلَّا أَنْ يُسْتَوْفَى قِصَاصُهَا قَبْلَ بُرْئِهَا، فَيَسْقُطُ ضَمَانُهَا."]]}],"group":"كِتَابُ الْجِنَاياتِ"},{"id":"um129","title":"كِتَابُ الدِّياتِ","units":[{"id":"um129_1","label":"كِتَابُ الدِّياتِ · ١","segs":[["matn","دِيَةُ الحُرِّ المُسْلِمِ، أَلفُ مِثقَالِ، مِنَ الذَّهَبِ أَوِ اثْنَا عَشَرَ أَلْفَ دِرْهَمٍ، أَوْ مِئَةٌ مِنَ الإِبِلِ، فَإِنْ كَانَتْ دِيَةَ عَمْدٍ، فَهِيَ ثَلَاثُونَ حِقَّةً، وَثَلَاثُونَ جَذَعَةً، وَأَرْبَعُونَ خَلِفَةً، وَهُنَّ الحَوَامِلُ، وَتَكُونُ حَالَّةً فِي مَالِ القَاتِلِ،"]]},{"id":"um129_2","label":"كِتَابُ الدِّياتِ · ٢","segs":[["matn","وَإِنْ كَانَ شِبْهَ عَمْدٍ فَكَذَلِكَ فِي أَسْنَانِهَا، وَهِيَ عَلَى العَاقِلَةِ، فِي ثَلَاثِ سِنِينَ، فِي رَأْسِ كُلُّ سَنَةٍ ثُلُثُهَا، وَإِنْ كَانَتْ دِيَةَ خَطَأٍ،"]]},{"id":"um129_3","label":"كِتَابُ الدِّياتِ · ٣","segs":[["matn","فَهِيَ عَلَى العَاقِلَةِ كَذَلِكَ، إِلَّا أَنَّهَا عِشْرُونَ بِنْتَ مَخَاضٍ، وَعِشْرُونَ ابْنَ مَخَاضٍ، وَعِشْرُونَ بِنْتَ لَبُونٍ، وَعِشْرُونِ حِقَّةً، وَعِشْرُونَ جَذَعَةً."]]},{"id":"um129_4","label":"كِتَابُ الدِّياتِ · ٤","segs":[["matn","وَدِيَةُ الحُرَّةِ المُسْلِمَةِ نِصْفُ دِيَةِ الرَّجُلِ، وَتُسَاوِي جِرَاحُهَا جِرَاحَهُ إِلَى ثُلُثِ الدِّيَةِ، فَإِذَا زَادَتْ، صَارَتْ عَلَى النِّصْفِ. وَدِيَةُ الكِتَابِيِّ نِصْفُ دِيَةِ المُسْلِمِ، وَنِسَاؤُهُمْ عَلَى النِّصْفِ مِنْ ذَلِكَ."]]},{"id":"um129_5","label":"كِتَابُ الدِّياتِ · ٥","segs":[["matn","وَدِيَةُ الْمَجُوسِيِّ ثَمَانُمِائَةِ دِرْهَمٍ، وَنِسَاؤُهُمْ عَلَى النِّصْفِ مِنْ ذَلِكَ. وَدِيَةُ العَبْدِ وَالأَمَةِ قِيمَتُهُمَا بَالِغَةً مَا بَلَغَتْ. وَمَنْ بَعْضُهُ حُرٌّ، فَفِيهِ بِالحِسَابِ مِنْ دِيَةِ حُرٍّ وَقِيمَةِ عَبْدٍ."]]},{"id":"um129_6","label":"كِتَابُ الدِّياتِ · ٦","segs":[["matn","وَدِيَةُ الجَنِينِ إِذَا سَقَطَ مَيْتًا غُرَّةٌ؛ عَبْدٌ أَوْ أَمَةٌ، قِيمَتُهَا خَمْسٌ مِنَ الإِبِلِ مَوْرُوثَةٌ عَنْهُ، وَلَوْ شَرِبَتِ الحَامِلُ دَوَاءً فَأَسْقَطَتْ بِهِ جَنِينَهَا، فَعَلَيْهَا غُرَّةٌ، لَا تَرِثُ مِنْهَا شَيْئًا."]]},{"id":"um129_7","label":"كِتَابُ الدِّياتِ · ٧","segs":[["matn","وَإِنْ كَانَ الجَنِينُ كِتَابِيًّا، فَفِيهِ عُشْرُ دِيَةِ أُمِّهِ، وَإِنْ كَانَ عَبْدًا، فَفِيهِ عُشْرُ قِيمَةِ أُمِّهِ، وَإِنْ سَقَطَ الجَنِينُ حَيًّا، ثُمَّ مَاتَ مِنَ الضَّرْبَةِ، فَفِيهِ دِيَةٌ كَامِلَةٌ. إِذَا كَانَ سُقُوطُهُ لِوَقْتٍ يَعِيشُ فِي مِثْلِهِ."]]}],"group":"كِتَابُ الدِّياتِ"},{"id":"um130","title":"بَابُ العَاقِلَةِ وَمَا تَحْمِلُهُ","units":[{"id":"um130_1","label":"بَابُ العَاقِلَةِ وَمَا تَحْمِلُهُ · ١","segs":[["matn","وَهِيَ عَصَبَةُ القَاتِلِ كُلُّهُمْ، قَرِيبُهُمْ وَبَعِيدُهُمْ، مِنَ النَّسَبِ وَالْمَوَالِي، إِلَّا الصَّبِيَّ وَالْمَجْنُونَ وَالفَقِيرَ، وَمَنْ يُخَالِفُ دِينُهُ دِينَ القَاتِلِ."]]},{"id":"um130_2","label":"بَابُ العَاقِلَةِ وَمَا تَحْمِلُهُ · ٢","segs":[["matn","وَيُرْجَعُ فِي تَقْدِيرِ مَا يَحْمِلُهُ كُلُّ وَاحِدٍ مِنْهُمْ إِلَى اجْتِهَادِ الإِمَامِ، فَيَفْرِضُ عَلَيْهِ قَدْرًا يَسْهُلُ وَلَا يَشُقُّ، وَمَا فَضَلَ فَعَلَى القَاتِلِ، وَكَذَلِكَ الدِّيَةُ فِي حَقِّ مَنْ لَا عَاقِلَةَ لَهُ."]]},{"id":"um130_3","label":"بَابُ العَاقِلَةِ وَمَا تَحْمِلُهُ · ٣","segs":[["matn","وَلَا تَحْمِلُ العَاقِلَةُ عَمْدًا، وَلَا عَبْدًا، وَلَا صُلْحًا، وَلَا اعْتِرَافًا، وَلَا مَا دُونَ الثُّلُثِ، وَيَتَعَاقَلُ أَهْلُ الذِّمَّةِ، وَلَا عَاقِلَةَ لِمُرْتَدٍّ، وَلَا لِمَنْ أَسْلَمَ بَعْدَ جِنَايَتِهِ، أَوِ انْجَرَّ وَلَاؤُهُ بَعْدَهَا."]]},{"id":"um130_4","label":"بَابُ العَاقِلَةِ وَمَا تَحْمِلُهُ · ٤","segs":[["matn","فَصْلٌ: وَجِنَايَةُ العَبْدِ فِي رَقَبَتِهِ، إِلَّا أَنْ يَفْدِيَهُ السَّيِّدُ بِأَقَلِّ الأَمْرَيْنِ، مِنْ أَرْشِهَا أَوْ قِيمَتِهِ، وَدِيَةُ الجِنَايَةِ عَلَيْهِ مَا نَقَصَ مِنْ قِيمَتِهِ فِي مَالِ الجَانِي."]]},{"id":"um130_5","label":"بَابُ العَاقِلَةِ وَمَا تَحْمِلُهُ · ٥","segs":[["matn","وَجِنَايَةُ البَهَائِمِ هَدَرٌ، إِلَّا أَنْ تَكُونَ فِي يَدِ إِنْسَانٍ، كَالرَّاكِبِ وَالقَائِدِ وَالسَّائِقِ، فَعَلَيْهِ ضَمَانُ مَا جَنَتْ بِيَدِهَا أَوْ فَمِهَا، دُونَ مَا جَنَتْ بِرِجْلِهَا أَوْ ذَنَبِهَا."]]},{"id":"um130_6","label":"بَابُ العَاقِلَةِ وَمَا تَحْمِلُهُ · ٦","segs":[["matn","وَإِنْ تَعَدَّى بِرَبْطِهَا فِي مِلْكِ غَيْرِهِ، أَوْ طَرِيقٍ، ضَمِنَ جِنَايَتَهَا كُلَّهَا. وَمَا أَتْلَفَتْ مِنَ الزَّرْعِ نَهَارًا، لَمْ يَضْمَنْهُ، إِلَّا أَنْ تَكُونَ فِي يَدِهِ، وَمَا أَتْلَفَتْ لَيْلاً، فَعَلَيْهِ ضَمَانُهُ."]]}],"group":"كِتَابُ الدِّياتِ"},{"id":"um131","title":"بَابُ دِيَاتِ الجِرَاحِ","units":[{"id":"um131_1","label":"بَابُ دِيَاتِ الجِرَاحِ · ١","segs":[["matn","كُلُّ مَا فِي الإِنْسَانِ مِنْهُ شَيْءٌ وَاحِدٌ، فَفِيهِ دِيَةٌ، كَلِسَانِهِ، وَأَنْفِهِ، وَذَكَرِهِ، وَسَمْعِهِ، وَبَصَرِهِ، وَشَمِّهِ، وَعَقْلِهِ، وَكَلَامِهِ، وَبَطْشِهِ، وَمَشْيِهِ،"]]},{"id":"um131_2","label":"بَابُ دِيَاتِ الجِرَاحِ · ٢","segs":[["matn","وَكذَلِكَ فِي كُلِّ وَاحِدٍ مِنْ صَعَرِهِ، وَهُوَ أَنْ يَجْعَلَ وَجْهَهُ فِي جَانِبِهِ، وَتَسْوِيدِ وَجْهِهِ، وَخَدَيْهِ، وَاسْتِطْلَاقِ بَوْلِهِ أَوْ غَائِطِهِ، وَقَرْعِ رَأْسِهِ، وَلِحْيَتِهِ دِيَةٌ."]]},{"id":"um131_3","label":"بَابُ دِيَاتِ الجِرَاحِ · ٣","segs":[["matn","وَمَا فِيهِ مِنْهُ شَيْئَانِ، فَفِيهِمَا الدِّيَةُ، وَفِي أَحَدِهِمَا نِصْفُهَا، كَالعَيْنَيْنِ، وَالحَاجِبَيْنِ، وَالشَّفَتَيْنِ، وَالأُذُنَيْنِ، وَاللِّحْيَيْنِ، وَاليَدَيْنِ، وَالثَّدْيَيْنِ، وَالأَلْيَتَيْنِ، وَالْأُنْثَيَيْنِ وَالإِسْكَتَيْنِ، وَالرِّجْلَيْنِ."]]},{"id":"um131_4","label":"بَابُ دِيَاتِ الجِرَاحِ · ٤","segs":[["matn","وَفِي الأَجْفَانِ الأَرْبَعَةِ الدِّيَةُ، وَفِي أَهْدَابِهَا الدِّيَةُ، وَفِي كُلِّ وَاحِدٍ رُبْعُهَا، فَإِنْ قَلَعَهَا بِأَهْدَابِهَا، وَجَبَتْ، دِيَةٌ وَاحِدَةٌ."]]},{"id":"um131_5","label":"بَابُ دِيَاتِ الجِرَاحِ · ٥","segs":[["matn","وَفِي أَصَابِعِ اليَدَيْنِ الدِّيَةُ، وَفِي أَصَابِعِ الرِّجْلَيْنِ الدِّيَةُ، وَفِي كُلِّ إِصْبَعٍ عُشْرُهَا، وَفِي كُلِّ أَنْمُلَةٍ ثُلُثُ عَقْلِهَا، إِلَّا الإِبْهَامَ فِي كُلِّ أَنْمُلَةٍ نِصْفُ عَقْلِهَا."]]},{"id":"um131_6","label":"بَابُ دِيَاتِ الجِرَاحِ · ٦","segs":[["matn","وَفِي كُلِّ سِنٍّ خَمْسٌ مِنَ الإِبِلِ إِذَا لَمْ تَعُدْ."]]},{"id":"um131_7","label":"بَابُ دِيَاتِ الجِرَاحِ · ٧","segs":[["matn","وَفِي مَارِنِ الأَنْفِ، وَحَلَمَةِ الثَّدْيِ، وَالكَفِّ، وَالقَدَمِ، وَحَشَفَةِ الذَّكَرِ، وَمَا ظَهَرَ مِنَ السِّنِّ، وَتَسْوِيدِهَا دِيَةُ العُضْوِ كُلِّهِ، وَفِي بَعْضِ ذَلِكَ بِالْحِسَابِ مِنْ دِيَتِهِ."]]},{"id":"um131_8","label":"بَابُ دِيَاتِ الجِرَاحِ · ٨","segs":[["matn","وَفِي الأَشَلِّ مِنَ اليَدِ وَالرِّجْلِ وَالذَّكَرِ، وَذَكَرِ الخَصِيِّ وَالعِنِّينِ، وَلِسَانِ الأَخْرَسِ، وَالعَيْنِ القَائِمَةِ، وَالسِّنِّ السَّوْدَاءِ، وَالذَّكَرِ دُونَ حَشَفَتِهِ، وَالثَّدْيِ دُونَ حَلَمَتِهِ، وَالأَنْفِ دُونَ أَرْنَبَتِهِ، وَالزَّائِدِ مِنَ الأَصَابِعِ وَغَيْرِهَا، حُكُومَةٌ."]]},{"id":"um131_9","label":"بَابُ دِيَاتِ الجِرَاحِ · ٩","segs":[["matn","وَفِي الأَشَلِّ مِنَ الْأَنْفِ وَالْأُذُنِ، وَأَنْفِ الأَخْشَمِ، وَأُذُنِ الأَصَمِّ دِيَتُهَا كَامِلَةً."]]}],"group":"كِتَابُ الدِّياتِ"},{"id":"um132","title":"بَابُ الشِّجَاجِ وَغَيْرِهَا","units":[{"id":"um132_1","label":"بَابُ الشِّجَاجِ وَغَيْرِهَا · ١","segs":[["matn","الشِّجَاجُ هِيَ: جُرُوحُ الرَّأْسِ وَالوَجْهِ. وَهِيَ تِسْعٌ: أَوَّلُهَا: الحَارِصَةُ: وَهِيَ الَّتِي تَشُقُّ الجِلْدَ شَقًّا لَا يَظْهَرُ مِنْهُ دَمٌ، ثُمَّ البَازِلَةُ: الَّتِي يَنْزِلُ مِنْهَا دَمٌ يَسِيرٌ، ثُمَّ البَاضِعَةُ: الَّتِي تَبْضَعُ اللَّحْمَ بَعْدَ الجِلْدِ،"]]},{"id":"um132_2","label":"بَابُ الشِّجَاجِ وَغَيْرِهَا · ٢","segs":[["matn","ثُمَّ الْمُتَلَاحِمَةُ: الَّتِي أَخَذَتْ فِي اللَّحْمِ، ثُمَّ السِّمْحَاقُ: الَّتِي بَيْنَهَا وَبَيْنَ العَظْمِ قِشْرَةٌ رَقِيقَةٌ، فَهَذِهِ الخَمْسُ لَا تَوْقِيتَ فِيهَا، وَلَا قِصَاصَ بِحَالٍ، ثُمَّ الْمُوضِحَةُ، وَهِيَ الَّتِي وَصَلَتْ إِلَى العَظْمِ،"]]},{"id":"um132_3","label":"بَابُ الشِّجَاجِ وَغَيْرِهَا · ٣","segs":[["matn","وَفِيهَا خَمْسٌ مِنَ الإِبِلِ، وَالقِصَاصُ إِذَا كَانَتْ عَمْدًا، ثُمَّ الْهَاشِمَةُ، وَهِيَ الَّتِي تُوضِحُ العَظْمَ وَتُهَشِّمُهُ، وَفِيهَا عَشْرٌ مِنَ الإِبِلِ، ثُمَّ الْمُنَقِّلَةُ وَهِيَ الَّتِي تُوضِحُ وَتُهَشِّمُ وَتَنْقُلُ عِظَامَهَا،"]]},{"id":"um132_4","label":"بَابُ الشِّجَاجِ وَغَيْرِهَا · ٤","segs":[["matn","وَفِيهَا خَمْسَةَ عَشَرَ مِنَ الإِبِلِ، ثُمَّ الْمَأْمُومَةُ: وَهِيَ الَّتِي تَصِلُ إِلَى جِلْدَةِ الدِّمَاغِ، وَفِيهَا ثُلُثُ الدِّيَةِ، وَفِي الجَائِفَةِ ثُلُثُ الدِّيَةِ، وَهِيَ الَّتِي تَصِلُ إِلَى الجَوْفِ، فَإِنْ خَرَجَتْ مِنْ جَانِبٍ آخَرَ، فَهِيَ جَائِفَتَانِ."]]},{"id":"um132_5","label":"بَابُ الشِّجَاجِ وَغَيْرِهَا · ٥","segs":[["matn","وَفِي الضَّلَعِ بَعِيرٌ، وَفِي التَّرْقُوَتَيْنِ بَعِيرَانِ، وَفِي الزَّنْدَيْنِ أَرْبَعَةُ أَبْعِرَةٍ."]]},{"id":"um132_6","label":"بَابُ الشِّجَاجِ وَغَيْرِهَا · ٦","segs":[["matn","وَمَا عَدَا هَذَا مِمَّا لَا مُقَدَّرَ فِيهِ، وَلَا هُوَ فِي مَعْنَاهُ، فَفِيهِ حُكُومَةٌ: وَهِيَ أَنْ يُقَوَّمَ الْمَجْنِيُّ عَلَيْهِ كَأَنَّهُ عَبْدٌ لَا جِنَايَةَ بِهِ، ثَمَّ يُقَوَّمَ، وَهِيَ بِهِ قَدْ بَرَأَتْ، فَمَا نَقَصَ مِنْ قِيمَتِهِ،"]]},{"id":"um132_7","label":"بَابُ الشِّجَاجِ وَغَيْرِهَا · ٧","segs":[["matn","فَلَهُ بِقِسْطِهِ مِنْ الدِّيَةِ إِلَّا أَنْ تَكُونَ الجِنَايَةُ عَلَى عُضْوٍ فِيهِ مُقَدَّرٌ، فَلَا يُجَاوِزُ بِهِ أَرْشَ الْمُقَدَّرِ، مِثْلَ أَنْ يَشُجَّهُ دُونَ الْمُوضِحَةِ، فَلَا يَجِبُ أَكْثَرُ مِنْ أَرْشِهَا، أَوْ يَجْرَحُ أَنْمُلَةً، فَلَا يَجِبُ أَكْثَرُ مِنْ دِيَتِهَا."]]}],"group":"كِتَابُ الدِّياتِ"},{"id":"um133","title":"بَابُ كَفَّارَةِ الْقَتْلِ","units":[{"id":"um133_1","label":"بَابُ كَفَّارَةِ الْقَتْلِ · ١","segs":[["matn","وَمَنْ قَتَلَ مُؤْمِنًا أَوْ ذِمِّيًّا بِغَيْرِ حَقٍّ، أَوْ شَارَكَ فِيهِ، أَوْ فِي إِسْقَاطِ جَنِينٍ، فَعَلَيْهِ كَفَّارَةٌ، وَهِيَ تَحْرِيرُ رَقَبَةٍ مُؤْمِنَةٍ، فَمَنْ لَمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ، تَوْبَةً مِنَ اللهِ، سَوَاءٌ كَانَ مُكَلَّفًا أَوْ غَيْرَ مُكَلَّفٍ، حُرًّا أَوْ عَبْدًا."]]},{"id":"um133_2","label":"بَابُ كَفَّارَةِ الْقَتْلِ · ٢","segs":[["matn","وَلَوْ تَصَادَمَ نَفْسَانِ فَمَاتَا، فَعَلَى كُلِّ وَاحِدٍ مِنْهُمَا كَفَّارَةٌ، وَدِيَةُ صَاحِبِهِ عَلَى عَاقِلَتِهِ، وَإِنْ كَانَا فَارِسَيْنِ، فَمَاتَ فَرَسَاهُمَا فَعَلَى كُلِّ وَاحِدٍ مِنْهُمَا ضَمَانُ فَرَسِ الآخَرِ، وَإِنْ كَانَ أَحَدُهُمَا وَاقِفًا وَالآخَرُ سَائِرًا،"]]},{"id":"um133_3","label":"بَابُ كَفَّارَةِ الْقَتْلِ · ٣","segs":[["matn","فَعَلَى السَّائِرِ ضَمَانُ دَابَّةِ الوَاقِفِ، وَعَلَى عَاقِلَتِهِ دِيَتُهُ، إِلَّا أَنْ يَكُونَ الوَاقِفُ مُتَعَدِّيًاًّ بِوُقُوفِهِ، كَالقَاعِدِ فِي طَرِيقٍ ضَيِّقٍ، أَوْ مِلْكِ السَّائِرِ، فَعَلَيْهِ الْكَفَّارَةُ وَضَمَانُ السَّائِرِ وَدَابَّتِهِ، وَلَا شَيْءَ عَلَى السَّائِرِ وَلَا عَلَى عَاقِلَتِهِ."]]},{"id":"um133_4","label":"بَابُ كَفَّارَةِ الْقَتْلِ · ٤","segs":[["matn","وَإِذَا رَمَى ثَلَاثَةٌ بِالْمَنْجَنِيقِ، فَقَتَلَ الحَجَرُ مَعْصُومًا، فَعَلَى كُلِّ وَاحِدٍ مِنْهُمْ كَفَّارَةٌ، وَعَلَى عَاقِلَتِهِ ثُلُثُ الدِّيَةِ وَإِنْ قُتِلَ أَحَدُهُمْ فَكَذَلِكَ،"]]},{"id":"um133_5","label":"بَابُ كَفَّارَةِ الْقَتْلِ · ٥","segs":[["matn","إِلَّا أَنَّهُ يَسْقُطُ ثُلُثُ دِيَتِهِ فِي مُقَابَلَةِ فِعْلِهِ، وَإِنْ كَانُوا أَكْثَرَ مِنْ ثَلَاثَةٍ، سَقَطَتْ حِصَّةُ القَتِيلِ وَبَاقِي الدِّيَةِ فِي أَمْوَالِ البَاقِينَ."]]}],"group":"كِتَابُ الدِّياتِ"},{"id":"um134","title":"بَابُ القَسَامَةِ","units":[{"id":"um134_1","label":"بَابُ القَسَامَةِ · ١","segs":[["matn","رَوَى سَهْلُ بْنُ أَبِي حَثْمَةَ، وَرَافِعُ بْنُ خَدِيجٍ: أَنَّ مُحَيِّصَةَ، وَعَبْدَ اللهِ بْنَ سَهْلٍ انْطَلَقَا قَبْلَ خَيْبَرَ فَتَفَرَّقَا فِي النَّخْلِ فَقُتِلَ عَبْدُ اللهِ بْنُ سَهْلٍ،"]]},{"id":"um134_2","label":"بَابُ القَسَامَةِ · ٢","segs":[["matn","فَاتَّهَمُوا الْيَهُودَ بِهِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «يُقْسِمُ خَمْسُونَ مِنْكُمْ عَلَى رَجُلٍ مِنْهُمْ، فَيُدْفَعُ بِرُمَّتِهِ» فَقَالُوا: أَمْرٌ لَمْ نَشْهَدْهُ، فَكَيْفَ نَحْلِفُ؟"]]},{"id":"um134_3","label":"بَابُ القَسَامَةِ · ٣","segs":[["matn","قَالَ: «فَتُبَرِّئُكُمْ يَهُودٌ بِأَيْمَانِ خَمْسِينَ مِنْهُمْ» قَالُوا: قَوْمٌ كُفَّارٌ، فَوَدَاهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ قِبَلِهِ: فَمَتَى وُجِدَ قَتِيلٌ،"]]},{"id":"um134_4","label":"بَابُ القَسَامَةِ · ٤","segs":[["matn","فَادَّعَى أَوْلِيَاؤُهُ عَلَى رَجُلٍ قَتْلَهُ، وَكَانَتْ بَيْنَهُمْ عَدَاوَةٌ وَلَوْثٌ، كَمَا كَانَ بَيْنَ الأَنْصَارِ، وَأَهْلِ خَيْبَرَ، أَقْسَمَ الأَوْلِيَاءُ عَلَى وَاحِدٍ مِنْهُمْ خَمْسِينَ يَمِينًا، وَاسْتَحَقُّوا دَمَهُ،"]]},{"id":"um134_5","label":"بَابُ القَسَامَةِ · ٥","segs":[["matn","فَإِنْ لَمْ يَحْلِفُوا حَلَفَ الْمُدَّعَى عَلَيْهِ خَمْسِينَ وَبَرِئَ، فَإِنْ نَكَلُوا فَعَلَيْهِمُ الدِّيَةُ، فَإِنْ لَمْ يَحْلِفِ الْمُدَّعُونَ، وَلَمْ يَرْضَوْا بِيَمِينِ الْمُدَّعَى عَلَيْهِ،"]]},{"id":"um134_6","label":"بَابُ القَسَامَةِ · ٦","segs":[["matn","فَدَاهُ الإِمَامُ مِنْ بَيْتِ الْمَالِ، وَلَا يُقْسِمُونَ عَلَى أَكْثَرَ مِنْ وَاحِدٍ، وَإِنْ لَمْ يَكُنْ بَيْنَهُمْ عَدَاوَةٌ، وَلَا لَوْثٌ حَلَفَ الْمُدَّعَى عَلَيْهِ يَمِينًا وَاحِدَةً، وَبَرِئَ."]]}],"group":"كِتَابُ الدِّياتِ"},{"id":"um135","title":"كِتَابُ الحُدُودِ","units":[{"id":"um135_1","label":"كِتَابُ الحُدُودِ · ١","segs":[["matn","لَا يَجِبُ الْحَدُّ إِلَّا عَلَى مُكَلَّفٍ، عَالِمٍ بِالتَّحرِيمِ، وَلَا يُقِيمُهُ إِلَّا الإِمَامُ أَوْ نَائِبُهُ، إِلَّا السَّيِّدُ، فَإِنَّ لَهُ إِقَامَتَهُ بِالْجَلْدِ خَاصَّةً عَلَى رَقِيقِهِ القِنِّ؛"]]},{"id":"um135_2","label":"كِتَابُ الحُدُودِ · ٢","segs":[["matn","لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «إِذَا زَنَتْ أَمَةُ أَحَدِكُمْ، فَلْيَجْلِدْهَا،» وَلَيْسَ لَهُ قَطْعُهُ فِي السَّرِقَةِ، وَلَا قَتْلُهُ فِي الرِّدَّةِ، وَلَا جَلْدُ مُكَاتَبِهِ وَلَا أَمَتِهِ الْمُزَوَّجَةِ."]]},{"id":"um135_3","label":"كِتَابُ الحُدُودِ · ٣","segs":[["matn","وَحَدُّ الرَّقِيقِ فِي الْجَلْدِ نِصْفُ حَدِّ الْحُرِّ، وَمَنْ أَقَرَّ بِحَدٍّ ثُمَّ رَجَعَ عَنْهُ سَقَطَ."]]},{"id":"um135_4","label":"كِتَابُ الحُدُودِ · ٤","segs":[["matn","فَصْلٌ: وَيُضْرَبُ فِي الْجَلْدِ بِسَوْطٍ، لَا جَدِيدٍ وَلَا خَلَقٍ، وَلَا يُمَدُّ، وَلَا يُرْبَطُ وَلَا يُجَرَّدُ، وَيُتَّقَى وَجْهُهُ وَرَأْسُهُ وَفَرْجُهُ. وَيُضْرَبُ الرَّجُلُ قَائِمًا، وَالْمَرْأَةُ جَالِسَةً وَتُشَدُّ عَلَيْهَا ثِيَابُهَا، وَتُمْسَكُ يَدَاهَا."]]},{"id":"um135_5","label":"كِتَابُ الحُدُودِ · ٥","segs":[["matn","وَمَنْ كَانَ مَرِيضًا يُرْجَى بُرْؤُهُ، أُخِّرَ حَتَّى يَبْرَأَ، لِمَا رُوِيَ عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ: أَنَّ أَمَةَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ زَنَتْ،"]]},{"id":"um135_6","label":"كِتَابُ الحُدُودِ · ٦","segs":[["matn","فَأَمَرَنِي أَنْ أَجْلِدَهَا، فَإِذَا هِيَ حَدِيثَةُ عَهْدٍ بِنِفَاسٍ، فَخَشِيتُ إِنْ أَنَا جَلَدْتُهَا أَنْ أَقْتُلَهَا، فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: «أَحْسَنْتَ.»"]]},{"id":"um135_7","label":"كِتَابُ الحُدُودِ · ٧","segs":[["matn","فَإِنْ لَمْ يُرْجَ بُرْؤُهُ وَخُشِيَ عَلَيْهِ مِنَ السَّوْطِ، جُلِدَ بِضِغْثٍ فِيهِ عِيدَانٌ بِعَدَدٍ مَا يَجِبُ عَلَيْهِ مَرَّةً وَاحِدَةً."]]},{"id":"um135_8","label":"كِتَابُ الحُدُودِ · ٨","segs":[["matn","فَصْلٌ: وَإِنِ اجْتَمَعَتْ حُدُودٌ لِلَّهِ تَعَالَى فِيهَا قَتْلٌ، قُتِلَ، وَسَقَطَ سَائِرُهَا، وَلَوْ زَنَى أَوْ سَرَقَ مِرَارًا، وَلَمْ يُحَدَّ، فَحَدٌّ وَاحِدٌ."]]},{"id":"um135_9","label":"كِتَابُ الحُدُودِ · ٩","segs":[["matn","وَإِنِ اجْتَمَعَتْ حُدُودٌ مِنْ أَجْنَاسِ لَا قَتْلَ فِيهَا، اسْتُوفِيَتْ كُلُّهَا، وَيُبْدَأُ بِالأَخَفِّ فَالأَخَفِّ مِنْهَا."]]},{"id":"um135_10","label":"كِتَابُ الحُدُودِ · ١٠","segs":[["matn","وَتُدْرَأُ الحُدُودُ بِالشُّبُهَاتِ، فَلَوْ زَنَى بِجَارِيَةٍ لَهُ فِيهَا شِرْكٌ وَإِنْ قَلَّ، أَوْ لِوَلَدِهِ، أَوْ وَطِئَ فِي نِكَاحٍ مُخْتَلَفٍ فِيهِ، أَوْ مُكْرَهًا،"]]},{"id":"um135_11","label":"كِتَابُ الحُدُودِ · ١١","segs":[["matn","أَوْ سَرَقَ مِنْ مَالٍ لَهُ فِيهِ حَقٌّ، أَوْ لِوَلَدِهِ وَإِنْ سَفَلَ، مِنْ مَالِ غَرِيمِهِ الَّذِي يَعْجِزُ عَنْ تَخْلِيصِهِ مِنْهُ بِقَدْرِ حَقِّهِ، لَمْ يُحَدَّ."]]},{"id":"um135_12","label":"كِتَابُ الحُدُودِ · ١٢","segs":[["matn","فَصْلٌ: وَمَنْ أَتَى حَدًّا خَارِجَ الْحَرَمِ، ثُمَّ لَجَأَ إِلَى الحَرَمِ، أَوْ لَجَأَ إِلَيْهِ مَنْ عَلَيْهِ قِصَاصٌ، لَمْ يُسْتَوْفَ مِنْهُ حَتَّى يَخْرُجَ،"]]},{"id":"um135_13","label":"كِتَابُ الحُدُودِ · ١٣","segs":[["matn","لَكِنْ لَا يُبَايِعُ وَلَا يُشَارِي، وَإِنْ فَعَلَ ذَلِكَ فِي الحَرَمِ، اسْتُوفِيَ مِنْهُ فِيهِ، وَإِنْ أَتَى حَدًّا فِي الغَزْوِ، لَمْ يُسْتَوْفَ حَتَّى يَخْرُجَ مِنْ دَارِ الحَرْبِ."]]}],"group":"كِتَابُ الحُدُودِ"},{"id":"um136","title":"بَابُ حَدِّ الزِّنَاNopages","units":[{"id":"um136_1","label":"بَابُ حَدِّ الزِّنَاNopages · ١","segs":[["matn","مَنْ أَتَى الفَاحِشَةَ فِي قُبُلٍ أَوْ دُبُرٍ، مِنِ امْرَأَةٍ لَا يَمْلِكُهَا، أَوْ مِنْ غُلَامٍ، أَوْ مَنْ فُعِلَ ذَلِكَ بِهِ فَحَدُّهُ الرَّجْمُ، إِنْ كَانَ مُحْصَنًا، أَوْ جَلْدُ مِئَةٍ وَتَغْرِيبُ عَامٍ،"]]},{"id":"um136_2","label":"بَابُ حَدِّ الزِّنَاNopages · ٢","segs":[["matn","إِنْ لَمْ يَكُنْ مُحْصَنًا، لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «خُذُوا عَنِّي، قَدْ جَعَلَ اللهُ لَهُنَّ سَبِيلاً؛ البِكْرُ بِالبِكْرِ، جَلْدُ مِئَةٍ وَتَغْرِيبُ عَامٍ، وَالثَّيِّبُ بِالثَّيِّبِ الرَّجْمُ،» وَالْمُحْصَنُ هُوَ:"]]},{"id":"um136_3","label":"بَابُ حَدِّ الزِّنَاNopages · ٣","segs":[["matn","الحُرُّ البَالِغُ الَّذِي قَدْ وَطِئَ زَوْجَةً مِثْلَهُ فِي هَذِهِ الصِّفَاتِ، فِي قُبُلِهَا فِي نِكَاحٍ صَحِيحٍ، وَلَا يَثْبُتُ الزِّنَا إِلَّا بِأَحَدِ أَمْرَيْنِ:"]]},{"id":"um136_4","label":"بَابُ حَدِّ الزِّنَاNopages · ٤","segs":[["matn","إِقْرَارٍ بِهِ أَرْبَعَ مَرَّاتٍ، مُصَرِّحًا بِذِكْرِ حَقِيقَتِهِ، أَوْ شَهَادَةِ أَرْبَعَةِ رِجَالٍ أَحْرَارٍ عُدُولٍ، يَصِفُونَ الزِّنَا، وَيَجِيئُونَ فِي مَجْلِسٍ وَاحِدٍ، وَيَتَّفِقُونَ عَلَى الشَّهَادَةِ بِزِنًا وَاحِدٍ،"]]}],"group":"كِتَابُ الحُدُودِ"},{"id":"um137","title":"بَابُ حَدِّ القَذْفِ","units":[{"id":"um137_1","label":"بَابُ حَدِّ القَذْفِ · ١","segs":[["matn","وَمَنْ رَمَى مُحْصَنًا بِالزِّنَا، أَوْ شَهِدَ عَلَيْهِ بِهِ، فَلَمْ تَكْمُلِ الشَّهَادَةُ عَلَيْهِ، جُلِدَ ثَمَانِينَ جَلْدَةً، إِذَا طَالَبَ المَقْذُوفُ، وَالْمُحْصَنُ هُوَ الحُرُّ الْبَالِغُ الْمُسْلِمُ الْعَاقِلُ العَفِيفُ."]]},{"id":"um137_2","label":"بَابُ حَدِّ القَذْفِ · ٢","segs":[["matn","وَيُحَدُّ مَنْ قَذَفَ الْمُلَاعِنَةَ أَوْ وَلَدَهَا. وَمَنْ قَذَفَ جَمَاعَةً بِكَلِمَةٍ وَاحِدَةٍ، فَحَدٌّ وَاحِدٌ، إِذَا طَالَبُوا أَوْ وَاحِدٌ مِنْهُمْ، فَإِنْ عَفَا بَعْضُهُمْ، لَمْ يَسْقُطْ حَقُّ غَيْرِهِ."]]}],"group":"كِتَابُ الحُدُودِ"},{"id":"um138","title":"بَابُ حَدِّ المُسْكِرِ","units":[{"id":"um138_1","label":"بَابُ حَدِّ المُسْكِرِ · ١","segs":[["matn","وَمَنْ شَرِبَ مُسْكِرًا، قَلَّ أَوْ كَثُرَ، مُخْتَارًا، عَالِمًا أَنَّ كَثِيرَهُ يُسْكِرُ، جُلِدَ الحَدَّ أَرْبَعِينَ جَلْدَةً؛"]]},{"id":"um138_2","label":"بَابُ حَدِّ المُسْكِرِ · ٢","segs":[["matn","لِأَنَّ عَلِيًّا رَضِيَ اللهُ عَنْهُ جَلَدَ الوَلِيدَ بْنَ عُقْبَةَ فِي الخَمْرِ أَرْبَعِينَ، وَقَالَ: جَلَدَ النَّبِيُّ أَرْبَعِينَ، وَأَبُو بَكْرٍ أَرْبَعِينَ، وَعُمَرُ ثَمَانِينَ، وَكُلٌّ سُنَّةٌ، وَهَذَا أَحَبُّ إِلَيَّ."]]},{"id":"um138_3","label":"بَابُ حَدِّ المُسْكِرِ · ٣","segs":[["matn","وَسَوَاءٌ كَانَ عَصِيرِ العِنَبِ أَوْ غَيْرِهِ. وَمَنْ أَتَى مِنَ الْمُحَرَّمَاتِ مَا لَا حَدَّ فِيهِ، لَمْ يَزِدْ عَلَى عَشْرِ جَلَدَاتٍ؛"]]},{"id":"um138_4","label":"بَابُ حَدِّ المُسْكِرِ · ٤","segs":[["matn","لِمَا رَوَى أَبُو بُرْدَةَ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «لَا يُجْلَدُ أَحَدٌ أَكْثَرَ مِنْ عَشْرِ جَلَدَاتٍ، إِلَّا فِي حَدٍّ مِنْ حُدُودِ اللهِ،» إِلَّا أَنْ يَطَأَ جَارِيَةَ امْرَأَتِهِ بِإِذْنِهَا، فَإِنَّهُ يُجْلَدُ مِئَةً."]]}],"group":"كِتَابُ الحُدُودِ"},{"id":"um139","title":"بَابُ حَدِّ السَّرِقَةِ","units":[{"id":"um139_1","label":"بَابُ حَدِّ السَّرِقَةِ · ١","segs":[["matn","وَمَنْ سَرَقَ رُبْعَ دِينَارٍ مِنَ العَيْنِ، أَوْ ثَلَاثَةَ دَرَاهِمَ مِنَ الوَرِقِ، أَوْ مَا يُسَاوِي أَحَدُهُمَا مِنْ سَائِرِ الْمَالِ، فَأَخْرَجَهُ مِنَ الحِرْزِ،"]]},{"id":"um139_2","label":"بَابُ حَدِّ السَّرِقَةِ · ٢","segs":[["matn","قُطِعَتْ يَدُهُ اليُمْنَى مِنْ مِفْصَلِ الكَفِّ وَحُسِمَتْ، فَإِنْ عَادَ، قُطِعَتْ رِجْلُهُ الْيُسْرَى مِنْ مِفْصَلِ الكَعْبِ وَحُسِمَتْ، فَإِنْ عَادَ حُبِسَ، وَلَا يُقْطَعُ غَيْرُ يَدٍ وَرِجْلٍ."]]},{"id":"um139_3","label":"بَابُ حَدِّ السَّرِقَةِ · ٣","segs":[["matn","وَلَا تَثْبُتُ السَّرِقَةُ إِلَّا بِشَهَادَةِ عَدْلَيْنِ، أَوِ اعْتِرَافٍ مَرَّتَيْنِ."]]},{"id":"um139_4","label":"بَابُ حَدِّ السَّرِقَةِ · ٤","segs":[["matn","وَلَا يُقْطَعُ حَتَّى يُطَالِبُ المَسْرُوقُ مِنْهُ بِمَالِهِ، وَإِنْ وَهَبَهَا لِلسَّارِقِ، أَوْ بَاعَهُ إِيَّاهَا قَبْلَ ذَلِكَ، سَقَطَ القَطْعُ، وَإِنْ كَانَ بَعْدَهُ، لَمْ يَسْقُطْ."]]},{"id":"um139_5","label":"بَابُ حَدِّ السَّرِقَةِ · ٥","segs":[["matn","وَإِنْ نَقَصَتْ عَنِ النِّصَابِ بَعْدَ الإِخْرَاجِ لَمْ يَسْقُطِ القَطْعُ، وَإِنْ كَانَ قَبْلَهُ لَمْ يَجِبْ، وَإِذَا قُطِعَ، فَعَلَيْهِ رَدُّ المَسْرُوقُ، إِنْ كَانَ بَاقِيًا، أَوْ قِيمَتُهُ إِنْ كَانَ تَالِفًا."]]}],"group":"كِتَابُ الحُدُودِ"},{"id":"um140","title":"بَابُ حَدِّ المُحَارِبِينَ","units":[{"id":"um140_1","label":"بَابُ حَدِّ المُحَارِبِينَ · ١","segs":[["matn","وَهُمُ الَّذِينَ يَعْرِضُونَ لِلنَّاسِ فِي الصَّحْرَاءِ جَهْرَةً؛ لِيَأْخُذُوا أَمْوَالَهُمْ، فَمَنْ قَتَلَ مِنْهُمْ، وَأَخَذَ الْمَالَ، قُتِلَ وَصُلِبَ حَتَّى يَشْتَهِرَ، وَدُفِعَ إِلَى أَهْلِهِ،"]]},{"id":"um140_2","label":"بَابُ حَدِّ المُحَارِبِينَ · ٢","segs":[["matn","وَمَنْ قَتَلَ وَلَمْ يَأْخُذِ المَالَ، قُتِلَ وَلَمْ يُصْلَبْ، وَمَنْ أَخَذَ المَالَ وَلَمْ يَقْتُلْ، قُطِعَتْ يَدُهُ اليُمْنَى وَرِجْلُهُ الْيُسْرَى فِي مَقَامٍ وَاحِدٍ،"]]},{"id":"um140_3","label":"بَابُ حَدِّ المُحَارِبِينَ · ٣","segs":[["matn","وَحُسِمَتَا، وَلَا يُقْطَعُ إِلَّا مَنْ أَخَذَ مَا يُقْطَعُ السَّارِقُ بِهِ، وَمَنْ أَخَافَ السَّبِيلَ وَلَمْ يَقْتُلْ وَلَا أَخَذَ مَالاً، نُفِيَ مِنَ الأَرْضِ، وَمَنْ تَابَ قَبْلَ القُدْرَةِ عَلَيْهِ، سَقَطَتْ عَنْهُ حُدُودُ اللهِ، تَعَالَى وَأُخِذَ بِحُقُوقِ الآدَمِيِّينَ، إِلَّا أَنْ يُعْفَى لَهُ عَنْهَا."]]},{"id":"um140_4","label":"بَابُ حَدِّ المُحَارِبِينَ · ٤","segs":[["matn","فَصْلٌ: وَمَنْ عُرِضَ لَهُ مَنْ يُرِيدُ نَفْسَهُ، أَوْ مَالَهُ، أَوْ حَرِيمَهُ، أَوْ حَمَلَ عَلَيْهِ سِلَاحًا، أَوْ دَخَلَ مَنْزِلَهُ بِغَيْرِ إِذْنِهِ،"]]},{"id":"um140_5","label":"بَابُ حَدِّ المُحَارِبِينَ · ٥","segs":[["matn","فَلَهُ دَفْعُهُ بِأَسْهَلِ مَا يَكُونُ أَنَّهُ يَنْدَفِعُ بِهِ، فَإِنْ لَمْ يَنْدَفِعْ إِلَّا بِقَتْلِهِ، فَلَهُ قَتْلُهُ، وَلَا ضَمَانَ عَلَيْهِ، وَإِنْ قُتِلَ الدَّافِعُ، فَهُوَ شَهِيدٌ، وَعَلَى قَاتِلِهِ ضَمَانُهُ."]]},{"id":"um140_6","label":"بَابُ حَدِّ المُحَارِبِينَ · ٦","segs":[["matn","وَمَنْ صَالَتْ عَلَيْهِ بَهِيمَةٌ، فَلَهُ دَفْعُهَا بِمِثْلِ ذَلِكَ، وَلَا ضَمَانَ فِي ذَلِكَ."]]},{"id":"um140_7","label":"بَابُ حَدِّ المُحَارِبِينَ · ٧","segs":[["matn","وَمَنِ اطَّلَعَ فِي دَارِ إِنْسَانٍ، أَوْ بَيْتِهِ مِنْ خَصَاصِ البَابِ أَوْ نَحْوِهِ، فَحَذَفَهُ بِحَصَاةٍ، فَفَقَأَ عَيْنَهُ، فَلَا ضَمَانَ عَلَيْهِ. وَإِنْ عَضَّ إِنْسَانٌ يَدَهُ فَانْتَزَعَهَا مِنْهُ فَسَقَطَتْ ثَنَايَاهُ، فَلَا ضَمَانَ."]]}],"group":"كِتَابُ الحُدُودِ"},{"id":"um141","title":"بَابُ قِتَالِ أَهْلِ البَغْيِ","units":[{"id":"um141_1","label":"بَابُ قِتَالِ أَهْلِ البَغْيِ · ١","segs":[["matn","وَهُمُ: الخَارِجُونَ عَلَى الإِمَامِ، يُرِيدُونَ إِزَالَتَهُ عَنْ مَنْصِبِهِ، فَعَلَى المُسْلِمِينَ مَعُونَةُ إِمَامِهِمْ فِي دَفْعِهِمْ بِأَسْهَلِ مَا يَنْدَفِعُونَ بِهِ، فَإِنْ آلَ إِلَى قِتَالِهِمْ أَوْ تَلَفِ مَالِهِمْ، فَلَا شَيْءَ عَلَى الدَّافِعِ، وَإِنْ قُتِلَ الدَّافِعُ كَانَ شَهِيدًا."]]},{"id":"um141_2","label":"بَابُ قِتَالِ أَهْلِ البَغْيِ · ٢","segs":[["matn","وَلَا يُتْبَعُ لَهُمْ مُدْبِرٌ، وَلَا يُجْهَزُ عَلَى جَرِيحٍ، وَلَا يُغْنَمُ لَهُمْ مَالٌ، وَلَا تُسْبَى لَهُمْ ذُرِّيَّةٌ، وَمَنْ قُتِلَ مِنْهُمْ غُسِّلَ وَكُفِّنَ وَصُلِّيَ عَلَيْهِ."]]},{"id":"um141_3","label":"بَابُ قِتَالِ أَهْلِ البَغْيِ · ٣","segs":[["matn","وَلَا ضَمَانَ عَلَى أَحَدِ الفَرِيقَيْنِ فِيمَا أَتْلَفَ حَالَ الحَرْبِ، مِنْ نَفْسٍ أَوْ مَالٍ."]]},{"id":"um141_4","label":"بَابُ قِتَالِ أَهْلِ البَغْيِ · ٤","segs":[["matn","وَمَا أَخَذَ الْبُغَاةُ حَالَ امْتِنَاعِهِمْ مِنْ زَكَاةٍ، أَوْ جِزْيَةٍ، أَوْ خَرَاجٍ لَمْ يُعَدْ عَلَيْهِمْ، وَلَا عَلَى الدَّافِعِ إِلَيْهِمْ. وَلَا يُنْقَضُ مِنْ حُكْمِ حَاكِمِهِمْ، إِلَّا مَا يُنْقَضُ مِنْ حُكْمِ غَيْرِهِ."]]}],"group":"كِتَابُ الحُدُودِ"},{"id":"um142","title":"بَابُ حُكْمِ المُرْتَدِّ","units":[{"id":"um142_1","label":"بَابُ حُكْمِ المُرْتَدِّ · ١","segs":[["matn","وَمَنِ ارْتَدَّ عَنِ الإِسْلَامِ مِنَ الرِّجَالِ وَالنِّسَاءِ، وَجَبَ قَتْلُهُ، لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «مَنْ بَدَّلَ دِينَهُ فَاقْتُلُوهُ،» وَلَا يُقْتَلُ حَتَّى يُسْتَتَابَ ثَلَاثًا، فَإِنْ تَابَ، وَإِلَّا قُتِلَ بِالسَّيْفِ."]]},{"id":"um142_2","label":"بَابُ حُكْمِ المُرْتَدِّ · ٢","segs":[["matn","وَمَنْ جَحَدَ اللهِ أَوْ جَعَلَ لَهُ شَرِيكًا، أَوْ صَاحِبَةً أَوْ وَلَدًا، أَوْ كَذَّبَ اللهَ تَعَالَى أَوْ سَبَّهُ، أَوْ كَذَّبَ رَسُولَهُ أَوْ سَبَّهُ، أَوْ جَحَدَ نَبِيًّا،"]]},{"id":"um142_3","label":"بَابُ حُكْمِ المُرْتَدِّ · ٣","segs":[["matn","أَوْ جَحَدَ كِتَابَ اللَّهِ أَوْ شَيْئًا مِنْهُ أَوْ جَحَدَ أَحَدَ أَرْكَانِ الإِسْلَامِ، أَوْ أَحَلَّ مُحَرَّمًا ظَهَرَ الإِجْمَاعُ عَلَى تَحْرِيمِهِ، فَقَدِ ارْتَدَّ، إِلَّا أَنْ يَكُونَ مِمَّنْ تَخْفَى عَلَيْهِ الوَاجِبَاتُ وَالْمُحَرَّمَاتُ، فَيُعَرَّفُ ذَلِكَ، فَإِنْ لَمْ يَقْبَلْ، كَفَرَ."]]},{"id":"um142_4","label":"بَابُ حُكْمِ المُرْتَدِّ · ٤","segs":[["matn","وَيَصِحُّ إِسْلَامُ الصَّبِيِّ العَاقِلِ، وَإِنِ ارْتَدَّ لَمْ يُقْتَلْ حَتَّى يُسْتَتَابَ ثَلَاثًا بَعْدَ بُلُوغِهِ، وَمَنْ ثَبَتَتْ رِدَّتُهُ فَأَسْلَمَ، قُبِلَ مِنْهُ، وَيَكْفِي فِي إِسْلَامِهِ أَنْ يَشْهَدَ أَنْ لَا إِلَهَ إِلَّا اللهُ، وَأَنَّ مُحَمَّدًا رَسُولُ اللهِ،"]]},{"id":"um142_5","label":"بَابُ حُكْمِ المُرْتَدِّ · ٥","segs":[["matn","إِلَّا أَنْ يَكُونَ كُفْرُهُ بِجَحْدِ نَبِيٍّ، أَوْ كِتَابٍ، أَوْ فَرِيضَةٍ، أَوْ نَحْوِهِ، أَوْ يَعْتَقِدَ أَنَّ مُحَمَّدًا صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بُعِثَ إِلَى العَرَبِ خَاصَّةً، فَلَا يُقْبَلُ مِنْهُ حَتَّى يُقِرَّ بِمَا جَحَدَهُ."]]},{"id":"um142_6","label":"بَابُ حُكْمِ المُرْتَدِّ · ٦","segs":[["matn","وَإِذَا ارْتَدَّ الزَّوْجَانِ وَلَحِقَا بِدَارِ الحَرْبِ فَسُبِيَا، لَمْ يَجُزْ اسْتِرْقَاقُهُمَا، وَلَا اسْتِرْقَاقُ مَنْ وُلِدَ لَهُمَا قَبْلَ رِدَّتِهِمَا، وَيَجُوزُ اسْتِرْقَاقُ سَائِرِ أَوْلَادِهِمَا."]]}],"group":"كِتَابُ الحُدُودِ"},{"id":"um143","title":"كِتَابُ الجِهَادِ","units":[{"id":"um143_1","label":"كِتَابُ الجِهَادِ · ١","segs":[["matn","وَهُوَ فَرْضُ كِفَايَةٍ، إِذَا قَامَ بِهِ مَنْ يَكْفِي، سَقَطَ عَنِ البَاقِينَ، وَيَتَعَيَّنُ عَلَى مَنْ حَضَرَ الصَّفَّ، أَوْ حَصَرَ العَدُوُّ بَلَدَهُ، وَلَا يَجِبُ إِلَّا عَلَى ذَكَرٍ حُرٍّ، بَالِغٍ، عَاقِلٍ، مُسْتَطِيعٍ."]]},{"id":"um143_2","label":"كِتَابُ الجِهَادِ · ٢","segs":[["matn","وَالجِهَادُ أَفْضَلُ التَّطَوُّعُ؛ لِقَوْلِ أَبِي هُرَيْرَةَ: رَضِيَ اللهُ عَنْهُ سُئِلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَيُّ الأَعْمَالِ أَفْضَلُ؟"]]},{"id":"um143_3","label":"كِتَابُ الجِهَادِ · ٣","segs":[["matn","قَالَ: «إِيمَانٌ بِاللهِ» قَالَ: ثُمَّ أَيُّ قَالَ: «الجِهَادُ فِي سَبِيلِ اللهِ، ثُمَّ حَجٌّ مَبْرُورٌ.» وَعَنْ أَبِي سَعِيدٍ قَالَ: سُئِلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَيُّ النَّاسِ أَفْضَلُ؟"]]},{"id":"um143_4","label":"كِتَابُ الجِهَادِ · ٤","segs":[["matn","قَالَ: «رَجُلٌ يُجَاهِدُ فِي سَبِيلِ اللهِ بِمَالِهِ وَنَفْسِهِ،» وَغَزْوُ البَحْرِ أَفْضَلُ مِنْ غَزْوِ البَرِّ، وَيُغْزَى مَعَ كُلِّ بِرٍّ وَفَاجِرٍ، وَيُقَاتِلُ كُلُّ قَوْمٍ مَنْ يَلِيهِمْ مِنَ العَدُوِّ."]]},{"id":"um143_5","label":"كِتَابُ الجِهَادِ · ٥","segs":[["matn","وَتَمَامُ الرِّبَاطِ أَرْبَعُونَ يَوْمًا، وَرُوِيَ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: «رِبَاطُ يَوْمٍ فِي سَبِيلِ اللهِ خَيْرٌ مِنْ أَلْفِ يَوْمٍ فِيمَا سِوَاهُ» وَقَالَ:"]]},{"id":"um143_6","label":"كِتَابُ الجِهَادِ · ٦","segs":[["matn","«رِبَاطُ يَوْمٍ فِي سَبِيلِ اللهِ خَيْرٌ مِنْ صِيَامِ شَهْرٍ وَقِيَامِهِ، وَمَنْ مَاتَ مُرَابِطًا أُجْرِيَ لَهُ أَجْرُهُ إِلَى يَوْمِ القِيَامَةِ وَوُقِيَ الفَتَّانُ»."]]},{"id":"um143_7","label":"كِتَابُ الجِهَادِ · ٧","segs":[["matn","وَلَا يُجَاهِدُ مَنْ أَحَدُ أَبَوَيْهِ مُسْلِمٌ، إِلَّا بِإِذْنِهِ، إِلَّا أَنْ يَتَعَيَّنَ عَلَيْهِ، وَلَا يَدْخُلُ مِنَ النِّسَاءِ دَارَ الحَرْبِ إِلَّا امْرَأَةً طَاعِنَةً فِي السِّنِّ؛"]]},{"id":"um143_8","label":"كِتَابُ الجِهَادِ · ٨","segs":[["matn","لِسَقْيِ المَاءِ وَمُعَالَجَةِ الجَرْحَى، وَلَا يُسْتَعَانُ بِمُشْرِكٍ إِلَّا عِنْدَ الحَاجَةِ إِلَيْهِ، وَلَا يَجُوزُ الجِهَادُ إِلَّا بِإِذْنِ الأَمِيرِ، إِلَّا أَنْ يَفْجَأَهُمْ عَدُوٌّ يَخَافُونَ كَلَبَهُ،"]]},{"id":"um143_9","label":"كِتَابُ الجِهَادِ · ٩","segs":[["matn","أَوْ تَعْرِضَ فُرْصَةٌ يَخَافُونَ فَوْتَهَا، وَإِذَا دَخَلُوا دَارَ الحَرْبِ، لَمْ يَجُزْ لِأَحَدٍ أَنْ يَخْرُجَ مِنَ العَسْكَرِ لِعَلَفٍ أَوِ احْتِطَابٍ، أَوْ غَيْرِهِ، إِلَّا بِإِذْنِ الأَمِيرِ."]]},{"id":"um143_10","label":"كِتَابُ الجِهَادِ · ١٠","segs":[["matn","وَمَنْ أَخَذَ مِنْ دَارِ الحَرْبِ مَا لَهُ قِيمَةٌ، لَمْ يَجُزْ لَهُ أَنْ يَخْتَصَّ بِهِ، إِلَّا الطَّعَامَ وَالعَلَفَ، فَلَهُ أَنْ يَأْخُذَ مِنْهُ مَا يَحْتَاجُ إِلَيْهِ،"]]},{"id":"um143_11","label":"كِتَابُ الجِهَادِ · ١١","segs":[["matn","فَإِنْ بَاعَهُ، رَدَّ ثَمَنَهُ فِي المَغْنَمِ، وَإِنْ فَضَلَ مَعَهُ مِنْهُ بَعْدَ رُجُوعِهِ إِلَى بَلَدِهِ، لَزِمَهُ رَدُّهُ، إِلَّا أَنْ يَكُونَ يَسِيرًا، فَلَهُ أَكْلُهُ وَهَدِيَّتُهُ."]]},{"id":"um143_12","label":"كِتَابُ الجِهَادِ · ١٢","segs":[["matn","وَيَجُوزُ تَبْيِيتُ الكُفَّارِ وَرَمْيُهُمْ بِالْمَنْجَنِيقِ، وَقِتَالُهُمْ قَبْلَ دُعَائِهِمْ؛ لِأَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَغَارَ عَلَى بَنِي المُصْطَلِقِ وَهُمْ غَارُّونَ وَأَنْعَامُهُمْ تُسْقَى عَلَى الْمَاءِ، فَقَتَلَ مُقَاتِلَتَهُمْ، وَسَبَى ذَرَارِيَّهُمْ."]]},{"id":"um143_13","label":"كِتَابُ الجِهَادِ · ١٣","segs":[["matn","وَلَا يُقْتَلُ مِنْهُمْ صَبِيٌّ، وَلَا مَجْنُونٌ، وَلَا امْرَأَةٌ، وَلَا رَاهِبٌ، وَلَا شَيْخٌ فَانٍ، وَلَا زَمِنٌ، وَلَا أَعْمَى، وَلَا مَنْ لَا رَأْيَ لَهُمْ، إِلَّا أَنْ يُقَاتِلُوا؟"]]},{"id":"um143_14","label":"كِتَابُ الجِهَادِ · ١٤","segs":[["matn","وَيُخَيَّرُ الإِمَامُ فِي أُسَارَى الرِّجَالِ، بَيْنَ القَتْلِ، وَالِاسْتِرْقَاقِ، وَالفِدَاءِ، وَالْمَنِّ، وَلَا يَخْتَارُ إِلَّا الأَصْلَحَ لِلْمُسِلِمِينَ، وَإِنِ اسْتَرَقَّهُمْ أَوْ فَادَاهُمْ بِمَالٍ، فَهُوَ غَنِيمَةٌ."]]},{"id":"um143_15","label":"كِتَابُ الجِهَادِ · ١٥","segs":[["matn","وَلَا يُفَرَّقُ فِي السَّبْيِ بَيْنَ ذَوِي رَحِمٍ مَحْرَمٍ، إِلَّا أَنْ يَكُونُوا بِالغِينِ، وَمَنِ اشْتُرِيَ مِنْهُمْ عَلَى أَنَّهُ ذُو رَحِمٍ فَبَانَ بِخِلَافِهِ رُدَّ الفَضْلُ الَّذِي فِيهِ بِالتَّفْرِيقِ، وَمَنْ أُعْطِيَ شَيْئًا يَسْتَعِينُ بِهِ فِي غَزْوِهِ،"]]},{"id":"um143_16","label":"كِتَابُ الجِهَادِ · ١٦","segs":[["matn","فَإِذَا رَجَعَ، فَلَهُ مَا فَضَلَ، إِلَّا أَنْ يَكُونَ لَمْ يُعْطَ لِغُزَاةٍ بِعَيْنِهَا، فَيَرُدُّ الفَضْلَ فِي الغَزْوِ، وَإِنْ حُمِلَ عَلَى فَرَسٍ فِي سَبِيلِ اللهِ، فَهِيَ لَهُ إِذَا رَجَعَ، إِلَّا أَنْ يُجْعَلَ حَبِيسًا."]]},{"id":"um143_17","label":"كِتَابُ الجِهَادِ · ١٧","segs":[["matn","وَمَا أُخِذَ مِنْ أَمْوَالِ المُسْلِمِينَ، رُدَّ إِلَيْهِمْ، إِذَا عُلِمَ صَاحِبُهُ قَبْلَ القَسْمِهِ، وَإِنْ قُسِمَ قَبْلَ عِلْمِهِ، فَلَهُ أَخْذُهُ بِثَمَنِهِ الَّذِي حُسِبَ بِهِ عَلَى آخِذِهِ، وَإِنْ أَخَذَهُ أَحَدُ الرَّعِيَّةِ بِثَمَنٍ، فَلِصَاحِبِهِ أَخْذُهُ بِثَمَنِهِ، وَإِنْ أَخَذَهُ بِغَيْرِ شَيْءٍ، رَدَّهُ."]]},{"id":"um143_18","label":"كِتَابُ الجِهَادِ · ١٨","segs":[["matn","وَمَنِ اشْتَرَى أَسِيرًا مِنَ العَدُوِّ، فَعَلَى الأَسِيرِ أَدَاءُ مَا اشْتَرَاهُ بِهِ."]]}],"group":"كِتَابُ الجِهَادِ"},{"id":"um144","title":"بَابُ الأَنْفَالِ","units":[{"id":"um144_1","label":"بَابُ الأَنْفَالِ · ١","segs":[["matn","وَهِيَ: الزِّيادَةِ عَلَى السَّهْمِ المُسْتَحَقِّ، وَهِيَ ثَلَاثَةُ أَضْرُبٍ: أَحَدُهَا: سَلَبُ المَقْتُولِ غَيْرُ مَخْمُوسٍ لِقَاتِلِهِ؛"]]},{"id":"um144_2","label":"بَابُ الأَنْفَالِ · ٢","segs":[["matn","لِقَوْلِ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «مَنْ قَتَلَ قَتِيلاً فَلَهُ سَلَبُهُ،» وَهُوَ مَا عَلَيْهِ مِنْ لِبَاسٍ، وَحَلْيٍ، وَسِلَاحٍ، وَفَرَسِهِ بِآلَتِهَا وَإِنَّمَا يَسْتَحِقُّهُ مَنْ قَتَلَهُ حَالَ قِيَامِ الحَرْبِ غَيْرَ مُثْخَنٍ، وَلَا مَمْنُوعٍ مِنَ القِتَالِ."]]},{"id":"um144_3","label":"بَابُ الأَنْفَالِ · ٣","segs":[["matn","الثَّانِي: أَنْ يُنَفِّلَ الأَمِيرُ مَنْ أَغْنَى عَنِ المُسْلِمِينَ غَنَاءً مِنْ غَيْرِ شَرْطٍ، كَمَا أَعْطَى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَلَمَةَ بْنَ الأَكْوَعِ يَوْمَ ذِي قَرَدٍ سَهْمَ فَارِسٍ وَرَاجِلٍ،"]]},{"id":"um144_4","label":"بَابُ الأَنْفَالِ · ٤","segs":[["matn","وَنَفَّلَهُ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ لَيْلَةَ جَاءَهُ بِأَهْلِ تِسْعَةِ أَبْيَاتٍ امْرَأَةً مِنْهُمْ."]]},{"id":"um144_5","label":"بَابُ الأَنْفَالِ · ٥","segs":[["matn","الثَّالِثُ: مَا يُسْتَحَقُّ بِالشَّرْطِ، وَهُوَ نَوْعَانِ: أَحَدُهُمَا: أَنْ يَقُولَ الأَمِيرُ، مَنْ دَخَلَ النَّقْبَ، أَوْ صَعِدَ السُّورَ، فَلَهُ كَذَا، وَمَنْ جَاءَ بِعَشْرٍ مِنَ البَقَرِ، أَوْ غَيْرِهَا، فَلَهُ وَاحِدَةٌ مِنْهَا، فَيَسْتَحِقُّ مَا جُعِلَ لَهُ."]]},{"id":"um144_6","label":"بَابُ الأَنْفَالِ · ٦","segs":[["matn","الثَّانِي: أَنْ يَبْعَثَ الأَمِيرُ فِي البَدَاءَةِ سَرِيَّةً، وَيَجْعَلَ لَهَا الرُّبُعَ، وَفِي الرَّجْعَةِ أُخْرَى وَيَجْعَلَ لَهَا الثُّلُثَ، فَمَا جَاءَتْ بِهِ، أَخْرَجَ خُمُسَهُ، ثُمَّ أَعْطَى السَّرِيَّةَ مَا جَعَلَ لَهَا، وَقَسَّمَ البَاقِيَ فِي الجَيْشِ وَالسَّرِيَّةَ مَعًا."]]},{"id":"um144_7","label":"بَابُ الأَنْفَالِ · ٧","segs":[["matn","فَصْلٌ: وَيَرْضَخُ لِمَنْ لَا سَهْمَ لَهُ مِنَ النِّسَاءِ، وَالصِّبْيَانِ، وَالعَبِيدِ، وَالكُفَّارِ، فَيُعْطِيهِمْ عَلَى قَدْرِ غَنَائِمِهِمْ وَلَا يَبْلُغُ بِالرَّاجِلِ مِنْهُمْ سَهْمَ رَاجِلٍ، وَلَا بِالفَارِسِ سَهْمَ فَارِسٍ، وَإِنْ غَزَا العَبْدُ عَلَى فَرَسٍ لِسَيِّدِهِ، فَسَهْمُ الْفَرَسِ لِسَيِّدِهِ، وَيُرْضَخُ لِلْعَبْدِ."]]}],"group":"كِتَابُ الجِهَادِ"},{"id":"um145","title":"بَابُ الغَنَائِمِ وَقِسْمَتِهَا","units":[{"id":"um145_1","label":"بَابُ الغَنَائِمِ وَقِسْمَتِهَا · ١","segs":[["matn","وَهِيَ نَوْعَانِ: أَحَدُهُمَا: الأَرْضُ، فَيُخَيَّرُ الإِمَامِ بَيْنَ قِسْمَتِهَا وَوَقْفِهَا لِلْمُسْلِمِينَ، وَيَضْرِبُ عَلَيْهَا خَرَاجًا مُسْتَمِرًّا، يُؤْخَذُ مِمَّنْ هِيَ فِي يَدِهِ كُلَّ عَامٍ أَجْرًا لَهَا، وَمَا وَقَفَهُ الأَئِمَّةُ مِنْ ذَلِكَ، لَمْ يَجُزْ تَغْيِيرُهُ وَلَا بَيْعُهُ."]]},{"id":"um145_2","label":"بَابُ الغَنَائِمِ وَقِسْمَتِهَا · ٢","segs":[["matn","الثَّانِي: سَائِرُ الأَمْوَالِ، فَهِيَ لِمَنْ شَهِدَ الوَقْعَةَ، مِمَّنْ يُمْكِنُهُ القِتَالُ، وَيَسْتَعِدُّ لَهُ، مِنَ التُّجَّارِ وَغَيْرِهِمْ، سَوَاءٌ قَاتَلَ أَوْ لَمْ يُقَاتِلْ عَلَى الصِّفَةِ الَّتِي شَهِدَ الوَقْعَةَ فِيهَا، مِنْ كَوْنِهِ فَارِسًا، أَوْ رَاجِلاً، أَوْ عَبْدًا، أَوْ مُسْلِمًا، أَوْ كَافِرًا."]]},{"id":"um145_3","label":"بَابُ الغَنَائِمِ وَقِسْمَتِهَا · ٣","segs":[["matn","وَلَا يُعْتَبَرُ مَا قَبْلَ ذَلِكَ وَلَا مَا بَعْدَهُ، وَلَا حَقَّ فِيهَا لِعَاجِزٍ عَنِ القِتَالِ بِمَرَضٍ أَوْ غَيْرِهِ، وَلَا لِمَنْ جَاءَ بَعْدَ مَا تَنْقَضِي الحَرْبُ مِنْ مَدَدٍ، أَوْ غَيْرِهِ، وَمَنْ بَعَثَ الأَمِيرُ لِمَصْلَحَةِ الجَيْشِ، أَسْهَمَ لَهُ."]]},{"id":"um145_4","label":"بَابُ الغَنَائِمِ وَقِسْمَتِهَا · ٤","segs":[["matn","وَيُشَارِكُ الجَيْشُ سَرَايَاهُ فِيمَا غَنِمَتْ، وَتُشَارِكُهُ فِيمَا غَنِمَ."]]},{"id":"um145_5","label":"بَابُ الغَنَائِمِ وَقِسْمَتِهَا · ٥","segs":[["matn","وَيَبْدَأُ بِإِخْرَاجِ مُؤْنَةِ الغَنِيمَةِ؛ لِحِفْظِهَا وَنَقْلِهَا، وَسَائِرِ حَاجَتِهَا ثُمَّ يَدْفَعُ الأَسْلَابَ إِلَى أَهْلِهَا، وَالأَجْعَالَ لِأَصْحَابِهَا، ثُمَّ يُخَمِّسُ بَاقِيَهَا، فَيَقْسِمُ خُمْسَهَا خَمْسَةَ أَسْهُمٍ: سَهْمٌ لِلَّهِ تَعَالَى وَلِرَسُولِهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، يُصْرَفُ فِي السِّلَاحِ وَالْكُرَاعِ وَالْمَصَالِحِ وَسَهْمٌ لِذَوِي القُرْبَى،"]]},{"id":"um145_6","label":"بَابُ الغَنَائِمِ وَقِسْمَتِهَا · ٦","segs":[["matn","وَهُمْ بَنُو هَاشِمٍ وَبَنُو المُطَّلِبِ غَنِيُّهُمْ وَفَقِيرُهُمْ، لِلذَّكَرِ مِثْلُ حَظِّ الأُنْثَيَيْنِ، وَسَهْمٌ لِلْيَتَامَى الفُقُرَاءِ، وَسَهْمٌ لِلْمَسَاكِينِ، وَسَهْمٌ لِأَبْنَاءِ السَّبِيلِ، ثُمَّ يُخْرِجُ بَاقِيَ الأَنْفَالِ، وَالرَّضْخِ، ثُمَّ يَقْسِمُ مَا بَقِيَ لِلرَّاجِلِ سَهْمٌ، وَلِلْفَارِسِ ثَلَاثَةُ أَسْهُمٍ، سَهْمٌ لَهُ وَلِفَرَسِهِ سَهْمَانِ؛"]]},{"id":"um145_7","label":"بَابُ الغَنَائِمِ وَقِسْمَتِهَا · ٧","segs":[["matn","لِمَا رَوَى ابْنُ عُمَرَ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جَعَلَ لِلْفَرَسِ سَهْمَيْنِ، وَلِصَاحِبِهِ سَهْمًا، وَإِنْ كَانَ الفَرَسُ غَيْرَ عَرَبِيٍّ،"]]},{"id":"um145_8","label":"بَابُ الغَنَائِمِ وَقِسْمَتِهَا · ٨","segs":[["matn","فَلَهُ سَهْمٌ وَلِصَاحِبِهِ سَهْمٌ، وَإِنْ كَانَ مَعَ الرَّجُلِ فَرَسَانِ، أُسهِمَ لَهُمَا، وَلَا يُسْهَمُ لِأَكْثَرَ مِنْ فَرَسَيْنِ، وَلَا يُسْهَمُ لِدَابَّةٍ غَيْرِ الخَيْلِ."]]},{"id":"um145_9","label":"بَابُ الغَنَائِمِ وَقِسْمَتِهَا · ٩","segs":[["matn","فَصْلٌ: وَمَا تَرَكَهُ الكُفَّارُ فَزَعًا وَهَرَبُوا، لَمْ يُوجَفْ عَلَيْهِ بِخَيْلٍ وَلَا رِكَابٍ، أَوْ أُخِذَ مِنْهُمْ بِغَيْرِ قِتَالٍ، فَهُوَ فَيْءٌ يُصْرَفُ فِي مَصَالِحِ المُسْلِمِينَ."]]},{"id":"um145_10","label":"بَابُ الغَنَائِمِ وَقِسْمَتِهَا · ١٠","segs":[["matn","وَمَنْ وَجَدَ كَافِرًا ضَالاً عَنِ الطَّرِيقِ أَوْ غَيْرِهِ فِي دَارِ الإِسْلَامِ، فَأَخَذَهُ فَهُوَ لَهُ، وَإِنْ دَخَلَ قَوْمٌ لَا مَنَعَةَ لَهُمْ أَرْضَ الحَرْبِ مُتَلَصِّصِينَ بِغَيْرِ إِذْنِ الإِمَامِ، فَمَا أَخَذُوهُ فَهُوَ لَهُمْ بَعْدَ الخُمُسِ."]]}],"group":"كِتَابُ الجِهَادِ"},{"id":"um146","title":"بَابُ الأَمَانِ","units":[{"id":"um146_1","label":"بَابُ الأَمَانِ · ١","segs":[["matn","وَمَنْ قَالَ لِحَرْبِيٍّ: قَدْ أَجَرْتُكَ، أَوْ أَمَّنْتُكَ، أَوْ لَا بَأْسَ عَلَيْكَ، وَنَحْوَ هَذَا، فَقَدْ أَمَّنَهُ."]]},{"id":"um146_2","label":"بَابُ الأَمَانِ · ٢","segs":[["matn","وَيَصِحُّ الأَمَانُ مِنْ كُلِّ مُسْلِمٍ، عَاقِلٍ، مُخْتَارٍ، حُرًّا كَانَ أَوْ عَبْدًا، رَجُلاً كَانَ أَوِ امْرَأَةً؛ لِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «الْمُؤْمِنُونَ تَتَكَافَأُ دِمَاؤُهُمْ، وَيَسْعَى بِذِمَّتِهِمْ أَدْنَاهُمْ»."]]},{"id":"um146_3","label":"بَابُ الأَمَانِ · ٣","segs":[["matn","وَيَصِحُّ أَمَانُ آحَادِ الرَّعِيَّةِ لِلْجَمَاعَةِ اليَسِيرَةِ، وَأَمَانُ الأَمِيرِ لِلْبَلَدِ الَّذِي أُقِيمَ بِإِزَائِهِ، وَأَمَانُ الإِمَامِ لِجَمِيعِ الكُفَّارِ، وَمَنْ دَخَلَ دَارَهُمْ بِأَمَانِهِمْ، فَقَدْ أَمَّنَهُمْ مِنْ نَفْسِهِ،"]]},{"id":"um146_4","label":"بَابُ الأَمَانِ · ٤","segs":[["matn","وَإِنْ خَلَّوْا أَسِيرًا مِنَّا بِشَرْطِ أَنْ يَبْعَثَ إِلَيْهِمْ مَالًا مَعْلُومًا، لَزِمَهُ الوَفَاءُ لَهُمْ، فَإِنْ شَرَطُوا عَلَيْهِ أَنْ يَعُودَ إِلَيْهِمْ، إِنْ عَجِزَ لَزِمَهُ الْوَفَاءُ لَهُمْ إِلَّا أَنْ تَكُونَ امْرَأَةً فَلَا تَرْجِعُ إِلَيْهِمْ."]]},{"id":"um146_5","label":"بَابُ الأَمَانِ · ٥","segs":[["matn","فَصْلٌ: وَتَجُوزُ مُهَادَنَةُ الكُفَّارِ، إِذَا رَأَى الإِمَامُ المَصْلَحَةَ فِيهَا، وَلَا يَجُوزُ عَقْدُهَا إِلَّا مِنَ الإِمَامِ أَوْ نَائِبِهِ، وَعَلَيْهِ حِمَايَتُهُمْ مِنَ المُسْلِمِينَ، دُونَ أَهْلِ الحَرْبِ، وَإِنْ خَافَ نَقْضَ العَهْدِ مِنْهُمْ نَبَذَ إِلَيْهِمْ عَهْدَهُمْ، وَإِنْ سَبَاهُمْ كُفَّارُ آخَرُونَ، لَمْ يَجُزْ لَنَا شِرَاؤُهُمْ."]]},{"id":"um146_6","label":"بَابُ الأَمَانِ · ٦","segs":[["matn","وَتَجِبُ الهَجْرَةُ عَلَى مَنْ لَمْ يَقْدِرْ عَلَى إِظْهَارِ دِينِهِ فِي دَارِ الحَرْبِ، وَتُسْتَحَبُّ لِمَنْ قَدِرَ عَلَى ذَلِكَ، وَلَا تَنْقَطِعُ الهِجْرَةُ مَا قُوتِلَ الكُفَّارُ، إِلَّا مِنْ بَلَدٍ بَعْدَ فَتْحِهِ."]]}],"group":"كِتَابُ الجِهَادِ"},{"id":"um147","title":"بَابُ الجِزْيَةِ","units":[{"id":"um147_1","label":"بَابُ الجِزْيَةِ · ١","segs":[["matn","وَلَا تُؤْخَذُ الجِزْيَةُ إِلَّا مِنْ أَهْلِ الكِتَابِ، وَهُمُ اليَهُودُ وَمَنْ دَانَ بِالتَّوْرَاةِ، وَالنَّصَارَى وَمَنْ دَانَ بِالإِنْجِيلِ، وَالْمَجُوسُ إِذَا التَزَمُوا أَدَاءَ الجِزْيَةِ وَأَحْكَامَ الْمِلَّةِ، وَمَتَى طَلَبُوا ذَلِكَ، لَزِمَ إِجَابَتُهُمْ وَحَرُمَ قِتَالُهُمْ."]]},{"id":"um147_2","label":"بَابُ الجِزْيَةِ · ٢","segs":[["matn","وَتُؤْخَذُ الجِزْيَةُ فِي رَأْسِ كُلِّ حَوْلٍ. مِنَ المُوسِرِ ثَمَانِيَةٌ وَأَرْبَعُونَ دِرْهَمًا، وَمِنَ الْمُتَوَسِّطِ أَرْبَعَةٌ وَعِشْرُونَ دِرْهَمًا، وَمِنْ دُونَهُ اثْنَا عَشَرَ دِرْهَمًا."]]},{"id":"um147_3","label":"بَابُ الجِزْيَةِ · ٣","segs":[["matn","وَلَا جِزْيَةَ عَلَى صَبِيٍّ، وَلَا امْرَأَةٍ، وَلَا شَيْخٍ فَانٍ، وَلَا زَمِنٍ، وَلَا أَعْمَى، وَلَا عَبْدٍ، وَلَا فَقِيرٍ عَاجِزٍ عَنْهَا. وَمَنْ أَسْلَمَ بَعْدَ وُجُوبِهَا، سَقَطَتْ عَنْهُ، وَإِنْ مَاتَ، أُخِذَتْ مِنْ تَرِكَتِهِ."]]},{"id":"um147_4","label":"بَابُ الجِزْيَةِ · ٤","segs":[["matn","وَمَنِ اتَّجَرَ مِنْهُمْ إِلَى غَيْرِ بَلَدِهِ، ثُمَّ عَادَ، أُخِذَ مِنْهُ نِصْفُ العُشْرِ، وَإِنْ دَخَلَ إِلَيْنَا تَاجِرٌ حَرْبِيٌّ، أُخِذَ مِنْهُ العُشْرُ."]]},{"id":"um147_5","label":"بَابُ الجِزْيَةِ · ٥","segs":[["matn","وَمَنْ نَقَضَ العَهْدَ بِامْتِنَاعِهِ مِنِ التِزَامِ الجِزْيَةِ، وَأَحْكَامِ الْمِلَّةِ، أَوْ قِتَالِ المُسْلِمِينَ وَنَحْوِهِ، أَوِ الْهَرَبِ إِلَى دَارِ الحَرْبِ، حَلَّ دَمُهُ وَمَالُهُ، وَلَا يَنْتَقِضْ عَهْدُ نِسَائِهِ وَأَوْلَادِهِ بِنَقْضِهِ، إِلَّا أَنْ يَذْهَبَ بِهِمْ إِلَى دَارِ الحَرْبِ."]]}],"group":"كِتَابُ الجِهَادِ"},{"id":"um148","title":"كِتَابُ القَضَاءِ","units":[{"id":"um148_1","label":"كِتَابُ القَضَاءِ · ١","segs":[["matn","وَهُوَ فَرْضُ كِفَايَةٍ، يَلْزَمُ الإِمَامَ نَصْبُ مَنْ يُكْتَفِى بِهِ فِي القَضَاءِ، وَيَجِبُ عَلَى مَنْ يَصْلُحُ لَهُ، إِذَا طُلِبَ مِنْهُ وَلَمْ يُوجَدْ غَيْرُهُ، الإِجَابَةُ إِلَيْهِ، وَإِنْ وُجِدَ غَيْرُهُ، فَالأَفْضَلُ تَرْكُهُ."]]},{"id":"um148_2","label":"كِتَابُ القَضَاءِ · ٢","segs":[["matn","وَمِنْ شَرْطِهِ أَنْ يَكُونَ رَجُلاً، حُرًّاً، مَسْلِمًا، سَمِيعًا، بَصِيرًا، مُتكَلِّمَاً، عَدْلاً، عَالِمًا."]]},{"id":"um148_3","label":"كِتَابُ القَضَاءِ · ٣","segs":[["matn","وَلَا يَجُوزُ لَهُ أَنْ يَقْبَلَ رِشْوَةً، وَلَا هَدِيَّةً مِمَّنْ لَمْ يَكُنْ يُهْدِيهِ إِلَيْهِ، وَلَا الحُكْمُ قَبْلَ مَعْرِفَةِ الحَقِّ، فَإِنْ أَشْكَلَ عَلَيْهِ،"]]},{"id":"um148_4","label":"كِتَابُ القَضَاءِ · ٤","segs":[["matn","شَاوَرَ فِيهِ أَهْلَ العِلْمِ وَالأَمَانَةِ، وَلَا يَحْكُمُ وَهُوَ غَضْبَانُ، وَلَا فِي حَالٍ يَمْنَعُ اسْتِيفَاءَ الرَّأْيِ، وَلَا يَتَّخِذُ فِي مَجْلِسِ الحُكْمِ بَوَّابًا. وَيَجِبُ العَدْلُ بَيْنَ الخَصْمَيْنِ فِي الدُّخُولِ عَلَيْهِ، وَالْمَجْلِسِ، وَالْخِطَابِ."]]}],"group":"كِتَابُ القَضَاءِ"},{"id":"um149","title":"بَابُ صِفَةِ الحُكْمِ","units":[{"id":"um149_1","label":"بَابُ صِفَةِ الحُكْمِ · ١","segs":[["matn","إِذَا جَلَسَ إِلَيْهِ الخَصْمَانِ، فَادَّعَى أَحَدُهُمَا عَلَى الآخَرِ، لَمْ تُسْمَعِ الدَّعْوَى إِلَّا مُحَرَّرَةً تَحْرِيرًا يَعْلَمُ بِهِ الْمُدَّعَى عَلَيْهِ، فَإِنْ كَانَ دَيْنًا، ذَكَرَ قَدْرَهُ وَجِنْسَهُ، وَإِنْ كَانَ عَقَارًا، ذَكَرَ مَوْضِعَهُ وَحَدَّهُ وَإِنْ كَانَ عَيْنًا حَاضِرَةً عَيَّنَهَا."]]},{"id":"um149_2","label":"بَابُ صِفَةِ الحُكْمِ · ٢","segs":[["matn","وَإِنْ كَانَتْ غَائِبَةً، ذَكَرَ جِنْسَهَا وَقِيمَتَهَا، ثُمَّ يَقُولُ لِخَصْمِهِ: مَا تَقُولُ؟"]]},{"id":"um149_3","label":"بَابُ صِفَةِ الحُكْمِ · ٣","segs":[["matn","فَإِنْ أَقَرَّ، حُكِمَ لِلْمُدَّعِي، وَإِنْ أَنْكَرَ، لَمْ يَخْلُ مِنْ ثَلَاثَةِ أَقْسَامٍ: أَحَدُهَا: أَنْ تَكُونَ فِي يَدِ أَحَدُهُمَا، فَيَقُولُ لِلْمُدَّعِي: أَلَكَ بَيِّنَةٌ؟"]]},{"id":"um149_4","label":"بَابُ صِفَةِ الحُكْمِ · ٤","segs":[["matn","فَإِنْ قَالَ: نَعَمْ، وَأَقَامَهَا، حَكَمَ لَهُ، بِهَا وَإِنْ لَمْ تَكُنْ لَهُ بَيِّنَةٌ، قَالَ فَلَكَ يَمِينُهُ، فَإِنْ طَلَبَهَا، اسْتَحْلَفَهُ وَبَرِئَ؛"]]},{"id":"um149_5","label":"بَابُ صِفَةِ الحُكْمِ · ٥","segs":[["matn","لِقَوْلِ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «لَوْ يُعْطَى النَّاسُ بِدَعْوَاهُمْ، لَادَّعَى قَوْمٌ دِمَاءَ رِجَالٍ وَأَمْوَالَهُمْ، وَلَكِنَّ الْيَمِينَ عَلَى الْمُدَّعَى عَلَيْهِ،» وَإِنْ نَكَلَ عَنِ اليَمِينِ، وَرَدَّهَا عَلَى الْمُدَّعِي، اسْتَحْلَفَهُ وَحَكَمَ لَهُ، وَإِنْ نَكَلَ أَيْضًا، صَرَفَهُمَا."]]},{"id":"um149_6","label":"بَابُ صِفَةِ الحُكْمِ · ٦","segs":[["matn","وَإِنْ كَانَ لِكُلِّ وَاحِدٍ مِنْهُمَا بَيِّنَةٌ، حَكَمَ بِهَا لِلْمُدَّعِي، فَإِنْ أَقَرَّ صَاحِبُ اليَدِ لِغَيْرِهِ، صَارَ الْمُقَرُّ لَهُ الخَصْمَ فِيهَا، وَقَامَ مَقَامَ صَاحِبِ اليَدِ فِيمَا ذَكَرْنَا."]]},{"id":"um149_7","label":"بَابُ صِفَةِ الحُكْمِ · ٧","segs":[["matn","الثَّانِي: أَنْ تَكُونَ فِي يَدَيْهِمَا، فَإِنْ كَانَتْ لِأَحَدُهُمَا بَيِّنَةٌ، حُكِمَ لَهُ بِهَا، وَإِنْ لَمْ يَكُنْ لِوَاحِدٍ مِنْهُمَا بَيِّنَةٌ، أَوْ لَهُمَا بَيِّنَتَانِ، قُسِمَتْ بَيْنَهُمَا،"]]},{"id":"um149_8","label":"بَابُ صِفَةِ الحُكْمِ · ٨","segs":[["matn","وَحَلَفَ كُلُّ وَاحِدٍ مِنْهُمَا عَلَى النِّصْفِ الْمَحْكُومِ لَهُ بِهِ، وَإِنِ ادَّعَاهَا أَحَدُهُمَا، وَادَّعَى الآخَرُ نِصْفَهَا، وَلَا بَيِّنَةَ، قُسِمَتْ بَيْنَهُمَا، وَاليَمِينُ عَلَى مُدَّعِي النَّصْفِ، وَإِنْ كَانَتْ لَهُمَا بَيِّنَتَانِ، حُكِمَ بِهَا لِمُدَّعِي الكَلِّ."]]},{"id":"um149_9","label":"بَابُ صِفَةِ الحُكْمِ · ٩","segs":[["matn","الثَّالِثُ: أَنْ تَكُونَ فِي يَدِ غَيْرِهِمَا، وَإِنْ أَقَرَّ بِهَا لِأَحَدُهُمَا، أَوْ لِغَيْرِهِمَا، صَارَ الْمُقَرُّ لَهُ كَصَاحِبِ اليَدِ، وَإِنْ أَقَرَّ لَهُمَا، صَارَتْ كَالَّتِي فِي يَدَيْهِمَا، وَإِنْ قَالَ:"]]},{"id":"um149_10","label":"بَابُ صِفَةِ الحُكْمِ · ١٠","segs":[["matn","لَا أَعْرِفُ صَاحِبَهَا مِنْهُمَا، وَلِأَحَدِهِمَا بَيِّنَةٌ، فَهِيَ لَهُ، وَإِنْ لَمْ يَكُنْ لَهُمَا بَيِّنَةٌ، أَوْ لِكُلِّ مِنْهُمَا بَيِّنَةٌ، اسْتَهَمَا عَلَى اليَمِينِ، فَمَنْ خَرَجَ سَهْمُهُ، حَلَفَ وَأَخَذَهَا."]]}],"group":"كِتَابُ القَضَاءِ"},{"id":"um150","title":"بَابُ تَعَارُضِ الدَّعَاوَى","units":[{"id":"um150_1","label":"بَابُ تَعَارُضِ الدَّعَاوَى · ١","segs":[["matn","إَذَا تَنَازَعَا قَمِيصًا، أَحَدُهُمَا لَابِسُهُ، وَالآخَرُ آخِذٌ بِكُمِّهِ، فَهُوَ لِلِابِسِهِ. وَإِنْ تَنَازَعَا دَابَّةً، أَحَدُهُمَا رَاكِبُهَا، أَوْ لَهُ عَلَيْهَا حِمْلٌ، فَهِيَ لَهُ."]]},{"id":"um150_2","label":"بَابُ تَعَارُضِ الدَّعَاوَى · ٢","segs":[["matn","وَإِنْ تَنَازَعَا أَرْضًا فِيهَا شَجَرٌ أَوْ بِنَاءٌ، أَوْ زَرْعٌ لِأَحَدُهُمَا، فَهِيَ لَهُ. وَإِنْ تَنَازَعَ صَانِعَانِ فِي قُمَاشِ دُكَّانٍ، فَآلَةُ كُلِّ صِنَاعَةٍ لِصَاحِبِهَا."]]},{"id":"um150_3","label":"بَابُ تَعَارُضِ الدَّعَاوَى · ٣","segs":[["matn","وَإِنْ تَنَازَعَ الزَّوْجَانِ فِي قُمَاشِ البَيْتِ، فَلِلزَّوْجِ مَا يَصْلُحُ لِلرِّجَالِ، وَلِلْمَرْأَةِ مَا يَصْلُحُ لِلنِّسَاءِ، وَمَا يَصْلُحُ لَهُمَا، بَيْنَهُمَا."]]},{"id":"um150_4","label":"بَابُ تَعَارُضِ الدَّعَاوَى · ٤","segs":[["matn","وَإِنْ تَنَازَعَا حَائِطًا مَعْقُودًا بِبِنَائِهِمَا، أَوْ مَحْلُولاً مِنْهُمَا، فَهُوَ بَيْنَهُمَا، وَإِنْ كَانَ مَعْقُودًا بِبِنَاءِ أَحَدُهُمَا وَحْدَهُ، فَهُوَ لَهُ."]]},{"id":"um150_5","label":"بَابُ تَعَارُضِ الدَّعَاوَى · ٥","segs":[["matn","وَإِنْ تَنَازَعَ صَاحِبُ العُلُوِّ وَالسُفْلِ فِي السَّقْفِ الَّذِي بَيْنَهُمَا، أَوْ تَنَازَعَ صَاحِبُ الأَرْضِ وَالنَّهْرِ فِي الحَائِطِ الَّذِي بَيْنَهُمَا، أَوْ تَنَازَعَا قَمِيصًا أَحَدُهُمَا آخِذٌ بِكُمِّهِ وَبَاقِيهِ مَعَ الآخَرِ، فَهُوَ بَيْنَهُمَا."]]},{"id":"um150_6","label":"بَابُ تَعَارُضِ الدَّعَاوَى · ٦","segs":[["matn","وَإِنْ تَنَازَعَ مُسْلِمٌ وَكَافِرٌ فِي مَيِّتٍ، يَزْعُمُ كُلُّ وَاحِدٍ مِنْهُمَا أَنَّهُ مَاتَ عَلَى دِينِهِ، فَإِنْ عُرِفَ أَصْلُ دِينِهِ، حُمِلَ عَلَيْهِ، وَإِنْ لَمْ يُعْرَفْ أَصْلُ دِينِهِ، فَالْمِيرَاثُ لِلْمُسْلِمِ، وَإِنْ كَانَتْ لَهُمَا بَيِّنَتَانِ، فَكَذَلِكَ، وَإِنْ كَانَتْ لِأَحَدُهُمَا بَيِّنَةٌ، حُكِمَ لَهُ بِهَا."]]},{"id":"um150_7","label":"بَابُ تَعَارُضِ الدَّعَاوَى · ٧","segs":[["matn","وَإِنِ ادَّعَى كُلُّ وَاحِدٍ مِنَ الشَّرِيكَيْنِ فِي العَبْدِ أَنَّ شَرِيكَهُ أَعْتَقَ نَصِيبَهُ وَهُمَا مُوسِرَانِ، عَتَقَ كُلُّهُ وَلَا وَلَاءَ لَهُمَا عَلَيْهِ، وَإِنْ كَانَ أَحَدُهُمَا مُوسِرًا وَالآخَرُ مُعْسِرًا، عَتَقَ نَصِيبُ الْمُوسِرِ وَحْدَهُ،"]]},{"id":"um150_8","label":"بَابُ تَعَارُضِ الدَّعَاوَى · ٨","segs":[["matn","وَإِنْ كَانَا مُعْسِرَيْنِ، لَمْ يَعْتِقْ مِنْهُ شَيْءٌ، وَإِنِ اشْتَرَى أَحَدُهُمَا نَصِيبَ صَاحِبِهِ، عَتَقَ حِينَئِذٍ وَلَمْ يَسْرِ إِلَى بَاقِيهِ، وَلَا وَلَاءَ عَلَيْهِ، وَإِنِ ادَّعَى كُلُّ وَاحِدٍ مِنَ الْمُوسِرَيْنِ أَنَّهُ أَعْتَقَهُ، تَحَالَفَا وَكَانَ وَلَاؤُهُ بَيْنَهُمَا."]]},{"id":"um150_9","label":"بَابُ تَعَارُضِ الدَّعَاوَى · ٩","segs":[["matn","وَإِنْ قَالَ الرَّجُلُ لِعَبْدِهِ: إِنْ بَرِئْتُ مِنْ مَرَضِي هَذَا، فَأَنْتَ حُرٌّ، وَإِنْ قُتِلْتُ، فَأَنْتَ حُرٌّ، فَادَّعَى العَبْدُ بُرْءَهُ، أَوْ قَتْلَهُ، وَأَنْكَرَتِ الوَرَثَةُ، فَالْقَوْلُ قَوْلُهُمْ، وَإِنْ أَقَامَ كُلُّ وَاحِدٍ مِنْهُمْ بَيِّنَةً بِقَوْلِهِ، عَتَقَ العَبْدُ؛ لِأَنَّ بَيِّنَتَهُ تَشْهَدُ بِزِيَادَةٍ."]]},{"id":"um150_10","label":"بَابُ تَعَارُضِ الدَّعَاوَى · ١٠","segs":[["matn","وَلَوْ مَاتَ رَجُلٌ وَخَلَّفَ ابْنَيْنِ وَعَبْدَيْنِ مُتَسَاوِيَيْ القِيمَةِ، لَا مَالَ لَهُ سِوَاهُمَا، فَأَقَرَّ الِابْنَانِ أَنَّهُ أَعْتَقَ أَحَدُهُمَا فِي مَرَضِ مَوْتِهِ، عَتَقَ مِنْهُ ثُلُثَاهُ إِنْ لَمْ يُجِيزَا عِتْقَهُ كُلَّهُ، وَإِنْ قَالَ أَحَدُهُمَا: أَبِي أَعْتَقَ هَذَا،"]]},{"id":"um150_11","label":"بَابُ تَعَارُضِ الدَّعَاوَى · ١١","segs":[["matn","وَقَالَ الآخَرُ: بَلْ هَذَا، عَتَقَ ثُلُثُ كُلِّ وَاحِدٍ مِنْهُمَا، وَكَانَ لِكُلِّ ابْنٍ سُدُسُ الَّذِي اعْتَرَفَ بِعِتْقِهِ وَنِصْفُ الآخَرِ، وَإِنْ قَالَ الثَّانِي: أَبِي أَعْتَقَ أَحَدُهُمَا لَا أَدْرِي مَنْ مِنْهُمَا، أُقْرِعَ بَيْنَهُمَا، وَقَامَتِ القُرْعَةُ مَقَامَ تَعْيِينِهِ."]]}],"group":"كِتَابُ القَضَاءِ"},{"id":"um151","title":"بَابُ حُكْمِ كِتَابِ القَاضِي","units":[{"id":"um151_1","label":"بَابُ حُكْمِ كِتَابِ القَاضِي · ١","segs":[["matn","يَجُوزُ الحُكْمُ عَلَى الغَائِبِ، إِذَا كَانَتْ لِلْمُدَّعِي بَيِّنَةٌ، وَمَتَى حَكَمَ عَلَى غَائِبٍ، ثُمَّ كَتَبَ بِحُكْمِهِ إِلَى قَاضِي بَلَدِ الغَائِبِ، لَزِمَهُ قَبُولُهُ، وَأَخَذَ الْمَحْكُومَ عَلَيْهِ بِهِ."]]},{"id":"um151_2","label":"بَابُ حُكْمِ كِتَابِ القَاضِي · ٢","segs":[["matn","وَلَا يَثْبُتُ إِلَّا بِشَاهِدَيْنِ عَدْلَيْنِ، يَقُولَانِ: قَرَأَهُ عَلَيْنَا، أَوْ قُرِئَ عَلَيْهِ بِحَضْرَتِنَا، فَقَالَ: اشْهَدَا عَلَيَّ أَنَّ هَذَا كِتَابِي إِلَى فُلَانٍ، أَوْ إِلَى مَنْ يَصِلُ إِلَيْهِ مِنْ قُضَاةِ الْمُسْلِمِينَ وَحُكَّامِهِمْ."]]},{"id":"um151_3","label":"بَابُ حُكْمِ كِتَابِ القَاضِي · ٣","segs":[["matn","فَإِنْ مَاتَ الْمَكْتُوبُ إِلَيْهِ، أَوْ عُزِلَ، فَوَصَلَ إِلَى غَيْرِهِ، عَمِلَ بِهِ، وَإِنْ مَاتَ الكَاتِبُ، أَوْ عُزِلَ بَعْدَ حُكْمِهِ، جَازَ قَبُولُ كِتَابِهِ، وَيُقْبَلُ كِتَابُ القَاضِي فِي كُلِّ حَقٍّ، إِلَّا الْحُدُودَ وَالْقِصَاصَ."]]}],"group":"كِتَابُ القَضَاءِ"},{"id":"um152","title":"بَابُ القِسْمَةِ","units":[{"id":"um152_1","label":"بَابُ القِسْمَةِ · ١","segs":[["matn","وَهِيَ نَوْعَانِ: قِسْمَةُ إِجْبَارٍ، وَهِيَ: مَا يُمْكِنُ قِسْمَتُهُ مِنْ غَيْرِ ضَرَرٍ، وَلَا رَدِّ عِوَضٍ إِذَا طَلَبَ أَحَدُ الشَّرِيكَيْنِ قَسْمَهُ، فَأَبَى الآخَرُ، أَجْبَرَهُ الحَاكِمُ عَلَيْهِ إِذَا ثَبَتَ عِنْدَهُ مِلْكُهُمَا بِبَيِّنَةٍ،"]]},{"id":"um152_2","label":"بَابُ القِسْمَةِ · ٢","segs":[["matn","فَإِنْ أَقَرَّ بِهِ، لَمْ يُجْبِرِ الْمُمْتَنِعَ عَلَيْهِ، وَإِنْ طَلَبَاهَا فِي هَذِهِ الحَالِ، قُسِمَتْ بَيْنَهُمَا، وَأَثْبَتَ فِي القَضِيَّةِ أَنَّ قَسْمَهُ كَانَ عَنْ إِقْرَارٍ لَا عَنْ بَيِّنَةٍ."]]},{"id":"um152_3","label":"بَابُ القِسْمَةِ · ٣","segs":[["matn","وَالثَّانِي: قِسْمَةُ التَّرَاضِي، وَهِيَ قِسْمَةُ مَا فِيهِ ضَرَرٌ؛ بِأَنْ لَا يَنْتَفِعَ أَحَدُهُمَا بِنَصِيبِهِ فِيمَا هُوَ لَهُ، أَوْ لَا يُمْكِنُ تَعْدِيلُهُ، إِلَّا بِرَدِّ عِوَضٍ مِنْ أَحَدُهُمَا، فَلَا إِجْبَارَ فِيهَا."]]},{"id":"um152_4","label":"بَابُ القِسْمَةِ · ٤","segs":[["matn","وَالقِسْمَةُ إِفْرَازُ حَقٍّ لَا يَسْتَحِقُّ بِهَا شُفْعَةٌ، وَلَا يَثْبُتُ فِيهَا خِيَارٌ، وَتَجُوزُ فِي المَكِيلِ وَزْنًا، وَفِي الْمَوْزُونِ كَيْلاً، وَفِي الثِّمَارِ خَرْصًا،"]]},{"id":"um152_5","label":"بَابُ القِسْمَةِ · ٥","segs":[["matn","وَتَجُوزُ قِسْمَةُ الوَقْفِ إِذَا لَمْ يَكُنْ فِيهَا رَدُّ عِوَضٍ، فَإِنْ كَانَ بَعْضُهُ طِلْقًا، وَبَعْضُهُ وَقْفًا، وَفِيهَا عِوَضٍ مِنْ صَاحِبِ الطِّلْقِ لَمْ يَجُزْ، وَإِنْ كَانَ مِنْ رَبِّ الوَقْفِ، جَازَ."]]},{"id":"um152_6","label":"بَابُ القِسْمَةِ · ٦","segs":[["matn","وَإِذَا عُدِّلَتِ الأَجْزَاءُ، أُقرِعَ عَلَيْهَا، فَمَنْ خَرَجَ سَهْمُهُ عَلَى شَيْءٍ، صَارَ لَهُ، وَلَزِمَ بِذَلِكَ. وَيَجِبُ أَنْ يَكُونَ قَاسِمَ الحَاكِمِ عَدْلاً، وَكَذَلِكَ كَاتِبُهُ."]]}],"group":"كِتَابُ القَضَاءِ"},{"id":"um153","title":"كِتَابُ الشَّهَادَاتِ","units":[{"id":"um153_1","label":"كِتَابُ الشَّهَادَاتِ · ١","segs":[["matn","تَحَمُّلُ الشَّهَادَةِ وَأَدَاؤُهَا فَرْضُ كِفَايَةٍ، إِذَا لَمْ يُوجَدْ مَنْ يَقُومُ بِهَا سِوَى اثْنَيْنِ، لَزِمَهُمَا القِيَامُ بِهَا، عَلَى القَرِيبِ وَالبَعِيدِ، إِذَا أَمْكَنَهُمَا ذَلِكَ مِنْ غَيْرِ ضَرَرٍ؛"]]},{"id":"um153_2","label":"كِتَابُ الشَّهَادَاتِ · ٢","segs":[["matn","لِقَوْلِ اللهِ تَعَالَى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا كُونُوا قَوَّامِينَ بِالْقِسْطِ شُهَدَاءَ لِلَّهِ وَلَوْ عَلَى أَنْفُسِكُمْ أَوِ الْوَالِدَيْنِ﴾ الْآيَةَ."]]},{"id":"um153_3","label":"كِتَابُ الشَّهَادَاتِ · ٣","segs":[["matn","وَالْمَشْهُودُ عَلَيْهِ أَرْبَعَةُ أَقْسَامٍ: أَحَدُهَا: الزِّنَا وَمَا يُوجِبُ حَدَّهُ، فَلَا يَثْبُتُ إِلَّا بِأَرْبَعَةِ رِجَالٍ أَحْرَارٍ عُدُولٍ."]]},{"id":"um153_4","label":"كِتَابُ الشَّهَادَاتِ · ٤","segs":[["matn","الثَّانِي: الْمَالُ وَمَا يُقْصَدُ بِهِ الْمَالُ، فَيَثْبُتُ بِشَاهِدَيْنِ، أَوْ رَجُلٍ وَامْرَأَتَيْنِ، وَبِرَجُلٍ مَعَ يَمِينِ الطَّالِبِ."]]},{"id":"um153_5","label":"كِتَابُ الشَّهَادَاتِ · ٥","segs":[["matn","الثَّالِثُ: مَا عَدَا هَذَيْنِ مِمَّا يَطَّلِعُ عَلَيْهِ الرِّجَالُ، فِي غَالِبِ الْأَحْوَالِ فَلَا يَثْبُتُ إِلَّا بِشَهَادَةِ رَجُلَيْنِ."]]},{"id":"um153_6","label":"كِتَابُ الشَّهَادَاتِ · ٦","segs":[["matn","الرَّابِعُ: مَا لَا يَطَّلِعُ عَلَيْهِ الرِّجَالُ، كَالوِلَادَةِ، وَالحَيْضِ، وَالعِدَّةِ، وَالعُيُوبِ تَحْتَ الثِّيَابِ، فَيَثْبُتُ بِشَهَادَةِ امْرَأَةٍ عَدْلٍ؛"]]},{"id":"um153_7","label":"كِتَابُ الشَّهَادَاتِ · ٧","segs":[["matn","لِأَنَّ عُقْبَةَ بْنَ الحَارِثِ قَالَ: تَزَوَّجْتُ أُمَّ يَحْيَى بِنْتَ أَبِي إِهَابٍ، فَجَاءَتْ أَمَةٌ سَوْدَاءٌ، فَقَالَتْ: قَدْ أَرْضَعْتُكُمَا، فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ،"]]},{"id":"um153_8","label":"كِتَابُ الشَّهَادَاتِ · ٨","segs":[["matn","فَقَالَ: «كَيْفَ وَقَدْ زَعَمَتْ ذَلِكَ،» وَتُقْبَلُ شَهَادَةُ الْعَبْدِ فِي كُلِّ شَيْءٍ إِلَّا الْحُدُودَ وَالْقِصَاصَ، وَتُقْبَلُ شَهَادَةُ الْأَمَةِ فِيمَا تُقْبَلُ فِيهِ شَهَادَةُ النِّسَاءِ؛"]]},{"id":"um153_9","label":"كِتَابُ الشَّهَادَاتِ · ٩","segs":[["matn","لِلْخَبَرِ، وَشَهَادَةُ الفَاعِلِ عَلَى فِعْلِهِ، كَالْمُرْضِعَةِ عَلَى الرَّضَاعِ، وَالقَاسِمِ عَلَى القِسْمَةِ، وَشَهَادَةُ الأَخِ لِأَخِيهِ، وَالصَّدِيقِ لِصَدِيقِهِ، وَشَهَادَةُ الأَصَمِّ عَلَى الْمَرْئِيَّاتِ، وَشَهَادَةُ الأَعْمَى إِذَا تَيَقَّنَ الصَّوْتَ، وَشَهَادَةُ المُسْتَخْفِي."]]},{"id":"um153_10","label":"كِتَابُ الشَّهَادَاتِ · ١٠","segs":[["matn","وَمَنْ سَمِعَ إِنْسَانًا يُقِرُّ بِحَقٍّ، وَإِنْ لَمْ يَقُلْ لِلشَّاهِدِ: اشْهَدْ عَلَيَّ وَمَا تَظَاهَرَتْ بِهِ الأَخْبَارُ، وَاسْتَقَرَّتْ مَعْرِفَتُهُ فِي قَلْبِهِ، جَازَ أَنْ يَشْهَدَ بِهِ، كَالشَّهَادَةِ عَلَى النَّسَبِ وَالوِلَادَةِ، وَلَا يَجُوزُ ذَلِكَ فِي حَدٍّ وَلَا قِصَاصٍ. وَتُقْبَلُ شَهَادَةُ القَاذِفِ وَغَيْرِهِ، بَعْدَ تَوْبَتِهِ."]]}],"group":"كِتَابُ الشَّهَادَاتِ"},{"id":"um154","title":"بَابُ مَنْ تُرَدُّ شَهَادَتُهُ","units":[{"id":"um154_1","label":"بَابُ مَنْ تُرَدُّ شَهَادَتُهُ · ١","segs":[["matn","لَا تُقْبَلُ شَهَادَةُ صَبِيٍّ، وَلَا زَائِلِ العَقْلِ، وَلَا أَخْرَسَ، وَلَا كَافِرٍ، وَلَا فَاسِقٍ، وَلَا مَجْهُولِ الحَالِ، وَلَا جَارٍّ إِلَى نَفْسِهِ نَفْعًا،"]]},{"id":"um154_2","label":"بَابُ مَنْ تُرَدُّ شَهَادَتُهُ · ٢","segs":[["matn","وَلَا دَافِعٍ عَنْهَا شَرًّا، وَلَا شَهَادَةُ وَالِدٍ وَإِنْ عَلَا لِوَلَدِهِ، وَلَا وَلَدٍ لِوَالِدِهِ، وَلَا سَيِّدٍ لِعَبْدِهِ وَلَا مُكَاتِبِهِ، وَلَا شَهَادَتُهُمَا لَهُ،"]]},{"id":"um154_3","label":"بَابُ مَنْ تُرَدُّ شَهَادَتُهُ · ٣","segs":[["matn","وَلَا أَحَدِ الزَّوْجَيْنِ لِصَاحِبِهِ، وَلَا شَهَادَةُ الوَصِيِّ فِيمَا هُوَ وَصِيٌّ فِيهِ، وَلَا الوَكِيلِ فِيمَا هُوَ وَكِيلٌ فِيهِ، وَلَا الشَّرِيكِ فِيمَا هُوَ شَرِيكٌ فِيهِ،"]]},{"id":"um154_4","label":"بَابُ مَنْ تُرَدُّ شَهَادَتُهُ · ٤","segs":[["matn","وَلَا العَدُوِّ عَلَى عَدُوِّهِ، وَلَا مَعْرُوفٍ بِكَثْرَةِ الغَلَطِ وَالغَفْلَةِ، وَلَا مَنْ لَا مُرُوءَةَ لَهُ، كَالْمَسْخَرَةِ وَكَاشِفِ عَوْرَتِهِ لِلنَّاظِرِينَ فِي حَمَّامٍ أَوْ غَيْرِهِ. وَمَنْ شَهِدَ بِشَهَادَةٍ يُتَّهَمُ فِي بَعْضِهَا، رُدَّتْ كُلُّهَا."]]},{"id":"um154_5","label":"بَابُ مَنْ تُرَدُّ شَهَادَتُهُ · ٥","segs":[["matn","وَلَا يُسْمَعُ فِي الجَرْحِ وَالتَّعْدِيلِ، وَالتَّرْجَمَةِ، وَنَحْوِهَا، إِلَّا شَهَادَةُ اثْنَيْنِ، وَإِذَا تَعَارَضَ الجَرْحُ وَالتَّعْدِيلُ، قُدِّمَ الجَرْحُ."]]},{"id":"um154_6","label":"بَابُ مَنْ تُرَدُّ شَهَادَتُهُ · ٦","segs":[["matn","وَإِنْ شَهِدَ شَاهِدٌ بِأَلْفٍ، وَآخَرُ، بِأَلْفَيْنِ، قُضِيَ لَهُ بِأَلْفٍ، وَحَلَفَ مَعَ شَاهِدِهِ عَلَى الأَلْفِ الآخَرِ إِنْ أَحَبَّ، وَإِنْ قَالَ أَحَدُهُمَا: أَلْفٌ مِنْ قَرْضٍ، وَقَالَ الآخَرُ: مِنْ ثَمَنِ مَبِيعٍ، لَمْ تَكْمُلِ الشَّهَادَةُ."]]},{"id":"um154_7","label":"بَابُ مَنْ تُرَدُّ شَهَادَتُهُ · ٧","segs":[["matn","وَإِذَا شَهِدَ أَرْبَعَةٌ بِالزِّنَا أَوْ شَهِدَ اثْنَانِ عَلَى فِعْلِ سِوَاهُ، وَاخْتَلَفُوا فِي الْمَكَانِ، أَوِ الزَّمَانِ، أَوِ الصِّفَةِ لَمْ تَكْمُلْ شَهَادَتُهُمْ."]]}],"group":"كِتَابُ الشَّهَادَاتِ"},{"id":"um155","title":"بَابُ الشَّهَادَةِ عَلَى الشَّهَادَةِ وَالرُّجُوعِ عَنْهَا","units":[{"id":"um155_1","label":"بَابُ الشَّهَادَةِ عَلَى الشَّهَادَةِ وَالرُّجُوعِ عَنْهَا · ١","segs":[["matn","تَجُوزُ الشَّهَادَةُ عَلَى الشَّهَادَةِ فِيمَا يَجُوزُ فِيهِ كِتَابُ القَاضِي، إَذَا تَعَذَّرَتْ شَهَادَةُ الأَصْلِ؛ بِمَوْتٍ، أَوْ غَيْبَةٍ، أَوْ مَرَضٍ وَنَحْوِهِ، بِشَرْطِ أَنْ يَسْتَرْعِيَهُ شَاهِدُ الأَصْلِ، فَيَقُولُ: اشْهَدْ عَلَى شَهَادَتِي، أَنِّي أَشْهَدُ أَنَّ فُلَانًا أَقَرَّ عِنْدِي، أَوْ أَشْهَدَنِي بِكَذَا."]]},{"id":"um155_2","label":"بَابُ الشَّهَادَةِ عَلَى الشَّهَادَةِ وَالرُّجُوعِ عَنْهَا · ٢","segs":[["matn","وَيُعْتَبَرُ مَعْرِفَةُ العَدَالَةِ فِي شُهُودِ الأَصْلِ وَالفَرْعِ. وَمَتَى لَمْ يُحْكَمْ بِشَهَادَةِ الفَرْعِ حَتَّى حَضَرَ شُهُودُ الأَصْلِ، وَقَفَ الحُكْمُ عَلَى سِمَاعِ شَهَادَتِهِمْ."]]},{"id":"um155_3","label":"بَابُ الشَّهَادَةِ عَلَى الشَّهَادَةِ وَالرُّجُوعِ عَنْهَا · ٣","segs":[["matn","وَإِنْ حَدَثَ مِنْ بَعْضِهِمْ مَا يَمْنَعُ قَبُولَ الشَّهَادَةِ، لَمْ يُحْكَمْ بِهَا."]]},{"id":"um155_4","label":"بَابُ الشَّهَادَةِ عَلَى الشَّهَادَةِ وَالرُّجُوعِ عَنْهَا · ٤","segs":[["matn","فَصْلٌ: وَمَتَى غَيَّرَ الْعَدْلُ شَهَادَتَهُ فَزَادَ فِيهَا أَوْ نَقَصَ قَبْلَ الْحُكْمِ قُبِلَتْ، وَإِنْ حَدَثَ مِنْهُ مَا يَمْنَعُ قَبُولَهَا بَعْدَ أَدَائِهَا، رُدَّتْ، وَإِنْ حَدَثَ ذَلِكَ بَعْدَ الحُكْمِ بِهَا لَمْ يُؤَثِّرْ."]]},{"id":"um155_5","label":"بَابُ الشَّهَادَةِ عَلَى الشَّهَادَةِ وَالرُّجُوعِ عَنْهَا · ٥","segs":[["matn","وَإِنْ رَجَعَ الشُّهُودُ بَعْدَ الحُكْمِ بِشَهَادَتِهِمْ، لَمْ يُنْقَضِ الحُكْمُ، وَلَمْ يُمْنَعْ الِاسْتِيفَاءُ، إِلَّا فِي الْحُدُودِ وَالقِصَاصِ، وَعَلَيْهِمْ غَرَامَةُ مَا فَاتَ بِشَهَادَتِهِمْ بِمِثْلِهِ، إِنْ كَانَ مِثْلِيًّا، وَقِيمَتِهِ إِنْ لَمْ يَكُنْ مِثْلِيًّا، وَيَكُونُ ذَلِكَ بَيْنَهُمْ عَلَى عَدَدِهِمْ، فَإِنْ رَجَعَ أَحَدُهُمْ، فَعَلَيْهِ حِصَّتُهُ."]]},{"id":"um155_6","label":"بَابُ الشَّهَادَةِ عَلَى الشَّهَادَةِ وَالرُّجُوعِ عَنْهَا · ٦","segs":[["matn","وَإِنْ كَانَ الْمَشْهُودُ بِهِ قَتْلاً، أَوْ جَرْحًا، فَقَالُوا: تَعَمَّدْنَا، فَعَلَيْهِمْ القِصَاصُ، وَإِنْ قَالُوا: أَخْطَأْنَا، غَرِمُوا الدِّيَةَ، وَأَرْشَ الجُرْحِ."]]}],"group":"كِتَابُ الشَّهَادَاتِ"},{"id":"um156","title":"بَابُ اليَمِينِ فِي الدَّعَاوَى","units":[{"id":"um156_1","label":"بَابُ اليَمِينِ فِي الدَّعَاوَى · ١","segs":[["matn","اليَمِينُ الْمَشْرُوعَةُ فِي الحُقُوقِ، هِيَ اليَمِينُ بِاللهِ تَعَالَى، سَوَاءٌ كَانَ الحَالِفُ مُسْلِمًا، أَوْ كَافِرًا. وَيَجُوزُ القَضَاءُ فِي الأَمْوَالِ وَأَسْبَابِهَا بِشَاهِدٍ وَيَمِينٍ؛ لِأَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَضَى بِشَاهِدٍ وَيَمِينٍ."]]},{"id":"um156_2","label":"بَابُ اليَمِينِ فِي الدَّعَاوَى · ٢","segs":[["matn","وَالأَيْمَانُ كُلُّهَا عَلَى البَتِّ، إِلَّا اليَمِينُ عَلَى نَفْيِ فِعْلِ غَيْرِهِ، فَإِنَّهَا عَلَى نَفْيِ العِلْمِ."]]},{"id":"um156_3","label":"بَابُ اليَمِينِ فِي الدَّعَاوَى · ٣","segs":[["matn","وَإِذَا كَانَ لِلْمَيِّتِ أَوِ، الْمُفْلِسِ حَقٌّ بِشَاهِدٍ، فَحَلَفَ الْمُفْلِسُ، أَوْ وَرَثَةُ الْمَيِّتِ ثَبَتَ، وَإِنْ لَمْ يَحْلِفْ فَبَذَلَ الغُرَمَاءُ اليَمِينَ لَمْ يُسْتَحْلَفُوا."]]},{"id":"um156_4","label":"بَابُ اليَمِينِ فِي الدَّعَاوَى · ٤","segs":[["matn","وَإِذَا كَانَتِ الدَّعْوَى لِجَمَاعَةٍ، فَعَلَيْهِ لِكُلِّ وَاحِدٍ يَمِينٌ، وَإِنْ قَالَ: أَنَا أَحْلِفُ يَمِينًا وَاحِدَةً لِجَمِيعِهِمْ، لَمْ يُقْبَلْ مِنْهُ، إِلَّا أَنْ يَرْضَوْا."]]},{"id":"um156_5","label":"بَابُ اليَمِينِ فِي الدَّعَاوَى · ٥","segs":[["matn","وَإِنِ ادَّعَى وَاحِدٌ حُقُوقًا عَلَى وَاحِدٍ، فَعَلَيْهِ فِي كُلِّ حَقٍّ يَمِينٌ. وَتُشْرَعُ اليَمِينُ فِي كُلِّ حَقٍّ لِآدَمِيٍّ، وَلَا تُشْرَعُ فِي حُقُوقِ اللهِ مِنَ الحُدُودِ وَالعِبَادَاتِ."]]}],"group":"كِتَابُ الشَّهَادَاتِ"},{"id":"um157","title":"بَابُ الإِقْرَارِ","units":[{"id":"um157_1","label":"بَابُ الإِقْرَارِ · ١","segs":[["matn","وَإِذَا أَقَرَّ الْمُكَلَّفُ، الْحُرُّ الرَّشِيدُ الصَّحِيحُ، الْمُخْتَارُ بِحَقٍّ، أُخِذَ بِهِ."]]},{"id":"um157_2","label":"بَابُ الإِقْرَارِ · ٢","segs":[["matn","وَمَنْ أَقَرَّ بِدَرَاهِمَ، ثُمَّ سَكَتَ سُكُوتًا يُمْكِنُهُ الكَلَامُ فِيهِ، ثُمَّ قَالَ: زُيُوفًا أَوْ صِغَارًا، أَوْ مُؤَجَّلَةً، لَزِمَتْهُ جِيَادًا، وَافِيَةً، حَالَّةً، وَإِنْ وَصَفَهَا بِذَلِكَ مُتَّصِلاً بِإِقْرَارِهِ، لَزِمَتْهُ كَذَلِكَ."]]},{"id":"um157_3","label":"بَابُ الإِقْرَارِ · ٣","segs":[["matn","وَإِنِ اسْتَثْنَى مِمَّا أَقَرَّ بِهِ، أَقَلَّ مِنْ نِصْفِهِ مُتَّصِلاً بِهِ، صَحَّ اسْتِثْنَاؤُهُ، وَإِنْ فَصَلَ بَيْنَهُمَا بِسُكُوتٍ يُمْكِنُهُ الكَلَامُ أَوْ بِكَلَامٍ أَجْنَبِيٍّ، أَوِ اسْتَثْنَى أَكْثَرَ مِنْ نِصْفِهِ، أَوْ مِنْ غَيْرِ جِنْسِهِ، لَزِمَهُ كُلُّهُ."]]},{"id":"um157_4","label":"بَابُ الإِقْرَارِ · ٤","segs":[["matn","وَمَنْ قَالَ: لَهُ عَلَيَّ دَرَاهِمُ، ثُمَّ قَالَ: وَدِيعَةٌ، لَمْ يُقْبَلْ قَوْلُهُ. وَمَنْ أَقَرَّ بِدَرَاهِمَ، فَأَقَلُّ مَا يَلْزَمُهُ ثَلَاثَةٌ، إِلَّا أَنْ يُصَدِّقُهُ المُقَرُّ لَهُ فِي أَقَلَّ مِنْهَا."]]},{"id":"um157_5","label":"بَابُ الإِقْرَارِ · ٥","segs":[["matn","وَمَنْ أَقَرَّ بِشَيْءٍ مُجْمَلٍ، قُبِلَ تَفْسِيرُهُ بِمَا يَحْتَمِلُهُ."]]},{"id":"um157_6","label":"بَابُ الإِقْرَارِ · ٦","segs":[["matn","فَصْلٌ: وَلَا يُقْبَلُ إِقْرَارُ غَيْرِ المُكَلَّفِ بِشَيْءٍ، إِلَّا الْمَأْذُونَ لَهُ مِنَ الصِّبْيَانِ فِي التَّصَرُّفِ فِي قَدْرِ مَا أُذِنَ لَهُ."]]},{"id":"um157_7","label":"بَابُ الإِقْرَارِ · ٧","segs":[["matn","وَإِنْ أَقَرَّ السَّفِيُهُ بِحَدٍّ أَوْ قِصَاصٍ، أَوْ طَلَاقٍ، أُخِذَ، بِهِ وَإِنْ أَقَرَّ بِمَالٍ، لَمْ يُقْبَلْ إِقْرَارُهُ، وَكَذَلِكَ الحُكْمُ فِي إِقْرَارِ العَبْدِ،"]]},{"id":"um157_8","label":"بَابُ الإِقْرَارِ · ٨","segs":[["matn","إِلَّا أَنَّهُ يَتَعَلَّقُ بِذِمَّتِهِ، يُتْبَعُ بِهِ بَعْدَ العِتْقِ، إِلَّا أَنْ يَكُونَ مَأْذُونًا لَهُ فِي التِّجَارَةِ، فَيَصِحُّ إِقْرَارُهُ فِي قَدْرِ مَا أُذِنَ لَهُ، فِيهِ."]]},{"id":"um157_9","label":"بَابُ الإِقْرَارِ · ٩","segs":[["matn","وَيَصِحُّ إِقْرَارُ الْمَرِيضُ بِالدَّيْنِ لِأَجْنَبِيٍّ، وَلَا يَصِحُّ إِقْرَارُهُ فِي مَرَضِ المَوْتِ لِوَارِثٍ، إِلَّا بِتَصْدِيقِ سَائِرِ الوَرَثَةِ، وَلَوْ أَقَرَّ لِوَارِثٍ، فَصَارَ غَيْرَ وَارِثٍ، لَمْ يَصِحَّ، وَإِنْ أَقَرَّ لَهُ وَهُوَ غَيْرُ وَارِثٍ، ثُمَّ صَارَ وَارِثاً، صَحَّ إِقْرَارُهُ، وَيَصِحَّ إِقْرَارُهُ بِوَارِثٍ."]]},{"id":"um157_10","label":"بَابُ الإِقْرَارِ · ١٠","segs":[["matn","وَإِذَا كَانَ عَلَى الْمَيِّتِ دَيْنٌ، لَمْ يَلْزَمِ الوَرَثَةَ وَفَاؤُهُ، إِلَّا أَنْ خَلَّفَ تَرِكَةً، فَيَتَعَلَّقُ دَيْنُهُ بِهَا، فَإِنْ أَحَبَّ الوَرَثَةُ وَفَاءَ الدَّيْنِ، وَأَخْذَ التَّرِكَةِ فَلَهُمْ ذَلِكَ."]]},{"id":"um157_11","label":"بَابُ الإِقْرَارِ · ١١","segs":[["matn","وَإِنْ أَقَرَّ جَمِيعَ الوَرَثَةِ بِدَيْنٍ عَلَى مُوَرِّثِهِمْ، ثَبَتَ بِإِقْرَارِهِمْ، وَإِنْ أَقَرَّ بِهِ بَعْضُهُمْ، ثَبَتَ بِقَدْرِ حَقِّهِ."]]},{"id":"um157_12","label":"بَابُ الإِقْرَارِ · ١٢","segs":[["matn","فَلَوْ خَلَّفَ ابْنَيْنِ وَمِائَتَيْ دِرْهَمٍ، فَأَقَرَّ أَحَدُهُمَا بِمِئَةٍ دِينَارٍ عَلَى أَبِيهِ لَزِمَهُ خَمْسُونَ دِرْهَمًا، فَإِنْ كَانَ عَدْلاً وَشَهِدَ بِهَا، فَلِلْغَرِيمِ أَنْ يَحْلِفَ مَعَ شَهَادَتِهِ وَيَأْخُذُ بَاقِيَهَا مِنْ أَخِيهِ."]]},{"id":"um157_13","label":"بَابُ الإِقْرَارِ · ١٣","segs":[["matn","وَإِنْ خَلَّفَ ابْنَا وَمِئَةً، فَادَّعَى رَجُلٌ مِئَةً عَلَى أَبِيهِ، فَصَدَّقَهُ، ثُمَّ ادَّعَى آخَرُ مِثْلَ ذَلِكَ فَصَدَّقَهُ الِابْنُ، فَإِنْ كَانَ فِي مَجْلِسٍ وَاحِدٍ، فَالْمِائَةُ بَيْنَهُمَا،"]]},{"id":"um157_14","label":"بَابُ الإِقْرَارِ · ١٤","segs":[["matn","وَإِنْ كَانَا فِي مَجْلِسَيْنِ فَهُوَ لِلْأَوَّلِ وَلَا شَيْءَ لِلثَّانِي، وَإِنْ كَانَ الأَوَّلُ ادَّعَاهَا فَصَدَّقَهُ الِابْنُ، ثُمَّ ادَّعَاهَا آخَرُ، فَصَدَّقَهُ الِابْنُ فَهِيَ لِلْأَوَّلِ، وَلَا شَيْءَ لِلثَّانِي، وَيغَرْمُهَا لِأَنَّهُ فَوَّتَهَا عَلَيْهِ بِإِقْرَارِهِ."]]}],"group":"كِتَابُ الشَّهَادَاتِ"}],"basmala":"بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ","sharh":false};
